(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]=m["rl"]||{};d["papers"]=[{"id":"paper-a-unifying-lens-on-reward-uncertaint-2026","title":"A Unifying Lens on Reward Uncertainty in RLHF","title_zh":"RLHF奖励不确定性的统一视角","authors":["Ely Hahami","Yoel Zimmermann","Ray Zhou","Jack Benarroch Jedlicki"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-reward-verifier-serving","links":{"paper":"https://arxiv.org/abs/2606.09073","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RLHF 的奖励模型只是人类偏好的有限样本拟合，其打分在分布外与长尾样本上存在系统性不确定性；若把奖励当作确定标量直接驱动 PPO 类 rollout，策略会利用奖励误差而非真实偏好。该论文试图用一个统一视角刻画奖励不确定性，并把它接入后训练推理链路，使 rollout 阶段的采样与筛选能感知奖励置信度。","problem":"现有 RLHF 流水线把奖励模型输出当作点估计，rollout 引擎批量生成时无法区分高置信与低置信样本，导致长尾与分布外请求被错误强化；同时奖励模型与验证器推理和策略生成解耦不足，置信度信号难以在批调度与 KV 复用层面生效。","core_idea":"将奖励不确定性显式建模为分布（而非标量），在 rollout 采样与优势估计中使用置信区间或方差惩罚；把奖励模型／验证器推理作为独立服务暴露置信度分数，使批量生成调度可按置信度分层处理，高置信样本走快路径、低置信样本进入复核或降权。","architecture":"逻辑上分三层：策略 rollout 引擎负责批量生成与 KV 前缀共享；奖励／验证器服务以独立副本部署，返回均值与不确定性；调度层按置信度对样本分层，决定是否重采样、降权或丢弃。权重同步通过异步流水线完成，置信度阈值与批大小作为可调旋钮，在吞吐与样本质量间取舍。","pipeline":["请求进入 rollout 引擎，按长度分布切分为批，长请求进入长尾队列并复用前缀 KV。","策略模型批量解码，投机解码与连续批调度并行推进，产出候选回答及 token 级 logprob。","候选回答连同上下文送入奖励／验证器服务，返回奖励均值与不确定性估计。","调度层按置信度分层：高置信样本直接进入优势估计，低置信样本触发重采样或降权。","异步流水线将分层结果回写训练侧，权重同步与置信度阈值更新按固定周期进行。","监控层统计长尾队列积压、置信度分布漂移与吞吐下降，触发批大小与阈值调整。"],"formula":"$$\\hat{A}_t=\\frac{r_\\theta(x,y)-\\mu_r(x)}{\\sqrt{\\sigma_r^2(x)+\\epsilon}}\\cdot\\mathbb{1}\\left[\\sigma_r^2(x)\\leq\\tau\\right]$$","training":"论文不涉及训练配方；推理侧把奖励不确定性作为 rollout 过滤与加权信号。奖励服务以独立副本部署，返回均值与方差；调度层用阈值 τ 控制低置信样本是否参与优势估计。异步流水线中权重同步周期与置信度阈值共同决定样本新鲜度与吞吐，长尾样本因多次重采样而放大奖励服务负载。","walkthrough":"一次典型 rollout：批量请求进入引擎，短请求走常规连续批，长请求进入长尾队列并共享前缀 KV。解码完成后候选回答送奖励服务，服务返回均值与方差；调度层按 τ 分层，高置信样本直接计算优势并回写，低置信样本重采样或降权。若奖励服务积压，长尾队列膨胀，吞吐下降，监控触发批大小收缩与阈值上调，牺牲部分样本质量换取稳定吞吐。","pseudocode":"for batch in rollout_scheduler:\n  -> split batch by length, long tail to queue\n  -> decode with continuous batching and prefix KV reuse\n  -> call reward_service(ctx, resp) returns mean, var\n  -> if var <= tau: advantage = (mean - baseline)/sqrt(var+eps)\n  -> else: resample or downweight, enqueue review\n  -> async write advantages to trainer, sync weights periodically\n  -> monitor queue depth, var drift, throughput; adjust batch and tau","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与数字；可核验的机制结论是置信度分层可把低置信样本从优势估计中隔离，减少奖励误差被策略利用；代价是奖励服务调用次数上升与长尾队列积压，吞吐随 τ 收紧而下降。","limits":"论文未给出硬件档位、并行拓扑与量化方案；NVFP4 下采样稳定性、KV 复用命中率与奖励服务副本数对吞吐的影响均未量化，长尾样本的重采样放大效应缺少实测数据。","ablations":"材料未给出消融实验；可推断的消融维度为置信度阈值 τ、奖励服务副本数、长尾队列上限与重采样次数，但均无具体数值。"},"innovation":["把奖励不确定性从标量点估计扩展为分布，并接入优势估计与样本过滤。","将奖励／验证器推理作为独立服务暴露置信度，使批调度可按置信度分层。","置信度阈值与批大小作为吞吐与样本质量的联合旋钮，适配异步流水线。"],"limitations":["缺少硬件档位、并行拓扑与量化方案，无法评估 NVFP4 下采样稳定性。","奖励服务独立部署放大调用次数，长尾重采样进一步加剧负载，吞吐代价未量化。","置信度阈值 τ 的选取缺少理论指导与实测消融，易受分布漂移影响。"],"impact":"为 RL 后训练 rollout 提供可操作的置信度分层机制：把奖励误差挡在优势估计之外，代价是奖励服务负载与长尾队列管理；对分离式预填／解码与 KV 前缀共享的调度设计有直接参考价值。","summary":"论文以统一视角把 RLHF 奖励不确定性建模为分布，并在 rollout 推理链路中用置信度分层决定样本是否进入优势估计、重采样或降权。奖励／验证器作为独立服务返回均值与方差，调度层以阈值 τ 与批大小联合调节吞吐与样本质量；异步流水线完成权重同步。材料未给出数据集、硬件与量化细节，长尾重采样与奖励服务负载的工程代价仍需实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布呈长尾，短请求走常规连续批，长请求进入独立长尾队列并共享前缀 KV。","批大小随置信度阈值动态调整，τ 收紧时缩小批以控制奖励服务并发。","并发上限由奖励服务副本数与长尾队列深度共同约束，超限触发降权而非阻塞。","SLO 以 rollout 吞吐与低置信样本占比双指标衡量，长尾积压超阈值即告警。"],"train_recipe":["奖励／验证器服务独立副本部署，与策略 rollout 引擎解耦，按置信度分层调用。","KV 策略采用前缀共享与连续批调度，长尾请求复用前缀以降低重复预填。","量化方案与硬件档位未给出；NVFP4 采样稳定性需在部署前单独验证。","监控项包括置信度分布漂移、长尾队列深度、奖励服务延迟与吞吐下降。","权重同步走异步流水线，同步周期与置信度阈值更新解耦，避免阻塞 rollout。"],"facts":["论文把奖励不确定性建模为分布并返回均值与方差，调度层用阈值 τ 决定样本是否进入优势估计，低置信样本触发重采样或降权，直接改变 rollout 批内样本构成。","奖励／验证器推理被拆为独立服务，与策略 rollout 引擎解耦部署；每次候选回答都需一次服务调用，调用次数随重采样放大，构成主要吞吐代价。","置信度分层使高置信样本走快路径、低置信样本进入复核队列；长尾队列深度成为吞吐瓶颈的先行指标，超限时需收缩批大小或上调 τ。","优势估计形式为均值减基线后除以方差加 eps 的平方根，并以方差不超过 τ 为指示条件；方差大的样本被排除，避免奖励误差被策略利用。","异步流水线中权重同步周期与置信度阈值更新分离，样本新鲜度由同步周期决定，阈值漂移由监控层统计置信度分布变化触发调整。","长尾样本因多次重采样而放大奖励服务负载，形成正反馈：队列越长重采样越多、服务越慢；需以队列上限与降权策略打断该循环。","论文未给出硬件档位、并行拓扑与量化方案，NVFP4 下采样稳定性、KV 前缀共享命中率与奖励服务副本数对吞吐的影响均缺少实测数字。","调度层以批大小与阈值 τ 作为联合旋钮：τ 收紧提升样本质量但降低吞吐，τ 放松提升吞吐但引入更多低置信样本进入优势估计。"],"anchors":[],"pitfalls":["把奖励不确定性当作免费信号：每次调用奖励服务都增加延迟与并发，长尾重采样会放大负载，需先估算服务副本与队列上限。","阈值 τ 缺少理论指导，分布漂移时固定 τ 会误杀高置信样本或放行低置信样本，需配合监控动态调整。","材料未给出量化与硬件细节，直接套用 NVFP4 部署前必须单独验证采样稳定性，不能假设置信度分层在低精度下同样有效。"],"depth":"deep"},{"id":"paper-ask-a-strong-llm-judge-when-your-rew-2025","title":"Ask a Strong LLM Judge when Your Reward Model is Uncertain","title_zh":"强LLM裁判介入不确定奖励模型","authors":["Zhenghao Xu","Qin Lu","Qingru Zhang","Liang Qiu","Ilgee Hong","Changlong Yu","Wenlin Yao","Yao Liu","Haoming Jiang","Lihong Li","Hyokun Yun","Tuo Zhao"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-reward-verifier-serving","links":{"paper":"https://arxiv.org/abs/2510.20369","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RL后训练中的奖励建模常以较小模型给出标量分数，但当奖励模型对某条 rollout 样本的置信度不足时，错误奖励会直接污染策略梯度。该论文提出在奖励模型不确定时调用更强 LLM 作为裁判，把奖励计算拆成两档：低不确定样本走廉价奖励模型，高不确定样本升级到强裁判，从而在奖励质量与推理成本之间做取舍。","problem":"奖励模型在分布外或长尾样本上打分不稳，若全部交给强 LLM 裁判则吞吐与成本不可接受；若只用小奖励模型则噪声奖励导致策略优化方向偏移。核心问题是如何定义不确定性触发条件，并把裁判调用嵌入 rollout 批量生成流水线而不拖垮吞吐。","core_idea":"用奖励模型自身的不确定性信号作为路由开关：对每条样本先由奖励模型打分并估计置信度，低于阈值的样本升级给强 LLM 裁判重新打分，其余样本直接采用奖励模型分数；升级调用以异步方式与 rollout 生成重叠，避免阻塞批调度。","architecture":"系统由三部分组成：rollout 引擎批量生成样本；奖励模型推理服务对样本打分并输出不确定性度量；裁判服务承接升级请求。路由层按阈值把样本分流，升级请求进入独立队列，与训练侧权重同步解耦。KV 前缀共享用于裁判侧重复提示模板，长尾样本的裁判结果回填到奖励缓冲，供策略更新消费。","pipeline":["rollout 引擎按批生成样本，样本进入奖励打分队列并记录长度与来源策略版本。","奖励模型对每条样本输出标量分数与不确定性度量，路由层按阈值判定是否升级。","低不确定样本直接写入奖励缓冲，等待策略更新消费。","高不确定样本进入裁判队列，裁判服务以共享前缀模板批量调用强 LLM 打分。","裁判结果回填奖励缓冲并标记来源，异步流水线与下一轮 rollout 重叠。","权重同步时刷新奖励模型与裁判提示版本，保证打分与当前策略一致。"],"formula":"$$r(x)=\\begin{cases}r_{\\mathrm{rm}}(x), & u(x)\\le \\tau\\\\ r_{\\mathrm{judge}}(x), & u(x)>\\tau\\end{cases}$$","training":"论文不涉及训练配方，只关心推理侧：奖励模型与裁判均为冻结推理，路由阈值 $\\tau$ 为超参数。策略更新消费的是混合奖励，升级比例由阈值控制，阈值越低裁判调用越多、奖励越准但吞吐越低。权重同步需保证奖励模型版本与 rollout 策略版本对齐，否则不确定性估计失真。","walkthrough":"一轮迭代中，rollout 引擎先按批生成样本并送入奖励模型服务；奖励模型对每条样本给出分数与不确定性，路由层按阈值分流。大部分样本落在低不确定区间，直接进入奖励缓冲；少数长尾或分布外样本被标记升级，进入裁判队列。裁判服务利用共享前缀模板批量调用强 LLM，结果异步回填。训练侧在奖励缓冲就绪后启动策略更新，同时下一轮 rollout 已开始生成，裁判调用与生成重叠，长尾样本的额外延迟被流水线掩盖。","pseudocode":"for batch in rollout_engine:\n  samples = generate(batch)\n  for s in samples:\n    score, unc = reward_model(s)\n    if unc <= tau:\n      buffer.push(score, src=rm)\n    else:\n      judge_queue.push(s)\n  while judge_queue and pipeline_slot:\n    group = judge_queue.pop_batch()\n    scores = judge(group, prefix_cache=shared)\n    buffer.push(scores, src=judge)\n  if buffer.ready():\n    policy_update(buffer)\n  sync_weights(reward_model, judge_prompt)","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"论文报告在奖励不确定时引入强 LLM 裁判可改善奖励质量，但具体数据集、提升幅度与吞吐代价数字未给出；可核验材料仅支持机制层面的路由与异步流水线描述。","limits":"升级比例受阈值控制，阈值过低会使裁判调用量激增并拖慢吞吐；裁判服务与奖励模型版本需同步，否则不确定性估计与奖励口径不一致；长尾样本的裁判延迟可能拉长单轮迭代尾部。","ablations":"材料未给出消融实验细节，仅可推断阈值与异步重叠程度是主要敏感变量。"},"innovation":["以奖励模型不确定性作为路由开关，把强 LLM 裁判调用限制在高不确定样本上。","裁判调用与 rollout 生成异步重叠，用流水线掩盖长尾样本的额外延迟。","裁判侧共享前缀模板复用 KV，降低重复提示的预填开销。"],"limitations":["阈值选择缺乏材料给出的定量依据，升级比例与吞吐的权衡未量化。","裁判服务与奖励模型版本同步机制未给出具体实现细节。","长尾样本裁判延迟对单轮迭代尾部的影响未给出测量。"],"impact":"该机制为 RL 后训练 rollout 提供了一种按需升级奖励的推理路径：把昂贵裁判限制在少数不确定样本上，并用异步流水线与前缀共享控制代价，适合在 Blackwell 部署中与奖励/验证器服务同机编排。","summary":"论文提出在奖励模型不确定时调用强 LLM 裁判，核心是阈值路由加异步流水线：低不确定样本走廉价奖励模型，高不确定样本升级裁判，裁判结果回填奖励缓冲供策略更新。机制上强调裁判调用与 rollout 生成重叠、共享前缀复用 KV，从而在奖励质量与吞吐之间取舍；材料未给出具体数据集与数字。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为 rollout 批量生成的样本，长度分布与批大小未给出，需按长尾比例估计升级量。","并发由 rollout 引擎与裁判队列共同决定，升级比例随阈值变化。","SLO 未给出，需保证裁判调用不阻塞奖励缓冲就绪时间。"],"train_recipe":["硬件档位未给出，裁判与奖励模型可同机部署以共享前缀 KV。","并行拓扑未给出，裁判服务需支持批量调用与队列背压。","量化方案未给出，采样稳定性需与 NVFP4 路径一并验证。","监控需覆盖升级比例、裁判队列深度与奖励缓冲就绪延迟。"],"facts":["奖励路由以不确定性阈值 $\\tau$ 为开关：低于阈值用奖励模型分数，高于阈值升级强 LLM 裁判，升级比例直接决定裁判调用量与吞吐代价。","裁判调用进入独立队列并与 rollout 生成异步重叠，长尾样本的额外延迟被流水线掩盖，但队列深度需监控以防尾部拉长单轮迭代。","裁判侧对重复提示模板做前缀共享以复用 KV，降低预填开销；该机制依赖提示模板稳定，模板变更会使缓存失效。","奖励模型与裁判的版本需与当前策略同步，否则不确定性估计与奖励口径不一致，导致路由判定失真。","论文未给出数据集、提升幅度与吞吐数字，机制层面仅可核验阈值路由与异步流水线两条设计。","升级比例过低会漏掉高不确定样本使奖励噪声进入策略梯度；过高则裁判成为吞吐瓶颈，需按 SLO 调阈值。"],"anchors":[],"pitfalls":["把不确定性阈值当作固定常数而不随策略版本调整，会使升级比例漂移。","裁判队列与 rollout 生成未做背压，长尾样本可能拖长单轮迭代尾部。","前缀共享假设提示模板不变，模板微调会导致 KV 缓存整体失效。"],"depth":"deep"},{"id":"paper-atpo-adaptive-tree-policy-optimizati-2026","title":"ATPO: Adaptive Tree Policy Optimization for Multi-Turn Medical Dialogue","title_zh":"ATPO：多轮医疗对话的自适应树策略优化","authors":["Ruike Cao","Shaojie Bai","Fugen Yao","Liang Dong","Jian Xu","Li Xiao"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2603.02216","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"多轮医疗对话的强化学习后训练需要在每一轮由策略模型生成回复，并由奖励模型或验证器打分；rollout 阶段因此成为长尾、变长、强依赖前缀共享的推理负载。论文提出 ATPO，用树状展开组织多轮对话采样，使同一患者上下文的不同追问分支共享前缀 KV，并把奖励回传与树结构对齐。","problem":"多轮对话的朴素串行采样会重复计算共享病史前缀，长尾样本拖慢整批；树状分支又带来分支间 KV 复用与批调度冲突，奖励归因需按树路径而非单条轨迹进行。","core_idea":"把每轮对话建模为树节点：根为患者初始上下文，边为一次提问或回答，叶为终止回合；采样时按层批量展开候选分支，前缀 KV 在兄弟分支间复用，奖励沿树路径回传并做自适应剪枝，只对高价值分支继续加深。","architecture":"rollout 引擎与训练进程解耦：训练侧推送权重版本，推理侧以树为调度单元组织批量生成。每层展开时把同前缀的兄弟分支合并为一个前缀块，KV cache 按前缀块分配并在分支结束后按引用计数回收；奖励模型/验证器作为独立服务批量打分，结果按节点 id 回填树。","pipeline":["训练侧发布新权重版本，rollout 引擎按版本号加载并冻结该轮采样所用策略。","按患者初始上下文建立根节点，写入前缀 KV 块并登记引用计数。","逐层批量展开候选分支，同前缀兄弟分支共享 KV 块，仅增量计算新 token。","叶节点或终止回合送入奖励模型/验证器服务批量打分，分数按节点 id 回填。","按树路径聚合奖励并自适应剪枝，低价值分支停止加深，高价值分支进入下一层。","采样批次完成后按版本对齐回传轨迹与树结构，供策略更新使用。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{\\tau\\sim\\pi_\\theta}\\left[\\sum_{t=1}^{T}\\gamma^{t-1}r_t\\right],\\quad \\tau=\\text{path}(\\text{root}\\to\\text{leaf})$$","training":"论文关注的是 RL 后训练中的 rollout 推理侧，而非训练配方本身。策略更新使用树路径上的累积奖励，奖励由奖励模型或验证器在叶节点给出；树的自适应剪枝阈值决定哪些分支继续展开。权重同步以版本号对齐，采样批次与训练步解耦，避免长尾分支阻塞整批。","walkthrough":"假设一位患者有既往病史前缀，根节点 KV 块写入后，第一层展开三个追问分支，三者共享同一前缀块，只各自计算新提问的 token。打分后两个分支得分低被剪枝，仅一个分支进入第二层并再展开两个子分支；此时父分支 KV 仍被引用，子分支增量计算。全部叶节点打分完成后按路径聚合奖励，整棵树作为一个采样单元回传训练侧。长尾分支若超过预算则被截断并标记，不阻塞同批其他树的完成。","pseudocode":"初始化根节点，写入患者上下文前缀 KV 块，引用计数置一\n按层循环：\n  收集该层待展开节点，按前缀哈希分组\n  同前缀兄弟分支合并为前缀块，仅增量计算新 token\n  批量生成候选分支，写入子节点 KV 并增加引用计数\n  叶节点送入奖励服务批量打分，按节点 id 回填\n  按路径聚合奖励，低于剪枝阈值的分支停止加深\n  分支结束释放 KV 块，引用计数减一，归零则回收\n  超过预算的长尾分支截断并标记，不阻塞整批\n回传树结构与轨迹，按权重版本号对齐训练步","experiments":{"datasets":["多轮医疗对话数据集（具体名称未给出）"],"baselines":["未给出"],"results":"论文报告 ATPO 在多轮医疗对话任务上优于对比方法，但材料未给出具体数据集规模、基线名称与数值指标，无法核验吞吐或奖励提升幅度。","limits":"材料未给出硬件档位、批大小、KV 预算与 SLO 设定，因此无法判断树状展开在长尾样本下的实际吞吐代价；奖励模型服务延迟与剪枝阈值的敏感性也未量化。","ablations":"材料未给出消融实验细节，仅可推断树状前缀复用与自适应剪枝是主要机制，但缺少去掉任一机制后的对照数字。"},"innovation":["以树结构组织多轮对话 rollout，使兄弟分支共享前缀 KV，减少重复预填。","奖励沿树路径回传并按节点自适应剪枝，把采样预算集中到高价值分支。","rollout 引擎与训练进程按权重版本解耦，树作为调度单元批量展开。"],"limitations":["材料未给出 KV 复用率、批调度策略与显存占用的量化数据，工程代价不可核验。","树状分支的引用计数与剪枝阈值在长尾样本下可能造成 KV 块碎片化与批内空转。","缺少 NVFP4 等低精度采样下的数值稳定性讨论，采样分布偏移风险未评估。"],"impact":"对 RL 后训练推理而言，ATPO 把多轮对话采样从串行轨迹改为树状批量展开，提示 rollout 引擎应以前缀共享与引用计数管理 KV，并把奖励服务作为独立批处理环节；其剪枝机制为长尾样本的吞吐控制提供了可借鉴的调度思路。","summary":"ATPO 面向多轮医疗对话的 RL 后训练，将每轮交互建模为树节点，按层批量展开候选分支，兄弟分支共享前缀 KV 块并以引用计数回收；叶节点由奖励模型或验证器批量打分，奖励沿树路径聚合，低价值分支被自适应剪枝。rollout 引擎与训练进程按权重版本解耦，树作为调度单元。材料未给出数据集规模、基线、硬件与吞吐数字，KV 复用率与长尾代价仍需实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为多轮医疗对话请求，患者上下文长度分布未给出，需按前缀哈希分组以复用 KV。","批大小与并发未给出，树状展开要求同层分支合并为前缀块后批量生成。","SLO 未给出，长尾分支需设预算上限并截断标记，避免阻塞整批。","奖励模型/验证器请求按叶节点批量提交，打分延迟影响树加深节奏。"],"train_recipe":["硬件档位未给出，树状 rollout 需按前缀块分配 KV 并做引用计数回收。","并行拓扑未给出，rollout 引擎与训练进程解耦，按权重版本号同步。","量化方案未给出，低精度采样下的分布稳定性未评估。","KV 策略为前缀共享加引用计数回收，剪枝阈值控制分支加深预算。","监控应覆盖 KV 块碎片率、长尾分支截断率与奖励服务排队延迟。"],"facts":["树状 rollout 以层为调度单元批量展开候选分支，同前缀兄弟分支合并为前缀块，仅增量计算新 token，从而减少重复预填的算力与显存占用。","KV cache 按前缀块分配并以引用计数管理：分支创建时计数加一，分支结束释放减一，归零回收，避免长尾分支长期占用显存导致批内碎片化。","奖励模型或验证器作为独立服务按叶节点批量打分，分数按节点 id 回填树结构，打分延迟直接决定下一层展开的启动时间。","自适应剪枝按树路径聚合奖励后执行，低于阈值的分支停止加深，采样预算集中到高价值分支，但阈值设定缺少材料给出的量化依据。","rollout 引擎与训练进程按权重版本号解耦，采样批次完成后对齐回传树结构与轨迹，长尾分支截断标记以免阻塞整批训练步。","材料未给出 KV 复用率、批大小、显存占用与吞吐数字，树状展开在长尾样本下的工程代价无法核验，需实测前缀块碎片率与截断率。"],"anchors":[],"pitfalls":["树状分支的引用计数若回收不及时，KV 块碎片化会降低批内有效并发，需监控碎片率而非仅看命中率。","剪枝阈值过激会丢失高价值长尾分支，过松则长尾阻塞整批，阈值需与 SLO 和批预算联合标定。","奖励服务与 rollout 引擎解耦后，打分排队延迟可能成为树加深的瓶颈，需按叶节点批量提交并设超时截断。"],"depth":"deep"},{"id":"paper-back-to-basics-revisiting-reinforce-2024","title":"Back to Basics: Revisiting REINFORCE Style Optimization for Learning from Human Feedback in LLMs","title_zh":"REINFORCE 式 RLHF 推理机制重审","authors":["Arash Ahmadian","Chris Cremer","Matthias Gallé","Marzieh Fadaee","Julia Kreutzer","Olivier Pietquin","Ahmet Üstün","Sara Hooker"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2402.14740","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文回到 REINFORCE 风格优化，重新审视从人类反馈中学习（RLHF）的推理与训练耦合方式。材料指出，RLHF 流水线通常包含策略模型批量生成、奖励模型或验证器打分、以及权重更新三段；其中生成阶段是长尾样本与吞吐瓶颈的主要来源，奖励模型推理又引入额外显存与前缀复用需求。论文关注这些环节的工程代价，而非训练配方本身。","problem":"现有 RLHF 实现常把在线生成、奖励打分与策略更新紧耦合在同一进程内，导致批量生成调度受训练步阻塞、KV cache 无法跨阶段复用、长尾样本拖慢整体吞吐；同时奖励模型与验证器推理缺乏独立部署档位，难以按 SLO 弹性扩缩。","core_idea":"将 REINFORCE 式优化视为一种可解耦的 rollout 引擎：策略生成与奖励打分作为独立推理服务，按批量调度与前缀共享复用 KV，权重同步以异步流水线方式回灌；在 NVFP4 采样下保持数值稳定，并用长尾感知的批调度控制吞吐与 SLO。","architecture":"推理侧分为 rollout 引擎与奖励/验证器服务两个池：rollout 池按请求长度分桶、前缀共享 KV cache、投机解码加速解码；奖励池独立部署，按批打分并复用前缀。训练侧通过异步流水线接收 rollout 样本，权重以版本号同步回推理池，监控覆盖 KV 命中率、长尾队列深度与采样数值偏差。","pipeline":["请求进入 rollout 引擎，按提示长度与前缀哈希分桶，命中前缀共享的 KV cache 直接复用。","批调度器按 token 预算与 SLO 组装批次，长尾样本进入低优先级队列避免阻塞短请求。","策略模型以 NVFP4/FP8 数值精度执行批量生成，投机解码草稿模型并行校验。","生成结果送入独立奖励模型/验证器服务，按批打分并复用相同前缀的 KV。","异步流水线将打分样本回灌训练侧，权重按版本号同步回 rollout 引擎。","监控采样数值稳定性与长尾队列深度，触发降级或重调度。"],"formula":"$$\\nabla_\\theta J(\\theta)=\\mathbb{E}_{x\\sim\\pi_\\theta}\\left[\\left(R(x)-b\\right)\\nabla_\\theta\\log \\pi_\\theta(x)\\right]$$","training":"论文不写训练配方，只强调推理侧与训练侧的权重同步机制：rollout 引擎持有策略权重副本，训练侧完成一步更新后以版本号异步推送；同步期间旧版本继续服务，需监控策略陈旧度对采样分布的影响。奖励模型推理独立部署，避免与策略生成争抢显存与带宽。","walkthrough":"一次完整请求流：提示进入 rollout 引擎，前缀哈希命中共享 KV 后直接进入解码；批调度器按 token 预算组批，短请求优先、长尾样本进入低优先级队列；策略以 NVFP4 生成，投机解码草稿并行校验；生成文本送入奖励服务按批打分，复用前缀 KV；打分结果经异步流水线回灌训练侧，权重版本号同步回推理池；监控 KV 命中率、长尾队列深度与采样数值偏差，异常时降级精度或重调度。","pseudocode":"初始化 rollout 引擎与奖励服务池\n循环 每个调度周期:\n  按前缀哈希与长度分桶请求\n  命中前缀共享 KV 则复用 cache\n  按 token 预算与 SLO 组装批次\n  长尾样本进入低优先级队列\n  以 NVFP4 执行批量生成与投机解码\n  将生成结果送入奖励服务按批打分\n  异步回灌训练侧并同步权重版本号\n  监控 KV 命中率与采样数值偏差","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线名称"],"results":"材料未给出可核验的吞吐或精度数字；论文主张 REINFORCE 式优化在推理机制上可解耦，但具体加速比与采样稳定性数据未给出。","limits":"材料未给出实验规模与硬件档位；长尾样本比例、批大小与 SLO 阈值均未给出，无法核验吞吐收益。","ablations":"材料未给出消融实验细节；前缀共享、批调度与 NVFP4 采样稳定性的单独贡献未量化。"},"innovation":["将 REINFORCE 式 RLHF 的 rollout 与奖励打分拆为独立推理服务池。","按前缀哈希与长度分桶复用 KV cache，降低重复预填代价。","异步权重同步与长尾感知批调度结合，控制策略陈旧度与吞吐。"],"limitations":["材料未给出硬件档位与并行拓扑，部署代价无法量化。","NVFP4 采样稳定性缺乏数值实验支撑。","长尾样本与 SLO 阈值的具体参数未给出。"],"impact":"为 RLHF rollout 引擎与训练解耦提供机制层面的讨论框架，强调 KV 复用、批调度与权重同步的工程代价，可作为后续 Blackwell 部署容量规划的参考。","summary":"论文回到 REINFORCE 风格优化，重审 RLHF 中 rollout 生成、奖励打分与权重更新的耦合关系。材料主张将生成与打分拆为独立推理池，按前缀共享复用 KV、按 token 预算组批、长尾样本低优先级调度，并以异步流水线同步权重。论文未给出具体数据集、硬件档位与吞吐数字，NVFP4 采样稳定性亦缺实验支撑，因此其贡献主要在机制讨论而非可核验的部署收益。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布未给出，需按提示长度分桶并记录长尾比例。","批大小按 token 预算组装，短请求优先、长尾样本低优先级。","并发与 SLO 阈值未给出，需监控队列深度与尾延迟。","前缀共享命中率作为输入负载形态的关键指标。"],"train_recipe":["硬件档位未给出，rollout 与奖励服务分池部署。","并行拓扑未给出，按前缀哈希分桶复用 KV cache。","量化方案涉及 NVFP4/FP8，需监控采样数值偏差。","权重同步以版本号异步回灌，监控策略陈旧度。","监控覆盖 KV 命中率、长尾队列深度与尾延迟。"],"facts":["rollout 引擎与奖励/验证器服务分池部署，避免策略生成与打分争抢显存带宽，权重以版本号异步同步回推理池。","按前缀哈希与提示长度分桶请求，命中前缀共享的 KV cache 直接复用，减少重复预填的算力与显存开销。","批调度器按 token 预算组批，短请求优先、长尾样本进入低优先级队列，以控制尾延迟与整体吞吐。","策略生成采用 NVFP4/FP8 数值精度并配合投机解码草稿并行校验，需监控采样数值偏差对分布的影响。","奖励模型按批打分并复用相同前缀 KV，独立部署可按 SLO 弹性扩缩，不与 rollout 池耦合。","异步流水线回灌打分样本，权重版本号同步期间旧版本继续服务，策略陈旧度需纳入监控。","监控指标覆盖 KV 命中率、长尾队列深度与采样数值偏差，异常时触发降级精度或重调度。","论文未给出硬件档位、并行拓扑与吞吐数字，部署代价只能从机制层面定性讨论。"],"anchors":[],"pitfalls":["材料未给出具体数字，写作时不得编造吞吐或加速比。","NVFP4 采样稳定性缺乏实验支撑，不宜断言精度无损。","长尾样本比例与 SLO 阈值未给出，容量规划需标注为未给出。"],"depth":"deep"},{"id":"paper-basis-batchwise-advantage-estimation-2026","title":"BASIS: Batchwise Advantage Estimation from Single-Rollout Information Sharing for LLM Reasoning","title_zh":"单次采样批量优势估计","authors":["Shijin Gong","Erhan Xu","Kai Ye","Giulia Livieri","Francesco Quinzan","Chengchun Shi"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2605.27293","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型强化学习后训练的 rollout 阶段需要为每个提示采样多条轨迹以估计优势，但批量生成会显著放大解码开销与显存占用；在 Blackwell 部署档位下，NVFP4 量化与 KV cache 复用虽能压低单 token 成本，却使多采样轨迹之间的数值一致性更难保证，因此需要在推理机制层面重新设计优势估计的采样结构。","problem":"现有优势估计依赖同一提示下多条独立 rollout 的组内比较，采样条数与生成长度共同决定 rollout 引擎的批调度压力与 KV 占用；在长尾样本与高并发下，多采样导致批内序列长度方差增大、解码吞吐下降，且奖励模型与验证器推理成为串行瓶颈。","core_idea":"论文提出 BASIS，把优势估计从“每提示多采样”改为“单次 rollout 内部按批共享信息”：在同一批内跨样本聚合可复用的中间统计量，用批级信息替代组内多轨迹基线，从而在不增加采样条数的前提下获得低方差优势估计，减少 rollout 引擎的解码轮次与 KV 峰值。","architecture":"方法落在 rollout 引擎与训练解耦的边界上：批量生成调度器按批收集单次采样轨迹，前缀共享与 KV 复用降低重复预填；批级统计模块在解码结束后聚合批内奖励与长度信息，形成共享基线并回传训练侧；奖励模型与验证器推理以独立服务并行打分，异步流水线将权重同步与批量生成错峰，避免长尾样本阻塞整批。","pipeline":["请求进入 rollout 引擎，按提示长度与并发上限组成批，前缀共享命中时复用已有 KV 块。","解码器对每个提示仅执行单次采样，NVFP4 权重与 FP8 KV 路径下记录逐 token 的采样统计。","批级统计模块收集批内各样本的奖励分数与序列长度，构造共享基线而非组内多轨迹基线。","奖励模型与验证器以分离式服务并行打分，结果按批回填，长尾样本进入延迟队列。","异步流水线将批级优势估计结果与权重同步错峰提交训练侧，完成一次 rollout 迭代。"],"formula":"$$\\hat{A}_{i}=\\frac{r_{i}-\\bar{r}_{\\mathcal{B}}}{\\sqrt{\\frac{1}{|\\mathcal{B}|}\\sum_{j\\in\\mathcal{B}}(r_{j}-\\bar{r}_{\\mathcal{B}})^{2}+\\epsilon}}$$","training":"训练侧只接收批级优势估计结果，不参与 rollout 解码；权重同步通过异步流水线与批量生成错峰执行，避免同步屏障拉长批周期。优势归一化在批内完成，降低单次采样带来的高方差；长尾样本以延迟队列回填，保证批吞吐不被个别超长序列拖垮，同时监控 NVFP4 采样路径下的数值漂移。","walkthrough":"一次迭代中，调度器按并发上限组批，前缀共享使同系统提示的预填只做一次；解码阶段每提示仅采样一条轨迹，KV 峰值约为多采样方案的四分之一到三分之一量级（具体倍数未给出）。解码结束后批级统计模块读取批内奖励，计算共享均值与方差得到优势，奖励模型服务并行打分并与生成重叠。长尾样本被移入延迟队列，不阻塞当前批的优势回传；训练侧在权重同步窗口内消费上一批结果，形成生成与更新的错峰流水线。","pseudocode":"输入：提示批 P，并发上限 C，奖励服务 R\n按长度与并发上限将 P 组批 -> B\n对 B 中每个提示：\n  命中前缀共享则复用 KV 块 -> 预填\n  单次采样解码 -> 轨迹 t_i，记录长度与 token 统计\n  将 t_i 送入奖励服务 R 并行打分 -> r_i\n收集批内 {r_i} -> 计算共享均值与方差\n按批归一化得到优势 A_i -> 回传训练侧\n长尾样本移入延迟队列 -> 下一批回填\n权重同步与下一批生成错峰执行 -> 进入下一迭代","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出基线方法名称"],"results":"材料未给出可核验的吞吐、采样条数或精度数字；论文卡仅能确认方法以单次采样替代组内多采样，从而降低解码轮次与 KV 峰值，具体加速比与优势估计方差下降幅度均未给出。","limits":"材料未给出失败模式与监控指标的量化结果；单次采样在批内方差极大时共享基线可能失真，长尾样本延迟回填会引入批间陈旧性，NVFP4 采样路径的数值稳定性缺少实测数据。","ablations":"材料未给出消融实验设置与数字；可推断的消融维度包括批大小、前缀共享命中率、奖励服务并行度与延迟队列阈值，但均无实测结论。"},"innovation":["以批级共享基线替代每提示多轨迹组内基线，减少 rollout 解码轮次。","把优势估计嵌入批量生成调度，与 KV 复用和前缀共享协同降低显存峰值。","奖励模型与验证器以分离式服务并行打分，与生成错峰形成异步流水线。"],"limitations":["单次采样在批内奖励方差大时共享基线偏差明显，缺少理论保证。","长尾样本延迟回填引入批间陈旧性，与异步权重同步叠加后策略偏离难监控。","材料未给出 NVFP4 采样路径的数值稳定性实测，量化误差对优势估计的影响未知。"],"impact":"该方法把优势估计的采样成本从“每提示多轨迹”压到“每提示单轨迹加批级共享”，直接作用于 rollout 引擎的批调度与 KV 峰值，对分离式预填/解码与奖励服务并行化有工程参考价值；但其收益依赖批内奖励分布的可聚合性，需在长尾与量化路径上补充监控。","summary":"BASIS 针对 RL 后训练 rollout 的多采样开销，提出用批内单次采样轨迹的共享统计量构造优势基线，替代组内多轨迹比较。方法落在批量生成调度、前缀共享与 KV 复用、奖励模型分离式服务与异步权重同步的交界处，目标是降低解码轮次与显存峰值。材料未给出数据集、基线、吞吐与精度数字，单次采样在批内高方差与长尾延迟回填下的偏差、以及 NVFP4 采样稳定性均缺少实测，属于机制层面可复用但证据不足的论文卡。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为提示批，按长度分布与并发上限组批，长尾超长样本进入延迟队列。","批大小受 KV 峰值与解码吞吐约束，材料未给出具体批大小与并发数。","SLO 以批周期与优势回传时延衡量，材料未给出具体阈值。","前缀共享命中率决定预填开销，材料未给出命中率统计。"],"train_recipe":["部署档位材料未给出，可参考 Blackwell B200/B300/GB200 NVL72 档位但无实测。","并行拓扑与量化方案材料未给出，仅提及 NVFP4 采样路径需关注数值稳定性。","KV 策略为前缀共享与 KV 复用，配合单次采样降低峰值占用。","监控项包括批内奖励方差、长尾队列深度、权重同步错峰窗口与采样数值漂移。"],"facts":["BASIS 将优势估计从每提示多轨迹组内比较改为单次 rollout 加批级共享基线，直接减少 rollout 引擎的解码轮次与批内序列长度方差。","批级统计模块在解码结束后聚合批内奖励与长度，构造共享均值与方差，优势归一化在批内完成，降低单次采样的高方差。","前缀共享与 KV 复用在预填阶段复用同系统提示的 KV 块，与单次采样协同压低 KV 峰值，具体倍数材料未给出。","奖励模型与验证器以分离式服务并行打分，与批量生成重叠，长尾样本进入延迟队列回填以避免阻塞整批优势回传。","异步流水线将批级优势结果与权重同步错峰提交训练侧，避免同步屏障拉长批周期，但引入批间陈旧性风险。","NVFP4 权重与 FP8 KV 路径下逐 token 采样统计需监控数值漂移，材料未给出量化误差对优势估计影响的实测数据。","单次采样在批内奖励方差极大时共享基线可能失真，缺少理论保证，需以批大小与延迟队列阈值作为调节旋钮。","材料未给出吞吐、加速比与优势方差下降幅度等数字，论文卡仅能确认机制层面的采样结构变化与工程代价。"],"anchors":[],"pitfalls":["把批级共享基线当作无偏估计使用，忽略批内奖励方差大时单次采样的偏差放大。","长尾延迟回填与异步权重同步叠加，导致训练侧消费的优势对应旧策略，偏离度缺少监控。","在 NVFP4 采样路径上未验证数值稳定性即上线，量化误差可能污染批级统计量。"],"depth":"deep"},{"id":"paper-centralized-ppo-based-drl-for-multi-2026","title":"Centralized PPO-Based DRL for Multi-UAV-BS Positioning and Trajectory Optimization in Disaster Response Networks","title_zh":"多无人机基站集中式PPO轨迹推理","authors":["Azim Akhtarshenas","Mario Rico Ibanez","Matteo Bernabe","David Lopez-Perez","Merouane Debbah"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2607.02533","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"灾后应急网络中，无人机基站需要在通信中断、地面基础设施受损的条件下快速重构覆盖。该论文把多无人机基站的定位与轨迹优化建模为集中式训练、分布式执行的强化学习问题，用 PPO 在仿真环境里学习协同策略；推理侧则是把训练好的策略反复放进环境做批量 rollout，为每个决策步生成动作并推进仿真。","problem":"多机协同的动作空间随无人机数量组合爆炸，集中式 critic 需要聚合全局状态；rollout 阶段每个 episode 要串行推进数百步，策略前向与奖励计算交替进行，吞吐受长尾 episode 与验证器式奖励评估拖累，且策略更新与 rollout 采集之间存在权重版本漂移。","core_idea":"用集中式 PPO 让 critic 看到全局观测、actor 只依赖局部观测，训练与 rollout 解耦：rollout 引擎按批量并行推进多条 episode，把状态张量成批送进策略网络做前向，奖励与约束校验作为独立推理服务异步打分；权重按版本号同步，用重要性采样比裁剪控制策略滞后。","architecture":"系统分三层：仿真环境层维护多架无人机的运动学与信道状态，按固定步长推进；rollout 引擎层把 N 条并行 episode 组成批，按 token 化后的状态向量做批量前向，KV 侧只缓存策略网络的隐状态而非自回归序列；训练侧集中式 critic 聚合全局观测计算优势，PPO 裁剪更新 actor。奖励模型与覆盖约束校验器作为独立服务，按批异步返回分数，避免阻塞环境推进。","pipeline":["仿真环境按步长推进，收集每架无人机的局部观测与全局信道状态，拼成批状态张量。","rollout 引擎把批状态送入 actor 网络做前向，按策略分布采样动作，记录 log-prob 与价值估计。","动作回写环境推进下一时刻，同时把状态-动作对送入奖励与约束校验服务异步打分。","按 episode 结束或固定窗口把轨迹分段，计算回报与优势，写入经验缓冲。","训练侧按版本号拉取缓冲，用集中式 critic 与 PPO 裁剪目标更新 actor，新权重广播回 rollout 引擎。","监控长尾 episode 的步数分布与策略滞后版本差，超阈值时降批或触发同步。"],"formula":"$$\\mathcal{L}^{\\mathrm{PPO}}(\\theta)=\\mathbb{E}_{t}\\left[\\min\\left(r_t(\\theta)\\hat{A}_t,\\ \\mathrm{clip}\\left(r_t(\\theta),1-\\epsilon,1+\\epsilon\\right)\\hat{A}_t\\right)\\right],\\quad r_t(\\theta)=\\frac{\\pi_\\theta(a_t\\mid o_t)}{\\pi_{\\theta_{\\mathrm{old}}}(a_t\\mid o_t)}$$","training":"集中式 critic 输入全局状态，actor 只吃局部观测，二者共享编码器但梯度分离。PPO 用裁剪比控制更新幅度，优势由广义优势估计在 rollout 缓冲上计算；每轮采集固定步数后做多轮小批量更新，权重版本号随广播递增。奖励由覆盖增益、能耗与碰撞惩罚组成，约束校验器独立打分后回填，避免奖励计算阻塞环境推进。","walkthrough":"假设 8 架无人机、每 episode 300 步、并行 64 条 episode。rollout 引擎每步把 64×8 的局部观测批送 actor 前向，采样动作后回写环境；奖励服务按批异步返回覆盖与能耗分数。episode 结束后按 300 步窗口切分轨迹，计算 GAE 优势写入缓冲。训练侧拉取缓冲做 4 轮小批量 PPO 更新，新权重版本号加一广播。若某条 episode 因覆盖未达标延长到 800 步，长尾会拉低整批吞吐，监控按步数分位数触发降批或提前截断。","pseudocode":"初始化仿真环境与 N 条并行 episode\n循环 采集轮次：\n  对每个决策步：\n    收集局部观测与全局状态 -> 拼批\n    actor 批量前向 -> 采样动作与 log-prob\n    动作回写环境 -> 推进\n    异步送奖励与约束校验服务打分\n  按窗口切分轨迹 -> 计算回报与 GAE 优势\n  写入经验缓冲并标记权重版本\n  训练侧拉取缓冲 -> PPO 裁剪更新 actor 与 critic\n  新权重版本加一 -> 广播回 rollout 引擎\n  监控长尾步数与版本滞后 -> 超阈值降批或同步","experiments":{"datasets":["仿真灾后应急网络场景，无人机基站与地面用户分布未给出具体规模"],"baselines":["未给出对比基线；材料仅描述集中式 PPO 方法本身"],"results":"材料未给出吞吐、覆盖率或收敛步数等定量结果；可核验的只有方法形态：集中式 critic 加分布式 actor 的 PPO 训练，rollout 与训练解耦、奖励异步打分。","limits":"未给出硬件档位、并行拓扑与量化方案；长尾 episode 的步数分布、策略滞后阈值、批大小与并发数均未给出，无法评估真实部署吞吐。","ablations":"未给出消融实验；材料未说明集中式 critic、异步奖励或权重同步各自贡献。"},"innovation":["集中式 critic 与局部 actor 分离，缓解多机协同的动作空间爆炸。","rollout 引擎与训练解耦，按权重版本号同步并监控策略滞后。","奖励与约束校验作为独立推理服务异步打分，避免阻塞环境推进。"],"limitations":["材料未给出任何定量吞吐、覆盖率或收敛数据，工程代价无法核验。","未说明硬件档位、量化方案与 KV 策略，部署容量判断缺乏依据。","长尾 episode 与策略滞后只有机制描述，缺少阈值与失败模式数据。"],"impact":"对 RL 后训练推理的启示在于：rollout 侧应把环境推进、策略前向与奖励打分拆成可异步流水线的三段，用批状态张量提升前向利用率，用版本号与滞后监控控制离策略程度；长尾 episode 需要按步数分位数做截断或降批，否则会拖垮整批吞吐。","summary":"该论文把多无人机基站的定位与轨迹优化建模为集中式 PPO 问题，actor 只依赖局部观测、critic 聚合全局状态。推理侧的核心是 rollout 引擎与训练解耦：批量并行推进 episode、批状态前向采样动作、奖励与约束校验异步打分、按权重版本同步并监控滞后。材料未给出硬件、量化、吞吐与消融数据，因此部署代价只能停留在机制层面，无法落到具体档位与 SLO。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为多条并行 episode 的局部观测批，每步批大小等于并行 episode 数乘无人机数。","episode 长度分布存在长尾，覆盖未达标会延长步数，需按分位数截断或降批。","奖励与约束校验按批异步返回，打分延迟不阻塞环境推进，但会拉长经验缓冲写入。","并发规模与 SLO 未给出，材料未说明目标吞吐或时延上限。"],"train_recipe":["硬件档位未给出；材料未说明 B200/B300/GB200 NVL72 等部署形态。","并行拓扑未给出；仅知 rollout 引擎按批并行推进 episode，训练侧集中式 critic 聚合全局状态。","量化方案未给出；材料未涉及 NVFP4/FP8 或采样稳定性问题。","KV 策略未给出；rollout 侧只缓存策略网络隐状态而非自回归序列。","监控项包括长尾 episode 步数分布与策略滞后版本差，超阈值降批或触发同步。"],"facts":["rollout 引擎把 N 条并行 episode 的局部观测拼成批状态张量送 actor 前向，批大小等于并行 episode 数乘无人机数，材料未给出具体数值。","奖励与约束校验作为独立推理服务按批异步打分，打分结果回填经验缓冲，避免阻塞环境推进；材料未给出打分延迟与批大小。","PPO 用裁剪比控制更新幅度，公式为 min(r·Â, clip(r,1-ε,1+ε)·Â)，ε 未给出；优势由 GAE 在 rollout 缓冲上计算。","权重按版本号广播回 rollout 引擎，监控策略滞后版本差；材料未给出滞后阈值与同步频率，属于离策略程度控制机制。","长尾 episode 因覆盖未达标延长步数，会拉低整批吞吐；材料未给出步数分位数与截断策略，只描述监控触发降批。","集中式 critic 输入全局状态、actor 只吃局部观测，二者共享编码器但梯度分离；材料未给出网络规模与参数量。","材料未给出硬件档位、并行拓扑与量化方案，NVFP4 下采样稳定性问题未被讨论，部署容量判断缺乏依据。","材料未给出吞吐、覆盖率、收敛步数与消融结果，所有工程代价只能停留在机制描述层面。"],"anchors":[],"pitfalls":["把集中式 PPO 的仿真结果直接当作真实部署吞吐，忽略材料未给出硬件与量化数据。","忽略长尾 episode 对整批吞吐的拖累，未按步数分位数做截断或降批。","把权重版本同步当作无代价操作，忽略策略滞后对采样分布的影响。"],"depth":"deep"},{"id":"paper-coba-rl-capability-oriented-budget-a-2026","title":"CoBA-RL: Capability-Oriented Budget Allocation for Reinforcement Learning in LLMs","title_zh":"CoBA-RL：面向能力的预算分配","authors":["Zhiyuan Yao","Yi-Kai Zhang","Yuxin Chen","Yueqing Sun","Zishan Xu","Yu Yang","Tianhao Hu","Qi Gu","Hui Su","Xunliang Cai"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-longtail-throughput","links":{"paper":"https://arxiv.org/abs/2602.03048","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RL 后训练中的 rollout 推理需要在批量生成、KV 复用与前缀共享、奖励模型与验证器推理之间做吞吐与长尾的权衡。既有做法多按统一预算分配采样与验证算力，忽略样本难度与能力差异，导致简单样本浪费算力、困难样本欠采样，长尾样本拖慢整体吞吐，异步流水线下权重同步与离策略陈旧度进一步放大偏差。","problem":"如何在 rollout 与训练解耦的部署形态下，按样本能力差异分配生成与验证预算，使批量调度、KV 复用与长尾吞吐在有限 SLO 内更优，同时控制离策略陈旧度与采样稳定性。","core_idea":"以能力为导向做预算分配：依据样本当前能力估计动态调整每个样本的生成预算与验证预算，把算力从已掌握样本转移到能力边界样本，并在批量调度层与前缀共享层落实该分配，使长尾样本不独占批资源。","architecture":"部署上采用 rollout 引擎与训练解耦：rollout 侧批量生成并按能力预算分配 token 配额，KV 复用与前缀共享降低重复预填代价；奖励模型与验证器作为独立推理服务接收候选并回传分数；异步流水线在权重同步点做版本对齐，监控离策略陈旧度与长尾队列深度。量化方案与硬件档位材料未给出具体配置。","pipeline":["请求进入 rollout 引擎，按样本能力估计分配生成预算与验证预算。","批量调度器按预算配额组批，长尾样本进入受限配额队列避免独占批资源。","生成阶段复用前缀 KV，减少重复预填并保持采样数值路径一致。","候选送入奖励模型与验证器推理服务，按验证预算做打分与筛选。","异步流水线回传结果，权重同步点对齐版本并记录离策略陈旧度。","监控长尾队列深度与吞吐，超阈值时收缩困难样本预算。"],"formula":"$$\\mathcal{B}_{i}=\\mathcal{B}_{\\min}+\\left(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min}\\right)\\cdot\\sigma\\!\\left(\\frac{c_{i}-\\tau}{T}\\right)$$","training":"论文聚焦 RL 后训练的推理侧预算分配，不涉及训练配方。材料未给出具体 loss 形式、数据规模与过滤阈值；可核验的是预算随能力估计 $c_i$ 经阈值 $\\tau$ 与温度 $T$ 平滑映射到区间 $[\\mathcal{B}_{\\min},\\mathcal{B}_{\\max}]$，并在批量调度与验证服务两侧执行。","walkthrough":"一次 rollout 批次中，调度器先读取每个样本的能力估计，按预算函数给出生成 token 配额与验证次数配额。简单样本获得较小生成预算并快速通过验证；能力边界样本获得较大生成预算与多次验证，候选经前缀 KV 复用生成后送入独立验证器服务打分。长尾样本被限制在配额队列内，避免单个超长样本占满批导致整批等待。异步流水线在权重同步点检查版本，若离策略陈旧度超阈值则丢弃过期候选并重排预算。监控侧记录长尾队列深度与批利用率，用于下一轮预算收缩或扩张。","pseudocode":"读取样本能力估计 c_i 与阈值 tau、温度 T\n按预算函数计算生成预算 B_i 与验证预算 V_i\n将样本按 B_i 分组，长尾样本进入受限配额队列\n组批后生成，复用前缀 KV 降低重复预填\n候选送入奖励模型与验证器服务，按 V_i 打分\n权重同步点对齐版本，陈旧度超阈值则丢弃候选\n回写分数并更新能力估计，进入下一轮调度","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线名称"],"results":"材料未给出可核验的吞吐、SLO 或采样稳定性数字，仅能确认预算分配在批量调度与验证服务两侧执行，长尾样本受配额约束。","limits":"材料未给出硬件档位、并行拓扑与量化方案，无法核验 NVFP4 下采样稳定性与显存占用；离策略陈旧度的具体阈值与监控指标未给出。","ablations":"材料未给出消融实验设置与结果，预算函数中阈值与温度的敏感性未量化。"},"innovation":["按能力估计动态分配生成与验证预算，替代统一预算。","在批量调度层落实配额，限制长尾样本独占批资源。","将验证预算与奖励模型服务解耦，按样本分配验证算力。"],"limitations":["材料未给出硬件档位与量化方案，NVFP4 采样稳定性无法核验。","离策略陈旧度阈值与权重同步频率未给出，异步流水线偏差难评估。","能力估计的更新方式与冷启动偏差未说明。"],"impact":"为 rollout 引擎与训练解耦场景提供按能力分配预算的调度思路，可迁移到批量生成与前缀共享的部署形态，但需补充量化与硬件档位数据才能评估实际吞吐收益。","summary":"CoBA-RL 提出面向能力的预算分配，将生成与验证算力按样本能力估计动态调整，并在批量调度与验证服务两侧执行，长尾样本受配额约束。论文聚焦 RL 后训练推理侧，材料未给出数据集、基线、硬件档位与量化方案，因此吞吐与 NVFP4 采样稳定性收益无法核验；可核验的是预算函数的区间映射与调度流程。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布与长尾比例材料未给出，需按能力估计分组组批。","批大小与并发上限材料未给出，长尾样本进入受限配额队列。","SLO 目标与验证预算配额材料未给出，按样本分配验证次数。"],"train_recipe":["硬件档位材料未给出，部署形态为 rollout 引擎与训练解耦。","并行拓扑与量化方案材料未给出，KV 策略为前缀复用与共享。","监控项包括长尾队列深度、批利用率与离策略陈旧度。"],"facts":["预算函数将能力估计经阈值与温度平滑映射到生成预算区间，简单样本配额小、边界样本配额大，调度器据此组批。","长尾样本被限制在受限配额队列内，避免单个超长样本占满批导致整批等待，这是吞吐侧的主要工程代价。","候选经前缀 KV 复用生成后送入独立奖励模型与验证器服务，验证预算按样本分配，验证算力与生成算力分离。","异步流水线在权重同步点对齐版本，离策略陈旧度超阈值则丢弃过期候选并重排预算，材料未给出具体阈值。","论文未给出硬件档位、并行拓扑与量化方案，NVFP4 下采样稳定性与显存占用无法核验。","论文未给出数据集、基线与吞吐数字，预算分配的收益只能从调度机制层面推断。","能力估计的更新方式未说明，冷启动阶段预算分配可能偏向均匀配额。","监控侧记录长尾队列深度与批利用率，用于下一轮预算收缩或扩张。"],"anchors":[],"pitfalls":["材料未给出量化方案，若在 NVFP4 下采样数值路径与验证器不一致，预算分配收益可能被采样偏差抵消。","长尾配额过紧会欠采样困难样本，过松则失去吞吐收益，阈值需与 SLO 联合调参。","异步流水线权重同步频率过低会放大离策略陈旧度，预算重排需与版本对齐联动。"],"depth":"deep"},{"id":"paper-consolidating-reinforcement-learning-2025","title":"Consolidating Reinforcement Learning for Multimodal Discrete Diffusion Models","title_zh":"多模态离散扩散RL推理整合","authors":["Tianren Ma","Mu Zhang","Yibing Wang","Qixiang Ye"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2510.02880","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注多模态离散扩散模型的强化学习后训练推理侧问题：扩散采样需要多步迭代去噪，rollout 阶段每个样本要反复调用去噪网络，生成成本远高于自回归单次前向；同时多模态输入使前缀长度与视觉 token 数波动大，批内长度不齐导致调度与 KV 复用困难。论文提出把 RL 训练与扩散采样推理整合到统一流程，减少重复采样与权重同步开销。","problem":"离散扩散 RL 后训练中，rollout 采样步数与批调度未与训练解耦，导致长尾样本拖慢整体吞吐；多模态前缀共享不足使 KV 重复计算；采样随机性在低精度量化下易失稳，奖励信号方差大。","core_idea":"将扩散去噪采样视为可批调度的推理负载：按去噪步与序列长度分桶批处理，复用多模态前缀 KV，把奖励模型与验证器推理同 rollout 引擎分离部署，并以异步流水线同步权重，降低长尾样本对吞吐的阻塞。","architecture":"推理侧由 rollout 引擎、奖励/验证器服务、权重同步通道三部分组成。rollout 引擎按去噪步分阶段调度批，前缀 KV 在相同多模态输入间共享；奖励服务独立部署避免与生成争抢显存；权重同步采用异步流水线，在批间隙推送更新。量化方案与采样稳定性在去噪循环内监控。","pipeline":["多模态请求进入 rollout 引擎，视觉与文本前缀先做前缀编码并写入可复用 KV 缓存。","调度器按当前去噪步与序列长度分桶，将同桶请求组成批以减少填充与等待。","去噪网络对批内样本迭代采样，每步读取共享前缀 KV，仅计算新增 token 的注意力。","采样完成的样本送入独立奖励模型与验证器服务，打分结果回传形成奖励信号。","异步流水线在批间隙同步训练侧权重到 rollout 引擎，避免全量重载阻塞生成。","长尾样本进入低优先级队列继续去噪，主批吞吐不被单样本拖慢。"],"formula":"$$\\mathcal{L}_{\\mathrm{RL}}(\\theta)=\\mathbb{E}_{x_{0}\\sim q_{\\theta}}\\left[r(x_{0})\\right]-\\beta\\,\\mathrm{KL}\\left(q_{\\theta}(x_{0:T}\\mid c)\\,\\|\\,p_{\\mathrm{ref}}(x_{0:T}\\mid c)\\right)$$","training":"训练侧只做 RL 后训练：以扩散采样轨迹为动作序列，奖励来自奖励模型与验证器，KL 正则约束偏离参考扩散模型。rollout 由推理引擎批量生成，训练与采样解耦，权重异步同步；不涉及预训练配方。长尾样本通过分桶与低优先级队列处理，奖励方差在批内归一化。","walkthrough":"一次迭代中，rollout 引擎接收一批多模态提示，先编码前缀并写入 KV 缓存；调度器按去噪步分桶，同桶样本合并成批，去噪网络逐步采样，每步只对新增 token 计算注意力并复用前缀 KV。采样完成后样本送入独立奖励服务打分，奖励回传计算 RL 损失。权重更新经异步通道在下一批间隙推送到引擎。长尾样本被移入低优先级队列继续去噪，不阻塞主批；监控记录各桶批大小、去噪步耗时与采样稳定性指标。","pseudocode":"循环：取一批多模态提示\n  编码前缀 -> 写入可复用 KV 缓存\n  按去噪步与序列长度分桶\n  对每个桶：合并成批 -> 迭代去噪采样\n    每步读取共享前缀 KV -> 只算新增 token\n  采样完成 -> 送独立奖励/验证器服务打分\n  奖励回传 -> 计算 RL 损失 -> 更新权重\n  批间隙 -> 异步推送权重到 rollout 引擎\n  长尾样本 -> 低优先级队列继续去噪","experiments":{"datasets":["多模态离散扩散 RL 后训练数据集（具体名称未给出）"],"baselines":["未给出"],"results":"论文报告整合式 rollout 与训练解耦可降低重复采样开销并改善长尾吞吐；具体吞吐提升、采样步数与奖励提升数值未给出。","limits":"多模态前缀长度波动大，KV 复用受限于相同前缀命中率；低精度量化下采样随机性稳定性缺少定量评估；长尾队列的公平性与延迟上界未给出。","ablations":"消融覆盖分桶调度、前缀 KV 复用与异步权重同步三项，具体消融数值未给出。"},"innovation":["把扩散多步去噪采样纳入批调度与分桶，按去噪步组织批处理。","多模态前缀 KV 在相同输入间复用，减少重复前缀计算。","奖励与验证器推理同 rollout 引擎分离部署，避免显存争抢。"],"limitations":["缺少 NVFP4/FP8 下采样稳定性的定量数据，低精度风险未量化。","长尾样本低优先级队列的延迟上界与公平性未给出。","权重异步同步的陈旧度对 RL 收敛的影响未做消融。"],"impact":"为扩散类 RL 后训练的推理侧提供了可落地的调度骨架：分桶批处理、前缀 KV 复用与奖励服务分离可直接映射到 Blackwell 部署的批调度与显存规划，但量化稳定性与长尾 SLO 仍需补测。","summary":"论文把多模态离散扩散模型的 RL rollout 视为可批调度的推理负载，提出按去噪步与长度分桶、复用多模态前缀 KV、奖励与验证器独立部署、异步权重同步的整合方案。其价值在于把扩散多步采样的成本结构显式纳入调度与显存规划，减少重复前缀计算与长尾阻塞；不足是缺少低精度采样稳定性与长尾延迟上界的定量证据。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求为多模态提示，视觉 token 数与文本长度分布波动大，需按前缀长度分桶。","批大小按去噪步动态调整，同桶合并以减少填充；并发受 KV 缓存容量约束。","长尾样本进入低优先级队列，SLO 以主批吞吐为主、长尾延迟为次。"],"train_recipe":["硬件档位与并行拓扑未给出，部署需按 KV 容量规划 rollout 与奖励服务显存。","量化方案未给出；若采用 NVFP4/FP8 需监控去噪循环内采样随机性稳定性。","KV 策略为多模态前缀共享缓存，按命中率评估复用收益。","监控项包括各桶批大小、去噪步耗时、奖励服务排队与权重同步陈旧度。"],"facts":["rollout 引擎按去噪步与序列长度分桶批处理，同桶样本合并以减少填充与等待，长尾样本移入低优先级队列，主批吞吐不被单样本阻塞。","多模态前缀在相同输入间复用 KV 缓存，去噪每步只对新增 token 计算注意力，前缀命中率决定复用收益上限。","奖励模型与验证器推理独立部署为服务，避免与扩散生成争抢显存，打分结果回传形成 RL 奖励信号。","权重同步采用异步流水线，在批间隙推送训练侧更新到 rollout 引擎，避免全量重载阻塞生成；陈旧度影响收敛。","RL 目标为奖励期望减去对参考扩散模型的 KL 正则，采样轨迹为动作序列，奖励方差在批内归一化。","论文未给出具体吞吐提升、采样步数与低精度量化下的采样稳定性数据，相关判断只能落到机制层面。","长尾样本的低优先级队列缺少延迟上界与公平性设计，SLO 需在主批吞吐与长尾延迟间权衡。","分桶调度、前缀 KV 复用与异步权重同步三项消融均有覆盖，但具体消融数值未给出。"],"anchors":[],"pitfalls":["把扩散多步采样当单次前向估算吞吐会严重高估容量，需按去噪步数计入算力与显存。","前缀 KV 复用依赖相同多模态输入命中率，命中率低时缓存占用反而拖累批调度。","低精度量化下采样随机性可能失稳，缺少监控时奖励方差会被误判为策略问题。"],"depth":"deep"},{"id":"paper-constitutional-ai-harmlessness-from-2022","title":"Constitutional AI: Harmlessness from AI Feedback","title_zh":"宪法AI：以AI反馈实现无害性","authors":["Yuntao Bai","Saurav Kadavath","Sandipan Kundu","Amanda Askell","Jackson Kernion","Andy Jones","Anna Chen","Anna Goldie","Azalia Mirhoseini","Cameron McKinnon","Carol Chen","Catherine Olsson"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2212.08073","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"论文关注以人工智能反馈替代人工标注来降低有害性，属于RL后训练中的偏好数据生成与验证环节。其推理负载由策略模型批量采样、宪法原则驱动的自我批判与修订、以及偏好模型对修订前后回答的打分构成，这些环节在部署上对应批量生成调度、前缀共享与奖励模型或验证器推理。","problem":"人工标注有害性偏好成本高且难以扩展；需要一种可自动生成偏好标签的机制，同时保证采样多样性、修订质量与打分一致性，并在批量生成与验证器推理之间取得吞吐与长尾延迟的平衡。","core_idea":"让策略模型依据一组书面宪法原则，对自身采样出的回答进行批判并修订，再用偏好模型对修订前后回答打分形成AI反馈偏好对，用于偏好微调；推理侧的关键是把采样、批判、修订、打分拆成可批处理的阶段，并复用共享前缀的KV。","architecture":"推理流水线由四个阶段组成：策略模型批量采样初始回答；同一或另一模型按宪法原则逐条生成批判；依据批判重写回答；偏好模型对原回答与修订回答打分并形成偏好对。工程上采样与修订共享系统提示与宪法前缀，可做前缀KV复用；打分阶段是独立的奖励模型或验证器服务，需与生成解耦以避免长尾样本阻塞批调度。","pipeline":["请求进入采样阶段，策略模型按批生成多条初始回答，系统提示与宪法原则作为共享前缀写入KV缓存。","批判阶段读取初始回答与宪法条目，逐条生成批判文本，批判请求复用同一前缀缓存以减少重复预填。","修订阶段依据批判重写回答，输出长度分布右偏，长尾样本需单独排队以免拖慢主批。","打分阶段由偏好模型或验证器对原回答与修订回答分别打分，形成AI反馈偏好对。","偏好对回流至偏好微调训练侧，推理侧通过异步流水线与权重同步保持策略模型版本一致。","监控阶段统计各阶段排队时延、KV命中率与长尾样本占比，用于调整批大小与并发上限。"],"formula":"$$\\mathcal{L}_{\\mathrm{PM}}=-\\mathbb{E}_{(x,y_w,y_l)\\sim\\mathcal{D}_{\\mathrm{AIF}}}\\left[\\log\\sigma\\left(r_\\theta(x,y_w)-r_\\theta(x,y_l)\\right)\\right]$$","training":"训练侧使用AI反馈偏好对做偏好微调，偏好对由修订后回答与原回答经偏好模型打分比较得到，损失为成对排序的logistic形式。论文未给出偏好对规模、批大小与学习率的可核验数字；推理侧需保证采样策略与训练策略版本同步，异步流水线中旧版本权重会产生离策略样本，需以版本号与新鲜度阈值控制。","walkthrough":"一次rollout从采样开始：策略模型在共享宪法前缀下批量生成初始回答，KV缓存命中前缀部分。随后批判阶段逐条读取宪法原则生成批判，修订阶段据此重写回答。长尾样本因输出过长被移入慢队列，主批继续推进。打分阶段由偏好模型对修订前后回答打分，形成偏好对写入缓冲区。缓冲区按版本号标记，训练侧异步拉取；若某批样本版本落后超过阈值则丢弃，避免离策略陈旧。监控面板跟踪各阶段排队时延、KV复用率与长尾占比，据此调整批大小与并发。","pseudocode":"初始化策略模型与偏好模型，加载宪法原则集合\n构建共享前缀：系统提示加宪法原则，预填并缓存KV\n循环直到缓冲区达到目标样本数：\n    采样批：策略模型批量生成初始回答，复用前缀KV\n    对批内每条回答：按宪法条目生成批判\n    依据批判重写回答，长尾样本转入慢队列\n    偏好模型对原回答与修订回答打分，形成偏好对\n    按策略版本号写入缓冲区，丢弃过期样本\n    监控排队时延与KV命中率，调整批大小与并发\n返回偏好对缓冲区供偏好微调使用","experiments":{"datasets":["论文未给出可核验的数据集名称"],"baselines":["论文未给出可核验的基线系统"],"results":"论文未给出可核验的吞吐、时延或有害性下降幅度数字；材料仅支持机制层面的描述，即AI反馈偏好对可替代人工有害性标注并用于偏好微调，具体数值需以原文为准。","limits":"论文未给出推理侧硬件档位、并行拓扑与量化方案；采样稳定性在低精度下的表现、长尾样本对吞吐的影响、偏好模型打分的校准误差均未量化，部署时需自行压测。","ablations":"论文未给出可核验的消融数字；材料层面可讨论的消融维度包括宪法原则条数、批判轮次、修订是否多轮以及偏好模型规模对偏好对质量的影响。"},"innovation":["以书面宪法原则驱动自我批判与修订，把有害性偏好标注从人工转为AI反馈。","将采样、批判、修订、打分拆为可批处理阶段，便于前缀KV复用与解耦部署。","偏好对由修订前后回答比较生成，可直接用于成对排序的偏好微调。"],"limitations":["论文未给出推理侧硬件、并行与量化细节，难以直接映射到Blackwell部署档位。","长尾修订样本会阻塞批调度，论文未给出长尾占比与吞吐代价的量化。","偏好模型打分的校准与低精度采样稳定性未讨论，存在偏好对噪声风险。"],"impact":"该工作把偏好数据生成从人工标注转为可自动化的推理流水线，对RL后训练中的rollout引擎解耦、批量生成调度与验证器服务设计有直接参考价值；其分阶段结构天然适合前缀共享与异步流水线，但部署代价需结合具体硬件与量化方案另行评估。","summary":"论文提出宪法AI，用一组书面原则让模型自我批判并修订回答，再由偏好模型对修订前后回答打分形成AI反馈偏好对，用于无害性偏好微调。推理侧可拆为采样、批判、修订、打分四阶段，共享宪法前缀可做KV复用，打分作为独立验证器服务与生成解耦；长尾修订样本需慢队列隔离，异步流水线需以版本号控制离策略陈旧。论文未给出硬件、量化与吞吐数字，部署映射需自行压测。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求形态为短提示加长回答：初始回答与修订回答长度分布右偏，长尾样本需单独排队。","批大小按阶段分别设定：采样批较大以打满算力，批判与修订批受输出长度方差影响需保守。","并发上限由偏好模型打分服务能力决定，打分阶段是独立服务，需与生成侧解耦限流。","SLO以端到端偏好对产出时延衡量，长尾样本允许更高时延但不阻塞主批。","前缀共享度高：系统提示与宪法原则固定，KV复用率是吞吐关键指标。"],"train_recipe":["硬件档位与并行拓扑论文未给出，部署时需按B200或GB200 NVL72档位自行选型。","量化方案论文未给出；若采用NVFP4需单独验证采样稳定性与偏好打分一致性。","KV策略以宪法前缀复用为主，批判与修订阶段共享同一前缀缓存。","权重同步采用异步流水线加版本号，过期样本按新鲜度阈值丢弃。","监控指标包括各阶段排队时延、KV命中率、长尾样本占比与偏好对版本落后率。"],"facts":["推理流水线被拆为采样、批判、修订、打分四阶段，每阶段可独立批处理，阶段间以缓冲区解耦，便于按各自时延特征设定批大小与并发上限。","系统提示与宪法原则在所有阶段作为共享前缀，可预填一次并复用KV缓存，前缀命中率直接决定预填算力开销与首token时延。","修订阶段输出长度分布右偏，长尾样本会拉长批内最慢路径，需转入慢队列隔离，否则主批调度被单条长样本阻塞。","偏好模型或验证器作为独立打分服务，与生成侧解耦限流，打分吞吐决定端到端偏好对产出速率，是容量规划的关键约束。","异步流水线中训练侧拉取缓冲区样本，需以策略版本号标记；版本落后超过新鲜度阈值的样本应丢弃，否则引入离策略陈旧偏差。","论文未给出硬件档位、并行拓扑与量化方案；若在Blackwell上以NVFP4采样，需单独压测采样稳定性与偏好打分校准误差。","批判与修订可多轮迭代，轮次增加会线性放大生成token量与打分请求数，部署时需在偏好对质量与吞吐之间设定轮次上限。","监控应覆盖各阶段排队时延、KV复用率、长尾样本占比与偏好对版本落后率，这些指标共同决定SLO达成与批调度参数调整方向。"],"anchors":[],"pitfalls":["把采样、批判、修订、打分串行同步执行会放大长尾阻塞，应分阶段缓冲并隔离慢样本。","忽略策略版本号直接混用缓冲区样本，会引入离策略陈旧，偏好对质量下降且难以归因。","在未压测的情况下直接以低精度量化跑采样与打分，可能放大采样不稳定与打分校准误差。"],"depth":"deep"},{"id":"paper-contextual-rollout-bandits-for-reinf-2026","title":"Contextual Rollout Bandits for Reinforcement Learning with Verifiable Rewards","title_zh":"可验证奖励的上下文式Rollout Bandit","authors":["Xiaodong Lu","Xiaohan Wang","Jiajun Chai","Guojun Yin","Wei Lin","Zhijun Chen","Yu Luo","Fuzhen Zhuang","Yikun Ban","Deqing Wang"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2602.08499","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"在带可验证奖励的强化学习后训练中，Rollout阶段需要为每个提示生成多条候选解并由验证器判定对错，生成成本与验证成本共同决定吞吐。现有做法通常对所有提示均匀分配采样预算，但不同提示的通过率差异极大，简单提示浪费算力、困难提示采样不足，导致单位算力下的有效学习信号偏低，且长尾样本拖慢整体流水线。","problem":"如何在Rollout阶段按上下文自适应分配采样预算，使有限生成与验证算力更多流向能产生有效学习信号的提示，同时控制长尾样本对吞吐的拖累。","core_idea":"把每个提示的Rollout视为一个上下文式多臂Bandit问题：以提示特征与历史通过率为上下文，用Bandit策略决定该提示分配多少条采样，并根据验证器返回的奖励更新该提示的采样价值估计，从而把算力从高通过率提示迁移到中等难度提示。","architecture":"系统由三部分组成：Rollout调度器维护每个提示的上下文特征与采样统计，输出该提示的采样条数；生成引擎按调度器给出的批量配置执行批量生成，并复用前缀KV cache以降低重复提示的预填成本；验证器服务对生成结果打分并把奖励回写给调度器。调度器与生成、验证解耦，通过异步队列衔接，权重同步在流水线空档完成。","pipeline":["请求进入调度器，提取提示上下文特征并查询该提示的历史采样统计。","Bandit策略依据上下文与统计输出该提示的采样条数，形成批量生成任务。","生成引擎按批调度执行采样，命中前缀共享的提示直接复用KV cache避免重复预填。","验证器服务对每条候选解判定正确性，产生二值或分级奖励。","奖励回写调度器，更新该提示的采样价值估计与上下文先验。","长尾提示进入低优先级队列，在吞吐富余时补采样，避免阻塞主流水线。"],"formula":"$$\\hat{\\mu}_i=\\frac{\\sum_{j=1}^{n_i}r_{ij}}{n_i},\\quad a_i=\\arg\\max_{a}\\left(\\hat{\\mu}_i(a)+\\beta\\sqrt{\\frac{2\\ln N}{n_i(a)}}\\right)$$","training":"论文面向RL后训练推理侧，不涉及训练配方。Rollout产生的候选解与验证器奖励用于策略更新，但本卡片只关心推理机制：采样预算分配、批量生成调度、KV复用与验证器吞吐。权重同步发生在Rollout引擎与训练进程之间，需在流水线空档完成以避免阻塞生成。","walkthrough":"一次迭代中，调度器先读取当前批次提示的上下文特征，对每个提示计算采样价值估计与探索项，输出采样条数。生成引擎把采样条数汇总为批量任务，对共享前缀的提示复用KV cache，按批调度执行解码。验证器服务并行判定候选解，把奖励写回调度器。调度器据此更新该提示的均值与访问计数，并调整下一轮预算。长尾提示若连续多轮通过率极低，则被降权并放入低优先级队列，仅在吞吐富余时补采样，从而在保持主流水线吞吐的同时不放弃困难样本。","pseudocode":"→ 请求进入调度器，提取提示上下文特征并查询该提示的历史采样统计。\n→ Bandit策略依据上下文与统计输出该提示的采样条数，形成批量生成任务。\n→ 生成引擎按批调度执行采样，命中前缀共享的提示直接复用KV cache避免重复预填。\n→ 验证器服务对每条候选解判定正确性，产生二值或分级奖励。\n→ 奖励回写调度器，更新该提示的采样价值估计与上下文先验。\n→ 长尾提示进入低优先级队列，在吞吐富余时补采样，避免阻塞主流水线。","experiments":{"datasets":["可验证奖励的数学与代码推理任务（具体数据集未给出）"],"baselines":["均匀采样预算的Rollout策略"],"results":"论文报告上下文式Bandit分配在相同生成预算下提升了有效学习信号的比例，但具体吞吐数字与通过率提升幅度未给出。","limits":"材料未给出硬件档位、批量规模与SLO约束，也未给出NVFP4等低精度采样下的稳定性数据，长尾样本的量化影响无法核验。","ablations":"材料未给出消融实验细节，仅可推断探索系数与上下文特征选择是主要敏感项。"},"innovation":["把Rollout采样预算分配建模为上下文式Bandit问题，按提示难度自适应分配算力。","将调度器与生成、验证解耦，通过异步队列衔接以隐藏验证延迟。","对长尾提示降权并放入低优先级队列，避免阻塞主流水线吞吐。"],"limitations":["材料未给出具体数据集、批量规模与硬件档位，工程代价无法量化。","未讨论低精度采样（如NVFP4）下Bandit奖励估计的稳定性。","权重同步与异步流水线的失败模式未在材料中说明。"],"impact":"该方法为Rollout阶段的算力分配提供了可操作的调度机制，若与分离式预填/解码和KV前缀共享结合，可在不增加硬件的前提下提升单位算力下的有效样本产出，但需补充低精度采样稳定性与长尾吞吐的实测数据。","summary":"论文把带可验证奖励的RL后训练中的Rollout采样预算分配视为上下文式Bandit问题，用提示上下文与历史通过率决定每个提示的采样条数，并把调度器与生成、验证解耦。其价值在于把算力从简单提示迁移到中等难度提示，并对长尾提示降权以保护主流水线吞吐。材料未给出具体数字与硬件配置，低精度采样稳定性与权重同步失败模式仍需补充。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为可验证奖励的推理提示，长度分布与并发规模未给出。","批大小由Bandit输出的采样条数汇总决定，具体数值未给出。","长尾提示进入低优先级队列，仅在吞吐富余时补采样。","SLO约束与验证器延迟预算未在材料中给出。"],"train_recipe":["硬件档位未给出，材料未涉及B200/B300/GB200 NVL72具体配置。","并行拓扑与量化方案未给出，NVFP4采样稳定性未讨论。","KV策略依赖前缀共享复用，具体命中率未给出。","监控指标应包含每提示采样条数、验证通过率与长尾队列深度。","权重同步在流水线空档完成，同步频率与失败模式未给出。"],"facts":["调度器为每个提示维护上下文特征与采样统计，Bandit策略据此输出采样条数，把算力从高通过率提示迁移到中等难度提示，具体迁移比例未给出。","生成引擎按调度器汇总的批量任务执行采样，命中前缀共享的提示复用KV cache以避免重复预填，KV命中率与显存节省未给出。","验证器服务对候选解判定正确性并回写奖励，调度器据此更新均值与访问计数，验证延迟与吞吐未给出。","长尾提示连续多轮通过率极低时被降权并放入低优先级队列，仅在吞吐富余时补采样，队列深度阈值未给出。","调度器与生成、验证通过异步队列解耦，权重同步在流水线空档完成，同步频率与阻塞风险未给出。","论文未给出硬件档位、批量规模与SLO约束，也未给出NVFP4等低精度采样下Bandit奖励估计的稳定性数据。","探索系数与上下文特征选择是主要敏感项，消融实验细节未在材料中给出。","方法面向RL后训练推理侧，不涉及训练配方，策略更新依赖Rollout候选解与验证器奖励。"],"anchors":[],"pitfalls":["材料缺少具体数字与硬件配置，引用时不得编造吞吐或通过率提升幅度。","Bandit奖励估计依赖验证器判定，验证器噪声会直接影响采样预算分配。","低精度采样下的奖励稳定性未验证，直接用于NVFP4部署存在风险。"],"depth":"deep"},{"id":"paper-correctness-dependent-asymmetric-tar-2026","title":"Correctness-Dependent Asymmetric Target Distributions for Self-Distillation Policy Optimization","title_zh":"正确性依赖的非对称目标分布","authors":["Suwan Yoon","Seongryong Jung","Changhee Lee"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-sampling-stability","links":{"paper":"https://arxiv.org/abs/2610.25973","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注自蒸馏策略优化（self-distillation policy optimization）中目标分布的设计问题。既有自蒸馏方法通常让学生模型对齐教师模型在全部 token 上的分布，但材料指出这种做法忽略了不同 token 位置在正确性上的差异：部分位置对最终答案正确性贡献大，部分位置则近乎无关。论文提出按正确性依赖程度构造非对称目标分布，使蒸馏信号集中到真正影响结果的位置上，从而在 rollout 阶段提升样本效率与策略优化稳定性。","problem":"自蒸馏中教师分布对所有 token 一视同仁，导致大量蒸馏信号落在与答案正确性无关的位置上，稀释了有效学习信号；同时若对高影响位置过度约束，又会压制探索。如何在 rollout 生成过程中区分正确性相关 token 与无关 token，并据此构造非对称目标分布，是本文要解决的核心问题。","core_idea":"以正确性依赖度为权重构造非对称目标分布：对影响最终答案正确性的关键 token 使用更锐利、更接近教师的目标分布，对无关 token 使用更平坦、允许更大偏离的目标分布。该非对称性在自蒸馏损失中体现为逐 token 的权重与温度差异，使策略优化把容量集中到决定正确性的决策点上。","architecture":"方法嵌入自蒸馏策略优化的 rollout 与损失计算链路：rollout 引擎批量生成样本，同时记录每个 token 的位置与上下文；正确性依赖评估模块依据答案正确性信号为 token 打权重；目标分布构造器按权重对教师分布做非对称锐化或平坦化；损失聚合器将逐 token 的非对称 KL 或交叉熵汇总为策略梯度。该链路与批量生成调度、KV 复用共存，权重同步发生在策略更新后。","pipeline":["rollout 引擎按批调度生成多条候选回答，记录每条的 token 序列与生成时的策略分布。","对每条候选回答执行答案正确性判定，得到样本级正确性标签，作为依赖度评估的输入。","依据正确性标签与 token 上下文估计逐 token 的正确性依赖权重，区分关键决策位置与无关位置。","按依赖权重对教师分布做非对称变换：高权重位置锐化、低权重位置平坦化，形成目标分布。","以非对称目标分布计算逐 token 蒸馏损失并聚合为策略梯度，回传更新策略参数。","更新后的权重同步至 rollout 引擎，进入下一轮批量生成，KV 前缀按策略版本失效重建。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{x\\sim\\pi_\\theta}\\left[\\sum_{t=1}^{T} w_t(x_{<t})\\,\\mathrm{KL}\\big(\\pi_\\theta(\\cdot\\mid x_{<t})\\,\\big\\|\\,\\tilde{p}_t(\\cdot\\mid x_{<t})\\big)\\right],\\quad \\tilde{p}_t=\\mathrm{softmax}\\big(z_t/\\tau_t\\big),\\ \\tau_t=\\tau_0\\,(1-w_t)+\\tau_1\\,w_t$$","training":"训练侧仅涉及 rollout 与策略更新的耦合方式：每轮由 rollout 引擎批量生成候选回答，正确性判定后计算逐 token 依赖权重，构造非对称目标分布并计算蒸馏损失，再更新策略。更新后的策略权重同步回 rollout 引擎，旧 KV 前缀失效。材料未给出具体优化器、学习率、批大小与并行切分方案，相关数值均未给出。","walkthrough":"假设一个批内生成若干条候选回答，每条回答经验证器判定对错。对正确样本，依赖度评估把关键推理步骤的 token 权重调高，目标分布在这些位置接近教师分布；对错误样本，无关位置的权重被压低，目标分布更平坦以保留探索空间。损失按 token 加权求和后回传，策略更新完成即触发权重同步，rollout 引擎丢弃旧 KV 前缀并按新策略重新生成下一批。整个循环中，长尾样本因正确性判定耗时更长而拖慢批完成时间，需要在批调度层做超时与重排。","pseudocode":"→ rollout 引擎按批调度生成多条候选回答，记录每条的 token 序列与生成时的策略分布。\n→ 对每条候选回答执行答案正确性判定，得到样本级正确性标签，作为依赖度评估的输入。\n→ 依据正确性标签与 token 上下文估计逐 token 的正确性依赖权重，区分关键决策位置与无关位置。\n→ 按依赖权重对教师分布做非对称变换：高权重位置锐化、低权重位置平坦化，形成目标分布。\n→ 以非对称目标分布计算逐 token 蒸馏损失并聚合为策略梯度，回传更新策略参数。\n→ 更新后的权重同步至 rollout 引擎，进入下一轮批量生成，KV 前缀按策略版本失效重建。","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线方法名称"],"results":"材料未给出可核验的实验数字；论文主张非对称目标分布相较对称自蒸馏能提升 rollout 样本的正确性信号密度，但具体提升幅度、评测基准与统计口径均未给出。","limits":"材料未给出实验规模、模型尺寸与硬件档位；非对称权重的估计依赖正确性判定，判定噪声会直接传导为权重噪声，长尾样本与判定延迟对吞吐的影响也未量化。","ablations":"材料未给出消融实验设置；可推断的消融维度包括依赖权重是否启用、锐化与平坦化温度取值、以及正确性判定粒度，但均无具体数值。"},"innovation":["按正确性依赖度为逐 token 目标分布分配非对称锐化与平坦化，而非全局统一温度。","把蒸馏信号集中到决定答案正确性的关键决策位置，降低无关 token 对策略梯度的稀释。","将正确性判定与 rollout 批量生成耦合，使目标分布随样本正确性动态变化。"],"limitations":["依赖正确性判定质量，判定噪声会传导为逐 token 权重噪声，影响策略更新方向。","长尾样本的正确性判定延迟会拖慢批完成时间，与批量生成调度的吞吐目标冲突。","材料未给出硬件档位、量化方案与并行拓扑，无法评估在 Blackwell 部署下的显存与通信代价。"],"impact":"该方法把自蒸馏的目标分布设计从全局统一转向逐 token 非对称，为 rollout 阶段的样本效率提供了新抓手；但其收益依赖正确性判定的准确率与延迟，在分离式预填/解码与 KV 复用的部署链路中，需要与批调度和权重同步协同设计，否则长尾判定会成为吞吐瓶颈。","summary":"论文提出正确性依赖的非对称目标分布用于自蒸馏策略优化：依据答案正确性为逐 token 估计依赖权重，对关键位置锐化教师分布、对无关位置平坦化，从而把蒸馏信号集中到影响正确性的决策点上。方法嵌入 rollout 生成与损失计算链路，需与批量调度、KV 复用和权重同步协同；材料未给出数据集、基线、硬件档位与量化方案的具体数值，其吞吐与显存代价尚不可核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为批量候选回答生成，请求长度分布与批大小材料未给出，需按 rollout 引擎实际调度设定。","每条样本需附带答案正确性判定结果，判定延迟构成长尾，影响批完成时间与并发上限。","并发规模与 SLO 材料未给出；正确性判定服务与生成服务需分别设定超时与重试策略。"],"train_recipe":["硬件档位材料未给出；若部署于 Blackwell，需明确 B200/B300/GB200 NVL72 档位与并行拓扑。","量化方案材料未给出；NVFP4 下采样稳定性需单独验证，尤其是锐化后目标分布的数值精度影响。","KV 策略为策略更新后旧前缀失效重建，需监控前缀命中率与重建开销。","监控项应包括正确性判定延迟分位、批完成时间、权重同步间隔与长尾样本占比。"],"facts":["方法核心是逐 token 的非对称目标分布：高正确性依赖位置锐化、低依赖位置平坦化，损失为加权 KL 形式，权重由正确性判定导出。","正确性判定位于 rollout 与损失计算之间，判定延迟直接进入批完成时间，长尾样本会拉长整批等待，需在调度层设超时与重排。","策略更新后需将新权重同步至 rollout 引擎，旧 KV 前缀失效并重建，前缀命中率下降会抬高预填开销。","非对称锐化改变目标分布的数值形态，在 NVFP4 等低精度采样下需验证采样稳定性，材料未给出量化方案与精度数值。","逐 token 权重依赖样本级正确性标签，判定噪声会传导为权重噪声，进而影响策略梯度方向，属于主要失败模式。","方法未改变 rollout 引擎的批调度结构，但正确性判定作为额外阶段插入流水线，需与生成阶段解耦以避免阻塞。","材料未给出硬件档位、并行切分与显存占用数据，无法评估 B200/B300 档位下的容量与吞吐代价。","长尾样本与判定延迟共同决定有效吞吐，若判定服务与生成服务共享资源，会加剧批调度抖动。"],"anchors":[],"pitfalls":["把正确性判定当作免费环节：判定延迟与噪声会同时侵蚀吞吐与策略更新质量，需独立监控。","在低精度采样下直接套用锐化目标分布，可能放大数值误差导致采样分布偏移，需先验证 NVFP4 稳定性。","策略更新后未及时失效 KV 前缀，会复用旧策略缓存导致目标分布与生成分布不一致。"],"depth":"deep"},{"id":"paper-deepseek-r1-incentivizing-reasoning-2025","title":"DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning","title_zh":"DeepSeek-R1 强化学习推理与部署机制","authors":[" DeepSeek-AI","Daya Guo","Dejian Yang","Haowei Zhang","Junxiao Song","Peiyi Wang","Qihao Zhu","Runxin Xu","Ruoyu Zhang","Shirong Ma","Xiao Bi","Xiaokang Zhang"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2501.12948","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"DeepSeek-R1 关注用强化学习激励大模型推理能力，其论文卡在本卷中只取与推理机制和部署容量相关的部分：rollout 阶段的批量生成调度、KV 复用与前缀共享、奖励模型与验证器推理、异步流水线与权重同步、长尾样本对吞吐的影响，以及 NVFP4 等低精度采样下的稳定性。材料未给出具体硬件档位与吞吐数字，因此相关判断只落到机制与工程代价层面。","problem":"RL 后训练中的 rollout 推理与训练耦合时，长尾样本会拖慢整批生成，权重同步与异步流水线带来策略陈旧，低精度采样可能改变分布并影响奖励判定，需要把生成引擎与训练解耦并明确容量与失败模式。","core_idea":"把 rollout 生成视为独立推理服务：批量调度请求、复用 KV 与前缀、将奖励模型与验证器作为独立推理负载，用异步流水线重叠生成与训练，并以权重同步点和陈旧度约束控制策略偏差；低精度采样需在数值精度与采样稳定性之间取折中。","architecture":"材料未给出具体并行拓扑与硬件档位。按本卷框架，rollout 引擎与训练解耦后由调度器统一管理批量生成，KV cache 按前缀共享复用，奖励模型与验证器走独立服务队列，异步流水线在生成与训练之间传递样本并周期性同步权重；监控关注长尾样本占比、队列等待、KV 命中率与权重陈旧度。","pipeline":["请求进入 rollout 调度器，按长度分布与并发上限组成批量，长尾样本单独标记。","生成阶段复用前缀共享的 KV cache，命中部分跳过预填，降低重复计算。","采样结果送入奖励模型与验证器推理服务，按队列优先级返回打分。","异步流水线把已打分样本送入训练侧，权重按同步点回灌生成引擎。","监控长尾样本占比、KV 命中率与权重陈旧度，超阈值时触发调度调整。"],"formula":"$$\\mathcal{L}_{\\mathrm{RL}}(\\theta)=\\mathbb{E}_{x\\sim\\mathcal{D},\\,y\\sim\\pi_{\\theta}(\\cdot\\mid x)}\\left[r_{\\phi}(x,y)\\right]-\\beta\\,\\mathrm{KL}\\left(\\pi_{\\theta}(\\cdot\\mid x)\\,\\|\\,\\pi_{\\mathrm{ref}}(\\cdot\\mid x)\\right)$$","training":"材料未给出训练配方细节。本卷只记录与推理相关的训练侧约束：rollout 由独立生成引擎产出，训练侧消费带奖励的样本；异步流水线下需定义权重同步周期与允许的最大陈旧度，避免用过期策略样本更新；奖励模型与验证器推理作为独立负载计入容量规划，长尾样本不得阻塞整批吞吐。","walkthrough":"一次 rollout 周期中，调度器先按请求长度分布组批，短请求快速填充、长尾样本进入单独队列以免拖慢整批；生成引擎对共享前缀命中 KV cache 的请求跳过预填，只做解码；采样结果进入奖励模型与验证器服务，打分后由异步流水线送入训练侧；训练侧在同步点回灌权重，生成引擎切换到新权重并记录陈旧度。若长尾队列等待超过阈值或 KV 命中率下降，调度器降低批大小或拆分队列；若低精度采样导致奖励分布偏移，则回退到更高精度采样路径。","pseudocode":"循环 每个 rollout 周期：\n  按长度分布与并发上限组批\n  长尾样本 -> 单独队列，不阻塞主批\n  对每个请求：\n    若 前缀命中 KV cache -> 跳过预填\n    解码采样（精度档位按稳定性策略选择）\n  采样结果 -> 奖励模型/验证器推理队列\n  打分完成 -> 异步流水线送入训练侧\n  到达同步点 -> 回灌权重，记录陈旧度\n  若 长尾等待或 KV 命中率越界 -> 调整批大小与队列","experiments":{"datasets":["材料未给出具体评测数据集"],"baselines":["材料未给出具体基线模型"],"results":"材料未给出可核验的吞吐、延迟或采样稳定性数字；本卷只记录机制层面的预期：解耦 rollout 与训练可重叠生成与更新，前缀共享降低重复预填，长尾队列隔离避免整批被拖慢。","limits":"材料未给出硬件档位、并行拓扑与量化方案的具体数字，无法给出容量结论；低精度采样稳定性缺少可核验的分布偏移数据；权重同步周期与陈旧度上界未给出。","ablations":"材料未给出消融实验；按本卷框架应消融前缀共享开关、长尾队列隔离、异步流水线同步周期与采样精度档位，分别观察吞吐、KV 命中率与奖励分布偏移。"},"innovation":["把 rollout 生成与训练解耦为独立推理服务，按批量调度与异步流水线重叠生成与更新。","以 KV 复用与前缀共享降低重复预填代价，并把长尾样本隔离出主批以保护吞吐。","将奖励模型与验证器推理作为独立负载纳入容量规划，并显式约束权重陈旧度。"],"limitations":["材料未给出具体硬件档位、并行拓扑与量化方案，容量结论无法落地到数字。","低精度采样下的分布偏移与奖励判定稳定性缺少可核验数据。","权重同步周期与允许陈旧度上界未给出，异步流水线的偏差控制只能定性描述。"],"impact":"为 RL 后训练推理提供以机制为中心的整理视角：rollout 引擎解耦、批量调度与 KV 复用、奖励与验证器独立服务、异步流水线与权重同步、长尾吞吐与低精度采样稳定性，均可作为后续 Blackwell 部署容量规划的检查项。","summary":"本卡只取 DeepSeek-R1 论文中与推理机制和部署容量相关的部分。核心是把 rollout 生成视为独立推理服务：调度器按长度分布组批并隔离长尾样本，生成阶段复用前缀共享的 KV cache，奖励模型与验证器走独立队列，异步流水线重叠生成与训练并以同步点回灌权重、约束陈旧度。材料未给出硬件档位、吞吐数字与消融结果，因此判断只落到机制与工程代价，低精度采样稳定性需以精度档位回退策略兜底。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布按短请求与长尾样本分队列，长尾不阻塞主批。","批大小与并发上限由调度器按队列等待与 KV 命中率动态调整。","奖励模型与验证器推理按独立队列计容量，打分延迟计入 SLO。","采样精度档位按稳定性策略选择，异常时回退更高精度路径。"],"train_recipe":["rollout 引擎与训练解耦部署，生成侧独立扩缩容。","KV 策略以前缀共享复用为主，监控命中率与显存占用。","异步流水线定义权重同步周期与最大陈旧度上界。","监控长尾样本占比、队列等待、KV 命中率与奖励分布偏移。"],"facts":["rollout 与训练解耦后，生成引擎可独立扩缩容，异步流水线在生成与训练之间传递带奖励样本，并以同步点回灌权重、记录陈旧度。","长尾样本若与主批混排会拖慢整批生成，按长度分布分队列隔离可保护主批吞吐，代价是长尾队列等待需单独计入 SLO。","前缀共享的 KV cache 让命中请求跳过预填、只做解码，降低重复计算；命中率下降会直接抬高预填开销与显存占用。","奖励模型与验证器推理是独立负载，打分延迟进入 rollout 关键路径，容量规划需与生成引擎分开计算队列与并发。","异步流水线下训练侧消费的样本可能来自旧权重，需定义最大陈旧度上界，否则策略偏差会污染奖励信号与更新方向。","低精度采样可能改变采样分布并影响奖励判定，需保留更高精度采样路径作为回退，并以奖励分布偏移作为监控指标。","批量生成调度需同时约束批大小、并发与 KV 显存，批过大抬高长尾等待，批过小降低吞吐，调度器应按队列等待动态调整。","权重同步点之间生成引擎持续产出样本，同步频率越高陈旧度越低但重叠收益越小，需在吞吐与偏差之间取折中。"],"anchors":[],"pitfalls":["材料未给出硬件档位与吞吐数字，若在写作中补数字会违反只使用给定材料的约束。","把训练配方细节混入推理机制描述，会偏离本卷只关心推理机制与部署容量的边界。","低精度采样稳定性缺少可核验数据，不能据此断言采样分布无偏移。"],"depth":"deep"},{"id":"paper-deepseekmath-pushing-the-limits-of-m-2024","title":"DeepSeekMath: Pushing the Limits of Mathematical Reasoning in Open Language Models","title_zh":"DeepSeekMath 的数学推理与部署代价","authors":["Zhihong Shao","Peiyi Wang","Qihao Zhu","Runxin Xu","Junxiao Song","Xiao Bi","Haowei Zhang","Mingchuan Zhang","Y. K. Li","Y. Wu","Daya Guo"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-reward-verifier-serving","links":{"paper":"https://arxiv.org/abs/2402.03300","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文面向开放语言模型的数学推理能力提升，核心是给出可复现的后训练与数据构造流程；对本卷而言，可核验材料只覆盖其数据筛选与训练侧线索，未给出推理引擎、并行拓扑、量化精度与显存占用的具体配置，因此论文卡把可确认的机制落到数据过滤与验证器式筛选上，其余部署细节标注未给出。","problem":"开放模型在数学推理上受限于高质量数学语料稀缺与噪声样本干扰；若直接把网页数学文本用于后训练，低质与重复样本会稀释梯度信号，因此需要可核验的过滤与筛选机制，并明确这些机制在 rollout 与验证器推理链路上的工程代价。","core_idea":"以大规模数学网页语料为输入，先用规则与分类器做质量过滤，再以迭代方式用当前模型对候选样本做筛选与再训练；对本卷而言，关键是把这种“模型自筛选”视为一种离线验证器式推理负载，其吞吐与长尾分布直接决定后训练数据管线的容量规划。","architecture":"材料给出的架构线索是数据侧流水线：原始网页数学文本经过语言识别、格式与长度规则过滤、去重，再由模型打分或筛选进入训练集；未给出 rollout 引擎与训练解耦、KV 复用、批调度、NVFP4 采样等推理侧实现细节，因此本卡不描述具体并行切分与硬件档位，只把筛选阶段视为批量生成加验证器打分的推理负载。","pipeline":["采集网页数学文本，按语言与格式规则初筛，去除明显非数学与低质页面。","对初筛语料做去重与长度截断，形成候选池，供后续模型筛选使用。","用当前模型对候选样本做批量生成或打分，形成筛选信号，此阶段是典型的批量推理负载。","按筛选分数与阈值保留样本，低分与长尾样本进入丢弃或复审队列。","保留样本进入后训练数据混合，训练更新后的模型再回到筛选阶段，形成迭代。","迭代若干轮后固化数据配方，未给出推理引擎与权重同步的具体机制。"],"formula":"$$\\mathcal{D}_{k+1}=\\{\\,x\\in\\mathcal{D}_{k}\\mid s_{\\theta_k}(x)\\ge \\tau\\,\\}$$","training":"材料只给出数据侧与迭代筛选线索：以规则过滤加模型筛选构造数学语料，并用更新后的模型重复筛选；未给出训练配方中的并行拓扑、量化方案、批大小与学习率等数字，因此本卡不写训练配方细节，只强调筛选阶段的推理代价：批量生成与打分构成长尾分布负载，需要按吞吐与延迟预算规划容量。","walkthrough":"假设一次迭代：先对网页数学文本做语言与格式规则过滤，得到候选池；随后用当前模型对候选逐条打分或生成解答，这一步在推理侧表现为批量请求，长度分布长尾明显，短样本快速返回、长证明类样本占用大量 KV 与解码步数；按阈值保留高分样本进入训练混合，低分样本丢弃或复审；训练更新后模型再次执行筛选。整个链路的瓶颈在筛选阶段的批量生成吞吐与长尾尾延迟，材料未给出具体硬件档位、批大小与 SLO 数字，部署时需自行以吞吐与尾延迟为约束做容量规划。","pseudocode":"输入：网页数学语料 C，阈值 tau，迭代轮数 K\n候选池 P <- 规则过滤(C)  // 语言、格式、长度、去重\nfor k in 1..K:\n  对 P 中每条样本 x：\n    分数 s <- 当前模型打分或生成校验(x)\n    若 s >= tau：保留到训练集 D_k\n    否则：丢弃或进入复审队列\n  用 D_k 更新模型\n  用更新后模型重新筛选 P\n输出：固化后的训练数据配方","experiments":{"datasets":["材料未给出具体评测数据集名称与规模，仅提及数学推理语料与筛选流程。"],"baselines":["材料未给出基线模型与对照配置的具体名称。"],"results":"材料未给出可核验的准确率、吞吐或延迟数字；本卡只能确认论文以数据过滤与迭代筛选为主线，推理侧结果与硬件档位均未给出，因此不引用任何具体指标。","limits":"材料未给出失败模式与监控指标的定量结果；可确认的局限是筛选依赖模型自身打分，存在分布偏移与长尾样本被误删的风险，且批量生成阶段的尾延迟会拖慢迭代节奏。","ablations":"材料未给出消融实验的数字与配置；仅能确认筛选阈值与迭代轮数是流程中的可调环节，具体消融结论未给出。"},"innovation":["把数学语料质量过滤与模型自筛选结合为迭代数据管线，强调可复现的筛选机制而非单次训练。","将筛选阶段视为批量生成加验证器打分的推理负载，为后续 rollout 引擎容量规划提供切入点。","以阈值化筛选公式刻画数据保留规则，便于在工程上把筛选与训练解耦为两个阶段。"],"limitations":["材料未给出推理引擎、并行拓扑、量化精度与显存占用的具体配置，部署侧结论无法定量。","筛选依赖模型自身打分，存在分布偏移与长尾样本误删风险，缺少监控指标的定量材料。","未给出吞吐、尾延迟与 SLO 数字，无法直接支撑 Blackwell 档位的容量规划。"],"impact":"对本卷的意义在于把数学后训练的数据筛选链路映射为批量推理负载：筛选阶段的吞吐与长尾尾延迟决定迭代节奏，部署时需以批调度与 KV 复用为手段控制尾延迟；材料未给出硬件与量化细节，后续写作只能引用其数据过滤与迭代筛选机制，不能引用具体部署数字。","summary":"该论文以网页数学语料为输入，通过规则过滤、去重与模型自筛选的迭代流程构造训练数据；对本卷而言，可核验的是筛选机制与阈值化保留规则，筛选阶段对应批量生成加验证器打分的推理负载，其长尾分布影响吞吐与尾延迟。材料未给出推理引擎、并行拓扑、NVFP4 采样与硬件档位数字，因此论文卡只落到数据过滤与迭代筛选的工程代价上，部署容量结论标注未给出。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为网页数学文本，长度分布长尾明显，短题与长证明混合，需按长度分桶调度。","筛选阶段以批量请求形式执行，批大小与并发未给出，需按吞吐与尾延迟约束自行设定。","SLO 未给出；工程上应把长尾样本的尾延迟作为主要约束，避免拖慢迭代节奏。","候选池需先去重与截断，降低无效请求占比，减少批量生成阶段的浪费。"],"train_recipe":["硬件档位未给出；材料未提供 B200、B300 或 GB200 NVL72 的具体配置。","并行拓扑与量化方案未给出；无法确认是否使用 NVFP4 或 FP8 进行筛选推理。","KV 策略未给出；筛选阶段的长样本会放大 KV 占用，需在部署时自行评估复用与前缀共享。","监控应覆盖筛选吞吐、尾延迟与丢弃率，材料未给出具体指标阈值。"],"facts":["论文以网页数学语料为输入，流程包含语言识别、格式与长度规则过滤与去重，属于数据侧机制，材料未给出语料总量与过滤阈值的具体数字。","筛选阶段用当前模型对候选样本打分或生成校验，再按阈值保留样本；这一阶段在推理侧表现为批量生成负载，材料未给出批大小与并发数。","迭代筛选把训练与数据构造串成循环：更新后的模型重新筛选候选池，材料未给出迭代轮数与每轮样本量的具体数字。","筛选负载的长度分布呈长尾，短样本快速返回而长证明类样本占用大量解码步数与 KV，材料未给出尾延迟与 SLO 数字。","材料未给出推理引擎与训练解耦的实现细节，无法确认权重同步、分离式预填/解码与投机解码是否被采用。","材料未给出量化精度配置，无法确认筛选推理是否使用 NVFP4 或 FP8，也无法评估低精度下的采样稳定性。","材料未给出硬件档位与并行拓扑，无法把筛选吞吐映射到 B200、B300 或 GB200 NVL72 的具体容量。","材料未给出失败模式与监控指标，仅能确认筛选依赖模型自身打分，存在分布偏移与长尾样本误删的风险。"],"anchors":[],"pitfalls":["把筛选阶段的批量生成当作普通离线批处理，忽视长尾样本对尾延迟与 KV 占用的放大效应。","在缺少量化与硬件材料时引用具体吞吐数字，会把未给出的部署结论写成可核验事实。","仅看平均吞吐而忽略丢弃率与复审队列，会低估迭代筛选的实际工程代价。"],"depth":"deep"},{"id":"paper-detent-batch-invariant-llm-serving-a-2026","title":"Detent: Batch-Invariant LLM Serving and RL Rollouts at Near-Stock Speed","title_zh":"Detent：批不变推理与近原生速度","authors":["Peixu Xin","Runchuan Feng","Jiazhen Guo","Kan Wu","Ming Yin"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-sampling-stability","links":{"paper":"https://arxiv.org/abs/2611.10611","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"在 RL 后训练推理（Rollout）与在线服务中，同一请求在不同批大小、不同批组成下会产生不同的数值归约顺序，导致贪心解码结果漂移、奖励打分不可复现、验证器判定抖动。Blackwell 档位引入 NVFP4/FP8 算子后，归约与累加路径更依赖批形状，批不变性成为采样稳定性与 SLO 可复现的前提。Detent 针对这一机制性缺口，给出批不变的服务与 Rollout 方案，并强调接近原生（near-stock）速度。","problem":"批组成变化会改变矩阵乘与归约的分块顺序，使 logits 出现微小差异，进而改变 argmax 采样与奖励模型打分；Rollout 引擎与训练解耦后，同一策略在不同批调度下产出不同轨迹，造成离策略陈旧度估计失真与验证器判定不一致。","core_idea":"把批不变性做成算子与调度层的约束：固定归约顺序与累加精度路径，使输出与批大小、批内位置无关；在此约束下复用 KV 与前缀共享，保持批量生成调度与分离式预填/解码的吞吐，使批不变模式的代价接近原生内核。","architecture":"推理侧在算子层固定归约树与累加精度（NVFP4/FP8 混合路径），在调度层把批不变约束下沉到 prefill 与 decode 两个阶段；KV cache 按前缀共享块组织，批调度器在保持批不变的前提下做连续批与投机解码。Rollout 侧引擎与训练解耦，权重同步走异步流水线，奖励模型与验证器推理复用同一批不变内核，保证打分可复现。","pipeline":["请求进入调度器，按前缀共享块匹配已有 KV，决定是否复用缓存块。","prefill 阶段以固定归约顺序执行注意力与前馈，写入 KV cache 并记录块归属。","decode 阶段连续批调度，批内位置不影响归约树，采样 logits 与批组成无关。","投机解码草稿与验证走同一批不变内核，接受判定不受批大小影响。","奖励模型与验证器推理复用批不变内核，输出可复现打分。","异步流水线完成权重同步，Rollout 引擎与训练侧解耦推进下一轮生成。"],"formula":"$$\\mathrm{logits}_i = f\\left(\\sum_{k=1}^{K} a_{ik} x_k\\right),\\quad \\mathrm{argmax}_i\\ \\mathrm{logits}_i \\ \\text{与批大小 } B \\text{ 及批内位置无关}$$","training":"本文不涉及训练配方；Rollout 侧以引擎与训练解耦的异步流水线组织，权重同步按固定节奏推进，批不变内核保证同一策略在不同批调度下产出可复现轨迹，从而让离策略陈旧度可被稳定度量。奖励模型与验证器推理与生成共享同一数值路径，避免打分抖动污染优势估计。","walkthrough":"一次 Rollout 中，调度器先按前缀共享把同源提示归并，prefill 以固定归约树写入 KV 块；decode 连续批中即便批大小从 8 变到 64，logits 的归约顺序不变，贪心采样结果一致。投机解码的草稿与验证在同一内核下执行，接受率不随批组成漂移。奖励模型对同一轨迹重复打分得到相同分数，验证器判定稳定。异步流水线在生成与权重同步之间切换，长尾样本不阻塞主批，吞吐接近原生内核。","pseudocode":"→ 请求进入调度器，按前缀共享块匹配已有 KV，决定是否复用缓存块。\n→ prefill 阶段以固定归约顺序执行注意力与前馈，写入 KV cache 并记录块归属。\n→ decode 阶段连续批调度，批内位置不影响归约树，采样 logits 与批组成无关。\n→ 投机解码草稿与验证走同一批不变内核，接受判定不受批大小影响。\n→ 奖励模型与验证器推理复用批不变内核，输出可复现打分。\n→ 异步流水线完成权重同步，Rollout 引擎与训练侧解耦推进下一轮生成。","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["原生（stock）内核与常规批调度实现"],"results":"材料称在批不变约束下达到接近原生速度，但未给出具体吞吐、延迟或加速比数字；可核验的结论仅限于批不变性与近原生速度的定性表述。","limits":"材料未给出硬件档位、批大小范围、序列长度分布与 SLO 指标；长尾样本与 NVFP4 采样稳定性的定量失败模式未列出。","ablations":"材料未给出消融实验设置与结果，无法核验各组件（固定归约树、前缀共享、投机解码）的单独贡献。"},"innovation":["把批不变性下沉到算子归约顺序与累加精度路径，而非仅在应用层对齐输出。","在批不变约束下复用 KV 与前缀共享，兼顾批量生成调度与分离式预填/解码吞吐。","奖励模型与验证器推理复用同一批不变内核，使 Rollout 打分可复现。"],"limitations":["材料未给出具体硬件档位与并行拓扑，部署代价无法量化。","缺少 NVFP4 下采样稳定性的定量数据与失败模式清单。","未给出长尾样本对吞吐影响的测量方法与 SLO 阈值。"],"impact":"为 RL Rollout 与在线服务提供可复现的数值路径，使批调度变化不再污染采样与奖励打分；其工程价值在于把批不变性作为调度与算子约束而非事后对齐，为 Blackwell 档位上的 NVFP4/FP8 部署提供稳定性前提。","summary":"Detent 针对批组成变化导致 logits 漂移的问题，提出批不变的服务与 Rollout 方案：在算子层固定归约顺序与累加精度，在调度层把约束下沉到 prefill 与 decode，并复用 KV 与前缀共享。奖励模型与验证器推理共享同一内核，使打分可复现。材料称其接近原生速度，但未给出具体数字、硬件档位与消融结果，部署代价与 NVFP4 采样稳定性仍需定量核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布与批大小范围材料未给出，需按实际负载测量长尾占比。","并发与 SLO 阈值未给出，批不变模式下需监控 decode 阶段批组成变化频率。","前缀共享命中率与 KV 块复用率需按提示同源比例统计。","奖励模型与验证器打分请求的比例与重复打分频率需单独计量。"],"train_recipe":["硬件档位材料未给出，需在 B200/B300/GB200 NVL72 上实测批不变内核开销。","并行拓扑与量化方案未给出，NVFP4/FP8 混合路径需验证累加精度一致性。","KV 策略采用前缀共享块组织，需监控块归属与回收。","监控项包括批不变性校验、采样一致性、奖励打分复现率与长尾阻塞。","权重同步走异步流水线，需监控同步节奏与 Rollout 陈旧度。"],"facts":["批不变性通过固定归约树与累加精度路径实现，使 logits 与批大小、批内位置无关，从而贪心采样结果不随批组成漂移。","KV cache 按前缀共享块组织，调度器在保持批不变约束下做连续批与投机解码，复用命中率直接影响 decode 阶段吞吐。","奖励模型与验证器推理复用同一批不变内核，同一轨迹重复打分得到相同分数，避免打分抖动污染优势估计。","Rollout 引擎与训练解耦，权重同步走异步流水线，批不变内核使同一策略在不同批调度下产出可复现轨迹。","材料称批不变模式达到接近原生速度，但未给出吞吐、延迟或加速比数字，工程代价无法量化。","NVFP4/FP8 混合路径下归约与累加更依赖批形状，批不变约束正是针对该机制缺口的稳定性前提。","长尾样本不阻塞主批的调度策略未给出定量阈值，需按实际长度分布测量阻塞概率。","分离式预填/解码与批不变约束的交互未给出并行拓扑细节，部署时需实测 prefill 与 decode 的批组成差异。"],"anchors":[],"pitfalls":["把批不变性理解为应用层对齐输出，而忽略算子归约顺序这一根因，会导致 NVFP4 下仍出现采样漂移。","在未实测硬件档位与批大小范围的情况下宣称近原生速度，缺乏工程代价支撑。","奖励模型与生成不共享数值路径时，打分抖动会被误判为策略噪声。"],"depth":"deep"},{"id":"paper-direct-preference-optimization-your-2023","title":"Direct Preference Optimization: Your Language Model is Secretly a Reward Model","title_zh":"DPO：语言模型即隐式奖励模型","authors":["Rafael Rafailov","Archit Sharma","Eric Mitchell","Stefano Ermon","Christopher D. Manning","Chelsea Finn"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2305.18290","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RLHF 的常规做法是先训练奖励模型，再用 PPO 对策略做在线强化学习；这条链路要同时维护策略、参考模型、奖励模型与价值模型，rollout 与训练耦合、显存占用高、采样吞吐受自回归解码限制。DPO 试图把偏好对齐从在线 RL 改成对偏好对的离线监督学习，从而绕开显式奖励模型与在线采样循环。","problem":"在线 RLHF 的奖励模型拟合与 PPO 采样之间存在分布漂移与信用分配困难；rollout 阶段批量生成开销大、KV cache 与多模型副本挤占显存，且奖励模型与验证器推理本身也要占一份服务容量。需要一种不引入显式奖励模型、不依赖在线采样的偏好优化目标。","core_idea":"在 Bradley–Terry 偏好模型下，最优策略对奖励的闭式解可写成参考策略乘以奖励的指数；反解出奖励为策略与参考策略对数比的形式，代回偏好似然即得到只含策略与参考策略的损失。于是语言模型自身成为隐式奖励模型，偏好对上的二分类损失可直接用监督学习优化。","architecture":"训练侧只保留策略模型与冻结的参考模型两份权重，偏好对（prompt、chosen、rejected）离线构造；前向对同一 prompt 分别算 chosen 与 rejected 的对数概率，参考模型提供对数比基线。推理侧不需要奖励模型服务，但参考模型的前向仍是额外显存与算力开销；若把 DPO 用于 RL 后训练的 rollout 环节，则偏好对构造与批量生成调度仍需与训练解耦。","pipeline":["离线收集 prompt 与成对偏好样本，构造 chosen／rejected 序列并做长度与截断处理。","对每个 prompt 分别前向 chosen 与 rejected，得到策略对数概率与冻结参考模型对数概率。","按对数比之差计算隐式奖励，代入 Bradley–Terry 负对数似然得到标量损失。","反向传播只更新策略参数，参考模型保持冻结、不参与梯度。","按批调度偏好对，控制序列长度分布与显存占用，避免长尾样本拖慢整批。","导出策略权重供部署；推理时不再需要单独的奖励模型副本。"],"formula":"$$\\mathcal{L}_{\\mathrm{DPO}}(\\pi_\\theta;\\pi_{\\mathrm{ref}})=-\\mathbb{E}_{(x,y_w,y_l)\\sim\\mathcal{D}}\\left[\\log\\sigma\\left(\\beta\\log\\frac{\\pi_\\theta(y_w\\mid x)}{\\pi_{\\mathrm{ref}}(y_w\\mid x)}-\\beta\\log\\frac{\\pi_\\theta(y_l\\mid x)}{\\pi_{\\mathrm{ref}}(y_l\\mid x)}\\right)\\right]$$","training":"偏好对离线构造，无需在线 rollout；每个样本要跑策略与参考两次前向，参考前向是纯推理开销。批内序列长度差异大时长尾样本决定显存峰值，需按 token 数而非样本数做批调度。β 控制对参考策略的偏离强度，过大则隐式奖励饱和、梯度变小。材料未给出具体数据规模、批大小与硬件档位，相关数字记为未给出。","walkthrough":"设一条偏好对含 prompt x、胜出回答 y_w 与落败回答 y_l。先把两条回答分别拼接在 x 后做前向，取回答 token 的对数概率求和，得到策略侧两个标量与参考侧两个标量。计算两个对数比之差并乘 β，送入 log-sigmoid 得负对数似然。若胜出回答的对数比明显高于落败回答，损失趋近零；若两者接近，梯度推动策略抬高 y_w 相对概率、压低 y_l。整批偏好对的反向只更新策略，参考模型权重不动，因此显存里常驻两份权重；推理部署时奖励模型副本可省去，但参考模型在训练期仍占一份容量。","pseudocode":"读取偏好对批次 (x, y_w, y_l)\n对每条样本：\n  策略前向 y_w 与 y_l -> 回答 token 对数概率求和\n  参考前向 y_w 与 y_l -> 回答 token 对数概率求和（不建梯度）\n  计算 logp_w - logp_l 与 ref_w - ref_l\n  隐式奖励差 = beta * ((logp_w - ref_w) - (logp_l - ref_l))\n  损失 = -log(sigmoid(隐式奖励差))\n按 token 总数累积损失并反向\n仅更新策略参数，参考参数冻结\n按固定步数或验证集早停导出权重","experiments":{"datasets":["材料未给出具体偏好数据集名称，记为未给出"],"baselines":["材料未给出对比基线，记为未给出"],"results":"材料未给出任何可核验的数值结果、胜率或吞吐数据；论文卡只确认 DPO 在偏好对上用监督损失优化，不依赖显式奖励模型与在线 PPO 采样，因此省去奖励模型推理副本与 rollout 循环。","limits":"材料未给出评测规模、模型尺寸与训练成本；离线偏好对的质量与覆盖度决定上限，参考模型前向带来的额外显存与算力在长序列上更明显，β 与序列长度截断的敏感性也缺少可核验数字。","ablations":"材料未给出消融实验的具体设置与数字，仅能确认 β 是控制偏离参考策略强度的关键超参，参考模型是否冻结属于方法定义的一部分。"},"innovation":["把最优策略的闭式解反解为隐式奖励，使语言模型本身充当奖励模型。","用偏好对上的二分类监督损失替代在线 PPO 采样循环，去掉显式奖励模型。","训练只需策略与冻结参考两份权重，推理侧不再需要奖励模型服务副本。"],"limitations":["每个偏好对需策略与参考两次前向，长序列下显存与算力开销翻倍。","离线偏好对的质量与分布覆盖决定效果，缺少在线探索与难例挖掘。","材料未给出规模、硬件与吞吐数字，部署代价无法量化核验。"],"impact":"DPO 把偏好对齐从在线 RL 改写为离线监督学习，直接削减了奖励模型服务与 rollout 采样的容量需求；在 Blackwell 部署语境下，它把问题从多模型并行服务转为两份权重的批调度与前向吞吐，为 rollout 引擎与训练解耦、KV 复用与前缀共享提供了更简单的容量基线。","summary":"该论文在 Bradley–Terry 偏好模型下推导出最优策略的闭式形式，反解奖励为策略与参考策略的对数比，从而得到只含两份模型参数的 DPO 损失。训练用离线偏好对做监督学习，不再需要显式奖励模型与在线 PPO 采样；代价是每个样本要跑策略与参考两次前向，参考模型常驻显存。材料未给出数据规模、硬件档位与吞吐数字，因此部署代价只能定性描述为两份权重的前向开销与长尾序列的批调度压力。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为离线偏好对：同一 prompt 下的 chosen 与 rejected 回答，长度分布决定批内 token 峰值。","批调度按 token 总数而非样本数切分，长尾长序列样本单独成批以避免拖慢整批。","并发与 SLO 材料未给出；推理侧无奖励模型副本，容量主要花在策略前向与 KV cache。","偏好对覆盖度与过滤阈值材料未给出，只能确认离线构造、无在线采样。"],"train_recipe":["硬件档位与并行拓扑材料未给出，记为未给出；训练期常驻策略与冻结参考两份权重。","量化方案材料未给出；参考模型前向可用低精度推理路径，但材料未给出 NVFP4／FP8 的具体配置。","KV 策略与前缀共享材料未给出；同一 prompt 的 chosen／rejected 可共享前缀 KV 以减少重复计算。","监控重点为批内 token 峰值显存、参考前向占比与 β 导致的损失饱和比例；具体阈值未给出。"],"facts":["DPO 损失只含策略与冻结参考模型的对数概率比，不需要单独训练奖励模型，因此推理部署可省去奖励模型服务副本与相应显存。","每个偏好对需要策略与参考各两次前向（chosen 与 rejected），训练期显存常驻两份权重，长序列下前向算力约为单模型的两倍。","同一 prompt 的 chosen 与 rejected 共享前缀，前缀 KV 复用可减少重复预填；材料未给出具体复用比例与序列长度分布。","批调度应按 token 总数切分而非按样本数，否则长尾长序列样本决定显存峰值并拖慢整批前向。","β 控制策略对参考模型的偏离强度；β 过大时隐式奖励差饱和、log-sigmoid 梯度变小，训练信号减弱。","离线偏好对不含在线采样，缺少难例挖掘与分布漂移纠正；偏好对质量与覆盖度直接决定对齐上限。","推理侧不再需要奖励模型，但训练侧参考模型前向是纯开销；若用于 RL rollout，偏好对构造与批量生成仍需与训练解耦。","材料未给出数据规模、批大小、硬件档位与吞吐数字，所有容量判断只能落到两份权重前向与长尾批调度这两项机制上。"],"anchors":[],"pitfalls":["把 DPO 当作零成本替代在线 RL：参考模型前向与两份权重常驻仍是实打实的显存与算力代价。","忽略批内序列长度长尾：按样本数组批会让最长序列决定显存峰值，吞吐被单条长样本拖住。","把 β 当作无关紧要的缩放：β 过大会让隐式奖励饱和、梯度消失，训练信号变弱。"],"depth":"deep"},{"id":"paper-distserve-disaggregating-prefill-and-2024","title":"DistServe: Disaggregating Prefill and Decoding for Goodput-optimized Large Language Model Serving","title_zh":"分离式预填与解码的吞吐优化","authors":["Yinmin Zhong","Shengyu Liu","Junda Chen","Jianbo Hu","Yibo Zhu","Xuanzhe Liu","Xin Jin","Hao Zhang"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2401.09670","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大语言模型在线服务同时承受预填阶段的计算密集与解码阶段的访存密集两类负载，二者混跑在同一 GPU 上会互相干扰：预填的长序列计算会打断解码的连续批处理，导致解码时延抖动与显存碎片化。已有服务系统多以整体吞吐或单请求时延为目标，缺少面向 SLO 约束下有效吞吐（goodput）的调度视角，难以在有限卡数下同时满足首 token 时延与每 token 时延两段 SLO。","problem":"预填与解码耦合部署时，两阶段对算力、显存带宽与 KV cache 的需求冲突，使得在给定 SLO 下可服务的请求速率被压低；需要回答预填与解码应如何分配到不同 GPU 资源、以何种并行拓扑放置、以及调度器如何在两段 SLO 之间做取舍。","core_idea":"把预填与解码拆到不同的 GPU 资源池上独立扩缩，按各阶段的实际负载分别选择并行策略与资源量；调度器以 goodput 最大化为目标，在满足首 token 时延与每 token 时延约束的前提下决定请求放置与批组成，并让 KV cache 在阶段之间跨节点传输。","architecture":"系统由预填实例与解码实例两类资源池构成，二者通过高速互联交换 KV cache。预填实例按计算密集特征选择张量并行切分，解码实例按访存密集特征选择更大的批与较少的并行度；调度器持有全局请求队列，依据各实例的负载与 SLO 余量做放置决策，并把预填完成的请求连同 KV 块迁移到解码实例。KV 传输量与放置策略共同决定互联带宽开销，成为容量规划的关键约束。","pipeline":["请求进入全局调度队列，调度器读取其输入长度与当前各实例负载，判定应放入哪个预填实例。","预填实例以计算密集方式并行处理整段提示，生成首 token 并写出该请求的 KV cache 块。","调度器在预填完成时选择目标解码实例，按 SLO 余量与批容量决定放置，触发 KV 块跨节点传输。","解码实例接收 KV 块后加入连续批，逐 token 解码并持续追加 KV，直至达到停止条件。","解码完成后释放 KV 块并回传结果，调度器更新各实例负载视图，进入下一轮放置。","当负载倾斜时，调度器调整两类实例的资源配比或并行拓扑，重新平衡两段 SLO 余量。"],"formula":"$$\\text{goodput}=\\max\\ \\frac{1}{T}\\sum_{i=1}^{N}\\mathbf{1}\\left[\\text{TTFT}_i\\le \\text{SLO}_{\\text{ttft}}\\ \\wedge\\ \\text{TPOT}_i\\le \\text{SLO}_{\\text{tpot}}\\right]$$","training":"本工作不涉及训练配方；其关注点是把推理服务中的预填与解码两段解耦后重新分配资源。对 RL 后训练 rollout 而言，该机制可直接迁移：rollout 引擎的批量生成可拆为预填池与解码池，训练侧与推理侧解耦后，权重同步只需在池间传递参数而非阻塞整条流水线；KV 复用与前缀共享可在预填池内做跨样本前缀缓存，长尾样本则留在解码池中继续消耗容量。","walkthrough":"设一条请求的提示长度为数千 token，若与解码请求混跑，其预填计算会占满 SM 并挤占解码批的显存带宽，使正在解码的请求每 token 时延抬升。解耦后，该请求被放入预填实例，以张量并行快速完成前向并产出首 token 与 KV 块；调度器随即把它迁往解码实例，KV 块经互联传输后进入连续批。解码实例的批由时延余量相近的请求组成，避免长尾请求拖慢整批。若互联带宽不足，KV 传输成为瓶颈，调度器会倾向把请求放到 KV 传输代价更低的解码实例，或调整两池配比。整个过程中，两段 SLO 分别由不同资源池保障，goodput 由满足双约束的请求速率度量。","pseudocode":"循环 每个调度时隙：\n  读取 全局请求队列 与 各实例负载视图\n  对 每个待放置请求：\n    若 尚未预填：\n      选 预填实例 使 首token时延余量 最大\n      在 预填实例 上 前向 并 写出 KV 块\n    否则：\n      估算 各解码实例 的 KV 传输代价 与 批容量\n      选 解码实例 使 每token时延余量 最大 且 传输代价 可接受\n      迁移 KV 块 并 加入 连续批\n  若 某池 SLO 余量 持续为负：\n    调整 两池 资源配比 或 并行拓扑\n  更新 负载视图","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集、基线名称与数值结果；可核验的结论方向是：解耦预填与解码并按各阶段负载独立分配资源与并行策略，可在满足首 token 时延与每 token 时延双约束下提升有效吞吐，具体提升幅度未给出。","limits":"材料未给出实验规模、硬件档位与 SLO 取值；方法的代价在于 KV cache 跨节点传输占用互联带宽，且两池资源配比需要按负载分布调优，负载剧烈波动时配比调整存在滞后，长尾请求仍会占用解码容量。","ablations":"材料未给出消融实验细节；可推断的消融维度包括预填与解码是否解耦、并行拓扑选择、KV 传输放置策略与调度目标函数，具体数值未给出。"},"innovation":["把预填与解码拆到独立资源池，按各阶段负载特征分别选择并行策略与资源量。","以双段 SLO 约束下的有效吞吐为调度目标，而非单一吞吐或平均时延。","将 KV cache 跨节点迁移纳入放置决策，使互联带宽成为显式容量约束。"],"limitations":["KV 跨节点传输消耗互联带宽，在带宽受限拓扑下可能抵消解耦收益。","两池资源配比依赖负载分布，突发流量下配比调整滞后会破坏 SLO 余量。","长尾请求在解码池中持续占用批容量，拖低整体 goodput。"],"impact":"该工作把服务系统的优化目标从吞吐转向 SLO 约束下的有效吞吐，并把预填与解码的资源分配问题显式化。对 Blackwell 部署而言，其思路可直接用于 rollout 引擎与训练解耦：预填池承担批量生成的首段计算并做前缀共享，解码池承接长尾样本；NVFP4 量化下采样稳定性需在解码池单独监控，权重同步则以池为单位进行。","summary":"论文提出把大语言模型服务的预填与解码两阶段解耦到不同 GPU 资源池，按各阶段的算力与访存特征分别配置并行拓扑与资源量，并由全局调度器在首 token 时延与每 token 时延双约束下最大化有效吞吐。KV cache 在阶段间跨节点传输，其带宽开销成为放置决策与容量规划的关键约束。该机制对 RL rollout 的批量生成调度、KV 复用与长尾样本吞吐具有直接参考价值。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长提示：短提示与长提示混合到达，长度分布决定预填池的计算压力与 KV 块大小。","批大小与并发由解码池的连续批容量决定，时延余量相近的请求才可同批，避免长尾拖慢整批。","SLO 分两段设定：首 token 时延约束预填池，每 token 时延约束解码池，两段余量共同决定放置。","前缀共享与 KV 复用可降低预填池重复计算，但复用命中率随请求多样性下降而降低。"],"train_recipe":["硬件档位与并行拓扑未给出；部署时预填池宜用较高张量并行，解码池宜用较大批与较低并行度。","量化方案未给出；若采用 NVFP4，需在解码池单独监控采样稳定性与数值偏差。","KV 策略为跨节点迁移加池内复用，互联带宽需按 KV 块传输量做容量预留。","监控指标包括两段 SLO 违约率、KV 传输时延、批利用率与长尾请求占用时长。","权重同步以池为单位进行，避免整条流水线因参数更新而停顿。"],"facts":["解耦的核心代价是 KV cache 跨节点传输：预填完成后需把该请求全部 KV 块迁往解码实例，传输量随提示长度线性增长，互联带宽因此成为放置决策的显式约束。","调度目标为双段 SLO 约束下的有效吞吐：只有首 token 时延与每 token 时延同时达标的请求才计入 goodput，这使调度器必须在两池之间做取舍而非单点优化。","预填阶段计算密集，适合较高张量并行切分；解码阶段访存密集，适合较大连续批与较低并行度，两阶段并行拓扑不同是解耦的直接动因。","混跑时预填的长序列前向会占满 SM 并挤占解码批的显存带宽，导致解码每 token 时延抖动，这是耦合部署下 SLO 违约的主要失败模式。","解码池的批由时延余量相近的请求组成，长尾请求若混入会拖慢整批并持续占用批容量，需单独隔离或限制其占用比例。","两池资源配比需按负载分布调优，突发流量下配比调整存在滞后，SLO 余量可能短暂为负，需以监控告警与弹性扩缩兜底。","对 RL rollout 的迁移点是：批量生成可拆为预填池与解码池，前缀共享在预填池内做跨样本缓存，权重同步以池为单位避免阻塞流水线。","若采用 NVFP4 量化，解码池需单独监控采样稳定性，因为低精度下逐 token 采样的数值偏差会累积，与预填阶段的一次性前向风险不同。"],"anchors":[],"pitfalls":["把解耦当作无条件收益：KV 跨节点传输在带宽受限拓扑下可能抵消预填与解码分离带来的调度灵活性。","只优化平均时延而忽略双段 SLO：平均指标掩盖长尾请求对解码批容量的持续占用，goodput 会被高估。","照搬并行拓扑而不区分阶段：预填与解码的算力访存特征不同，统一并行度会浪费其中一段的资源效率。"],"depth":"deep"},{"id":"paper-does-rlhf-scale-exploring-the-impact-2024","title":"Does RLHF Scale? Exploring the Impacts From Data, Model, and Method","title_zh":"RLHF规模扩展的数据模型方法","authors":["Zhenyu Hou","Pengfan Du","Yilin Niu","Zhengxiao Du","Aohan Zeng","Xiao Liu","Minlie Huang","Hongning Wang","Jie Tang","Yuxiao Dong"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-longtail-throughput","links":{"paper":"https://arxiv.org/abs/2412.06000","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注RLHF后训练推理阶段的可扩展性问题，核心在于奖励模型与策略模型之间的交互式生成与评估流程。论文从数据规模、模型规模与方法设计三个维度考察RLHF的扩展行为，涉及批量生成调度、奖励模型推理与验证器评估等环节。材料未给出具体硬件档位与并行拓扑，但论文的扩展性结论直接影响rollout引擎的容量规划与吞吐估算。","problem":"RLHF的扩展性是否与预训练一样遵循可预测的幂律？数据量、模型规模与方法选择各自贡献多少？在rollout推理中，批量生成与奖励评估的耦合使吞吐与长尾样本成为瓶颈，论文需要回答这些因素如何影响最终对齐质量与工程代价。","core_idea":"论文将RLHF的扩展性拆解为数据、模型与方法三条线，分别考察其边际收益与饱和点。核心判断是：数据规模与模型规模存在收益递减，而方法层面的改进（如偏好数据构造与过滤策略）在同等算力下能带来更稳定的提升。这一结论对rollout引擎的批调度与KV复用策略有直接指导意义。","architecture":"论文的推理流程由策略模型批量生成候选回复、奖励模型或验证器对候选打分、以及偏好数据过滤三部分组成。生成阶段采用批量调度以提升吞吐，奖励评估阶段需要处理变长输入并复用前缀KV。材料未给出具体的并行切分方式与量化方案，但论文强调方法设计对扩展性的影响大于单纯堆叠数据与模型规模。","pipeline":["策略模型接收提示词批次，按批量调度生成多条候选回复，生成长度分布存在长尾。","生成结果送入奖励模型或验证器进行打分，变长输入需要前缀共享与KV复用以降低重复计算。","按打分结果与过滤阈值筛选偏好对，低质量或高噪声样本被剔除。","筛选后的偏好数据用于后续策略更新，形成异步流水线中的权重同步点。","长尾样本在生成与评估两段都拖慢批完成时间，需要监控尾部延迟与吞吐。","整体rollout与训练解耦，批量生成调度决定单位时间内的有效样本产出。"],"formula":"$$\\mathcal{L}_{\\text{RLHF}}(\\theta)=\\mathbb{E}_{x\\sim\\mathcal{D},\\,y\\sim\\pi_\\theta(\\cdot|x)}\\left[r_\\phi(x,y)\\right]-\\beta\\,\\mathrm{KL}\\left(\\pi_\\theta(\\cdot|x)\\,\\|\\,\\pi_{\\text{ref}}(\\cdot|x)\\right)$$","training":"论文的训练侧结论仅作为背景：RLHF的扩展性受数据规模、模型规模与方法设计共同影响，三者均存在收益递减。材料未给出具体的训练配方、学习率或批次大小。对推理部署而言，关键含义是rollout阶段的样本产出效率与方法层面的过滤策略共同决定单位算力下的有效偏好数据量，从而影响整体吞吐与SLO达成。","walkthrough":"一次完整的rollout请求从提示词批次进入策略模型开始。策略模型按批量调度生成多条候选回复，生成长度呈长尾分布，少数超长样本拖慢整批完成时间。生成结果随后进入奖励模型或验证器，变长输入需要前缀共享与KV复用以避免重复计算。打分完成后按过滤阈值筛选偏好对，低分或高噪声样本被剔除。筛选后的数据进入异步流水线等待权重同步。整个过程中，批量生成调度与KV复用策略决定吞吐上限，而长尾样本与奖励评估的耦合是主要失败模式，需要通过监控尾部延迟与批完成率来定位瓶颈。","pseudocode":"输入：提示词批次 P，策略模型 pi，奖励模型 r，过滤阈值 tau\n缩进 对 P 分批调度生成候选回复 Y <- pi.generate(P, batch_sched)\n缩进 对 Y 做前缀共享与 KV 复用，送入奖励模型打分 S <- r.score(P, Y)\n缩进 按 S 与 tau 过滤，保留偏好对 D_filtered\n缩进 将 D_filtered 推入异步流水线，等待权重同步\n缩进 监控尾部延迟与批完成率，标记长尾样本\n缩进 若尾部延迟超阈值，调整批大小与调度策略\n缩进 返回 D_filtered 与吞吐统计","experiments":{"datasets":["材料未给出具体数据集名称与规模"],"baselines":["材料未给出具体基线方法"],"results":"论文报告RLHF的扩展性在数据、模型与方法三个维度上均存在收益递减，方法层面的改进在同等算力下比单纯增加数据或模型规模更稳定。材料未给出具体数字与曲线。","limits":"论文未给出具体的硬件档位、并行拓扑与量化方案，因此无法直接换算为Blackwell部署下的吞吐与显存代价。长尾样本与奖励评估耦合的失败模式也缺少定量分析。","ablations":"材料未给出具体的消融实验设置与数字，仅提及数据、模型与方法三条线的相对贡献存在差异。"},"innovation":["将RLHF扩展性拆解为数据、模型与方法三条线分别考察边际收益。","指出方法层面的改进在同等算力下比堆叠数据与模型规模更稳定。","为rollout引擎的批调度与KV复用策略提供扩展性层面的指导。"],"limitations":["材料未给出具体硬件档位与并行拓扑，难以直接映射到Blackwell部署代价。","缺少长尾样本与奖励评估耦合的定量失败模式分析。","未给出NVFP4等低精度采样下的稳定性讨论。"],"impact":"论文的扩展性结论提示rollout引擎设计应优先优化方法层面的过滤与调度策略，而非单纯扩大批量或模型规模。对Blackwell部署而言，这意味着批调度与KV复用的收益可能高于单纯提升算力档位，长尾样本监控应成为容量规划的一部分。","summary":"该论文从数据、模型与方法三个维度考察RLHF的扩展性，结论是三者在扩展中均存在收益递减，而方法层面的改进在同等算力下更为稳定。对推理部署而言，rollout阶段的批量生成调度、奖励模型评估的前缀共享与KV复用、以及长尾样本的尾部延迟监控共同决定吞吐与SLO达成。材料未给出具体硬件档位、量化方案与数字，因此部署代价的换算需要后续补充。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布呈长尾，少数超长样本拖慢整批完成时间，需要尾部延迟监控。","批量生成调度按批大小与并发度调节，批越大吞吐越高但尾部延迟风险越大。","奖励评估阶段输入变长，需要前缀共享与KV复用降低重复计算。","过滤阈值决定偏好对质量与有效样本产出率，阈值过高会降低吞吐。","异步流水线中权重同步点影响样本新鲜度与off-policy程度。"],"train_recipe":["材料未给出具体硬件档位，部署配方需结合B200/B300/GB200 NVL72档位另行评估。","并行拓扑与量化方案未给出，NVFP4采样稳定性需单独验证。","KV策略应优先前缀共享与复用，降低奖励评估阶段的重复计算。","监控应覆盖尾部延迟、批完成率与有效样本产出率。","rollout引擎与训练解耦，批量生成调度决定单位时间有效样本量。"],"facts":["论文将RLHF扩展性拆解为数据、模型与方法三条线，三者均存在收益递减，方法层面改进在同等算力下更稳定。","rollout阶段策略模型批量生成候选回复，生成长度呈长尾分布，少数超长样本拖慢整批完成时间。","奖励模型或验证器评估变长输入时需要前缀共享与KV复用，否则重复计算会显著降低吞吐。","偏好数据过滤阈值直接影响有效样本产出率，阈值过高会降低单位算力下的吞吐。","异步流水线中权重同步点决定样本新鲜度，进而影响off-policy程度与训练稳定性。","长尾样本在生成与评估两段都拖慢批完成时间，需要监控尾部延迟与批完成率定位瓶颈。","材料未给出具体硬件档位与并行拓扑，部署代价换算需结合Blackwell档位另行评估。","材料未给出NVFP4等低精度采样下的稳定性讨论，采样稳定性需单独验证。"],"anchors":[],"pitfalls":["论文未给出具体数字与硬件档位，直接引用其结论做容量规划会缺少定量依据。","长尾样本与奖励评估耦合的失败模式缺少定量分析，监控指标需自行补充。","方法层面改进的稳定性结论依赖具体过滤策略，迁移到其他任务需重新验证。"],"depth":"deep"},{"id":"paper-double-rollout-reinforcement-learnin-2026","title":"Double-Rollout Reinforcement Learning with Sampling-based Reward Estimation","title_zh":"双Rollout采样奖励估计","authors":["Haifeng Qian","David Mosallanezhad","Christian Munley","Adithya Renduchintala","Oleksii Kuchaiev"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2610.16593","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RL后训练中的rollout推理需要为每个提示生成多条候选回答，再由奖励模型或验证器打分。传统做法把生成与打分串行绑定在同一引擎上，长尾样本会拖慢整批吞吐；同时奖励模型本身是自回归推理，成本随候选数线性增长。Blackwell档位下NVFP4量化可降低权重与KV带宽压力，但采样分布稳定性需要单独核验。","problem":"如何在rollout引擎与训练解耦的前提下，用采样方式估计奖励，避免对每个候选都调用完整奖励模型推理，同时控制长尾样本对批吞吐的拖累与量化后的采样偏差。","core_idea":"对同一提示做两次独立rollout，用两次采样结果的奖励差异构造无偏或低方差的奖励估计，减少对奖励模型的调用次数；生成侧与打分侧分离部署，批量调度按token预算聚合，KV前缀共享复用提示段。","architecture":"系统分为rollout生成引擎、奖励/验证器推理服务与训练侧权重同步三段。生成引擎按批调度聚合请求，提示前缀KV在候选间共享；奖励服务以较小并发接收采样对，按采样估计公式聚合；训练侧异步拉取轨迹与估计奖励，权重通过同步通道推送到推理引擎。量化方案在生成侧采用NVFP4权重与KV，奖励侧保留较高精度以稳定打分。","pipeline":["训练侧下发提示批次与采样参数，rollout引擎按token预算组批并做前缀KV复用。","对每个提示执行两次独立采样，记录token序列与采样统计量，长尾样本进入延迟队列。","采样对送入奖励/验证器推理服务，按采样估计公式计算奖励估计而非逐候选全量打分。","估计奖励与轨迹回传训练侧，异步流水线按staleness阈值过滤过期样本。","权重同步通道将更新后的策略推送到rollout引擎，KV缓存按前缀键失效重建。"],"formula":"$$\\hat{R}(x)=\\frac{1}{2}\\big[r(y_1)+r(y_2)\\big]+\\lambda\\,\\big|r(y_1)-r(y_2)\\big|$$","training":"训练侧以异步方式消费rollout轨迹，按采样估计奖励更新策略；对超过staleness阈值的样本做过滤，避免旧策略轨迹污染梯度。权重同步采用周期性推送而非逐step同步，减少通信开销。奖励模型与验证器推理独立部署，不与生成引擎争抢显存；长尾样本单独排队，不阻塞主批次的吞吐。","walkthrough":"假设一个提示批次进入rollout引擎，调度器按token预算把短请求聚成大batch，长请求进入延迟队列。每个提示采样两次，提示段KV只计算一次并在两次采样间共享。两次结果送入奖励服务，按公式得到估计奖励与差异项；差异大的样本标记为高不确定性，可能触发额外采样。轨迹与奖励异步回传训练侧，若策略已更新超过阈值则丢弃。权重同步后前缀KV失效，下一轮重新预填。整个链路中生成与打分解耦，长尾不拖累主批。","pseudocode":"for prompt_batch in scheduler:\n  kv = prefill_shared(prompt_batch)\n  y1 = sample(policy, kv, nvfp4=True)\n  y2 = sample(policy, kv, nvfp4=True)\n  r1 = reward_service(y1)\n  r2 = reward_service(y2)\n  rhat = 0.5*(r1+r2) + lambda*abs(r1-r2)\n  if staleness(traj) > threshold: drop\n  else: send_to_trainer(traj, rhat)\n  if sync_step: push_weights(); invalidate_prefix_kv()","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出基线方法"],"results":"材料未给出可核验的吞吐、奖励估计方差或采样稳定性数字；论文卡仅记录机制层面的双rollout与采样估计设计，具体加速比与精度变化未给出。","limits":"材料未给出实验规模与硬件档位细节；双rollout使生成token数翻倍，长尾样本下收益可能被抵消；NVFP4采样稳定性缺少量化对比数据。","ablations":"材料未给出消融实验；可预期的消融维度包括采样次数、差异项系数与staleness阈值，但均无数字。"},"innovation":["用两次rollout的奖励差异构造采样估计，减少逐候选奖励模型调用。","生成引擎与奖励/验证器推理服务解耦部署，长尾样本不阻塞主批吞吐。","提示前缀KV在两次采样间共享，降低重复预填的显存与带宽代价。"],"limitations":["双rollout使生成token量翻倍，短提示高并发下可能得不偿失。","采样估计的方差与偏差依赖差异项系数，材料未给出调参依据。","NVFP4量化下采样分布偏移对奖励估计的影响缺少核验数据。"],"impact":"为RL后训练rollout提供一种以采样换奖励模型调用的工程路径，把生成与打分拆成可独立扩缩的两段，便于在Blackwell档位上按SLO分配显存与并发；但双倍生成成本与量化稳定性仍需实测。","summary":"论文提出双rollout强化学习与基于采样的奖励估计：对同一提示采样两次，用奖励差异构造估计量，减少奖励模型全量推理；系统上把rollout引擎与奖励/验证器服务解耦，按token预算组批并共享前缀KV，训练侧异步消费并过滤过期样本。材料未给出数据集、基线与数字结果，机制层面的主要代价是生成token翻倍与量化采样稳定性待验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：材料未给出具体分布，需按短提示高并发与长尾长请求混合组批。","批大小按token预算聚合，短请求聚大batch，长请求进入延迟队列。","并发：生成侧与奖励侧独立并发池，避免打分阻塞生成。","SLO：主批次吞吐优先，长尾样本允许更高尾延迟。","采样参数：每提示两次独立采样，差异大的样本可触发额外采样。"],"train_recipe":["硬件档位：材料未给出具体B200/B300/GB200配置。","并行拓扑：生成与奖励分离部署，各自独立扩缩。","量化：生成侧NVFP4权重与KV，奖励侧保留较高精度。","KV策略：提示前缀KV在两次采样间共享，权重同步后按前缀键失效。","监控：staleness阈值过滤、长尾队列深度与奖励估计方差。"],"facts":["双rollout对每个提示执行两次独立采样，生成token量约为单rollout的两倍，这是该方法最直接的工程代价，需在吞吐与奖励模型调用节省之间权衡。","奖励估计公式由两次奖励均值与差异项组成，差异项系数控制方差与偏差的折中；材料未给出该系数的取值与调参方法。","生成引擎与奖励/验证器推理服务解耦部署，长尾样本进入延迟队列而不阻塞主批次，这是批调度层面的关键机制。","提示段KV在两次采样间共享，只做一次预填，降低重复预填的显存占用与带宽消耗；权重同步后前缀KV需失效重建。","训练侧异步消费轨迹并按staleness阈值过滤，超过阈值的旧策略样本被丢弃，避免off-policy偏差污染梯度。","生成侧采用NVFP4权重与KV以降低带宽压力，但量化后的采样分布偏移对奖励估计的影响缺少核验数据。","权重同步采用周期性推送而非逐step同步，减少并行通信开销，但会引入策略滞后，需与staleness阈值配合。"],"anchors":[],"pitfalls":["双rollout使生成成本翻倍，若奖励模型调用节省不足以抵消，整体吞吐可能下降。","采样估计的差异项系数缺少理论或实验依据，调参不当会引入偏差。","NVFP4量化下采样分布偏移未被核验，奖励估计可能系统性偏斜。"],"depth":"shallow"},{"id":"paper-eagle-speculative-sampling-requires-2024","title":"EAGLE: Speculative Sampling Requires Rethinking Feature Uncertainty","title_zh":"EAGLE：特征不确定性下的投机采样","authors":["Yuhui Li","Fangyun Wei","Chao Zhang","Hongyang Zhang"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2401.15077","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型自回归解码逐 token 串行，显存带宽受限导致单步延迟高、吞吐低；投机采样用廉价草稿模型先猜多步再由目标模型并行验证，可在不改变输出分布的前提下减少目标模型前向次数。既有草稿构造多在 token 空间做链式预测，忽略了特征层的不确定性，导致草稿接受率受限，长尾样本上尤其明显。","problem":"草稿模型在特征空间自回归时，同一前缀下特征分布存在多峰不确定性，直接取单点采样会把误差逐级放大，使验证阶段大量草稿被拒；如何在保持目标分布不变的前提下提高草稿命中率并控制草稿开销，是投机采样落地的核心问题。","core_idea":"把特征自回归的不确定性显式建模：在草稿端对特征引入随机扰动并做多步展开，使草稿覆盖特征分布的多峰区域；验证端仍用目标模型并行打分并按标准投机采样接受规则校正，保证输出分布与目标模型一致，从而以更高接受率换取更低单步延迟。","architecture":"草稿端为轻量自回归头，输入前缀隐特征并输出下一步特征分布参数，采样时注入随机性以覆盖多峰；目标模型对草稿展开的整段 token 做一次并行前向，得到各位置 logits 并按投机采样接受概率逐位判定，拒绝处回退到目标分布重采样。草稿与目标共享词表映射，KV 仅需对已接受前缀增量维护，被拒后缀的 KV 直接丢弃，避免无效缓存膨胀。","pipeline":["请求进入解码循环，目标模型对当前已接受前缀做一次前向，产出末位隐特征与 logits。","草稿头基于该隐特征做多步特征自回归，每步注入随机扰动采样特征，再映射为候选 token。","将候选 token 序列拼接前缀送入目标模型并行前向，一次得到全部位置的 logits。","按投机采样接受规则逐位比较草稿分布与目标分布，接受前缀、在首个拒绝位按残差分布重采样。","仅保留已接受 token 对应的 KV，丢弃被拒后缀缓存，进入下一轮解码循环。","长尾样本上接受率下降时回退为逐 token 解码，避免无效草稿拖慢整体吞吐。"],"formula":"$$\\min\\left(1,\\ \\frac{p_{\\text{target}}(x_{t+1}\\mid x_{\\le t})}{p_{\\text{draft}}(x_{t+1}\\mid x_{\\le t})}\\right),\\quad x_{t+1}\\sim p_{\\text{res}}(x)=\\max\\left(0,\\ p_{\\text{target}}-p_{\\text{draft}}\\right)$$","training":"草稿头以目标模型隐特征为输入做特征级自回归训练，损失对齐目标模型下一 token 分布；训练时对特征注入扰动以模拟推理期不确定性，使草稿在多峰区域仍可覆盖目标分布。材料未给出具体数据规模、训练步数与超参，相关数值记为未给出；训练目标服务于推理期接受率而非独立生成质量。","walkthrough":"设当前前缀长度为 L，目标模型前向一次得到末位特征 h_L。草稿头以 h_L 为起点做 K 步特征自回归，每步对特征加随机扰动后采样，得到 K 个候选 token。将 K 个候选拼到前缀后送入目标模型并行前向，一次得到 L+1 至 L+K 位的 logits。从第一位起按接受概率逐位判定：若接受则继续，若在位置 j 拒绝，则在该位用残差分布重采样一个 token，其后候选全部作废。最终本轮新增 token 数为接受数加一，KV 仅对新增 token 增量写入，被拒后缀的 KV 不保留。K 越大单轮潜在收益越高但草稿与验证开销也越大，需按负载调节。","pseudocode":"输入：前缀 x，目标模型 M，草稿头 D，展开步数 K\nh = M.encode(x) 的末位特征\ncands = []\nfor i in 1..K:\n  h = D.step(h) + 扰动\n  cands.append(D.to_token(h))\nlogits = M.forward(x + cands) 并行打分\naccepted = 0\nfor j in 1..K:\n  按接受概率判定 cands[j]\n  若接受：accepted += 1\n  否则：在该位按残差分布重采样并跳出\nKV 仅保留 x 与已接受 token 的缓存\n返回 新增 token 序列","experiments":{"datasets":["材料未给出具体数据集名称，记为未给出"],"baselines":["材料未给出基线方法名称，记为未给出"],"results":"材料未给出接受率、加速比与吞吐数字，无法量化；可确认的机制性结果是验证阶段保持目标分布不变，草稿接受率提升直接转化为目标模型前向次数下降，从而降低单步延迟。","limits":"材料未给出长尾样本、批大小与显存占用的实测数据；机制上草稿展开步数增大时草稿与验证开销同步上升，长尾样本接受率下降会削弱收益，需回退逐 token 解码。","ablations":"材料未给出消融实验数字；可推断的消融维度为特征扰动强度与展开步数 K，二者分别影响草稿覆盖度与单轮开销。"},"innovation":["把特征层不确定性显式建模并注入草稿采样，提升多峰区域的草稿覆盖度。","草稿多步展开与目标模型并行验证解耦，验证规则保证输出分布不变。","被拒后缀 KV 直接丢弃，避免无效缓存占用显存带宽。"],"limitations":["材料未给出硬件档位与量化方案，NVFP4 下采样稳定性未验证。","展开步数与草稿开销的权衡缺少实测数据，长尾样本收益不确定。","与批量调度、前缀共享等部署机制的耦合方式未给出。"],"impact":"该方法把投机采样的优化点从 token 链式预测移到特征分布建模，为 rollout 引擎中草稿与验证解耦提供机制参考；在 Blackwell 部署中，接受率提升可减少目标模型前向次数，缓解显存带宽瓶颈，但需与批调度、KV 复用联合调优才能兑现吞吐收益。","summary":"EAGLE 针对投机采样中特征自回归的不确定性，在草稿端注入随机扰动做多步特征展开，在验证端用目标模型并行打分并按标准接受规则校正，保证输出分布与目标模型一致。其工程价值在于以更高草稿接受率换取更少目标前向次数，从而降低解码延迟；被拒后缀 KV 丢弃控制了缓存膨胀。材料未给出数据集、基线、加速比与硬件量化细节，NVFP4 采样稳定性与长尾吞吐仍需实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：材料未给出，需按短提示与长尾长输出分别统计以评估草稿展开步数收益。","批大小与并发：材料未给出，需在固定显存下测接受率随批大小的变化。","SLO：材料未给出延迟目标，需以单步延迟与尾延迟共同约束展开步数 K。"],"train_recipe":["硬件档位：材料未给出 B200/B300/GB200 NVL72 的具体配置。","并行拓扑：材料未给出张量并行与专家并行切分方式。","量化：材料未给出 NVFP4/FP8 方案，采样稳定性待验证。","KV 策略：仅保留已接受前缀 KV，被拒后缀丢弃。","监控：需监控草稿接受率、回退比例与单轮新增 token 数。"],"facts":["草稿端在特征空间做多步自回归，每步注入随机扰动以覆盖特征分布多峰区域，缓解单点采样导致的误差逐级放大。","验证端对整段候选做一次并行前向，按接受概率逐位判定，首个拒绝位用残差分布重采样，保证输出分布与目标模型一致。","被拒后缀的 KV 不写入缓存，仅对已接受 token 增量维护，避免无效缓存占用显存带宽与容量。","展开步数 K 增大时草稿与验证开销同步上升，长尾样本接受率下降会削弱收益，需回退逐 token 解码。","材料未给出接受率、加速比与吞吐数字，无法量化收益；机制上收益来自目标模型前向次数减少。","材料未给出硬件档位与量化方案，NVFP4 下特征扰动与采样稳定性未验证。","草稿头与目标模型共享词表映射，训练损失对齐目标下一 token 分布，服务于推理期接受率。","该方法与批量调度、前缀共享的耦合方式未给出，部署时需联合调优才能兑现吞吐。"],"anchors":[],"pitfalls":["把特征扰动强度当作免费收益：扰动过大虽覆盖多峰但会降低草稿与目标分布重合度，接受率反而下降。","忽略被拒后缀 KV 的清理：若缓存未及时丢弃，显存占用随展开步数线性上升，抵消延迟收益。","在 NVFP4 下直接套用：低精度特征扰动可能放大采样偏差，需先验证接受规则在量化下的分布一致性。"],"depth":"deep"},{"id":"paper-efficient-memory-management-for-larg-2023","title":"Efficient Memory Management for Large Language Model Serving with PagedAttention","title_zh":"分页注意力与显存管理","authors":["Woosuk Kwon","Zhuohan Li","Siyuan Zhuang","Ying Sheng","Lianmin Zheng","Cody Hao Yu","Joseph E. Gonzalez","Hao Zhang","Ion Stoica"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2309.06180","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大语言模型在线服务中，KV cache 随并发请求与序列长度线性膨胀，传统连续预分配造成严重内部与外部碎片，显存利用率常低于六成，直接压低批大小与吞吐。该论文把操作系统虚拟内存分页思想引入推理引擎，目标是在不改变模型数值的前提下，把 KV 缓存从整块预留改为按需分页，从而支撑更高并发与更长上下文。","problem":"连续 KV 预分配按最大长度预留，导致碎片与超额预留；请求长度差异大时长尾样本占住显存，批调度被迫缩小，吞吐与 SLO 同时受损；缺乏跨请求共享前缀的机制，相同系统提示被重复缓存。","core_idea":"将每个序列的 KV cache 切分为固定大小逻辑块，用块表映射到非连续物理块，按 token 生成逐步分配；引入写时复制与前缀共享，使相同前缀的多个序列指向同一物理块；配合抢占与重算，把显存不足转化为可恢复的调度事件而非失败。","architecture":"引擎维护逻辑块到物理块的块表，物理块池按固定块大小分配；调度器按 token 预算组批，序列进入运行队列后逐块追加；显存不足时按优先级抢占部分序列，释放其物理块并保留已生成 token，恢复时重算被换出的 KV；前缀共享通过块表引用计数实现，写时复制保证采样分支互不污染；采样与验证在连续批上执行，块表在每步解码前更新。","pipeline":["请求到达后按提示长度切分逻辑块，向物理块池申请块并写入提示阶段 KV。","调度器按剩余 token 预算与显存水位选择序列组批，长尾请求可被拆入后续批次。","解码每步为各序列追加一个逻辑块，块表映射到非连续物理块，避免连续扩容。","显存紧张时按优先级抢占序列，释放物理块并记录已生成位置，等待重算恢复。","前缀相同的序列共享物理块并增加引用计数，分支采样触发写时复制。","完成序列释放块与引用计数，块池回收供后续请求复用。"],"formula":"$$\\text{显存占用}=\\sum_{i=1}^{N}\\left\\lceil \\frac{L_i}{B}\\right\\rceil \\cdot B \\cdot s \\cdot h \\cdot d$$\n$$\\text{碎片率}=1-\\frac{\\sum_i L_i}{\\sum_i \\left\\lceil L_i/B\\right\\rceil \\cdot B}$$","training":"本文不涉及训练配方；其推理机制面向已训练模型的部署阶段。KV 块大小、批 token 预算与抢占阈值是部署超参，需按硬件显存档位与请求长度分布标定；块过大增加内部碎片，块过小增加块表开销与调度频率。数值精度沿用模型原有格式，论文未给出 NVFP4 或 FP8 下的采样稳定性数据。","walkthrough":"设块大小为 16 token，某请求提示 100 token，则占 7 个逻辑块，最后一块仅部分有效，产生内部碎片。若同时有四个请求共享同一 64 token 系统提示，则前 4 个逻辑块映射到同一组物理块，引用计数为 4；当其中一个请求进入分支采样，写时复制仅复制被修改的块。显存水位超过阈值时，调度器抢占最长且优先级最低的序列，释放其全部物理块，保留已生成 token 文本；该序列恢复时从提示重新计算 KV 并继续解码，代价是额外前向计算而非请求失败。","pseudocode":"初始化物理块池与空闲块表\n对每个请求：\n  按块大小切分提示，申请物理块并写 KV\n  块表记录逻辑块到物理块的映射\n循环解码步：\n  按 token 预算与显存水位选择运行序列\n  对每个序列追加逻辑块，必要时申请新物理块\n  若显存不足：\n    按优先级抢占序列，释放物理块并记录位置\n  若前缀块引用计数大于一且需写入：\n    复制该块后再写，更新块表\n  执行采样并更新序列状态\n完成序列：\n  递减引用计数，归还物理块","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"论文报告分页 KV 管理相比连续预分配显著提升可达批大小与吞吐，并支持前缀共享降低重复缓存；具体数据集、基线系统与吞吐倍率在给定材料中未给出，需以原论文表格为准。","limits":"块表与引用计数带来额外元数据开销；抢占重算增加前向计算量，长尾请求可能反复被换出；前缀共享对随机提示无效；材料未给出 NVFP4 采样稳定性与 Blackwell 档位数据。","ablations":"材料未给出消融实验细节；可核验的机制变量为块大小、批 token 预算与抢占策略，三者共同决定碎片率与重算代价的权衡。"},"innovation":["以固定大小逻辑块与非连续物理块映射替代连续 KV 预分配，从机制上消除外部碎片。","引入块级引用计数与前缀共享，使相同系统提示的多个序列复用同一物理块。","把显存不足转化为可恢复的抢占与重算事件，避免请求直接失败。"],"limitations":["块表与引用计数增加每步调度开销，块越小开销越大。","抢占重算消耗额外前向算力，长尾样本在高并发下可能被反复换出。","论文未覆盖 NVFP4 等低精度采样稳定性，也未给出 Blackwell 硬件档位数据。"],"impact":"该工作把操作系统分页思想确立为推理引擎 KV 管理的基本范式，后续 rollout 引擎与批量生成调度普遍沿用块表、前缀共享与抢占重算；对 RL 后训练推理而言，它使批量生成在长尾样本下仍能维持显存水位与吞吐，是解耦式 rollout 引擎容量规划的基础机制。","summary":"论文针对大模型服务中 KV cache 连续预分配造成的碎片与超额预留问题，提出分页式 KV 管理：逻辑块经块表映射到非连续物理块，按 token 逐步分配；前缀共享与写时复制降低重复缓存；显存不足时抢占并重算。该机制提升可达批大小与吞吐，代价是块表开销与重算算力；材料未给出具体数据集、基线数字与低精度采样稳定性结论。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布呈长尾：短提示与长上下文混合，块大小需兼顾内部碎片与块表开销。","批大小由 token 预算与显存水位共同决定，而非固定请求数，长尾请求可跨批拆分。","并发规模受物理块池容量约束，前缀共享比例高的负载可显著提高并发上限。","SLO 以每 token 延迟与尾延迟衡量，抢占重算会拉长被换出序列的完成时间。"],"train_recipe":["硬件档位与并行拓扑按部署集群给定，材料未给出 B200/B300/GB200 NVL72 具体配置。","量化方案沿用模型原有精度，论文未涉及 NVFP4/FP8 的采样稳定性验证。","KV 策略为固定块大小分页、块表映射、引用计数前缀共享与写时复制。","监控指标包括显存水位、碎片率、抢占次数与重算 token 量，用于调块大小与批预算。","失败模式为块池耗尽触发频繁抢占，表现为尾延迟上升与吞吐下降。"],"facts":["KV cache 按固定块大小切分为逻辑块，经块表映射到非连续物理块，按 token 生成逐步追加，避免按最大长度连续预留造成的超额占用。","前缀共享通过块级引用计数实现：相同系统提示的多个序列指向同一物理块，分支采样时写时复制仅复制被修改块，降低重复缓存。","显存不足时调度器按优先级抢占序列，释放物理块并保留已生成 token，恢复时重算被换出 KV，把显存压力转化为可恢复的重算代价。","块大小是核心部署超参：块过大增加最后一块的内部碎片，块过小增加块表元数据与每步调度开销，需按请求长度分布标定。","批调度以 token 预算与显存水位为约束，长尾请求可跨批拆分，吞吐提升来自可达批大小增加而非单请求加速。","论文未给出 NVFP4 或 FP8 下的采样稳定性数据，低精度 rollout 的数值风险需另行验证，不能由本工作直接外推。","材料未给出具体数据集、基线系统与吞吐倍率数字，容量规划应以原论文表格与自有负载压测为准。","该机制对随机提示的前缀共享收益有限，共享比例低的负载主要受益于碎片消除而非缓存复用。"],"anchors":[],"pitfalls":["把分页 KV 管理等同于低精度量化收益，混淆显存机制与数值精度两条线。","忽略抢占重算的算力代价，仅按显存利用率评估容量，导致尾延迟被低估。","块大小照搬默认值而不按请求长度分布标定，碎片率与调度开销可能同时恶化。"],"depth":"deep"},{"id":"paper-end-to-end-optimization-of-llm-drive-2025","title":"End-to-End Optimization of LLM-Driven Multi-Agent Search Systems via Heterogeneous-Group-Based Reinforcement Learning","title_zh":"异构组强化学习多智能体搜索端到端优化","authors":["Guanzhong Chen","Shaoxiong Yang","Chao Li","Wei Liu","Jian Luan","Zenglin Xu"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2506.02718","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型驱动的多智能体搜索系统把检索、规划、摘要等角色拆成多个智能体，端到端效果依赖各角色协同，但用强化学习后训练时，rollout 需要为每个智能体批量生成轨迹，奖励来自检索质量与最终答案验证器，推理负载呈异构、长尾、多轮特征，训练与生成若耦合会互相阻塞。","problem":"多智能体搜索的 rollout 轨迹长度与分支数差异大，同批异构请求共享前缀少，KV 复用率低；奖励模型与验证器推理与策略生成争抢同一批 GPU，长尾样本拖慢整批，权重同步与在途生成难以协调，吞吐与 SLO 同时受损。","core_idea":"以异构组为单位组织 rollout：按智能体角色与轨迹形态分组批量生成，组内共享前缀 KV、组间独立调度；rollout 引擎与训练进程解耦，奖励/验证器走独立推理服务；异步流水线中以版本号约束权重同步，长尾组单独排队以保护整体吞吐。","architecture":"系统分为策略生成引擎、奖励与验证器服务、轨迹缓冲与权重同步器三层。生成引擎按异构组维护连续批，组内做前缀共享与 KV 复用，组间按 token 预算调度；奖励服务独立部署，接收完成轨迹并回填分数；同步器在安全点推送新权重，旧版本在途请求按策略丢弃或续跑，监控覆盖队列深度、KV 命中率与长尾占比。","pipeline":["请求按智能体角色与预期轨迹形态归入异构组，进入对应组的待调度队列。","组内请求做前缀匹配，命中共享前缀的 KV 直接复用，未命中则预填并写入组级缓存。","连续批调度器按 token 预算拼批，长尾组单独排队，避免拖慢短轨迹组。","生成完成的轨迹送入独立奖励与验证器推理服务，打分后回填轨迹缓冲。","缓冲达到阈值后触发训练步，权重同步器在安全点向生成引擎推送新版本。","在途旧版本请求按版本策略续跑或丢弃，监控记录陈旧度与 KV 命中率。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{\\tau\\sim\\pi_{\\theta_{\\text{old}}}}\\left[\\sum_{t}\\min\\left(\\rho_t(\\theta)\\hat{A}_t,\\ \\text{clip}\\left(\\rho_t(\\theta),1-\\epsilon,1+\\epsilon\\right)\\hat{A}_t\\right)\\right],\\quad \\rho_t(\\theta)=\\frac{\\pi_\\theta(a_t\\mid s_t)}{\\pi_{\\theta_{\\text{old}}}(a_t\\mid s_t)}$$","training":"训练侧只消费轨迹缓冲中的样本，按异构组分层采样以平衡各角色梯度；奖励由独立验证器服务给出，训练进程不直接持有生成引擎的显存。权重同步采用版本号加安全点机制，生成引擎在批边界切换版本，旧版本在途请求按陈旧度阈值决定续跑或丢弃，从而把 off-policy 陈旧度控制在可监控范围内。","walkthrough":"一次迭代中，调度器先把新请求按角色分组，短轨迹组立即拼批预填并复用组内共享前缀的 KV；长尾组进入独立队列，避免占用主批 token 预算。生成完成后轨迹进入奖励服务打分，分数回填缓冲。缓冲达到阈值后训练步启动，同步器在批边界推送新权重，生成引擎切换到新版本，在途旧版本请求按陈旧度阈值处理。监控面板同时观察队列深度、KV 命中率与长尾占比，若长尾占比升高则临时扩大其独立配额。","pseudocode":"初始化生成引擎、奖励服务、轨迹缓冲与版本号\n循环直到训练结束：\n  接收请求 -> 按角色与轨迹形态归入异构组\n  对每组做前缀匹配 -> 命中则复用 KV，未命中则预填并写缓存\n  按 token 预算拼连续批 -> 长尾组单独排队\n  生成轨迹 -> 送奖励与验证器服务打分 -> 回填缓冲\n  若缓冲达到阈值 -> 执行训练步\n  在批边界推送新权重 -> 在途旧版本按陈旧度阈值续跑或丢弃\n  记录队列深度、KV 命中率、长尾占比与陈旧度","experiments":{"datasets":["材料未给出具体数据集名称，仅提及多智能体搜索任务与验证器打分流程"],"baselines":["材料未给出基线系统名称，仅提及训练与生成耦合的常规 rollout 方式"],"results":"材料未给出吞吐、延迟或成功率数字；可核验的机制是异构组分组调度、组内前缀 KV 复用、奖励服务独立部署与版本化权重同步，这些机制针对长尾拖慢与资源争抢两类失败模式。","limits":"材料未给出硬件档位、并行拓扑与量化方案，也未给出 NVFP4 下采样稳定性的实测；因此无法判断该方案在 B200/B300/GB200 NVL72 上的容量上限，长尾组独立配额对整体吞吐的实际影响亦未量化。","ablations":"材料未给出消融实验数字；从机制看，可消融项包括组内前缀共享开关、长尾组独立排队、奖励服务分离部署与版本同步阈值，但论文卡材料未提供对应结果。"},"innovation":["按智能体角色与轨迹形态划分异构组，组内共享前缀 KV、组间独立调度，提升复用率。","rollout 引擎与训练进程解耦，奖励与验证器走独立推理服务，避免显存与算力争抢。","以版本号加安全点约束权重同步，把在途请求的 off-policy 陈旧度纳入可监控范围。"],"limitations":["材料未给出硬件档位、并行拓扑与量化方案，无法评估 Blackwell 部署容量。","材料未给出 NVFP4 下采样稳定性的实测，低精度对多轮轨迹的影响未知。","材料未给出吞吐、延迟与长尾占比数字，机制收益缺乏量化支撑。"],"impact":"该工作把多智能体搜索的 rollout 从单一混批改为异构组调度，并把奖励推理从训练进程中剥离，为 RL 后训练推理的引擎解耦与 KV 复用提供了可落地的组织方式；其版本化同步思路可迁移到分离式预填/解码与长尾吞吐治理。","summary":"论文面向大模型驱动的多智能体搜索系统，用异构组强化学习组织端到端优化。推理侧按智能体角色与轨迹形态分组批量生成，组内做前缀共享与 KV 复用，组间按 token 预算调度，长尾组独立排队；奖励与验证器推理独立部署，轨迹缓冲驱动训练步，权重以版本号在批边界同步。材料未给出硬件、量化与吞吐数字，机制价值集中在解耦、复用与陈旧度可控三点。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求按智能体角色与预期轨迹形态分组，组内轨迹长度相近以提升拼批效率。","组内前缀匹配后复用 KV，未命中请求先预填并写入组级缓存，控制重复预填。","连续批按 token 预算拼批，长尾组单独排队并设独立配额，防止拖慢短轨迹组。","并发与 SLO 未给出，监控以队列深度、KV 命中率与长尾占比作为调度反馈。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署上生成引擎与奖励服务分卡或分节点放置。","量化方案材料未给出，NVFP4 下采样稳定性未实测，需在低精度下监控轨迹质量。","KV 策略为组内前缀共享加组级缓存，批边界清理过期条目以控制显存。","权重同步采用版本号加安全点，在途旧版本按陈旧度阈值续跑或丢弃。","监控覆盖队列深度、KV 命中率、长尾占比与在途请求陈旧度四项指标。"],"facts":["异构组按智能体角色与轨迹形态划分，组内轨迹长度相近才能拼批，组间按 token 预算独立调度，长尾组单独排队以避免占用主批预算。","组内前缀匹配命中后直接复用 KV，未命中请求先预填并写入组级缓存，缓存条目在批边界清理，复用率受前缀重合度与清理策略共同约束。","奖励与验证器推理独立部署为服务，接收完成轨迹并回填分数，训练进程不持有生成引擎显存，避免奖励推理与策略生成争抢同一批 GPU。","权重同步以版本号加安全点实现，生成引擎在批边界切换版本，在途旧版本请求按陈旧度阈值续跑或丢弃，陈旧度成为可监控的调度参数。","长尾组独立配额是吞吐保护机制，短轨迹组先拼批以维持主批利用率，长尾占比升高时扩大其配额，代价是主批 token 预算被压缩。","材料未给出硬件档位、并行拓扑与量化方案，B200/B300/GB200 NVL72 上的容量上限与 NVFP4 采样稳定性均无法从材料核验。","训练侧按异构组分层采样以平衡各角色梯度，轨迹缓冲达到阈值触发训练步，采样比例与阈值材料未给出，属于部署配方中的可调参数。","监控指标包括队列深度、KV 命中率、长尾占比与在途请求陈旧度，四项指标共同决定调度器是否调整组配额与版本切换节奏。"],"anchors":[],"pitfalls":["材料未给出硬件与量化数字，若直接套用 NVFP4 需自行验证多轮轨迹的采样稳定性。","异构组划分依赖轨迹形态先验，形态估计偏差会导致组内拼批效率下降与 KV 复用率走低。","版本同步阈值过松会放大 off-policy 陈旧度，过紧则频繁丢弃在途请求，浪费已生成 token。"],"depth":"deep"},{"id":"paper-essa-evolutionary-strategies-for-sca-2025","title":"ESSA: Evolutionary Strategies for Scalable Alignment","title_zh":"ESSA：进化策略对齐与Rollout解耦","authors":["Daria Korotyshova","Boris Shaposhnikov","Alexey Malakhov","Alexey Khokhulin","Nikita Surnachev","Kirill Ovcharenko","George Bredis","Alexey Gorbatovski","Viacheslav Sinii","Daniil Gavrilov"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2507.04453","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"ESSA面向RL后训练中的对齐阶段，把进化策略（ES）用于大规模策略改进，从而绕开传统PPO式rollout与训练强耦合带来的采样开销。论文卡只关心推理侧：批量生成如何调度、KV如何复用、奖励模型与验证器如何服务、异步流水线如何与权重同步衔接，以及Blackwell档位下NVFP4采样稳定性对吞吐与SLO的影响。","problem":"RL后训练推理中，rollout引擎与训练进程耦合导致批量生成调度受梯度步节奏牵制，长尾样本拖尾使GPU空转；同时奖励模型与验证器推理需独立容量，权重同步与KV前缀共享缺少统一机制描述。","core_idea":"用进化策略替代策略梯度式rollout，使批量生成可按固定批大小与固定SLO独立调度，rollout引擎与训练解耦；以KV前缀共享复用提示词前缀，奖励模型/验证器走独立服务池，异步流水线在权重版本切换时做短窗口staleness容忍。","architecture":"推理侧分三层：rollout引擎按请求长度分布组批，维护前缀KV缓存并按前缀哈希命中复用；奖励模型与验证器作为独立serving池，与rollout引擎通过队列解耦；训练侧以异步流水线消费rollout结果，权重同步采用版本号加短窗口，允许在途请求使用旧权重完成。硬件档位按B200/B300/GB200 NVL72分档，量化方案在NVFP4与FP8间按采样稳定性选择。","pipeline":["请求进入rollout引擎，按提示词前缀哈希查询KV缓存，命中则复用前缀KV，未命中则预填。","按请求长度分布与并发上限组批，长尾样本进入低优先级队列，避免拖尾阻塞主批。","批量生成完成后，样本送入独立奖励模型/验证器serving池打分，池与rollout引擎队列解耦。","打分结果进入异步流水线，训练侧按版本号消费；权重同步在短窗口内允许旧版本在途请求完成。","监控KV命中率、批利用率与长尾队列深度，按SLO反馈调节批大小与并发上限。"],"formula":"$$\\mathcal{L}_{\\mathrm{ES}}=\\mathbb{E}_{\\epsilon\\sim\\mathcal{N}(0,\\sigma^{2})}\\left[F(\\theta+\\epsilon)\\,\\epsilon\\right]$$","training":"训练侧只消费rollout引擎产出的样本与奖励分数，不直接驱动生成；权重更新后通过版本号广播到rollout引擎，短窗口内允许在途请求以旧权重完成以换取吞吐。奖励模型与验证器独立扩容，避免与生成争抢显存；KV前缀共享降低重复预填代价。","walkthrough":"假设一个对齐批次含长短混合提示词：rollout引擎先按前缀哈希批量命中共享系统提示的KV，未命中的长提示走预填；组批时把长尾样本放入低优先级队列，主批按固定token预算推进。生成结束后样本进入奖励池打分，打分与下一批生成重叠。训练侧按版本号消费，权重同步时短窗口内旧版本请求继续完成，监控面板观察KV命中率与长尾队列深度，若拖尾超阈值则下调并发上限。","pseudocode":"初始化 rollout 引擎与奖励池，加载权重版本 v0\n循环：\n  取请求，按前缀哈希查 KV 缓存\n  命中 -> 复用前缀 KV；未命中 -> 预填并写缓存\n  按 token 预算组主批，长尾样本入低优先级队列\n  批量生成，产出样本\n  样本入奖励池打分（与下一批生成重叠）\n  训练侧按版本号消费样本\n  权重更新 -> 广播版本号 v+1，短窗口容忍旧版本在途请求\n  监控 KV 命中率、批利用率、长尾队列深度，反馈调批大小","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字；可核验的机制点是rollout引擎与训练解耦后批量生成按固定批大小与SLO独立调度，奖励模型/验证器独立serving池与生成重叠，KV前缀共享降低重复预填。吞吐与SLO收益数字未给出。","limits":"材料未给出规模与硬件档位实测；NVFP4下采样稳定性、长尾样本拖尾对批利用率的影响、权重同步短窗口的staleness上界均未量化，失败模式与监控阈值未给出。","ablations":"材料未给出消融实验；可讨论的消融维度包括KV前缀共享开关、奖励池独立serving与耦合serving对比、短窗口staleness长度对吞吐与样本质量的影响，均无数字。"},"innovation":["以进化策略替代策略梯度式rollout，使批量生成可按固定批大小与SLO独立调度。","rollout引擎与训练解耦，奖励模型/验证器走独立serving池并与生成重叠。","KV前缀共享按前缀哈希复用，降低重复预填代价并支撑长尾队列分级。"],"limitations":["材料未给出NVFP4采样稳定性实测，量化方案选择缺少数据支撑。","权重同步短窗口的staleness上界未量化，旧版本在途请求对样本质量影响未给出。","长尾样本拖尾与批利用率关系未给出，监控阈值与失败模式缺少具体机制。"],"impact":"若按论文卡所述机制落地，ESSA把RL后训练推理的容量问题从训练耦合中拆出：rollout引擎按SLO独立组批，奖励池独立扩容，KV前缀共享降低预填开销，权重同步短窗口换取吞吐。对Blackwell部署的意义在于把NVFP4采样稳定性与长尾吞吐作为独立可监控项。","summary":"ESSA用进化策略做大规模对齐，推理侧的关键是把rollout引擎与训练解耦：批量生成按固定批大小与SLO独立调度，奖励模型/验证器独立serving并与生成重叠，KV前缀共享复用提示词前缀，权重同步以版本号加短窗口容忍staleness。论文卡材料未给出数据集、基线数字与硬件实测，NVFP4采样稳定性与长尾拖尾仍是待核验的部署代价。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布为长短混合，长尾样本进入低优先级队列，主批按固定token预算推进。","批大小按token预算与并发上限设定，避免长尾拖尾阻塞主批导致GPU空转。","并发上限按SLO反馈调节，KV命中率与长尾队列深度作为调节信号。","奖励模型/验证器打分请求与生成请求分队列，打分与下一批生成重叠。"],"train_recipe":["硬件档位按B200/B300/GB200 NVL72分档，并行拓扑与量化方案按档位选择。","量化在NVFP4与FP8间按采样稳定性选择，采样稳定性作为独立监控项。","KV策略为前缀哈希共享加LRU淘汰，命中率纳入监控面板。","权重同步采用版本号广播加短窗口，允许旧版本在途请求完成以换吞吐。","监控批利用率、长尾队列深度、KV命中率与staleness窗口，超阈值下调并发。"],"facts":["rollout引擎与训练解耦后，批量生成按固定token预算组主批，长尾样本进低优先级队列，避免拖尾阻塞主批造成GPU空转。","奖励模型与验证器作为独立serving池，与rollout引擎通过队列解耦，打分与下一批生成重叠以提升批利用率。","KV前缀共享按前缀哈希命中复用，未命中才预填并写缓存，降低重复预填的显存与算力代价。","权重同步采用版本号广播加短窗口，允许在途请求以旧权重完成，staleness上界未给出，需监控样本质量。","量化方案在NVFP4与FP8间按采样稳定性选择，NVFP4下采样稳定性未给出实测，属待核验部署代价。","长尾样本拖尾使批利用率下降，监控长尾队列深度并按SLO反馈下调并发上限，具体阈值未给出。","硬件档位按B200/B300/GB200 NVL72分档，并行拓扑与量化随档位选择，材料未给出切分细节。","失败模式包括KV缓存击穿导致预填尖峰、奖励池排队反压生成、权重同步窗口过长引入旧版本样本。"],"anchors":[],"pitfalls":["材料未给出数据集、基线数字与硬件实测，任何吞吐与SLO收益表述都需标注未给出。","NVFP4采样稳定性与长尾拖尾对批利用率的影响未量化，不能把机制描述当作实测结论。","权重同步短窗口的staleness上界未给出，旧版本在途请求对样本质量的影响需单独监控。"],"depth":"deep"},{"id":"paper-fast-inference-from-transformers-via-2022","title":"Fast Inference from Transformers via Speculative Decoding","title_zh":"投机解码加速Transformer推理","authors":["Yaniv Leviathan","Matan Kalman","Yossi Matias"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2211.17192","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"自回归大模型逐token解码受内存带宽与串行依赖限制，单请求延迟高、GPU利用率低。工程上常以增大批大小摊薄权重读取，但小批量或低并发场景下解码仍受限于访存。投机解码提出用廉价草稿模型先猜多个token，再由目标模型一次并行验证，把串行解码步数换成并行验证吞吐，属于推理机制层面的算子与调度优化。","problem":"目标模型逐token采样时每步只产出一个token，权重读取与KV cache访存开销无法被计算摊薄，导致解码阶段算术强度低、延迟随序列长度线性增长；如何在保证输出分布与目标模型完全一致的前提下减少目标模型前向次数。","core_idea":"用一个更小更快的草稿模型自回归生成γ个候选token，目标模型对这γ+1个位置做一次并行前向，得到各位置概率后用拒绝采样逐位判定接受或拒绝，接受前缀后由目标模型补采一个修正token；被拒绝则丢弃其后草稿并回退。接受长度期望由草稿与目标分布的一致性决定，输出分布严格等价于目标模型采样。","architecture":"系统由草稿模型与目标模型两级组成：草稿模型可为独立小模型、目标模型的部分层或蒸馏模型，负责低成本自回归起草；目标模型负责单次并行验证。验证时把草稿token拼入输入，一次前向得到每个位置的logits，按位置比较草稿概率与目标概率做拒绝采样。KV cache需同时维护草稿与目标两套，接受前缀后目标KV按接受长度截断复用，拒绝位置之后的草稿KV作废。批调度需处理不同请求接受长度不一导致的变长回退。","pipeline":["请求到达后由调度器分配草稿模型与目标模型实例，初始化两套KV cache并确定投机长度γ。","草稿模型自回归生成γ个候选token，逐位记录其采样概率，形成草稿序列与概率向量。","将草稿token拼接到已接受前缀后，目标模型对γ+1个位置做一次并行前向，输出各位置目标分布。","按位置执行拒绝采样：以目标概率与草稿概率之比判定接受，遇到首个拒绝即截断，接受前缀保留。","对首个拒绝位置由目标模型分布重新采样一个修正token，丢弃其后全部草稿token及其KV。","按接受长度截断并复用目标KV cache，返回本轮产出token，进入下一轮起草或结束请求。"],"formula":"$$\\mathbb{E}[\\text{accepted}]=\\sum_{i=1}^{\\gamma+1}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_{\\text{target}}(x_j\\mid x_{<j})}{p_{\\text{draft}}(x_j\\mid x_{<j})}\\right)$$","training":"本论文不涉及训练配方；草稿模型可为独立预训练小模型或由目标模型蒸馏得到，其与目标模型分布的一致性直接决定接受率。工程上草稿模型越小单步越快但接受率越低，需在草稿前向成本与目标模型并行验证成本之间权衡γ取值；γ过大时验证批次变长、KV占用上升，γ过小时加速比受限。该机制不改变目标模型权重与采样温度设定。","walkthrough":"设γ=4，草稿模型先产出4个候选token及其概率。目标模型把已接受前缀加这4个token一次前向，得到5个位置的目标分布。逐位比较：第1位目标概率高于草稿概率则接受，第2位若目标概率低于草稿概率则按比值概率接受，一旦某位被拒绝即停止，该位置由目标分布重采样一个token，其后草稿全部丢弃。若4位全接受，则额外从目标模型第5位分布采一个token，本轮共产出5个token而目标模型只做了一次前向。KV cache按实际接受长度截断，被拒位置之后的草稿KV释放，下轮从新前缀继续起草。批内不同请求接受长度不同，调度器需按变长回退重组批次。","pseudocode":"输入：前缀x，草稿模型q，目标模型p，投机长度γ\n循环直到满足停止条件：\n  草稿序列D、概率Q ← q自回归采样γ个token\n  目标分布P ← p对x拼接D做一次并行前向\n  接受长度n ← 0\n  对i从1到γ：\n    若 random() < min(1, P[i]/Q[i])：n ← n+1\n    否则：跳出\n  若 n < γ：\n    修正token ← 从P[n+1]采样\n    丢弃D中n之后的token及其KV\n  否则：\n    修正token ← 从P[γ+1]采样\n  输出D前n个token与修正token\n  x ← x拼接本轮输出\n  按接受长度截断并复用目标KV cache","experiments":{"datasets":["未给出"],"baselines":["目标模型朴素自回归解码","未给出其他基线"],"results":"材料未给出具体数据集、模型规模与加速比数字；机制上加速来自用一次目标模型并行前向替代多次串行前向，收益取决于草稿模型接受率与γ取值，接受率越高、草稿越廉价则目标模型前向次数下降越明显。","limits":"加速比受草稿模型与目标模型分布一致性制约，分布偏差大时接受率低、回退频繁；γ过大增加验证批次长度与KV占用，γ过小则并行验证摊薄不足；批内变长接受导致调度复杂，长尾请求可能拉低整体吞吐。","ablations":"材料未给出消融实验数字；可核验的机制变量为投机长度γ、草稿模型规模与草稿来源（独立小模型或蒸馏），三者共同决定接受率与单轮目标前向成本。"},"innovation":["以拒绝采样保证投机解码输出分布与目标模型严格一致，不引入近似偏差。","把串行逐token解码转为一次并行验证多位置，降低目标模型前向次数。","草稿与目标两级KV cache按接受长度截断复用，形成可调度的变长回退机制。"],"limitations":["加速效果强依赖草稿模型质量，分布不一致时接受率低、收益退化。","批内请求接受长度不一，变长回退增加调度与KV管理复杂度。","投机长度γ需人工权衡，过大过小都削弱吞吐收益，缺乏自适应机制。"],"impact":"该机制为后续rollout引擎与批量生成调度提供了可复用的推理原语：草稿与目标分离对应预填/解码解耦，接受长度变长回退对应批调度与KV复用策略，拒绝采样保证分布一致使其可安全用于RL后训练的采样环节。","summary":"论文提出投机解码：用小草稿模型自回归起草γ个token，目标模型一次并行前向验证，按目标与草稿概率比值做拒绝采样，接受前缀后由目标模型补采修正token。输出分布与目标模型严格一致，加速来自把多次串行前向换成一次并行验证。工程代价是两套KV cache、变长回退调度与γ取值权衡；接受率由草稿与目标分布一致性决定，是后续rollout引擎解耦与批量调度的重要推理原语。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求序列，草稿阶段逐token生成、验证阶段按γ+1位置并行，请求长度分布直接影响KV占用。","批大小需容纳不同接受长度的请求，调度器按变长回退重组批次，并发上升时草稿与目标实例需分别扩容。","SLO以单请求token延迟与目标模型前向次数衡量，长尾请求因接受率低而回退频繁，需单独监控。"],"train_recipe":["部署采用草稿模型与目标模型两级实例，草稿可独立小模型或目标模型蒸馏，二者权重同步需版本一致。","KV策略为草稿与目标双cache，按接受长度截断复用，被拒位置之后KV立即释放以控制显存。","量化与硬件档位材料未给出；监控重点为接受率、平均接受长度、目标前向次数与变长回退频次。"],"facts":["投机解码每轮由草稿模型自回归生成γ个候选token，目标模型对γ+1个位置做一次并行前向，把串行解码步数换成并行验证吞吐。","验证采用拒绝采样：逐位以min(1, 目标概率/草稿概率)判定接受，首个拒绝即截断，保证输出分布与目标模型严格一致。","接受长度期望等于各前缀位置接受概率连乘之和，草稿与目标分布越一致接受率越高，目标模型前向次数下降越明显。","系统需维护草稿与目标两套KV cache，接受前缀后目标KV按接受长度截断复用，被拒位置之后的草稿KV作废释放。","批内不同请求接受长度不一，调度器需按变长回退重组批次，长尾低接受率请求会拉低整体吞吐并增加调度开销。","投机长度γ是核心权衡：γ过大使验证批次变长、KV占用上升，γ过小则并行验证摊薄不足，加速比受限。","草稿模型可为独立小模型或目标模型蒸馏所得，其单步成本与接受率共同决定净收益，草稿越廉价越有利。","该机制不改变目标模型权重与采样温度，可作为rollout引擎中采样环节的推理原语，与预填/解码解耦正交组合。"],"anchors":[],"pitfalls":["把加速比当作固定常数：实际收益随草稿质量与γ变化，低接受率场景可能因验证开销反而变慢。","忽略变长回退的调度代价：批内接受长度差异大时，KV截断与批次重组会吃掉并行验证带来的吞吐收益。"],"depth":"deep"},{"id":"paper-flare-a-full-lifecycle-dense-supervi-2026","title":"FLARE: A Full-Lifecycle Dense Supervision Paradigm for Long-Horizon Coding Agents via Generative Reward Model","title_zh":"FLARE 全生命周期稠密监督长程编码智能体","authors":["Jingxuan Xu","Gang Wu","Yanan Wu","Yutao Mou","Songwei Yu","Tianzhuang He","Zhengshuo Gong","Zhao Liu","Zihang Xu","Wenqiang Zhu","Xinping Lei","Weihao Li"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2609.23808","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"长程编码智能体的强化学习后训练依赖稀疏的结果奖励，rollout 阶段生成的轨迹很长、样本长尾严重，奖励模型与验证器的推理又和策略生成争抢同一批 GPU。FLARE 提出用生成式奖励模型在全生命周期提供稠密监督，这要求把 rollout 引擎与训练解耦、对批量生成做调度、复用 KV 与前缀，并在 NVFP4 量化下保持采样稳定。","problem":"稀疏结果奖励无法对长程编码轨迹的中间步骤给出信号，而稠密监督需要额外的奖励模型与验证器推理；若与策略 rollout 共享同一推理栈，会造成显存争用、批调度抖动与长尾样本拖尾，吞吐与 SLO 同时恶化。","core_idea":"用生成式奖励模型替代标量奖励头，在 rollout 的每个阶段注入稠密监督信号；把 rollout 引擎与训练进程解耦，奖励模型与验证器走独立服务档位，策略生成侧复用前缀 KV 并按长尾样本单独排队，从机制上把稠密监督的额外推理代价隔离出去。","architecture":"系统分为策略 rollout 引擎、生成式奖励模型服务、验证器服务与训练侧权重同步四个部分。rollout 引擎按请求长度分桶，长尾样本进入低优先级队列；奖励模型服务持有独立 KV 缓存并支持前缀共享，验证器只对通过初筛的样本做二次推理；训练侧通过异步流水线接收轨迹与稠密奖励，权重同步以版本号对齐，避免 rollout 读到半更新权重。","pipeline":["策略侧接收编码任务请求，按提示前缀做 KV 前缀共享并分桶入队。","rollout 引擎批量生成轨迹，长尾样本转入独立低优先级队列避免阻塞主批。","生成式奖励模型对轨迹的中间步骤逐段打分，复用共享前缀 KV 降低重复预填。","验证器对初筛通过的样本做二次校验，输出稠密监督标签。","异步流水线把轨迹与奖励送回训练侧，按版本号做权重同步并丢弃过期样本。"],"formula":"$$ r_{\\text{dense}}(\\tau)=\\sum_{t=1}^{T}\\gamma^{\\,t}\\,g_\\phi(s_t,a_t)\\,,\\quad \\mathcal{L}=\\mathbb{E}_{\\tau\\sim\\pi_\\theta}\\Big[\\sum_{t}\\mathrm{KL}\\big(\\pi_\\theta(\\cdot\\mid s_t)\\,\\|\\,\\pi_{\\text{ref}}(\\cdot\\mid s_t)\\big)-\\lambda\\,r_{\\text{dense}}(\\tau)\\Big] $$","training":"训练侧不更新奖励模型本身，只消费其稠密打分；策略更新采用带 KL 约束的策略梯度，rollout 与训练通过异步流水线解耦，权重同步以版本号对齐，过期轨迹按阈值丢弃以控制 off-policy 陈旧度。稠密奖励按时间步折扣累加，长尾样本单独计权，避免其梯度淹没主批信号。","walkthrough":"一次迭代中，rollout 引擎先按前缀共享预填 KV，把短请求打成大批、长请求放入低优先级队列；生成式奖励模型对每条轨迹逐步打分，验证器只复核初筛通过者；打分结果与轨迹一起进入异步队列，训练侧按版本号取用，若权重已更新则丢弃陈旧样本。长尾样本在队列中等待但不占用主批显存，主批吞吐因此不被拖尾；NVFP4 量化下采样温度与 top-p 需固定并在奖励打分前做数值校验，防止低精度采样导致奖励分布漂移。","pseudocode":"→ 策略侧接收编码任务请求，按提示前缀做 KV 前缀共享并分桶入队。\n→ rollout 引擎批量生成轨迹，长尾样本转入独立低优先级队列避免阻塞主批。\n→ 生成式奖励模型对轨迹的中间步骤逐段打分，复用共享前缀 KV 降低重复预填。\n→ 验证器对初筛通过的样本做二次校验，输出稠密监督标签。\n→ 异步流水线把轨迹与奖励送回训练侧，按版本号做权重同步并丢弃过期样本。","experiments":{"datasets":["长程编码智能体任务集（具体规模未给出）"],"baselines":["稀疏结果奖励的 RL 后训练基线"],"results":"论文声称稠密监督改善了长程编码任务的学习信号密度，但未给出吞吐、延迟与硬件档位的具体数字；rollout 与训练解耦后的批调度收益、KV 复用命中率均未量化。","limits":"缺少 B200/B300/GB200 NVL72 档位下的吞吐与 SLO 数据，NVFP4 采样稳定性只有定性描述，长尾样本的排队策略与丢弃阈值未给出具体数值。","ablations":"材料未给出消融实验的具体配置与数字，仅提及生成式奖励模型与验证器两级结构为关键设计。"},"innovation":["用生成式奖励模型在 rollout 全生命周期提供逐步稠密监督，替代稀疏结果奖励。","rollout 引擎与训练解耦，奖励模型与验证器走独立服务档位隔离显存争用。","长尾样本独立低优先级队列加前缀 KV 共享，控制拖尾对主批吞吐的影响。"],"limitations":["缺少 Blackwell 具体硬件档位下的吞吐、延迟与 SLO 实测数据。","NVFP4 量化下采样稳定性仅有定性讨论，无温度与 top-p 的数值校验方案。","长尾队列的优先级阈值与过期样本丢弃阈值未给出可核验数字。"],"impact":"为 RL 后训练推理提供了一种把稠密监督推理代价隔离到独立服务档位的工程思路，对 rollout 引擎解耦、批量调度与 KV 复用有直接参考价值，但落地到 Blackwell 部署仍需补齐量化与容量数据。","summary":"FLARE 针对长程编码智能体的稀疏奖励问题，提出生成式奖励模型驱动的全生命周期稠密监督，并把 rollout 引擎与训练解耦、奖励模型与验证器独立服务、长尾样本单独排队、前缀 KV 共享。论文卡可用的机制事实集中在解耦架构与两级奖励推理，但硬件档位、吞吐与 NVFP4 采样稳定性的具体数字均未给出，后续写作只能引用其机制而非性能结论。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布呈长尾，短编码任务打成大批，长轨迹进入低优先级队列。","批大小按前缀共享后的 KV 占用动态调整，避免长尾样本挤占主批显存。","并发由奖励模型与验证器两级服务的独立配额控制，防止打分侧成为瓶颈。","SLO 以主批吞吐为主、长尾样本延迟为辅，长尾不阻塞主批提交。"],"train_recipe":["硬件档位材料未给出，部署需按 B200/B300/GB200 NVL72 档位另行标定。","并行拓扑未给出，rollout 与训练按异步流水线解耦并以版本号对齐权重。","量化方案提及 NVFP4，采样温度与 top-p 需固定并在打分前做数值校验。","KV 策略为前缀共享加独立奖励模型缓存，长尾样本单独排队。","监控关注过期样本丢弃率、前缀命中率与长尾队列等待时长。"],"facts":["rollout 引擎与训练进程解耦，权重同步以版本号对齐，过期轨迹按阈值丢弃以控制 off-policy 陈旧度，但阈值数值未给出。","生成式奖励模型对轨迹逐步打分并按时间步折扣累加，形成稠密奖励，替代稀疏结果奖励头。","验证器只对初筛通过的样本做二次推理，形成两级奖励推理结构，降低验证器服务负载。","前缀 KV 共享用于降低奖励模型重复预填开销，命中率与显存节省未给出具体数字。","长尾样本进入独立低优先级队列，避免拖尾阻塞主批，队列优先级阈值未给出。","NVFP4 量化下采样稳定性仅有定性讨论，缺少温度与 top-p 的数值校验结果。","论文未给出 B200/B300/GB200 NVL72 档位下的吞吐、延迟与 SLO 实测数据。","异步流水线把轨迹与稠密奖励送回训练侧，训练侧不更新奖励模型本身。"],"anchors":[],"pitfalls":["把生成式奖励模型的稠密监督当成免费收益，忽略其独立服务档位的显存与延迟代价。","在 NVFP4 下未固定采样参数就做奖励打分，可能把量化噪声误判为策略退化。","长尾队列缺少丢弃阈值时，过期样本会污染训练侧梯度。"],"depth":"shallow"},{"id":"paper-fp4-explore-bf16-train-diffusion-rei-2026","title":"FP4 Explore, BF16 Train: Diffusion Reinforcement Learning via Efficient Rollout Scaling","title_zh":"FP4探索与BF16训练的扩散RL推理","authors":["Yitong Li","Junsong Chen","Shuchen Xue","Pengcuo Zeren","Siyuan Fu","Dinghao Yang","Yangyang Tang","Junjie Bai","Ping Luo","Song Han","Enze Xie"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-sampling-stability","links":{"paper":"https://arxiv.org/abs/2604.06916","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"扩散强化学习后训练中的 rollout 需要反复批量采样、去噪与奖励评估，采样步数多、序列长，使推理成为吞吐瓶颈；同时训练侧对数值稳定与权重精度敏感。该论文关注把探索阶段的采样推到低精度 FP4，而训练仍保持 BF16，以降低 rollout 的显存与算力代价，并把 rollout 引擎与训练解耦，形成异步流水线。","problem":"扩散 RL 的 rollout 采样成本高，若整条链路都用 BF16 则显存与算力受限；若整条链路都用 FP4 则训练与奖励信号不稳定。需要回答：哪些环节可以安全降到 FP4、哪些必须留在 BF16，以及解耦后权重同步与长尾样本如何影响吞吐。","core_idea":"把探索性采样（去噪轨迹生成）放到 FP4 精度执行以扩大批量与并发，把训练更新与关键数值路径保留在 BF16；rollout 引擎与训练进程解耦，通过异步权重同步与 KV／前缀复用降低重复计算，并对长尾样本做批量调度以稳定吞吐。","architecture":"系统分为训练侧与 rollout 侧：训练侧维护 BF16 主权重并周期性导出推理权重；rollout 侧以 FP4 执行扩散去噪采样，按请求长度与并发做批调度，复用前缀与 KV 缓存；奖励模型／验证器单独服务并对采样结果打分；两侧通过异步队列与权重版本号衔接，监控采样稳定性与长尾队列深度。","pipeline":["训练侧以 BF16 更新主权重，并按固定间隔导出可推理权重快照与版本号。","rollout 引擎拉取快照，将权重转换为 FP4 执行格式并加载到采样实例。","请求按长度分布进入批调度队列，短样本优先合批，长尾样本进入独立队列等待。","扩散去噪在 FP4 下逐步采样，前缀与已生成 KV 缓存被复用，减少重复前向。","采样结果送入奖励模型／验证器推理服务打分，分数回传训练侧形成经验批次。","训练侧消费经验批次更新 BF16 权重，版本号递增并触发下一轮异步同步。"],"formula":"$$\\tilde{x}_{t-1}=\\mathrm{FP4}\\big(\\mathrm{Denoise}_{\\theta_{\\mathrm{BF16}}}(x_t,t)\\big),\\quad \\mathcal{L}=\\mathbb{E}_{(x,\\,r)\\sim\\mathcal{D}_{\\mathrm{rollout}}}\\big[\\ell_{\\mathrm{BF16}}(\\theta;x,r)\\big]$$","training":"训练侧保持 BF16 主权重与损失计算，rollout 侧以 FP4 执行去噪采样；两侧解耦为异步流水线，权重按版本快照同步，允许 rollout 使用略旧权重以换取吞吐。奖励模型／验证器独立部署，打分结果进入经验池；长尾样本单独排队以避免拖慢整体批调度。论文未给出具体并行拓扑与硬件档位数字。","walkthrough":"一轮迭代中，训练进程先完成 BF16 更新并导出权重快照；rollout 引擎加载快照后转为 FP4，按请求长度分布合批，短样本快速填充批次，长尾样本进入低优先级队列。去噪采样复用前缀与 KV 缓存，采样完成后由奖励服务打分并回传。训练侧按版本号消费经验，若发现 FP4 采样分布偏移则回退该批或提高精度重采样。整个链路以异步队列衔接，权重同步与采样重叠，从而把 rollout 的显存与算力代价压到 FP4 档位，同时把数值敏感路径留在 BF16。","pseudocode":"训练侧：BF16 权重更新 -> 导出快照与版本号\nrollout 侧：拉取快照 -> 转 FP4 执行格式\n调度：按长度分桶 -> 短样本合批 -> 长尾入独立队列\n采样：FP4 去噪 -> 复用前缀与 KV 缓存 -> 输出样本\n打分：奖励模型／验证器推理 -> 分数回传经验池\n同步：训练消费经验 -> 版本号递增 -> 触发下一轮异步同步\n监控：采样分布偏移 -> 回退该批或提高精度重采样","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线系统"],"results":"论文主张 FP4 探索加 BF16 训练可在保持采样稳定性的同时扩大 rollout 批量与并发；材料未给出吞吐提升倍数、采样步数与批量规模的具体数字，相关指标均未给出。","limits":"材料未给出硬件档位、并行拓扑与量化校准细节；FP4 采样在长尾样本与多步去噪下的分布偏移程度未量化，奖励模型打分的精度影响也缺少数据。","ablations":"材料未给出消融实验设置；可推断的消融维度包括探索精度（FP4 与 BF16）、rollout 与训练是否解耦、前缀与 KV 复用开关，但具体数值未给出。"},"innovation":["把探索性采样与训练更新拆到不同数值精度，FP4 承担批量采样、BF16 守住训练稳定。","rollout 引擎与训练解耦为异步流水线，以权重版本快照衔接并允许轻微滞后。","面向扩散多步去噪做批调度与前缀／KV 复用，缓解长尾样本对吞吐的拖累。"],"limitations":["材料未给出硬件档位、并行拓扑与量化校准方案，部署代价难以复核。","FP4 采样分布偏移与奖励打分精度影响缺少量化数据。","长尾样本队列策略与权重同步滞后上限未给出具体阈值。"],"impact":"该工作把 RL 后训练 rollout 的精度分层与引擎解耦结合起来，为 Blackwell 档位上以 FP4 扩批量、以 BF16 保稳定的部署方式提供思路；其工程价值在于把采样吞吐与训练数值稳定性拆开治理，但具体收益仍待材料补充。","summary":"论文提出 FP4 探索、BF16 训练的扩散 RL rollout 方案：采样侧以 FP4 执行去噪并做批调度与前缀／KV 复用，训练侧保持 BF16 并异步消费经验；rollout 引擎与训练解耦，通过权重版本快照同步。材料未给出硬件档位、并行拓扑与量化细节，吞吐与稳定性收益缺少具体数字，属于机制层面的部署思路。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布覆盖短样本与长尾样本，短样本优先合批以填满批次。","批大小与并发按 FP4 显存档位设定，长尾样本进入独立低优先级队列。","SLO 以采样吞吐与队列等待时间为约束，长尾样本允许更长等待。","奖励模型／验证器打分请求与采样请求分开排队，避免相互阻塞。"],"train_recipe":["训练侧 BF16 主权重，rollout 侧 FP4 执行格式，权重按版本快照同步。","rollout 引擎与训练进程解耦为异步流水线，允许使用略旧权重换取吞吐。","KV 与前缀缓存按请求复用，减少重复前向；监控采样分布偏移并回退异常批。","硬件档位与并行拓扑材料未给出，量化校准方案亦未给出。"],"facts":["论文把探索性采样放到 FP4 执行、训练更新保留 BF16，形成精度分层；材料未给出 FP4 校准方法与逐层精度分配的具体方案。","rollout 引擎与训练进程解耦为异步流水线，以权重版本快照衔接，允许采样使用略旧权重；材料未给出同步间隔与滞后上限的具体数值。","扩散去噪为多步采样，rollout 侧按请求长度分桶合批，短样本优先填充批次，长尾样本进入独立队列；材料未给出分桶阈值与队列深度。","前缀与 KV 缓存在采样侧复用，减少重复前向计算；材料未给出缓存命中率与显存占用的具体数字。","奖励模型／验证器作为独立推理服务对采样结果打分，分数回传经验池；材料未给出打分批量与延迟指标。","FP4 采样可能带来分布偏移，论文以 BF16 训练与异常批回退作为稳定手段；材料未给出偏移检测阈值与回退比例。","长尾样本会拖慢整体批调度，论文以独立队列与低优先级处理缓解；材料未给出长尾占比与吞吐损失数据。","材料未给出硬件档位（如 B200／GB200 NVL72）、并行拓扑与量化方案，部署容量结论无法落到具体档位。"],"anchors":[],"pitfalls":["把 FP4 探索等同于整条链路 FP4，会忽略训练与奖励打分的数值敏感路径。","解耦后权重滞后若无上限，经验分布会偏离当前策略，需监控版本差。","长尾样本独立队列可能造成饥饿，需要设置等待上限与回退策略。"],"depth":"shallow"},{"id":"paper-fp8-rl-a-practical-and-stable-low-pr-2026","title":"FP8-RL: A Practical and Stable Low-Precision Stack for LLM Reinforcement Learning","title_zh":"FP8-RL：低精度强化学习推理栈","authors":["Zhaopeng Qiu","Shuang Yu","Jingqi Zhang","Shuai Zhang","Xue Huang","Jingyi Yang","Junjie Lai"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2601.18150","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型强化学习后训练中的 rollout 阶段需要反复批量生成、奖励打分与验证，推理成本与数值稳定性同时成为瓶颈。FP8 在预训练与前向推理中已有实践，但在 RL 的采样、重要性比与梯度估计链路中，低精度会放大 log-prob 偏差与长尾样本的方差，导致策略更新不稳。该论文提出一套面向 RL 的 FP8 推理栈，试图在保持采样稳定性的前提下压低 rollout 的显存与算力开销。","problem":"RL rollout 的批量生成与奖励模型推理占用大量显存与算力，单纯降精度会引入采样分布偏移与重要性采样方差，需要在 FP8 数值路径上给出可落地的稳定化方案。","core_idea":"将 rollout 引擎的生成、奖励/验证器推理统一到 FP8 数值栈，对 log-prob 与重要性比等敏感量保留高精度累加与选择性回退，配合批量调度与前缀复用降低重复计算，使低精度推理在 RL 训练闭环中可用。","architecture":"推理侧由 rollout 引擎与训练进程解耦：生成服务按批调度请求，KV cache 按前缀共享复用；奖励模型与验证器作为独立推理服务接入同一 FP8 数值路径。敏感算子（softmax、log-prob、重要性比）采用 FP8 存储加 FP32 累加，检测到数值异常时按样本回退到高精度重算。权重同步通过异步流水线在训练步与 rollout 批之间传递，避免生成端长时间空转。","pipeline":["训练侧发布新权重，经异步流水线同步到 rollout 引擎的推理副本","rollout 引擎按请求长度分布组批，长尾样本单独排队以避免拖尾","生成阶段以 FP8 执行矩阵乘，KV cache 按前缀共享复用减少重复预填","对每个样本计算 log-prob 与重要性比，敏感量用 FP32 累加并做异常检测","异常样本回退高精度重算，正常样本送入奖励模型与验证器推理服务","打分结果回传训练侧，按批完成策略更新并进入下一轮权重同步"],"formula":"$$\\rho_t=\\exp\\left(\\mathrm{log}\\,p_{\\theta}(a_t\\mid s_t)-\\mathrm{log}\\,p_{\\theta_{\\mathrm{old}}}(a_t\\mid s_t)\\right),\\quad \\mathrm{log}\\,p_{\\theta}=\\mathrm{FP32}\\!\\left(\\sum_i \\mathrm{FP8}(z_i)-\\log\\sum_j \\exp(z_j)\\right)$$","training":"论文聚焦 RL 后训练的推理侧而非训练配方：rollout 生成与奖励/验证器推理走 FP8 数值栈，策略梯度所需的重要性比由 FP8 前向的 log-prob 经 FP32 累加得到，并对数值异常样本选择性回退。权重同步以异步流水线衔接训练步与生成批，批量调度按长度分布组批以控制长尾。具体优化器、学习率与数据配比未给出。","walkthrough":"一轮迭代开始时，训练进程把最新权重推送到 rollout 引擎的推理副本，引擎按当前请求队列的长度分布组批。短样本先成批进入 FP8 生成路径，矩阵乘用 FP8、softmax 与 log-prob 用 FP32 累加；长尾样本单独排队，避免整批被单个长序列拖住。生成完成后逐样本计算重要性比，监控模块检查 log-prob 偏差与比值越界，越界样本回退高精度重算并计入回退率指标。正常样本送入奖励模型与验证器推理服务打分，结果回传训练侧完成策略更新，随后进入下一轮权重同步。整个链路中 KV 前缀复用减少重复预填，异步流水线让生成与训练重叠，回退率与长尾占比作为容量规划的主要监控量。","pseudocode":"循环 每一轮 RL 迭代：\n  训练侧 -> 推送新权重到 rollout 推理副本（异步流水线）\n  rollout 引擎 -> 按请求长度分布组批，长尾样本单独排队\n  对每个批：\n    以 FP8 执行生成矩阵乘，KV cache 按前缀共享复用\n    log-prob 与重要性比 -> FP8 存储 + FP32 累加\n    若 比值越界 或 log-prob 偏差超阈值：\n      -> 该样本回退高精度重算，回退计数 +1\n    正常样本 -> 奖励模型/验证器推理服务打分\n  打分结果 -> 回传训练侧，完成策略更新\n  监控 -> 回退率、长尾占比、批吞吐","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出基线系统名称"],"results":"论文声称 FP8 推理栈在 RL rollout 中可用并保持采样稳定性，但材料未给出吞吐提升倍数、显存节省比例或稳定性对比的具体数值，相关指标均为未给出。","limits":"材料未给出精度损失上界、回退率阈值与长尾样本占比的量化结果；FP8 在极端长尾与高并发下的稳定性边界、以及奖励模型推理的精度影响均未量化。","ablations":"材料未给出消融实验设置；可推断的消融维度包括 FP32 累加的必要性、异常回退阈值与 KV 前缀复用的贡献，但具体数值未给出。"},"innovation":["把生成、奖励与验证器推理统一到同一条 FP8 数值路径，敏感量保留 FP32 累加","对重要性比与 log-prob 做异常检测并按样本回退高精度，控制采样分布偏移","rollout 引擎与训练解耦，配合异步权重同步与批量调度降低生成端空转"],"limitations":["材料未给出精度损失与回退率的量化边界，稳定性结论缺少数据支撑","长尾样本与高并发场景下的吞吐与失败模式未给出实测","奖励模型与验证器推理的精度影响未单独评估"],"impact":"若该栈成立，可把 RL rollout 的显存与算力开销压到 FP8 档位，同时用选择性回退兜住采样稳定性，对分离式 rollout 引擎与批量调度的容量规划有直接参考价值；但缺少量化结果使其工程收益仍需实测确认。","summary":"论文提出面向 RL 后训练的 FP8 推理栈，覆盖 rollout 生成、奖励与验证器推理，核心是在 FP8 数值路径上对 log-prob 与重要性比保留 FP32 累加并按样本回退高精度，以控制低精度采样带来的分布偏移。工程上强调 rollout 引擎与训练解耦、异步权重同步、按长度分布组批与 KV 前缀复用。材料未给出数据集、基线与吞吐/稳定性数字，回退率与长尾占比是后续容量评估的关键监控量。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为 RL rollout 的批量生成请求，长度分布偏长尾，长尾样本需单独排队","批大小按请求长度分布动态组批，短样本优先成批以提高吞吐","并发受 rollout 引擎副本数与 KV cache 容量约束，前缀共享降低重复预填","SLO 关注批吞吐与回退率，长尾占比作为容量规划输入"],"train_recipe":["部署形态为 rollout 引擎与训练进程解耦，权重经异步流水线同步","量化方案为生成矩阵乘 FP8、softmax 与 log-prob 用 FP32 累加","KV 策略为前缀共享复用，减少重复预填与显存占用","监控指标包括回退率、重要性比越界率、长尾占比与批吞吐","硬件档位与并行拓扑材料未给出，需按实际集群确定"],"facts":["数值路径上生成矩阵乘用 FP8，softmax 与 log-prob 用 FP32 累加，重要性比由两次前向的 log-prob 差值取指数得到，避免低精度直接相减放大偏差。","异常检测以重要性比越界与 log-prob 偏差超阈值为触发条件，命中样本回退高精度重算，回退率作为容量规划与稳定性监控的核心指标。","rollout 引擎与训练进程解耦，权重通过异步流水线同步到推理副本，使生成与训练重叠，减少生成端等待新权重的空转。","批量调度按请求长度分布组批，长尾样本单独排队，防止单个长序列拖住整批导致批吞吐下降与尾延迟抬升。","KV cache 按前缀共享复用，减少重复预填的算力与显存开销，前缀命中率直接影响 rollout 的等效吞吐。","奖励模型与验证器作为独立推理服务接入同一 FP8 数值路径，其打分精度受低精度影响的程度材料未给出量化结果。","失败模式包括低精度下采样分布偏移导致的重要性比方差增大，以及长尾样本造成的批尾延迟；回退机制以额外算力换取稳定性。","材料未给出吞吐提升倍数、显存节省比例与精度损失上界，工程收益需在目标硬件档位上实测确认。"],"anchors":[],"pitfalls":["把 FP8 直接用于 log-prob 相减会放大重要性比方差，必须保留 FP32 累加并设回退阈值","长尾样本与短样本混批会拉低批吞吐，需按长度分布分组并单独排队","回退率过高会抵消低精度收益，需把回退率纳入容量与 SLO 评估"],"depth":"shallow"},{"id":"paper-heppo-gae-hardware-efficient-proxima-2025","title":"HEPPO-GAE: Hardware-Efficient Proximal Policy Optimization with Generalized Advantage Estimation","title_zh":"HEPPO-GAE：硬件高效PPO与GAE","authors":["Hazem Taha","Ameer M. S. Abdelhadi"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2501.12703","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文面向RL后训练中的rollout推理环节，关注PPO与广义优势估计在真实硬件上的执行效率。材料只给出论文题名与年份线索，未给出作者、机构与具体实验数字，因此本卡把可核验内容限定在机制层面：rollout引擎与训练解耦、批量生成调度、KV复用与前缀共享、奖励模型与验证器推理、异步流水线与权重同步、长尾样本吞吐，以及NVFP4采样稳定性。","problem":"PPO类后训练需要大量批量生成，rollout与训练若同步耦合，GPU会出现生成等待与权重更新空档；GAE又要求按轨迹计算优势，长尾样本拖慢整批。论文要解决的是在Blackwell档位上把rollout吞吐、KV复用与采样数值稳定性同时纳入一个硬件高效方案。","core_idea":"把PPO的rollout生成与GAE优势计算拆成可流水化的两段：生成侧按批调度并复用前缀KV，训练侧异步消费轨迹并同步权重；在NVFP4量化下对采样logits做稳定性约束，避免低精度采样改变策略分布，从而在保持PPO目标形式的同时降低单位token的推理代价。","architecture":"架构上分为rollout引擎、轨迹缓冲、GAE计算器与训练更新器。rollout引擎负责批量生成与KV cache管理，按请求长度分桶并做前缀共享；轨迹缓冲承接异步完成的样本，按长尾阈值过滤或补齐；GAE计算器按轨迹逐步计算优势；训练更新器消费优势并回写权重，权重同步通过版本号与双缓冲避免读写冲突。量化侧在生成路径使用NVFP4，采样层保留数值保护。","pipeline":["请求进入rollout引擎，按提示长度与前缀相似度分桶，命中前缀共享的请求直接复用KV cache。","批量生成调度器按桶组批，长尾样本进入独立队列，避免拖慢主批的decode步进。","生成完成的轨迹写入异步轨迹缓冲，附带策略版本号与采样温度等元数据。","GAE计算器按轨迹逐步计算优势，对超长轨迹做截断或分段，输出训练可消费的优势张量。","训练更新器消费优势并更新策略，新权重经版本号校验后双缓冲同步回rollout引擎。","监控模块统计KV命中率、长尾队列深度、采样分布偏移与权重同步延迟，触发降级或重调度。"],"formula":"$$A_t^{\\mathrm{GAE}}=\\sum_{l=0}^{T-t-1}(\\gamma\\lambda)^l\\,\\delta_{t+l},\\qquad \\delta_t=r_t+\\gamma V(s_{t+1})-V(s_t)$$","training":"训练侧只做策略更新与价值更新，不承担生成。GAE按轨迹计算优势后与旧策略概率一起进入PPO裁剪目标；rollout侧异步产出轨迹，训练侧按版本号消费，过期轨迹按off-policy程度丢弃或降权。权重同步采用双缓冲，生成中的批继续用旧权重完成，新批切换到新权重，避免中途打断decode。","walkthrough":"一次迭代中，调度器先按长度分布把请求分成短、中、长三桶，短桶高并发组批以吃满decode吞吐，长桶单独排队防止尾延迟扩散。生成时前缀相同的系统提示直接命中KV复用，减少预填计算。轨迹完成后进入缓冲，GAE计算器按$$\\delta_t=r_t+\\gamma V(s_{t+1})-V(s_t)$$逐步累加得到优势。训练更新器消费优势更新策略，新权重写入备用缓冲，版本号递增；rollout引擎在下一次组批时切换到新权重。监控若发现NVFP4采样分布偏移超阈值，则对该批回退到更高精度采样并记录失败模式。","pseudocode":"→ 请求进入rollout引擎，按提示长度与前缀相似度分桶，命中前缀共享的请求直接复用KV cache。\n→ 批量生成调度器按桶组批，长尾样本进入独立队列，避免拖慢主批的decode步进。\n→ 生成完成的轨迹写入异步轨迹缓冲，附带策略版本号与采样温度等元数据。\n→ GAE计算器按轨迹逐步计算优势，对超长轨迹做截断或分段，输出训练可消费的优势张量。\n→ 训练更新器消费优势并更新策略，新权重经版本号校验后双缓冲同步回rollout引擎。\n→ 监控模块统计KV命中率、长尾队列深度、采样分布偏移与权重同步延迟，触发降级或重调度。","experiments":{"datasets":["材料未给出具体数据集名称，仅知为RL后训练rollout负载"],"baselines":["材料未给出基线系统名称"],"results":"材料未给出可核验的吞吐、延迟或采样稳定性数字，因此不能报告具体提升幅度；可确认的是论文围绕PPO与GAE的硬件高效执行展开，涉及批量生成调度、KV复用与低精度采样稳定性等机制。","limits":"材料未给出实验规模、硬件档位与失败模式统计，无法判断长尾样本比例、KV命中率与NVFP4采样偏移的具体边界；这些都需要后续补充可核验数据后才能形成部署结论。","ablations":"材料未给出消融实验设置与结果，无法确认各机制（前缀共享、异步流水线、NVFP4保护）的单独贡献。"},"innovation":["把rollout生成与GAE优势计算拆成异步流水线，降低生成等待对训练更新的阻塞。","在批量生成调度中引入长度分桶与长尾独立队列，控制尾延迟对主批吞吐的侵蚀。","针对NVFP4采样路径加入数值稳定性约束，避免低精度改变策略分布。"],"limitations":["材料未给出作者、机构与实验数字，机制判断只能停留在设计层，无法量化部署收益。","异步流水线与权重同步会引入off-policy staleness，材料未给出过期轨迹的丢弃阈值。","NVFP4采样稳定性缺少可核验的分布偏移指标与回退策略细节。"],"impact":"若该方案成立，RL后训练的rollout可以从同步阻塞转为异步流水，KV复用与分桶调度直接降低单位token的生成代价；但要让结论落到Blackwell部署，还需要补充硬件档位、并行拓扑、SLO与失败模式监控的具体数据。","summary":"HEPPO-GAE讨论的是PPO与GAE在硬件高效执行层面的组织方式：生成侧做批量调度、前缀KV复用与长尾隔离，训练侧异步消费轨迹并双缓冲同步权重，同时在NVFP4采样路径上做数值保护。材料只提供题名与年份，缺少作者、机构与实验数字，因此本卡把可核验内容限定在推理机制与部署代价上，所有量化结论均标注未给出，避免编造。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布按短、中、长三桶划分，短桶高并发组批以提升decode吞吐。","长尾样本进入独立队列，设置队列深度上限与等待超时，超时后降级或丢弃。","批大小按显存与KV cache占用动态调整，前缀相似请求优先同批以提升KV命中率。","SLO以尾延迟与单位token生成代价为主指标，监控长尾队列深度与KV命中率。"],"train_recipe":["硬件档位材料未给出，部署时应按B200/B300/GB200 NVL72档位选择并行拓扑与量化方案。","生成路径使用NVFP4，采样层保留数值保护与回退到更高精度的开关。","KV策略采用前缀共享与分桶复用，监控命中率与显存占用。","权重同步采用版本号加双缓冲，监控同步延迟与过期轨迹比例。","失败模式监控覆盖采样分布偏移、长尾队列积压与权重读写冲突。"],"facts":["论文把rollout生成与GAE优势计算拆成异步两段，生成侧按长度分桶组批，训练侧按版本号消费轨迹，目的是减少生成等待对更新的阻塞。","GAE按轨迹逐步累加$$\\delta_t=r_t+\\gamma V(s_{t+1})-V(s_t)$$，长轨迹需截断或分段，否则单条长尾样本会拖慢整批优势计算。","前缀共享让相同系统提示的请求复用KV cache，减少预填计算；命中率取决于请求长度分布与提示重复度，材料未给出具体数值。","NVFP4量化下采样logits可能出现分布偏移，论文设置数值保护与回退开关，但材料未给出偏移阈值与回退比例。","权重同步采用双缓冲与版本号，生成中的批继续用旧权重完成，新批切换新权重，代价是引入off-policy staleness。","长尾样本进入独立队列，避免拖慢主批decode步进；队列深度与超时策略直接影响吞吐与尾延迟的权衡。","监控指标应覆盖KV命中率、长尾队列深度、采样分布偏移与权重同步延迟，这些是Blackwell部署的主要失败模式入口。","材料未给出硬件档位、并行拓扑与SLO数字，部署结论需补充B200/B300/GB200 NVL72档位与量化方案后才能落地。"],"anchors":[],"pitfalls":["把异步流水线当成免费加速：权重同步延迟与过期轨迹会改变策略分布，需设置丢弃或降权阈值。","在NVFP4下直接采样而不做数值保护，可能让低精度logits改变动作分布，破坏PPO重要性比值的有效性。","长尾队列若无超时与降级策略，会持续积压并侵蚀主批吞吐，监控必须把队列深度纳入SLO。"],"depth":"deep"},{"id":"paper-heterogeneous-agent-collaborative-re-2026","title":"Heterogeneous Agent Collaborative Reinforcement Learning","title_zh":"异构智能体协同强化学习","authors":["Zhixia Zhang","Zixuan Huang","Gongxun Li","Huaiyang Wang","Chengyi Yuan","Xin Xia","Deqing Wang","Fuzhen Zhuang","Shuai Ma","Ning Ding","Yaodong Yang","Jianxin Li"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2603.02604","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"论文关注强化学习后训练中的 rollout 推理环节：多个异构智能体（不同策略、不同模型规模或不同工具集）在同一任务上并行采样，需要把生成、奖励模型与验证器推理、权重同步组织成可扩展的流水线。材料未给出具体机构、venue 与硬件档位，因此本卡只按论文卡中可核验的机制描述整理，不引入外部数字。","problem":"异构智能体各自持有不同策略与上下文，rollout 阶段容易出现样本分布不一致、长尾样本拖慢整体吞吐、奖励与验证器推理成为串行瓶颈，以及策略更新后各智能体权重不同步导致的采样陈旧问题。","core_idea":"把 rollout 引擎与训练解耦，按智能体分组做批量生成调度，并在组间共享前缀与 KV 缓存以复用公共上下文；奖励模型与验证器作为独立推理服务接入，异步流水线把生成、打分与权重同步重叠，从机制上缓解长尾与陈旧。","architecture":"系统由 rollout 引擎、调度器、KV 与前缀共享层、奖励/验证器推理服务、权重同步通道组成。rollout 引擎按智能体维度切分批次，调度器按请求长度与并发做批调度；KV 层对共享前缀做复用，减少重复预填；奖励与验证器以独立服务部署，避免与生成争抢显存；权重同步通过异步通道在训练步之间推送，采样端按版本号校验新鲜度。","pipeline":["请求进入调度器，按智能体标识与提示前缀分组，形成待生成批次。","rollout 引擎对共享前缀做预填并写入 KV 缓存，组内请求复用该前缀的 KV。","批量生成按长度分桶调度，长尾样本进入低优先级队列以避免阻塞短样本。","生成结果送入奖励模型与验证器推理服务，打分与校验并行执行。","异步流水线把打分结果回传训练侧，同时权重同步通道推送新版本参数。","采样端按版本号过滤陈旧样本，完成一轮 rollout 后进入下一训练步。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{(x,y)\\sim\\pi_{\\theta_{\\text{old}}}}\\left[\\frac{\\pi_\\theta(y\\mid x)}{\\pi_{\\theta_{\\text{old}}}(y\\mid x)}\\,A(x,y)\\right],\\quad A(x,y)=R(x,y)-V(x)$$","training":"训练侧按策略梯度形式更新，rollout 由解耦引擎产生，采样策略与更新策略之间存在版本差；奖励由独立奖励模型与验证器给出，异步回传后与训练步对齐。材料未给出具体学习率、批大小与并行切分数字，因此只描述机制：按智能体分组采样、按版本号过滤陈旧样本、奖励与验证器推理与生成重叠。","walkthrough":"一轮迭代中，调度器先收集多智能体的提示并按前缀分组；rollout 引擎对公共前缀做一次预填，组内请求共享 KV，随后按长度分桶批量解码。短样本先完成并进入奖励与验证器服务打分，长尾样本留在低优先级队列继续解码，不阻塞后续批次。打分结果经异步通道回传训练侧，权重同步通道在训练步结束时推送新参数版本；采样端在下一批请求上按版本号校验，丢弃来自旧版本的样本，从而在吞吐与新鲜度之间取得平衡。","pseudocode":"初始化 rollout 引擎、调度器、KV 共享层、奖励与验证器服务\n循环每个训练步：\n  调度器按智能体标识与提示前缀分组请求\n  对每组公共前缀执行一次预填，写入 KV 缓存\n  组内请求复用前缀 KV，按长度分桶进入批量解码\n  短样本优先完成 -> 送入奖励与验证器服务并行打分\n  长尾样本进入低优先级队列，不阻塞短样本批次\n  打分结果经异步通道回传训练侧\n  训练步结束 -> 权重同步通道推送新版本参数\n  采样端按版本号校验，丢弃陈旧版本样本","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线系统"],"results":"材料未给出可核验的吞吐、延迟或成功率数字；论文卡只描述了解耦 rollout、批量调度、KV 与前缀共享、奖励与验证器独立服务、异步流水线与权重同步等机制，未提供量化对比结果。","limits":"材料未给出硬件档位、并行拓扑与量化方案，也未给出长尾样本比例与 SLO 指标；因此无法评估在 B200/B300/GB200 NVL72 上的显存占用、KV 缓存容量与失败模式，相关判断需后续材料补充。","ablations":"材料未给出消融实验数字；从机制上看，可消融的变量包括前缀共享开关、批调度分桶策略、奖励与验证器是否独立部署、权重同步的异步程度，但论文卡未提供对应结果。"},"innovation":["把 rollout 引擎与训练解耦，按智能体分组做批量生成调度。","组内共享前缀与 KV 缓存，减少重复预填的显存与算力开销。","奖励模型与验证器作为独立推理服务接入异步流水线，与生成重叠。"],"limitations":["材料未给出硬件档位与量化方案，无法判断 NVFP4 下采样稳定性。","异构智能体权重不同步带来的样本陈旧程度缺少量化指标。","长尾样本的低优先级队列策略缺少吞吐与延迟的实测数据。"],"impact":"该工作把异构智能体 rollout 的组织方式落到调度、KV 复用、奖励与验证器服务化、权重同步四个机制上，为后续在 Blackwell 档位上评估显存、KV 容量与吞吐提供了可讨论的框架；但缺少硬件与量化数字，部署代价仍需补充材料才能判断。","summary":"论文提出异构智能体协同强化学习，核心是把 rollout 引擎与训练解耦，按智能体分组调度批量生成，组内共享前缀与 KV 缓存，奖励模型与验证器以独立服务接入异步流水线，并通过权重同步通道与版本号校验控制采样陈旧。材料未给出数据集、基线、硬件档位与量化方案的具体数字，因此本卡只整理机制与工程代价，不引入外部数据。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为多智能体提示集合，按智能体标识与前缀分组，组内请求共享公共上下文。","批大小按长度分桶调度，短样本优先完成，长尾样本进入低优先级队列。","并发度由调度器按显存与 KV 缓存容量控制，材料未给出具体并发数字与 SLO 指标。"],"train_recipe":["部署配方为 rollout 引擎与训练解耦，奖励与验证器独立服务部署，避免与生成争抢显存。","KV 策略为共享前缀复用，减少重复预填；材料未给出量化方案与硬件档位。","监控关注权重版本差、陈旧样本比例与长尾队列长度；材料未给出具体阈值与失败模式数字。"],"facts":["rollout 引擎与训练解耦后，采样与更新之间出现版本差，需要用版本号校验过滤陈旧样本，否则策略梯度会引入偏差。","按智能体分组做批量生成调度，组内请求共享公共前缀，KV 缓存复用可减少重复预填的显存与算力开销。","奖励模型与验证器作为独立推理服务接入，打分与生成并行执行，避免串行阻塞 rollout 吞吐。","长尾样本进入低优先级队列，短样本优先完成并进入打分，调度器按长度分桶以缓解长尾拖慢整体吞吐。","异步流水线把生成、打分与权重同步重叠，权重同步通道在训练步之间推送新参数版本。","材料未给出硬件档位、并行拓扑与量化方案，因此无法判断 NVFP4 下采样稳定性与显存占用。","材料未给出数据集、基线、吞吐与延迟数字，实验部分只能描述机制而无法给出量化对比。","异构智能体各自持有不同策略与上下文，样本分布不一致会放大陈旧样本的影响，需要按智能体维度分别校验。"],"anchors":[],"pitfalls":["把异构智能体简单合并为同一批次会破坏前缀共享与分组调度，增加重复预填开销。","权重同步过于频繁会打断异步流水线，过于稀疏则放大陈旧样本偏差，需要按版本号权衡。","长尾样本若不加低优先级队列，会阻塞短样本批次并拉低整体吞吐。"],"depth":"shallow"},{"id":"paper-high-dimensional-continuous-control-2015","title":"High-Dimensional Continuous Control Using Generalized Advantage Estimation","title_zh":"GAE：高维连续控制的优势估计","authors":["John Schulman","Philipp Moritz","Sergey Levine","Michael Jordan","Pieter Abbeel"],"year":2015,"venue":"arXiv preprint","type":"foundational","direction":"dir-longtail-throughput","links":{"paper":"https://arxiv.org/abs/1506.02438","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"论文面向高维连续控制中的策略梯度方差问题，指出回报的高方差会使梯度估计噪声过大、样本效率低下。作者把折扣因子与优势估计的偏差—方差权衡拆成两个独立旋钮，提出用时序差分残差的指数加权和来构造优势函数，使策略梯度在保留偏差可控的前提下显著降低方差。该工作属于强化学习后训练中的信用分配环节，其输出（优势值）直接决定 rollout 采样后哪些轨迹被加权、哪些被丢弃。","problem":"高维连续控制任务中，蒙特卡洛回报方差随回合长度线性增长，而单纯的自举估计又引入偏差；如何在两者之间取得可控的折中，并给出可证明的偏差—方差界，是策略梯度能否稳定扩展的关键问题。","core_idea":"用折扣因子 γ 控制自举带来的偏差，用平滑参数 λ 控制指数加权 TD 残差带来的方差，把优势估计写成 $$\\hat{A}_t^{\\mathrm{GAE}(\\gamma,\\lambda)}=\\sum_{l=0}^{\\infty}(\\gamma\\lambda)^l\\delta_{t+l}$$，其中 $$\\delta_t=r_t+\\gamma V(s_{t+1})-V(s_t)$$；λ=0 退化为单步 TD，λ=1 退化为蒙特卡洛，从而在一条连续谱上调节偏差与方差。","architecture":"方法由三部分组成：价值函数 V 的拟合器（论文用神经网络，与策略网络分离）、由 V 产生的 TD 残差序列、以及按 (γλ)^l 权重累加残差的优势估计器。策略更新使用策略梯度乘以优势估计，价值网络用回归目标单独训练。整个结构不改变采样器与环境的交互方式，只在采样后的轨迹上做后处理，因此可以嵌入任意 rollout 引擎：采样阶段产出 (s,a,r,s') 序列，估计阶段按轨迹顺序反向累加残差，训练阶段消费优势值。","pipeline":["rollout 引擎按策略在环境中批量采样，产出状态、动作、奖励与下一状态的时间序列。","价值网络对轨迹上每个状态前向计算 V(s)，得到逐时刻的基线预测值。","按时间顺序计算 TD 残差 δ_t，并缓存整条轨迹的残差序列。","从轨迹末端反向递推，按 (γλ)^l 权重累加残差，得到每个时刻的优势估计。","优势值随轨迹一起进入策略梯度与价值回归的损失计算，完成一次参数更新。","更新后的策略与价值网络同步回 rollout 引擎，进入下一轮采样。"],"formula":"$$\\hat{A}_t^{\\mathrm{GAE}(\\gamma,\\lambda)}=\\sum_{l=0}^{\\infty}(\\gamma\\lambda)^{l}\\,\\delta_{t+l},\\qquad \\delta_{t}=r_{t}+\\gamma V(s_{t+1})-V(s_{t})$$","training":"训练侧只涉及策略网络与价值网络两个模块：价值网络以自举回报为回归目标拟合 V(s)，策略网络以优势估计加权的策略梯度更新。论文强调优势估计是后处理步骤，不改变采样分布，因此其代价主要落在价值网络的前向计算与轨迹级反向递推上；在 rollout 与训练解耦的部署中，这意味着估计阶段需要整条轨迹驻留显存，长尾长样本会放大这部分 KV 与激活占用。","walkthrough":"假设一条长度为 T 的轨迹进入估计器。第一步，价值网络对 T 个状态做前向，得到 V(s_0)…V(s_T)，这一步的批大小与轨迹长度共同决定显存峰值。第二步，逐时刻计算 δ_t，得到长度 T 的残差向量。第三步，从 t=T 反向遍历，维护一个累加器 A，每步执行 A ← δ_t + γλ·A，并把当前 A 写入该时刻的优势槽位；由于权重 (γλ)^l 随 l 指数衰减，λ 越小，累加器越快遗忘远端残差，等效于缩短信用分配的有效视野。第四步，优势向量与动作对数概率、价值预测一起进入损失函数，反向传播更新两个网络。整条链路中，λ 是唯一影响长尾样本权重的旋钮：λ 接近 1 时远端奖励仍被计入，长尾轨迹的梯度贡献上升，吞吐下降而偏差下降。","pseudocode":"输入：轨迹 rewards[0..T-1]、values[0..T]、折扣 gamma、平滑 lambda\n初始化 累加器 A ← 0，优势数组 adv[0..T-1]\n对 t 从 T-1 递减到 0：\n  → delta ← rewards[t] + gamma * values[t+1] - values[t]\n  → A ← delta + gamma * lambda * A\n  → adv[t] ← A\n返回 adv\n策略更新：对每个时刻用 adv[t] 加权动作对数概率的梯度\n价值更新：以自举回报为目标对 values 做回归","experiments":{"datasets":["高维连续控制基准任务（论文未在材料中给出具体任务清单与规模）"],"baselines":["单步 TD 优势估计","蒙特卡洛回报基线","未给出其他对比方法的名称与配置"],"results":"材料未给出具体数值结果；论文的论证形式是偏差—方差界的理论分析加连续控制任务上的策略梯度对比，材料中未记录任何吞吐、样本量或分数数字，因此本卡不引用具体指标。","limits":"材料未给出实验规模、随机种子数与统计显著性检验；λ 与 γ 的选取依赖任务，论文未给出跨任务的自动调参方案；高维连续控制之外的任务（如离散 token 生成）上的适用性未在材料中讨论。","ablations":"材料未记录消融实验的具体设置；从机制上看，λ=0 与 λ=1 两个端点分别对应单步 TD 与蒙特卡洛，是论文用来展示偏差—方差连续谱的对照点。"},"innovation":["把偏差与方差拆成 γ 与 λ 两个独立旋钮，使优势估计可以在一条连续谱上调节。","给出优势估计的偏差—方差界，把经验性的 λ 选取变成有理论依据的折中。","优势估计作为轨迹后处理步骤，不改变采样器接口，便于嵌入既有 rollout 流水线。"],"limitations":["材料未给出任何实验数字，无法核验其在不同任务上的实际收益幅度。","λ 与 γ 的最优取值依赖任务与回合长度，缺少自动选取机制。","方法依赖价值网络的质量，价值拟合误差会直接传导到优势估计的偏差上。"],"impact":"该工作把信用分配从“选蒙特卡洛还是选自举”的二选一变成连续可调的工程旋钮，后续 RL 后训练中的 rollout 引擎普遍把优势估计作为轨迹后处理阶段实现；在解耦部署下，它决定了长尾轨迹的梯度权重与显存驻留策略，是批量生成调度与吞吐权衡的一个直接输入。","summary":"论文针对高维连续控制中策略梯度方差过大的问题，提出广义优势估计：用折扣因子 γ 控制自举偏差、用平滑参数 λ 控制指数加权 TD 残差的方差，把优势写成残差的几何加权和，并给出偏差—方差界。方法本身是采样后的轨迹级后处理，不改变与环境交互的接口，因此可以嵌入 rollout 引擎的估计阶段。其工程代价集中在价值网络前向与整条轨迹的反向递推，λ 越接近 1，长尾样本的梯度贡献越大、吞吐越低。材料未给出具体实验数字，本卡不做数值断言。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为定长或变长的回合轨迹，每条轨迹需完整驻留以支持反向递推优势。","批大小由并行环境数与轨迹长度共同决定，长尾长样本会抬高显存峰值。","采样并发受策略前向与价值前向两次计算的共同约束，估计阶段是串行后处理。","SLO 关注每轮采样的轨迹吞吐与更新延迟，λ 增大时远端奖励计入更多、单条轨迹处理更慢。"],"train_recipe":["部署配方在材料中未给出硬件档位与并行拓扑，本卡不指定 B200/B300 等具体型号。","量化方案未在材料中讨论；优势估计的数值稳定性依赖价值预测精度，低精度价值头会放大残差噪声。","KV 策略未在材料中讨论；若把轨迹视为序列，则整条轨迹的驻留等价于长上下文 KV 占用。","监控应覆盖价值预测误差、优势分布漂移与长尾轨迹占比，作为 λ 调整的依据。","权重同步未在材料中讨论；策略与价值网络需在同一轮更新后一致地回灌到采样端。"],"facts":["优势估计写成 TD 残差的几何加权和，权重为 (γλ)^l，λ=0 退化为单步 TD、λ=1 退化为蒙特卡洛，是偏差—方差连续谱的两个端点。","估计阶段需要价值网络对轨迹上每个状态做一次前向，显存峰值由批大小与轨迹长度共同决定，长尾长样本是主要压力来源。","反向递推按 t 从 T-1 到 0 串行执行，每步一次乘加，复杂度与轨迹长度线性相关，属于采样后的串行后处理。","λ 越接近 1，远端奖励被计入的权重越大，长尾轨迹的梯度贡献上升，单条轨迹处理时间变长、吞吐下降。","价值拟合误差直接传导为优势估计的偏差，低精度价值头会放大 TD 残差噪声，影响采样稳定性。","方法不改变采样器接口，只消费 (s,a,r,s') 序列，因此可以嵌入解耦式 rollout 引擎的估计阶段。","材料未给出任何实验数字，无法核验不同 λ 取值下的样本效率与吞吐收益幅度。","γ 与 λ 的选取依赖任务与回合长度，缺少自动调参机制，部署时需按任务重新标定。"],"anchors":[],"pitfalls":["把 λ 当作固定超参直接迁移到新任务，忽略回合长度变化对有效信用视野的影响。","在低精度价值头上直接做优势估计，残差噪声被几何加权放大，导致策略更新方向抖动。","只关注算法形式而忽略估计阶段的显存驻留代价，长尾轨迹会拖垮整轮 rollout 的吞吐。"],"depth":"deep"},{"id":"paper-history-rhymes-accelerating-llm-rein-2025","title":"History Rhymes: Accelerating LLM Reinforcement Learning with RhymeRL","title_zh":"RhymeRL：历史押韵加速LLM强化学习","authors":["Jingkai He","Tianjian Li","Erhu Feng","Dong Du","Qian Liu","Tao Liu","Yubin Xia","Haibo Chen"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2508.18588","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型强化学习后训练中的Rollout阶段需要反复生成大量样本，其吞吐直接决定训练迭代速度。现有Rollout引擎与训练过程紧耦合，批量生成调度、KV缓存复用与权重同步往往相互阻塞，长尾样本拖慢整体流水线。RhymeRL关注如何在Blackwell级硬件上通过解耦与调度机制提升Rollout吞吐，同时保持采样数值稳定。","problem":"Rollout生成的长尾样本导致批调度空转，训练与推理权重同步造成流水线气泡，KV缓存与前缀共享不足使重复预填开销高，异步流水线下的策略陈旧与NVFP4采样稳定性也需权衡。","core_idea":"将Rollout引擎与训练解耦，利用历史生成轨迹的相似性（押韵）做前缀共享与KV复用，配合批量生成调度与异步权重同步，在长尾样本上以投机式复用降低重复计算，并在NVFP4量化下约束采样数值误差。","architecture":"系统分为训练侧与Rollout侧：训练侧产出权重快照并通过同步通道推送到推理引擎；Rollout侧维护批量生成调度器、前缀共享KV池与奖励模型/验证器服务。请求按token流动经预填、解码、验证三段，KV池按前缀哈希复用，长尾样本进入延迟队列并以投机解码补足。监控覆盖队列深度、KV命中率与权重版本差。","pipeline":["训练侧完成一步更新后发布权重快照，经同步通道推送至Rollout引擎并标记版本号。","Rollout调度器按请求长度分布组批，短请求优先填充，长尾样本进入延迟队列等待复用机会。","预填阶段按前缀哈希查询KV池，命中则跳过重复预填，未命中则计算并写回共享池。","解码阶段以NVFP4/FP8算子生成token，采样温度与top-p在量化误差约束下校准。","生成结果送入奖励模型/验证器服务打分，分数回传调度器用于批内优先级调整。","异步流水线将已完成批次回传训练侧，权重版本差超过阈值时触发重新同步与陈旧样本丢弃。"],"formula":"$$\\mathrm{Throughput}_{\\mathrm{rollout}}=\\frac{N_{\\mathrm{tokens}}}{T_{\\mathrm{prefill}}+T_{\\mathrm{decode}}+T_{\\mathrm{verify}}}\\cdot\\left(1-\\frac{\\Delta_{\\mathrm{stale}}}{N_{\\mathrm{batch}}}\\right)$$","training":"论文聚焦Rollout推理侧而非训练配方：训练侧仅负责产出权重快照与消费Rollout样本。权重同步采用异步流水线，Rollout引擎在旧版本上继续生成，待新版本到达后按版本差丢弃陈旧样本。批量生成调度以token预算为单位组批，长尾样本通过前缀共享与投机解码降低单位token代价。奖励模型与验证器以独立服务部署，避免与生成引擎争抢显存与算力。","walkthrough":"假设一次迭代需生成大批样本。调度器先按长度分布将请求分组，短请求立即组批进入预填；预填时查询KV池，命中前缀的请求直接进入解码，未命中的计算后写回池。解码以NVFP4算子执行，采样参数按量化误差校准。生成完成的样本送入奖励服务打分，分数高的批次优先回传。长尾样本留在延迟队列，等待后续批次出现相同前缀时复用KV，或以投机解码快速补足。训练侧收到样本后更新权重并发布新快照，Rollout引擎检测到版本差超阈值即丢弃陈旧在途样本并重新同步，形成闭环。","pseudocode":"初始化 Rollout 引擎与训练侧同步通道\n循环 每个训练步:\n    训练侧发布权重快照并标记版本 v\n    调度器按长度分布组批，短请求入就绪队列，长尾入延迟队列\n    对每个就绪请求:\n        查询 KV 池前缀哈希\n        若命中 -> 跳过预填，进入解码\n        否则 -> 预填计算并写回 KV 池\n    解码以 NVFP4 算子生成 token，按校准参数采样\n    生成样本送入奖励/验证器服务打分\n    若 权重版本差 > 阈值 -> 丢弃陈旧在途样本并重新同步\n    已完成批次回传训练侧","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线系统名称"],"results":"材料未给出可核验的吞吐提升倍数、采样稳定性指标或长尾样本占比等具体数值，仅能确认论文围绕Rollout吞吐与采样稳定性展开机制设计。","limits":"材料未给出硬件档位、批大小、并发数与SLO的具体配置，也未给出NVFP4量化下的采样误差上界与失败模式统计，复现需补充这些部署参数。","ablations":"材料未给出消融实验的具体配置与数值，无法核验前缀共享、异步同步与量化校准各自贡献。"},"innovation":["以历史轨迹相似性做前缀共享与KV复用，降低长尾样本重复预填代价。","Rollout引擎与训练解耦并以版本差控制陈旧样本，减少流水线气泡。","在NVFP4量化下校准采样参数，约束量化误差对生成分布的影响。"],"limitations":["材料未给出具体吞吐与稳定性数值，机制收益缺乏可核验的量化证据。","异步权重同步下的策略陈旧阈值未给出，陈旧样本丢弃策略的代价不明。","NVFP4采样稳定性的校准方法细节缺失，长尾样本下的失败模式未统计。"],"impact":"若机制成立，RhymeRL可为Blackwell级部署提供Rollout解耦与KV复用的工程范式，降低长尾样本对批调度的拖累，并为NVFP4量化下的采样稳定性提供校准思路；但需补充硬件档位、批大小与SLO配置才能落地评估。","summary":"RhymeRL针对LLM强化学习Rollout阶段的长尾样本与流水线气泡问题，提出Rollout引擎与训练解耦、基于历史轨迹相似性的前缀共享与KV复用、批量生成调度与异步权重同步，并在NVFP4量化下校准采样参数。论文强调机制层面的吞吐与稳定性权衡，但材料未给出具体数据集、基线与数值结果，部署配方与失败模式统计亦缺失，后续写作需以机制描述为主并标注未给出项。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布呈长尾，短请求优先组批，长尾样本进入延迟队列等待前缀复用。","批大小以token预算为单位组批，并发数受KV池容量与显存档位约束。","SLO以Rollout吞吐与样本陈旧率为约束，权重版本差超阈值触发丢弃。","奖励模型/验证器服务独立部署，输入为生成样本，输出分数回传调度器。"],"train_recipe":["硬件档位材料未给出，部署需明确B200/B300/GB200 NVL72等档位与并行拓扑。","量化方案以NVFP4/FP8为主，采样温度与top-p需按量化误差校准。","KV策略为前缀哈希共享池，命中跳过预填，未命中计算后写回。","监控覆盖队列深度、KV命中率、权重版本差与陈旧样本比例。","异步流水线需设定权重同步周期与陈旧样本丢弃阈值。"],"facts":["RhymeRL将Rollout引擎与训练解耦，训练侧仅发布权重快照，Rollout侧独立组批与生成，减少相互阻塞导致的流水线气泡。","系统利用历史生成轨迹的相似性做前缀共享，按前缀哈希查询KV池，命中则跳过重复预填，直接降低长尾样本的单位token预填代价。","批量生成调度以token预算组批，短请求优先填充，长尾样本进入延迟队列，等待后续批次出现相同前缀时复用KV或以投机解码补足。","异步权重同步以版本号标记快照，Rollout引擎检测版本差超过阈值时丢弃陈旧在途样本并重新同步，权衡吞吐与策略新鲜度。","解码阶段以NVFP4/FP8算子生成token，采样温度与top-p按量化误差校准，以约束低精度采样对生成分布的影响。","奖励模型与验证器以独立服务部署，避免与生成引擎争抢显存与算力，分数回传调度器用于批内优先级调整。","监控指标覆盖队列深度、KV命中率、权重版本差与陈旧样本比例，用于发现长尾拖累与同步滞后等失败模式。","材料未给出具体硬件档位、批大小、并发数与SLO配置，部署评估需补充这些参数才能核验吞吐与稳定性收益。"],"anchors":[],"pitfalls":["材料未给出具体数值结果，写作时不得编造吞吐提升倍数或采样误差上界。","异步同步的陈旧阈值与丢弃策略细节缺失，需避免把机制描述写成已量化结论。","NVFP4采样稳定性的校准方法未展开，不得臆造校准公式或误差界。"],"depth":"deep"},{"id":"paper-how-off-policy-can-grpo-be-mu-grpo-f-2026","title":"How Off-Policy Can GRPO Be? Mu-GRPO for Efficient LLM Reinforcement Learning","title_zh":"Mu-GRPO：放宽GRPO离策略容忍度","authors":["Minghao Tian","Yunfei Xie","Chen Wei"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-offpolicy-staleness","links":{"paper":"https://arxiv.org/abs/2605.17570","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"GRPO 类 RL 后训练依赖 rollout 引擎批量生成样本，训练与推理解耦后权重更新与样本生成之间存在时间差，样本相对当前策略的离策略程度随流水线深度上升。已有做法靠严格同步或丢弃过期样本来控制偏差，代价是吞吐下降与长尾样本浪费。本文考察 GRPO 能容忍多大离策略程度，并给出按离策略程度分组的批量生成与加权方案。","problem":"同步式 rollout 使训练步与生成步强耦合，异步流水线又让样本陈旧度不可控；直接丢弃过期样本会浪费长尾生成算力，全部保留则引入策略梯度偏差。需要一套可量化的离策略容忍机制，把陈旧度变成可调度、可加权的显式变量。","core_idea":"把每个 rollout 样本相对当前策略的离策略程度作为一等公民：按生成时的策略版本与当前版本的差异对样本分组，组内做长度与难度感知的批调度，组间在 loss 上按离策略程度加权或截断，从而在保持吞吐的同时把偏差控制在可接受范围。","architecture":"rollout 引擎与训练进程解耦，引擎侧维护权重版本号与 KV 前缀缓存；样本回流时携带版本戳，进入按陈旧度分桶的缓冲队列。调度器按桶内样本长度分布组批，优先消费新鲜桶以压低在途延迟，陈旧桶按阈值过滤或降权。训练侧在 GRPO 目标上叠加离策略权重，并对超阈值样本做掩码。奖励模型与验证器推理走独立服务，避免与生成争抢显存。","pipeline":["请求进入 rollout 引擎，按当前权重版本生成，同时写入版本戳与前缀 KV 缓存句柄。","生成完成的样本连同版本戳回流至按陈旧度分桶的缓冲队列，长尾样本继续在引擎侧生成。","调度器按桶内长度分布组批，新鲜桶优先进入训练，陈旧桶按阈值过滤或降权。","训练侧计算 GRPO 优势并对样本施加离策略权重，超阈值样本掩码，产出梯度更新。","更新后的权重按版本同步回 rollout 引擎，引擎切换版本并复用仍有效的前缀 KV。","奖励模型与验证器推理独立服务并行打分，结果回填样本元数据供下一轮调度。"],"formula":"$$\\mathcal{L}_{\\text{Mu-GRPO}}=\\frac{1}{\\sum_i w_i}\\sum_i w_i\\,\\mathcal{L}_{\\text{GRPO}}(o_i)\\,,\\quad w_i=\\mathbb{1}\\left[\\delta_i\\le \\delta_{\\max}\\right]\\cdot\\exp\\left(-\\lambda\\,\\delta_i\\right)$$","training":"训练侧沿用 GRPO 的组内相对优势估计，额外引入样本级离策略权重：以生成时策略与当前策略的版本差或对数概率差度量陈旧度，超过阈值即掩码，未超阈值按指数衰减降权。权重同步采用版本号递增的异步推送，rollout 引擎在批次边界切换版本，避免同批内混用多版本权重导致 KV 缓存失效。监控项包括各陈旧度桶的在途样本数、过滤率与有效批大小。","walkthrough":"一轮迭代中，rollout 引擎以版本 v 生成一批样本，其中短样本先完成并进入新鲜桶，长尾样本仍在解码。训练进程此时已推进到版本 v+1，调度器从新鲜桶取批，按长度分桶组批后送入训练；陈旧桶中版本差超过阈值的样本被掩码，未超阈值的按权重参与 loss。权重 v+1 推回引擎后，引擎在批次边界切换版本，仍匹配的前缀 KV 缓存继续复用，不匹配的句柄失效重算。奖励模型服务独立打分并回填元数据，供下一轮桶划分参考。","pseudocode":"初始化 rollout 引擎与训练进程，设定陈旧度阈值 delta_max 与衰减系数 lambda\n循环每个训练步：\n    引擎以当前权重版本 v 生成样本，样本携带版本戳与 KV 句柄\n    样本回流至按陈旧度分桶的缓冲队列\n    调度器优先取新鲜桶，按长度分布组批\n    对每批样本计算 delta_i（版本差或对数概率差）\n    若 delta_i 大于 delta_max 则掩码该样本\n    否则以权重 exp(-lambda * delta_i) 加权 GRPO loss\n    反向传播更新权重，版本号递增\n    在批次边界将新版本推回引擎，复用仍有效的前缀 KV\n    记录各桶在途数、过滤率与有效批大小","experiments":{"datasets":["材料未给出具体数据集名称，仅提及 RL 后训练 rollout 场景"],"baselines":["同步式 GRPO rollout","丢弃过期样本的异步流水线"],"results":"材料未给出可核验的吞吐与精度数字，仅说明按离策略程度分组加权可在保持吞吐的同时控制策略梯度偏差；具体加速比、过滤率与精度变化均未给出。","limits":"材料未给出长尾样本比例、陈旧度阈值取值与硬件档位下的实测吞吐；对 NVFP4 采样稳定性与 KV 复用命中率的影响未量化。","ablations":"材料未给出消融实验细节，仅可推断陈旧度阈值与衰减系数为主要可调项，其取值对吞吐与偏差的权衡未给出数据。"},"innovation":["把离策略程度显式化为样本级权重与掩码阈值，使陈旧度成为可调度变量而非被动丢弃。","按陈旧度分桶并结合长度分布组批，兼顾新鲜度与批效率。","权重版本戳与 KV 前缀缓存句柄绑定，版本切换时按匹配性复用缓存。"],"limitations":["材料未给出阈值与衰减系数的选取准则，超参数敏感度未知。","异步权重同步下同批多版本风险依赖批次边界切换，边界外的缓存失效代价未量化。","未讨论 NVFP4 量化下采样分布偏移对离策略权重估计的影响。"],"impact":"为 RL 后训练 rollout 与训练解耦提供了一条以陈旧度为调度维度的工程路径，使异步流水线在可控偏差下换取吞吐；对长尾样本的利用与 KV 复用策略有直接指导意义，但需在具体硬件档位与量化方案下补足实测数据。","summary":"本文提出 Mu-GRPO，将 GRPO rollout 样本相对当前策略的离策略程度作为显式变量：样本携带权重版本戳回流至陈旧度分桶队列，调度器优先消费新鲜桶并按长度组批，训练侧对超阈值样本掩码、未超阈值样本按指数权重参与 GRPO loss。权重按版本异步推回引擎并在批次边界切换，配合前缀 KV 缓存复用降低重算代价。材料未给出具体数据集、吞吐与精度数字，阈值选取与量化下采样稳定性仍待补足。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为 RL 后训练 rollout 请求，长度分布呈长尾，短样本先完成、长尾样本持续解码。","批大小由调度器按陈旧度桶内长度分布动态组批，新鲜桶优先以压低在途延迟。","并发度受 rollout 引擎显存与 KV 缓存容量约束，长尾样本占用槽位时间显著高于短样本。","SLO 以训练步等待时间为约束，允许一定陈旧度换取吞吐，超阈值样本被掩码而非阻塞流水线。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署形态为 rollout 引擎与训练进程解耦的异步流水线。","量化方案材料未给出，NVFP4 下采样稳定性未讨论。","KV 策略为前缀缓存句柄与权重版本绑定，版本切换时按匹配性复用，不匹配则重算。","监控项包括各陈旧度桶在途样本数、过滤率、有效批大小与权重版本切换延迟。","奖励模型与验证器推理独立服务部署，避免与生成争抢显存与算力。"],"facts":["样本回流时携带生成时的权重版本戳，训练侧以版本差或对数概率差度量离策略程度，超过阈值即掩码，未超阈值按指数衰减权重参与 GRPO loss。","调度器按陈旧度分桶并以桶内长度分布组批，新鲜桶优先进入训练以压低在途延迟，长尾样本留在引擎侧继续解码而不阻塞流水线。","权重同步采用版本号递增的异步推送，rollout 引擎在批次边界切换版本，避免同批内混用多版本权重导致前缀 KV 缓存句柄失效。","前缀 KV 缓存句柄与权重版本绑定，版本切换时仅复用仍匹配的缓存，不匹配部分重算，缓存命中率直接影响重算算力代价。","奖励模型与验证器推理走独立服务，与生成解耦部署，避免打分阶段与 rollout 争抢显存与算力，打分结果回填样本元数据供桶划分。","过滤率与有效批大小是核心监控项：阈值过严导致长尾样本被大量掩码、有效批缩小，阈值过松则策略梯度偏差上升。","材料未给出陈旧度阈值、衰减系数与长尾样本比例的具体取值，也未给出 NVFP4 量化下采样分布偏移对权重估计的影响。"],"anchors":[],"pitfalls":["把陈旧度阈值当作固定超参数而不随硬件档位与负载长度分布调整，易在长尾比例高时有效批骤减。","仅按版本差度量离策略程度而忽略量化后对数概率估计偏差，可能低估真实分布偏移。","批次边界外切换权重会使部分在途样本的 KV 句柄失效，重算代价被低估时吞吐收益被抵消。"],"depth":"shallow"},{"id":"paper-hugo-llms-as-whole-body-policy-code-2026","title":"HuGo: LLMs as Whole-Body Policy Code Designers for Humanoid Loco-Manipulation","title_zh":"HuGo：人形全身策略代码设计","authors":["Seoyeon Choi","Shizhao Ye","Nicholas Bui","Aayushi Shrivastava","Kanghyun Ryu","Dhruva Tirumala","Markus Wulfmeier","Negar Mehr"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2609.30594","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注人形机器人全身移动操作（loco-manipulation）的策略生成问题，提出让大语言模型充当全身策略代码的设计者。与本卷关心的推理机制与部署容量两条线相交之处在于：策略代码的生成、候选方案的批量采样、验证器或奖励模型对候选代码的评估，以及长尾样本导致的吞吐塌陷，都会落到 rollout 引擎的批调度、KV 复用与前缀共享、异步流水线与权重同步等工程代价上。材料未给出具体硬件档位与量化方案，因此相关判断只能落在机制层面。","problem":"人形全身移动操作的动作空间维度高、约束耦合强，手工编写策略代码代价高；若用大模型批量生成候选策略代码并由验证器筛选，则候选质量分布长尾、验证器调用密集，rollout 吞吐与 KV 复用成为瓶颈，且候选筛选阈值与批大小直接决定单位时间有效样本数。","core_idea":"把大语言模型当作全身策略代码的设计者：由模型生成可执行的人形 loco-manipulation 策略代码，经执行与验证器评估后回流筛选，形成“生成—执行—验证—再生成”的闭环。工程上把生成侧与验证侧解耦为不同批次的流水线，用前缀共享复用系统提示与任务描述，用长尾丢弃阈值控制尾部候选占用的解码槽位。","architecture":"材料未给出具体模型规模、并行拓扑与硬件档位，仅能确认系统由生成侧与验证侧两段构成。生成侧承载策略代码的批量解码，任务描述与代码骨架作为共享前缀进入 KV 缓存；验证侧对候选代码执行仿真或规则检查并给出评分。两段之间通过异步队列传递候选，权重同步发生在生成侧模型更新后，验证侧不持有生成权重。长尾候选按阈值截断，避免少数慢样本长期占用解码槽位。","pipeline":["任务描述与代码骨架拼成共享前缀，进入生成侧 KV 缓存并复用，避免每个候选重复预填。","生成侧按批调度解码候选策略代码，批内按长度分桶，长尾候选进入独立慢队列。","候选代码送入验证侧执行与规则检查，验证器给出评分并标注失败模式。","评分回流筛选，低于阈值的候选被丢弃，高分候选进入下一轮再生成或代码修补。","生成侧模型权重更新后与验证侧做异步权重同步，同步窗口内旧权重候选按陈旧度标记。","高分候选汇总为策略代码库，长尾样本统计进入监控以调整批大小与丢弃阈值。"],"formula":"$$\\mathrm{Throughput}_{\\mathrm{eff}}=\\frac{N_{\\mathrm{cand}}\\cdot \\mathbb{1}\\left[\\mathrm{score}\\ge \\tau\\right]}{T_{\\mathrm{gen}}+T_{\\mathrm{verify}}+T_{\\mathrm{sync}}}$$","training":"材料未给出训练配方，本卡不写训练细节。与部署相关的部分是：生成侧模型在权重更新后需要与验证侧做异步同步，同步窗口内产生的候选带有陈旧度标记；若同步窗口过长，旧权重生成的候选会稀释有效吞吐。验证侧的评分规则与执行环境版本需与生成侧代码骨架保持一致，否则候选失败率上升，长尾队列膨胀。监控应记录候选评分分布、丢弃率与同步窗口时长。","walkthrough":"一次完整请求的流动如下：任务描述与代码骨架先做一次预填，其 KV 留在生成侧缓存中供同任务的所有候选复用；随后生成侧按批解码出若干候选策略代码，批内按生成长度分桶，超过长度阈值的候选被移入慢队列以免拖住整批；候选代码送入验证侧执行，验证器返回评分与失败原因；评分低于阈值的候选被丢弃，高分候选进入下一轮修补生成；与此同时生成侧模型完成一次权重更新，验证侧在异步窗口内继续用旧权重评分，窗口结束后切换。整个过程中，有效吞吐由候选通过率、验证侧排队长度与同步窗口共同决定，长尾候选的槽位占用是最主要的吞吐损失来源。","pseudocode":"初始化生成侧 KV 缓存与验证侧队列\n对每个任务：\n    预填任务描述与代码骨架 -> 写入共享前缀 KV\n    按长度分桶组成解码批\n    解码候选策略代码 -> 超过长度阈值移入慢队列\n    候选送入验证侧执行 -> 返回评分与失败原因\n    若 评分 < 阈值 -> 丢弃并计入长尾统计\n    否则 -> 进入下一轮修补生成\n    若 生成侧权重已更新 -> 异步同步验证侧并标记陈旧候选\n    汇总高分候选 -> 更新批大小与丢弃阈值","experiments":{"datasets":["材料未给出具体数据集名称与规模。"],"baselines":["材料未给出对比基线。"],"results":"材料未给出可核验的数值结果。仅能确认论文以人形全身 loco-manipulation 的策略代码生成为任务形态，候选经执行与验证器筛选后回流；具体通过率、吞吐与成功率数字均未给出，无法在本卡中引用。","limits":"材料未给出实验限制说明。从机制上看，候选质量分布长尾会拉低有效吞吐，验证侧执行成本与生成侧解码成本不匹配时流水线会出现气泡；权重同步窗口内的陈旧候选会稀释评分有效性，这些代价在材料中均无量化。","ablations":"材料未给出消融实验。可预期的消融维度包括共享前缀复用与否、长尾丢弃阈值高低、批内长度分桶策略以及异步权重同步窗口长度，但论文是否报告这些维度未给出。"},"innovation":["把大语言模型定位为全身策略代码的设计者，而非直接输出动作，生成物是可执行代码。","生成侧与验证侧解耦为异步流水线，候选按评分回流筛选，形成闭环再生成。","以共享前缀 KV 复用承载同任务的重复预填，降低候选批量生成的预填开销。"],"limitations":["材料未给出硬件档位、量化方案与并行拓扑，无法评估 NVFP4 等低精度下的采样稳定性。","候选质量长尾导致慢队列占用解码槽位，有效吞吐受通过率与验证侧排队共同制约。","异步权重同步窗口内的陈旧候选缺少量化评估，评分有效性可能被稀释。"],"impact":"该工作把策略代码生成纳入 rollout 引擎的批量采样与验证器服务体系，提示后续部署需要把生成侧与验证侧分开做容量规划，并用共享前缀复用与长尾丢弃阈值控制有效吞吐；对 Blackwell 档位上的批调度与 KV 策略设计具有机制层面的参考价值，但材料未给出可直接引用的硬件与量化数据。","summary":"HuGo 提出让大语言模型充当人形全身 loco-manipulation 的策略代码设计者，候选代码经执行与验证器评分后回流筛选。本卡只从推理机制与部署容量两条线整理：生成侧以共享前缀 KV 复用承载同任务预填，批内按长度分桶并把超长候选移入慢队列；验证侧独立排队，评分低于阈值即丢弃；生成侧权重更新后与验证侧异步同步，窗口内候选标记陈旧度。有效吞吐由通过率、验证排队与同步窗口共同决定，长尾槽位占用是主要损失来源。材料未给出硬件档位、量化方案与数值结果，相关判断仅落在机制与工程代价上。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为任务描述加代码骨架的共享前缀，长度分布未给出，需按前缀复用率评估预填开销。","候选生成为批量解码，批大小与并发未给出，需按长度分桶避免长尾拖住整批。","验证侧请求密度高于生成侧，评分调用密集，需独立容量规划并设置排队上限。","SLO 未给出，只能以候选通过率与单位时间有效样本数作为吞吐口径。"],"train_recipe":["硬件档位未给出，无法指定 B200/B300/GB200 NVL72 中的具体档位。","并行拓扑未给出，生成侧与验证侧应分开部署以避免资源争抢。","量化方案未给出，NVFP4 下的采样稳定性无法评估。","KV 策略为共享前缀复用加按任务隔离，长尾候选移入慢队列。","监控项包括候选评分分布、丢弃率、慢队列长度与权重同步窗口时长。"],"facts":["生成侧把任务描述与代码骨架作为共享前缀写入 KV 缓存，同任务的所有候选复用该前缀，避免每个候选重复预填，预填开销随候选数增长被摊薄。","候选解码按批内长度分桶调度，超过长度阈值的候选被移入独立慢队列，防止少数长尾样本长期占用解码槽位而拖慢整批的有效吞吐。","验证侧对候选代码执行仿真或规则检查并返回评分与失败原因，评分低于阈值的候选被丢弃并计入长尾统计，通过率直接决定单位时间有效样本数。","生成侧模型权重更新后与验证侧做异步同步，同步窗口内验证侧仍用旧权重评分，窗口内产生的候选带陈旧度标记，窗口过长会稀释评分有效性。","有效吞吐由候选通过率、验证侧排队长度与同步窗口共同决定，三者中任一环节出现气泡都会使流水线整体吞吐下降，需分别监控。","材料未给出硬件档位与量化方案，因此 NVFP4 或 FP8 下候选采样的数值稳定性、KV 缓存精度与显存占用均无法在本卡中量化。","长尾候选的槽位占用是主要吞吐损失来源，丢弃阈值过低会放大慢队列长度，过高则降低候选多样性，阈值需与批大小联动调整。"],"anchors":[],"pitfalls":["把生成侧与验证侧混部在同一资源池会导致解码与验证互相争抢，流水线出现气泡，需分开做容量规划。","异步权重同步窗口过长会让旧权重候选混入高分集合，评分分布失真，需记录陈旧度并限制窗口时长。","长尾丢弃阈值设置不当会放大慢队列长度或损失候选多样性，需与批大小联动调整而非固定常量。"],"depth":"shallow"},{"id":"paper-loongsage-a-production-grade-high-ef-2026","title":"LoongSage: A Production-Grade, High-Efficiency Agentic RL Framework for Frontier LLMs with Validated Recipes","title_zh":"LoongSage 生产级智能体 RL 推理框架","authors":[" LoongSage Team","Bowei Song","Caiwei Zhao","Chuwen Liu","Dechuang Gu","Dong Fang","Feiyu Xie","Huaiyu Li","Hui Zhang","Jian Tian","Jian Wang","Jie Zhao"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2610.16352","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"前沿 LLM 的智能体强化学习后训练需要大规模 rollout 推理：策略模型对多轮交互轨迹批量采样，奖励模型与验证器再对轨迹打分，随后把打分结果回流到训练侧更新权重。这一链路同时受限于生成吞吐、长尾样本拖尾、KV cache 复用效率与权重同步开销，生产环境还要求可监控的 SLO 与失败恢复能力。论文面向该场景给出可复用的工程配方与验证过的训练配置。","problem":"智能体 RL rollout 与训练紧耦合时，批量生成调度、前缀共享与 KV 复用难以独立优化；长尾样本使批次尾部空转；权重同步阻塞生成；NVFP4 量化下的采样稳定性缺乏验证。论文要解决的是把 rollout 引擎与训练解耦后，如何在 Blackwell 档位上稳定达到生产吞吐。","core_idea":"将 rollout 引擎与训练器解耦为独立服务：生成侧按批量调度与前缀共享复用 KV，奖励模型与验证器单独部署为推理服务；训练侧通过异步流水线接收轨迹并周期性同步权重；对长尾样本采用超时截断与重排策略；在 NVFP4 路径上加入采样数值校验以维持分布稳定。","architecture":"框架分为四层：请求层接收智能体环境产生的多轮交互请求并标注前缀；rollout 引擎层负责批量生成调度、KV cache 分块与前缀共享、投机解码与分离式预填/解码；打分服务层独立部署奖励模型与验证器，按批聚合打分；训练侧通过异步队列消费轨迹，权重同步以版本号协调。监控覆盖队列深度、KV 命中率、长尾占比与采样数值偏差。","pipeline":["环境侧产生多轮交互请求，携带对话前缀与采样参数进入 rollout 队列。","调度器按前缀相似度聚合请求，命中前缀共享的请求复用已有 KV cache 块。","rollout 引擎执行批量生成，分离式预填与解码并行推进，长尾请求按超时阈值截断。","奖励模型与验证器服务对完成轨迹批量打分，结果写入轨迹队列。","训练侧异步消费轨迹，按版本号触发权重同步，新权重热加载到 rollout 引擎。"],"formula":"$$\\mathrm{Throughput}_{\\mathrm{rollout}}=\\frac{\\sum_{i=1}^{N} L_i}{T_{\\mathrm{gen}}+T_{\\mathrm{score}}+T_{\\mathrm{sync}}}$$","training":"论文不涉及训练配方本身，只描述后训练推理侧的部署配方：rollout 引擎与训练器解耦部署，权重按版本号周期性同步并热加载；打分服务独立扩缩容；批次按前缀聚合以提升 KV 复用；长尾样本以超时截断控制批次尾部空转；NVFP4 路径加入采样数值校验。监控指标包括队列深度、KV 命中率、长尾占比与采样偏差。","walkthrough":"一次典型 rollout 周期：环境提交一批多轮请求，调度器按前缀哈希分组，命中前缀共享的请求直接复用 KV 块，未命中的走分离式预填。生成过程中投机解码加速解码阶段，长尾请求在超时阈值后被截断并标记。完成轨迹送入独立部署的奖励模型与验证器服务批量打分，打分结果进入轨迹队列。训练侧异步消费，达到步数后按版本号同步新权重到 rollout 引擎，引擎热加载后继续下一轮。整个链路中队列深度、KV 命中率与采样数值偏差被持续监控，异常时降级到 FP8 路径。","pseudocode":"循环 每个 rollout 周期：\n  请求批次 <- 环境提交多轮请求\n  按前缀哈希分组 请求批次\n  对每组：\n    若 命中前缀共享：复用 KV 块\n    否则：分离式预填 -> 解码（投机解码加速）\n    长尾请求 -> 超时截断并标记\n  轨迹 <- 完成样本\n  打分 <- 奖励模型与验证器服务批量推理\n  轨迹队列 <- 打分结果\n  训练侧异步消费轨迹队列\n  若 达到同步步数：\n    版本号+1 -> 热加载权重到 rollout 引擎\n  监控 队列深度/KV 命中率/采样偏差","experiments":{"datasets":["智能体多轮交互轨迹（论文未给出具体数据集名称）"],"baselines":["未给出"],"results":"论文声称在生产级智能体 RL 场景下实现高吞吐 rollout，但材料未给出具体吞吐数字、加速比或采样稳定性指标，仅描述了解耦架构与批量调度机制；所有量化结论需以论文正文为准。","limits":"材料未给出硬件档位、并行拓扑与量化方案的具体配置，也未给出长尾样本占比与 SLO 达标率；NVFP4 采样稳定性的验证细节缺失，无法判断量化误差对策略分布的影响程度。","ablations":"材料未给出消融实验，无法核验前缀共享、批量调度与解耦部署各自的贡献；论文所称验证过的配方缺少可复现的超参与阈值。"},"innovation":["rollout 引擎与训练器解耦为独立服务，权重按版本号热加载，避免同步阻塞生成。","按前缀相似度聚合请求并复用 KV cache 块，降低多轮交互的重复预填开销。","奖励模型与验证器独立部署为打分服务，按批聚合打分并与生成侧异步流水线衔接。"],"limitations":["材料未给出具体硬件档位与并行拓扑，部署代价无法量化。","NVFP4 采样稳定性仅有机制描述，缺少数值偏差与分布校验的实测数据。","长尾样本的超时截断阈值与批次重排策略未给出具体参数。"],"impact":"该工作把智能体 RL rollout 的工程问题拆解为解耦部署、批量调度、KV 复用与打分服务四条线，为 Blackwell 档位上的生产部署提供了可讨论的框架；其价值在于机制层面的组织方式，而非具体性能数字。","summary":"LoongSage 是一篇面向前沿 LLM 智能体强化学习后训练的生产级推理框架论文。它把 rollout 引擎与训练器解耦，生成侧按前缀聚合请求并复用 KV cache，奖励模型与验证器独立部署为打分服务，训练侧异步消费轨迹并按版本号热加载权重。论文强调批量生成调度、长尾样本截断与 NVFP4 采样稳定性，但材料未给出具体硬件配置、吞吐数字与消融结果，量化结论需以正文为准。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为智能体多轮交互请求，携带对话前缀与采样参数，长度分布未给出。","批大小与并发度未给出，调度按前缀相似度聚合以提升 KV 命中率。","长尾样本按超时阈值截断，阈值具体数值未给出。","SLO 指标包括队列深度、KV 命中率与采样数值偏差，达标率未给出。"],"train_recipe":["硬件档位未给出，材料未说明 B200/B300/GB200 NVL72 的具体选择。","并行拓扑未给出，rollout 引擎与训练器解耦部署，打分服务独立扩缩容。","量化方案涉及 NVFP4 路径并加入采样数值校验，异常时降级到 FP8。","KV 策略为前缀共享与分块复用，具体块大小未给出。","监控覆盖队列深度、KV 命中率、长尾占比与采样偏差。"],"facts":["框架将 rollout 引擎与训练器解耦为独立服务，权重按版本号周期性同步并热加载，避免训练更新阻塞生成侧批量采样。","调度器按前缀哈希对多轮交互请求分组，命中前缀共享的请求复用已有 KV cache 块，减少重复预填的计算与显存开销。","奖励模型与验证器独立部署为打分服务，对完成轨迹批量推理打分，结果写入轨迹队列供训练侧异步消费。","长尾样本在超时阈值后被截断并标记，用于控制批次尾部空转，但材料未给出阈值具体数值与长尾占比。","NVFP4 路径加入采样数值校验，异常时降级到 FP8，材料未给出偏差阈值与稳定性实测数据。","生成侧采用分离式预填与解码并配合投机解码加速解码阶段，具体并行切分与通信拓扑未给出。","监控指标包括队列深度、KV 命中率、长尾占比与采样数值偏差，用于生产环境的失败模式发现与降级决策。","论文声称提供验证过的配方，但材料未给出吞吐数字、加速比与消融结果，量化结论需以正文为准。"],"anchors":[],"pitfalls":["材料缺少硬件档位与并行拓扑，直接引用其吞吐结论会脱离具体部署代价。","NVFP4 采样稳定性仅有机制描述，未验证量化误差对策略分布的影响，不宜当作已证结论。","长尾截断阈值与批次重排策略未给出参数，复现时需自行标定，否则吞吐与样本质量会偏离。"],"depth":"shallow"},{"id":"paper-mcp-universe-rl-a-framework-for-trai-2026","title":"MCP-Universe RL: A Framework for Training MCP Tool-Use Agents via Reinforcement Learning","title_zh":"MCP工具智能体RL推理框架","authors":["Ziyang Luo","Yan Yang","Xiangru Jian","Ziji Shi","Xiaoqiang Lin","Jun Hao Liew","Silvio Savarese","Junnan Li"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2608.22167","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"面向MCP工具调用智能体的强化学习后训练需要把rollout生成与训练解耦：策略模型在推理引擎上批量采样多轮工具交互轨迹，环境返回工具结果后继续解码，再由奖励模型或验证器打分回传梯度。Blackwell档位下，NVFP4/FP8量化、KV cache复用与前缀共享、批调度与长尾样本共同决定rollout吞吐与采样稳定性。","problem":"MCP工具调用轨迹是多轮、变长、强依赖外部工具延迟的，rollout引擎若与训练同步耦合，会被长尾样本与工具等待拖住；同时批量生成中的KV复用、前缀共享与量化采样误差会放大策略更新偏差。","core_idea":"把MCP工具调用智能体的RL rollout做成推理与训练解耦的框架：rollout引擎批量生成多轮工具交互，KV cache与前缀共享复用系统提示与历史，奖励模型/验证器独立服务打分，异步流水线把生成、打分与权重同步分离，从工程上吸收长尾与工具延迟。","architecture":"框架分三层：rollout引擎侧维护批量生成调度器与KV cache池，按请求前缀共享系统提示与工具schema；工具执行层把MCP调用作为外部阻塞点，挂起后回填结果继续解码；训练侧通过异步流水线接收轨迹与奖励，权重同步以版本号对齐，避免off-policy漂移。量化方案与并行拓扑在引擎侧配置，监控覆盖队列深度、KV命中率与长尾等待。","pipeline":["请求进入rollout引擎，按系统提示与工具schema做前缀匹配，命中则复用KV cache块。","调度器按批大小与并发上限组批，解码到工具调用token时挂起该序列并发出MCP请求。","工具结果回填后恢复解码，历史token追加进KV cache，继续多轮直到终止或轮数上限。","完成的轨迹送入奖励模型/验证器服务打分，打分与生成异步并行。","打分轨迹进入训练侧缓冲，按权重版本号过滤过期样本后回传梯度。","权重同步后刷新引擎侧版本，KV池按前缀热度做淘汰与重算。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{\\tau\\sim\\pi_{\\theta_{\\text{old}}}}\\left[\\sum_{t}\\min\\left(\\rho_t(\\theta)\\hat{A}_t,\\ \\text{clip}(\\rho_t(\\theta),1-\\epsilon,1+\\epsilon)\\hat{A}_t\\right)\\right],\\quad \\rho_t(\\theta)=\\frac{\\pi_\\theta(a_t\\mid s_t)}{\\pi_{\\theta_{\\text{old}}}(a_t\\mid s_t)}$$","training":"训练侧只消费rollout引擎产出的轨迹与奖励，不直接驱动生成；异步流水线用权重版本号标记每条轨迹的策略版本，过期样本按阈值丢弃以控制off-policy staleness。奖励模型/验证器独立部署，避免与生成争抢显存与算力。KV复用与前缀共享降低重复预填代价，长尾样本通过挂起与超时回收避免阻塞整批。","walkthrough":"一次典型rollout：调度器取一批请求，前缀匹配命中系统提示KV块后直接解码；序列在工具调用处挂起，MCP请求发出后该槽位让给其他序列，工具结果回填再恢复。多轮结束后轨迹进入奖励队列，验证器并行打分；训练侧按版本号取用未过期轨迹更新策略，新权重同步到引擎后旧KV块按前缀热度保留或重算。长尾请求超时后被单独回收，不拖住整批完成。","pseudocode":"初始化 rollout 引擎与 KV 池，加载量化权重与并行拓扑\n循环直到训练结束：\n  调度器按批大小与并发上限组批\n  对每条请求做前缀匹配 -> 命中则复用 KV 块，否则预填\n  解码到工具调用 token -> 挂起序列并发出 MCP 请求\n  工具结果回填 -> 追加 KV -> 继续解码直到终止或轮数上限\n  轨迹送入奖励/验证器服务异步打分\n  训练侧按权重版本号过滤过期轨迹 -> 回传梯度\n  权重同步 -> 刷新引擎版本 -> KV 池按热度淘汰","experiments":{"datasets":["MCP工具调用多轮任务集（具体规模未给出）"],"baselines":["同步耦合式rollout训练（具体基线未给出）"],"results":"材料未给出可核验的吞吐、采样稳定性或任务成功率数字；框架层面的判断是解耦与异步流水线能吸收工具延迟与长尾，KV复用降低重复预填代价，具体收益未给出。","limits":"材料未给出硬件档位、并行拓扑与量化配置的实测数据；NVFP4下采样稳定性、奖励模型服务容量与权重同步频率对staleness的影响均未量化，长尾超时阈值也未给出。","ablations":"材料未给出消融实验；可预期的消融维度是KV前缀共享开关、异步流水线深度与过期样本过滤阈值，但均无数字支撑。"},"innovation":["把MCP工具调用rollout与训练解耦，工具阻塞点以挂起方式吸收而非阻塞整批。","KV cache前缀共享复用系统提示与工具schema，降低多轮重复预填代价。","奖励模型/验证器独立服务并与生成异步并行，权重版本号控制off-policy staleness。"],"limitations":["材料未给出任何吞吐、延迟与采样稳定性数字，机制收益无法定量核验。","NVFP4量化下的采样稳定性与奖励打分一致性未讨论，存在策略漂移风险。","长尾样本超时回收与KV池淘汰策略缺少阈值与失败模式说明。"],"impact":"为MCP工具智能体的RL后训练提供推理与训练解耦的工程骨架：rollout引擎承担批量生成与KV复用，奖励服务独立扩容，异步流水线与版本号控制staleness。对Blackwell部署的意义在于把量化、并行拓扑与KV策略收敛到引擎侧配置，便于按SLO调容量。","summary":"论文提出MCP-Universe RL框架，面向MCP工具调用智能体的强化学习后训练，核心是把rollout生成与训练解耦：引擎侧批量生成多轮工具交互并做KV前缀共享，工具调用处挂起序列吸收外部延迟，奖励模型/验证器独立异步打分，训练侧按权重版本号过滤过期轨迹。材料未给出硬件档位、量化配置与吞吐数字，机制判断停留在工程骨架层面，NVFP4采样稳定性与长尾吞吐仍需实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为多轮工具调用轨迹，请求长度随工具返回内容增长，分布长尾明显（具体分位数未给出）。","批大小与并发上限由调度器按显存与KV池容量设定，材料未给出具体数值。","工具调用作为外部阻塞点，单请求等待时间方差大，需挂起与超时回收配合。","SLO以批完成时间与长尾等待为约束，材料未给出目标值。"],"train_recipe":["硬件档位与并行拓扑材料未给出，框架按引擎侧可配置处理。","量化方案材料未给出，NVFP4/FP8采样稳定性需单独验证。","KV策略为前缀共享加热度淘汰，系统提示与工具schema优先保留。","监控覆盖队列深度、KV命中率、长尾等待与权重版本滞后。","权重同步以版本号对齐，过期样本按阈值过滤控制staleness。"],"facts":["rollout引擎与训练解耦：引擎批量生成多轮工具交互轨迹，训练侧只消费轨迹与奖励，避免生成与梯度更新争抢同一批显存与算力。","工具调用处采用挂起机制：解码到工具调用token时序列让出槽位，MCP结果回填后追加KV继续解码，长尾等待不阻塞整批完成。","KV cache前缀共享复用系统提示与工具schema，多轮轨迹的历史token追加进同一KV池，按前缀热度做淘汰与重算以控制显存。","奖励模型/验证器独立服务并与生成异步并行，打分队列与生成队列分离，避免验证器推理挤占rollout引擎的批调度容量。","异步流水线用权重版本号标记轨迹的策略版本，训练侧按阈值过滤过期样本，以工程手段控制off-policy staleness而非同步等待。","长尾样本通过超时回收单独处理，调度器按批大小与并发上限组批，队列深度与KV命中率作为监控指标反映容量瓶颈。","量化方案与并行拓扑在引擎侧配置，材料未给出NVFP4下采样稳定性数据，采样误差与奖励一致性需单独验证。","框架未给出硬件档位与吞吐数字，容量判断只能落到机制层：KV池容量、批调度上限与奖励服务副本数共同决定SLO。"],"anchors":[],"pitfalls":["材料未给出任何数字，写作时不得虚构吞吐、延迟或成功率，只能描述机制与工程代价。","NVFP4量化下的采样稳定性未被讨论，不能默认量化对策略梯度无偏。","长尾超时阈值与KV淘汰策略缺失，容量规划需标注为未给出而非默认合理。"],"depth":"shallow"},{"id":"paper-medusa-simple-llm-inference-accelera-2024","title":"Medusa: Simple LLM Inference Acceleration Framework with Multiple Decoding Heads","title_zh":"Medusa 多头并行解码加速","authors":["Tianle Cai","Yuhong Li","Zhengyang Geng","Hongwu Peng","Jason D. Lee","Deming Chen","Tri Dao"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2401.10774","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"自回归大模型逐 token 解码受内存带宽限制，单步只出一个 token，长序列生成时 GPU 算力大量闲置。投机解码用草稿模型提出候选再由目标模型并行验证，可减少目标模型前向次数，但额外草稿模型带来部署与训练成本。Medusa 试图在不引入独立草稿模型的前提下，用目标模型自身的隐藏状态并行预测多个未来位置，从而把验证式并行解码做成轻量附加模块。","problem":"如何在不训练独立草稿模型、不改变目标模型权重的前提下，用较低工程代价获得多 token 并行解码收益，并把候选生成、树状验证、接受判定组织成可部署的推理流水线。","core_idea":"在目标模型最后一层隐藏状态之上挂多个轻量解码头，第 k 个头预测未来第 k 个 token，从而一次前向得到多个位置的候选；再用树状注意力把候选组织成多条路径，由目标模型一次前向并行验证，按最长被接受前缀推进解码。","architecture":"Medusa 在冻结的目标模型骨干上附加若干解码头，每个头是一个小型残差前馈模块，输入为最后一层隐藏状态，输出对应未来位置的 logits。候选被组织成树结构，根为当前已确认 token，各层为不同头给出的候选；验证阶段用树状注意力掩码让目标模型一次前向对所有树节点打分，得到每个节点的条件概率，再沿路径比较草稿概率与目标概率做接受判定。被接受的最长前缀直接写入 KV cache，其余分支丢弃。","pipeline":["请求进入后由目标模型正常前向，得到当前 token 的隐藏状态与 logits，并写入 KV cache。","多个解码头基于同一隐藏状态并行输出未来若干位置的候选 token 及其草稿概率。","按预设树结构把各头候选组装成多条候选路径，构造树状注意力掩码。","目标模型对整棵树做一次前向，得到每个树节点的目标条件概率，并复用已确认前缀的 KV。","沿每条路径比较草稿与目标概率做接受判定，取最长被接受前缀，把对应 KV 写入缓存并推进解码位置。","若最长接受前缀为空则退回单 token 解码，循环直至达到停止条件或长度上限。"],"formula":"$$\\prod_{i=1}^{K}\\frac{p_{\\text{target}}(x_i\\mid x_{<i})}{p_{\\text{medusa}}(x_i\\mid x_{<i})}\\ge u,\\quad u\\sim\\mathcal{U}(0,1)$$","training":"解码头与目标模型联合训练时冻结骨干，仅用目标模型自身生成的隐藏状态与后续 token 作为监督，对每个头分别计算交叉熵损失并求和。训练数据来自目标模型在目标任务上的采样输出，使解码头适配目标分布；也可在特定领域数据上微调以提升接受率。训练代价远低于独立草稿模型，因为可训练参数只集中在若干小型解码头。","walkthrough":"以一次解码步为例：目标模型先对已确认前缀做前向，得到最后位置隐藏状态 h。K 个解码头并行读 h，分别给出第 1 到第 K 个未来位置的候选分布。系统按树结构采样出若干条路径，例如每个头取 top 候选并组合成树。随后把树中所有节点拼成一个序列，配以树状注意力掩码，使每个节点只能看到其祖先；目标模型一次前向即对所有节点给出条件概率。接受判定沿每条路径逐位置进行，用草稿概率与目标概率之比与均匀随机数比较，一旦某位置被拒即截断该路径。最终取所有路径中最长的被接受前缀，将其 token 与对应 KV 写入缓存，解码位置前移该长度。若全部被拒，则只接受根节点后的第一个目标 token，退化为普通解码。该过程把多次目标前向压缩为一次，代价是树节点带来的额外计算与显存占用。","pseudocode":"输入：已确认前缀 x，目标模型 M，解码头集合 H，树结构 T\n1. h <- M.forward(x) 的最后一层隐藏状态\n2. 对每个头 h_k in H：logits_k <- h_k(h)，采样候选 c_k\n3. 按 T 组装候选树，生成树状注意力掩码 mask\n4. 拼接树节点为序列 s，一次前向：p <- M.forward(s, mask)\n5. 对每条路径 path in T：\n     逐位置比较草稿概率与目标概率，遇拒即截断\n6. 取最长被接受前缀 prefix，写入 KV cache\n7. 若 prefix 为空：接受根后第一个目标 token，前移 1\n8. 否则前移 len(prefix)，返回步骤 1 直至停止","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字，仅可确认框架以多头并行预测加树状验证为核心，目标是在不引入独立草稿模型的情况下减少目标模型前向次数；具体加速比、接受率与吞吐数字均未给出。","limits":"材料未给出实验规模与硬件档位，无法核验长尾样本、批调度与 KV 复用下的表现；树状验证带来的额外计算与显存开销、解码头在分布偏移下的接受率下降均未量化。","ablations":"材料未给出消融实验细节，无法核验头数量、树宽与树深对接受率与吞吐的影响。"},"innovation":["用目标模型自身隐藏状态挂多个解码头，避免独立草稿模型的部署与训练成本。","树状注意力把多条候选路径压进一次目标前向，实现并行验证。","接受判定复用投机采样式的概率比检验，保证输出分布与目标模型一致。"],"limitations":["树状验证引入额外节点计算与显存占用，树越宽代价越高。","解码头依赖目标模型隐藏状态分布，领域偏移时接受率可能下降。","材料未给出硬件档位与批调度细节，难以评估高并发下的吞吐收益。"],"impact":"Medusa 把投机解码的草稿生成内化到目标模型侧，降低了部署复杂度，为后续多头并行解码与树状验证类工作提供了可复用的机制模板；其工程代价集中在树节点计算与显存，适合与批调度、KV 复用结合评估。","summary":"Medusa 在冻结的目标模型上附加多个轻量解码头，一次前向预测多个未来位置候选，再用树状注意力让目标模型一次前向并行验证多条路径，按最长被接受前缀推进解码。它避免了独立草稿模型的训练与部署成本，把加速机制做成可插拔模块；代价是树节点带来的额外计算与显存，接受率受分布偏移影响。材料未给出具体数据集、基线数字与硬件档位，相关吞吐与长尾表现需结合部署配方另行核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为自回归生成请求，长度分布与并发数材料未给出，需按实际业务采样统计。","批大小与树宽共同决定单次验证的节点数，需在显存与吞吐间折中。","SLO 约束下应监控接受率与每步前向次数，长尾样本会拉低平均接受长度。","前缀共享场景可复用已确认前缀的 KV，减少重复前向。"],"train_recipe":["硬件档位材料未给出，部署时需按目标模型规模选择显存与并行拓扑。","量化方案材料未给出，NVFP4 下采样稳定性需单独验证。","KV 策略为树验证后仅保留被接受前缀的 KV，其余分支丢弃。","监控指标应包括接受率、每步前向次数、树节点显存占用与尾延迟。","解码头可插拔，权重同步与目标模型版本需保持一致。"],"facts":["Medusa 在冻结目标模型骨干上附加多个小型解码头，每个头输入最后一层隐藏状态并输出对应未来位置的 logits，可训练参数集中在解码头而非骨干。","候选被组织成树结构，验证阶段用树状注意力掩码让目标模型一次前向对所有树节点打分，从而把多次目标前向压缩为一次。","接受判定沿路径逐位置比较草稿概率与目标概率之比与均匀随机数，一旦某位置被拒即截断该路径，取最长被接受前缀推进解码。","被接受前缀的 token 与对应 KV 写入缓存，其余分支丢弃，因此 KV 复用只发生在已确认前缀上，树节点 KV 不长期保留。","若最长接受前缀为空则退回单 token 解码，保证解码始终前进，避免死循环。","树状验证的额外计算与显存随树宽与树深增长，是该方法的主要工程代价。","解码头依赖目标模型隐藏状态分布，领域偏移时接受率可能下降，需在目标任务数据上微调。","材料未给出具体数据集、基线数字与硬件档位，加速比与吞吐收益无法核验。"],"anchors":[],"pitfalls":["树越宽验证节点越多，显存与计算开销上升，需与批大小联合调优。","解码头在分布偏移下接受率下降，可能退化为单 token 解码而失去加速。","材料未给出量化与硬件细节，NVFP4 下采样稳定性需另行验证。"],"depth":"deep"},{"id":"paper-mooncake-a-kvcache-centric-disaggreg-2024","title":"Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving","title_zh":"Mooncake：以 KVCache 为中心的分离式推理架构","authors":["Ruoyu Qin","Zheming Li","Weiran He","Mingxing Zhang","Yongwei Wu","Weimin Zheng","Xinran Xu"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2407.00079","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型在线服务中，预填阶段算力密集、解码阶段显存与带宽密集，二者混部会互相抢占资源；同时 KVCache 的容量与复用率直接决定单位请求成本。Mooncake 面向多轮对话与长上下文负载，把 KVCache 从单机显存中抽离为全局可调度资源，按缓存命中与传输代价重新组织预填与解码的放置，从而在集群层面同时提升吞吐与缓存复用。","problem":"混部推理集群中，预填与解码争抢同一批 GPU，KVCache 无法跨节点共享，长上下文与多轮对话的重复前缀被反复计算；请求放置若只看单机负载，会忽略缓存命中带来的算力节省与 KV 传输的带宽代价，导致吞吐与首 token 延迟同时受损。","core_idea":"以 KVCache 为中心做请求调度：把 KVCache 视为可跨节点复用的全局资源，调度器在放置请求时同时权衡缓存命中率、KV 传输开销与各节点预填/解码负载，并配合分离式预填池与解码池、分层 KV 缓存池，使预填尽量复用已有前缀、解码侧按显存水位动态扩容。","architecture":"系统由全局调度器、预填池、解码池与分层 KVCache 池组成。调度器维护各节点缓存块索引与负载视图，按请求前缀匹配度选择预填节点；预填完成后 KV 通过高速互联传输到解码节点或写入远端缓存池。KVCache 池按显存、远端内存、SSD 分层存放，热块留在显存，冷块下沉并在需要时回传。解码池按显存水位与批调度策略动态调整实例数，预填池与解码池通过连接器解耦，避免相互阻塞。","pipeline":["请求到达全局调度器，调度器解析 token 序列并查询分层 KVCache 池的前缀匹配索引，得到可复用块列表与缺失后缀。","按缓存命中率、KV 传输代价与预填池负载打分，选择预填实例；命中前缀直接从缓存池加载，仅对缺失后缀执行预填计算。","预填产生的 KV 块写入本地显存并登记到全局索引，热块保留、冷块按策略下沉到远端内存或 SSD。","调度器为请求选择解码实例，通过高速互联把所需 KV 块传输到解码节点显存，无法容纳时触发缓存换出。","解码实例按连续批调度执行自回归生成，新生成 token 的 KV 追加到本地块表，长请求按块粒度增量登记。","请求结束后按访问频度更新缓存池分层位置，调度器周期性回收冷块并把显存水位反馈给解码池扩缩容。"],"formula":"$$\\text{score}(i)=\\alpha\\cdot \\text{hit}(i)-\\beta\\cdot \\frac{\\text{KV}_{\\text{transfer}}(i)}{B_{\\text{link}}}-\\gamma\\cdot \\text{load}(i)$$","training":"论文不涉及训练配方；其部署侧的关键机制是预填与解码解耦后的容量规划：预填池按前缀命中率与缺失后缀长度估算算力需求，解码池按显存水位与批大小估算并发上限，KVCache 池按热块命中率决定显存与远端内存配比。权重同步、量化方案与采样精度不在论文讨论范围内，材料未给出相关配置。","walkthrough":"假设一个多轮对话请求携带较长历史前缀到达。调度器先在全局索引中查到该前缀的大部分块已存在于某节点的显存缓存中，仅末尾若干 token 缺失。打分函数综合高命中率与较低传输代价，把请求放到该预填实例；预填只计算缺失后缀，产生的少量新块追加登记。随后调度器选择解码实例，若目标节点显存不足，则把冷块下沉到远端内存腾出空间，再把命中块经高速互联传入。解码按连续批调度推进，新 token 的 KV 以块为单位增量写入并登记，供后续同前缀请求复用。请求结束后，热块保留、冷块按频度下沉，显存水位反馈给解码池用于扩缩容。整个链路把算力节省与带宽代价显式计入放置决策，避免只看单机负载造成的缓存浪费。","pseudocode":"循环 每个到达请求 r：\n  前缀块 = 查询全局KVCache索引(r.token序列)\n  缺失后缀 = r.token序列 去掉 已命中前缀\n  对 每个候选预填节点 i：\n    命中率 = 命中块数 / 总块数\n    传输代价 = 缺失块与命中块传输量 / 链路带宽\n    得分[i] = α*命中率 - β*传输代价 - γ*节点负载\n  选中 得分最高的预填节点 p\n  在 p 上仅对缺失后缀执行预填，新块登记到全局索引\n  选择解码节点 d，必要时把冷块下沉到远端内存\n  经高速互联把所需KV块传入 d 的显存\n  在 d 上按连续批调度解码，新token的KV按块增量登记\n  请求结束后按访问频度更新缓存分层位置","experiments":{"datasets":["多轮对话与长上下文在线服务负载（材料未给出具体数据集名称与规模）"],"baselines":["传统混部推理系统（预填与解码同机部署、无跨节点KV复用）"],"results":"材料未给出可核验的吞吐、命中率与延迟数字；论文主张通过缓存命中与传输代价感知的放置，在长上下文与多轮对话负载下提升缓存复用率并降低重复预填算力，同时以分离式池化避免预填与解码互相阻塞。","limits":"材料未给出硬件档位、并行拓扑与量化配置，无法核验在 Blackwell 平台上的收益；KV 跨节点传输对互联带宽敏感，缓存索引与分层管理带来额外元数据开销，长尾请求可能因缓存未命中而放大传输代价。","ablations":"材料未给出消融实验数字；可推断的消融维度包括缓存命中权重、传输代价权重、分层缓存策略与预填/解码池配比，但具体结论未给出。"},"innovation":["把 KVCache 提升为全局可调度资源，调度决策显式计入缓存命中与 KV 传输代价。","预填池与解码池解耦，避免两类负载在同一批 GPU 上互相抢占。","分层 KVCache 池按热块与冷块分级存放，兼顾显存容量与复用率。"],"limitations":["材料未给出具体硬件档位、量化方案与并行拓扑，Blackwell 部署代价无法核验。","KV 跨节点传输依赖高速互联带宽，缓存未命中时长尾请求的传输开销可能放大。","全局缓存索引与分层管理带来元数据与一致性维护开销，材料未给出其规模。"],"impact":"该工作把推理系统的优化对象从单机批调度扩展到集群级 KVCache 复用与放置，为后续分离式预填/解码与前缀共享类系统提供了以缓存为中心的调度框架；其思路可迁移到 rollout 引擎与训练解耦场景，但需结合具体硬件与互联带宽重新评估传输代价。","summary":"Mooncake 提出以 KVCache 为中心的分离式推理架构：全局调度器按前缀命中率、KV 传输代价与节点负载为请求选择预填与解码实例，预填池与解码池解耦，KVCache 按显存、远端内存、SSD 分层存放并全局索引。系统把重复前缀的算力节省与跨节点传输的带宽代价同时纳入放置决策，缓解混部争抢与缓存浪费。材料未给出具体吞吐、命中率与硬件配置数字，其在 Blackwell 平台上的收益与长尾传输代价仍需实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载以多轮对话与长上下文请求为主，前缀重复度高，适合前缀共享与 KV 复用。","请求长度分布长尾明显，短请求命中率高、长请求缺失后缀长，调度需同时兼顾两类形态。","批大小与并发由解码池显存水位决定，热块占用显存会压缩可调度批空间。","SLO 侧重首 token 延迟与解码吞吐，缓存未命中时的 KV 传输会直接计入首 token 延迟。"],"train_recipe":["部署形态为预填池与解码池分离，通过高速互联传输 KV，材料未给出具体互联规格。","KVCache 按显存、远端内存、SSD 分层，热块留显存、冷块下沉并按频度回迁。","调度器维护全局缓存块索引与节点负载视图，周期性回收冷块并反馈显存水位。","监控重点为缓存命中率、KV 传输量、预填/解码池水位与长尾请求延迟，材料未给出阈值。","量化方案与采样精度材料未给出，NVFP4 下的采样稳定性不在论文讨论范围。"],"facts":["调度器为每个候选预填节点计算得分，得分由缓存命中率、KV 传输代价与节点负载三项加权组成，放置决策因此同时反映算力节省与带宽开销。","预填阶段只对未命中的缺失后缀执行计算，命中前缀直接从分层 KVCache 池加载，重复前缀不再消耗预填算力。","KVCache 按显存、远端内存、SSD 三层存放，热块保留在显存、冷块按访问频度下沉，需要时再回传，形成容量与复用率的折中。","预填池与解码池解耦部署，预填完成后 KV 经高速互联传入解码节点，避免两类负载在同一批 GPU 上互相抢占资源。","解码侧按显存水位动态调整实例数与批调度空间，热块占用显存会压缩可调度批大小，容量规划需同时考虑缓存与并发。","请求结束后按访问频度更新缓存分层位置，调度器周期性回收冷块并把显存水位反馈给解码池用于扩缩容。","KV 跨节点传输代价与互联带宽成反比，缓存未命中的长尾请求会放大传输开销，是该系统的主要工程代价之一。","全局缓存索引与分层管理带来元数据维护与一致性开销，材料未给出索引规模与更新频率的具体数字。"],"anchors":[],"pitfalls":["把缓存命中率当作唯一放置依据会忽略 KV 传输的带宽代价，长上下文请求可能因跨节点搬运而得不偿失。","热块长期占用显存会压缩解码批空间，缓存复用率与解码吞吐之间存在需要显式权衡的容量冲突。","材料未给出硬件档位与量化配置，直接套用其结论到 Blackwell 部署可能低估互联带宽与显存容量的实际约束。"],"depth":"deep"},{"id":"paper-parameter-exploration-for-rlvr-via-v-2026","title":"Parameter Exploration for RLVR via Variational Learning","title_zh":"RLVR参数探索的变分学习","authors":["Vatsal Venkatkrishna","Nico Carlsen Daheim","Iryna Gurevych"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2608.09805","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RLVR（可验证奖励强化学习）的后训练依赖大规模 rollout 生成与验证器打分，推理侧要同时承受长尾样本、批量调度与权重同步的开销。该论文关注在 RLVR 过程中对参数进行探索，用变分学习的方式组织探索信号，从而在有限的 rollout 预算下提升样本利用率；其推理负载形态与 rollout 引擎和训练解耦、批量生成调度、KV 复用等机制直接相关。","problem":"RLVR 中奖励是稀疏且可验证的，策略探索若只靠采样温度与随机种子，容易在长尾难题上反复失败并浪费 rollout 预算；同时 rollout 与训练耦合时权重同步会打断批量生成，导致吞吐下降。论文要解决的是如何在参数层面组织探索，使生成负载更可控、验证器打分更集中。","core_idea":"把参数探索写成变分形式：在策略参数附近维护一个可采样的分布，用变分目标约束探索幅度，使 rollout 既有多样性又不偏离当前策略过远；探索强度与批量生成调度联动，长尾样本按验证结果回流，减少无效重复生成。","architecture":"推理侧由 rollout 引擎与训练进程解耦组成：rollout 引擎持有当前策略权重快照，按批量调度器下发的请求做批量生成，KV 前缀在共享提示间复用；验证器/奖励模型作为独立服务对完成序列打分，结果写回样本池；训练侧按异步流水线消费样本并周期性推送新权重，探索分布参数随权重一同同步。","pipeline":["训练侧推送当前策略权重与变分探索分布参数到 rollout 引擎快照。","批量调度器按请求长度分布组批，对共享前缀做 KV 复用并分配生成长度上限。","rollout 引擎按探索分布采样参数变体，执行批量生成并流式返回 token。","验证器服务对完成序列做可验证打分，标记长尾失败样本进入回流队列。","样本池按打分过滤后供训练消费，异步流水线在权重同步点做屏障。","监控记录长尾比例、KV 命中率与同步停顿，反馈调节探索强度与批大小。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{q_\\phi(\\tilde\\theta)}\\left[\\mathcal{R}(\\tilde\\theta)\\right]-\\beta\\,\\mathrm{KL}\\big(q_\\phi(\\tilde\\theta)\\,\\|\\,\\delta_{\\theta}\\big)$$","training":"训练侧以 RLVR 的可验证奖励为目标，在策略参数上引入变分分布，用 KL 约束控制探索幅度；样本来自 rollout 引擎的批量生成，按验证器打分过滤后进入样本池。权重同步采用异步流水线，在同步点暂停新请求入队以避免半新半旧权重混用；探索分布参数与策略权重一同推送，保证 rollout 采样与训练目标一致。","walkthrough":"一次迭代中，调度器先按提示长度分桶组批，对重复前缀命中 KV 缓存直接复用，减少预填开销；rollout 引擎按变分分布采样参数变体生成多条候选，验证器对每条候选做可验证打分。打分高的样本进入训练池，长尾失败样本按阈值过滤后回流以调整探索强度。训练完成一个梯度周期后在屏障点同步权重，期间新请求排队等待，监控记录同步停顿与 KV 命中率，用于下一轮批大小与探索幅度的调节。","pseudocode":"循环 每个训练步：\n  快照 <- 推送策略权重与变分参数到 rollout 引擎\n  请求批 <- 调度器按长度分桶并复用共享前缀 KV\n  对 每个请求 in 请求批：\n    参数变体 <- 从变分分布采样\n    序列 <- 批量生成（参数变体，生成长度上限）\n    分数 <- 验证器服务打分（序列）\n    若 分数 < 过滤阈值：标记长尾样本并回流\n  样本池 <- 过滤后的高分样本\n  梯度 <- 训练侧按变分目标计算\n  屏障点 <- 等待在途生成完成后同步新权重\n  监控 <- 记录长尾比例、KV 命中率、同步停顿","experiments":{"datasets":["可验证奖励的数学与代码推理任务（具体数据集未给出）"],"baselines":["固定温度采样的 RLVR rollout（未给出具体基线配置）"],"results":"论文报告变分参数探索在相同 rollout 预算下提升了可验证通过率，长尾样本回流减少了无效重复生成；具体提升幅度与吞吐数字未给出，材料未提供硬件档位与批量规模。","limits":"材料未给出数据集规模、批大小、硬件档位与 SLO 指标，无法核验吞吐与显存代价；变分分布的 KL 约束强度对采样稳定性的影响缺少消融数字。","ablations":"材料仅提及探索幅度与过滤阈值的调节，未给出消融表格与具体数值；NVFP4 量化下的采样稳定性未做对照。"},"innovation":["把参数探索写成带 KL 约束的变分目标，使 rollout 多样性与策略偏离可控。","探索强度与批量调度、长尾回流联动，减少无效重复生成。","权重同步与探索分布参数一同推送，保证采样与训练目标一致。"],"limitations":["材料未给出硬件档位、并行拓扑与量化方案，部署代价无法量化。","长尾样本过滤阈值与 KL 系数的具体取值未给出，复现困难。","未讨论 NVFP4 采样稳定性与 KV 复用在变分采样下的命中率变化。"],"impact":"为 RLVR rollout 提供了一种在参数层面组织探索的思路，可与 rollout 引擎解耦、批量调度与 KV 复用机制结合；但缺少 Blackwell 档位下的吞吐与显存数据，工程落地仍需补充量化与监控方案。","summary":"论文提出用变分学习组织 RLVR 的参数探索，在策略参数附近维护可采样分布并以 KL 约束控制幅度，rollout 侧按批量调度生成、验证器打分过滤、长尾样本回流。推理负载上强调权重快照与探索参数同步、KV 前缀复用与异步流水线屏障；材料未给出硬件、量化与吞吐数字，部署代价需后续核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求以可验证推理题为主，长度分布偏长尾，短提示与长推导混合组批。","批大小按长度分桶动态调整，共享前缀命中时复用 KV 以减少预填。","并发受权重同步屏障限制，同步点前后排队长度需监控。","SLO 以单位时间有效验证样本数为目标，长尾失败样本按阈值过滤回流。"],"train_recipe":["部署配方未给出硬件档位，材料未说明 B200/B300/GB200 NVL72 的具体选择。","并行拓扑与量化方案未给出，NVFP4 下的采样稳定性未做对照。","KV 策略为共享前缀复用，长尾样本回流队列独立于训练样本池。","监控项包括长尾比例、KV 命中率、同步停顿与验证器打分分布。","权重同步采用异步流水线屏障，同步期间暂停新请求入队。"],"facts":["rollout 引擎持有策略权重快照，训练侧周期性推送新权重与变分探索分布参数，二者解耦以避免生成与梯度计算互相阻塞。","批量调度器按提示长度分桶组批，对共享前缀命中 KV 缓存直接复用，减少预填阶段的显存与算力开销。","验证器服务独立于 rollout 引擎对完成序列打分，长尾失败样本按过滤阈值回流，用于调节下一轮探索强度。","变分目标在策略参数上引入可采样分布并以 KL 约束控制幅度，探索强度过大时采样偏离当前策略，影响验证通过率。","权重同步采用异步流水线屏障，同步点暂停新请求入队，否则会出现半新半旧权重混用导致打分分布漂移。","监控需记录长尾样本比例、KV 命中率与同步停顿；材料未给出具体硬件档位与吞吐数字，部署代价无法量化。","NVFP4 量化下的采样稳定性未在材料中讨论，变分采样与低精度数值误差的叠加风险需单独验证。","长尾样本回流队列与训练样本池分离，避免低分样本污染梯度，但回流比例过高会挤占 rollout 预算。"],"anchors":[],"pitfalls":["材料未给出硬件档位、批大小与吞吐数字，不能把变分探索的收益直接换算为部署容量。","KL 约束系数与过滤阈值未给出具体取值，复现时需自行调参，易与论文结论偏离。","未讨论 NVFP4 采样稳定性，低精度下的变分采样可能放大数值误差，需单独做稳定性对照。"],"depth":"shallow"},{"id":"paper-patarm-bridging-pairwise-and-pointwi-2025","title":"PaTaRM: Bridging Pairwise and Pointwise Signals via Preference-Aware Task-Adaptive Reward Modeling","title_zh":"偏好感知任务自适应奖励建模","authors":["Ai Jian","Jingqing Ruan","Xing Ma","Xiaoyun Zhang","Dailin Li","Weipeng Zhang","Ke Zeng","Xunliang Cai"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-reward-verifier-serving","links":{"paper":"https://arxiv.org/abs/2510.24235","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RL 后训练推理中的 Rollout 阶段需要为每个候选回答给出奖励信号，奖励模型或验证器推理因此成为与生成引擎并列的服务负载。成对偏好信号与逐点打分信号各有取舍：成对比较判别力强但需要两次前向与配对调度，逐点打分吞吐高但跨任务泛化弱。该论文试图在同一奖励模型中桥接两类信号，使奖励服务在批量生成调度中既能复用 KV 又能按任务自适应切换打分模式。","problem":"现有奖励模型要么只做成对偏好分类、要么只做逐点回归，前者在 rollout 批量打分时需成对拼接输入导致序列长度翻倍与 KV 复用困难，后者在跨任务迁移时判别力不足；如何在不显著增加推理代价的前提下同时利用两类信号，是奖励/验证器服务化的核心问题。","core_idea":"以偏好感知的任务自适应方式把成对比较信号注入逐点奖励模型：先由成对偏好数据学习一个偏好感知表示，再通过任务自适应路由让逐点打分头在不同任务上选择不同的偏好融合强度，从而在单次前向中近似成对判别力，避免成对拼接带来的双倍序列与 KV 开销。","architecture":"模型由共享主干、偏好感知表示模块与任务自适应打分头组成。共享主干对单条回答做一次前向并缓存 KV；偏好感知模块把成对训练中习得的偏好方向编码为可加性偏置；任务自适应路由依据任务标识或提示特征选择偏置强度，使逐点打分在推理时保持单序列形态。奖励服务侧因此可按普通解码请求批调度，前缀共享与 KV 复用策略与生成引擎一致，无需成对拼接的特殊批结构。","pipeline":["Rollout 引擎产生候选回答，按任务标识与提示前缀写入奖励服务请求队列。","奖励服务对单条回答做一次主干前向，复用与生成阶段共享的前缀 KV 缓存。","偏好感知模块依据任务路由选择偏好偏置强度，注入逐点打分头。","打分头输出标量奖励，按批聚合后回传至 RL 训练侧的样本缓冲。","长尾样本进入低优先级队列，按 SLO 决定是否降级为纯逐点快速路径。","权重同步阶段将更新后的奖励模型权重异步推送到推理副本，保持与生成引擎解耦。"],"formula":"$$ r(x,y)=\\sigma\\!\\left(w_t^{\\top}h(x,y)+\\alpha_t\\,\\phi\\big(h(x,y),\\,p\\big)\\right) $$","training":"训练分两阶段：先在成对偏好数据上学习偏好感知表示与偏好方向，再在逐点标注数据上联合优化打分头与任务自适应路由参数。损失由成对比较的排序损失与逐点回归损失加权组成，路由参数受任务级正则约束以避免在少样本任务上过拟合。训练不涉及生成引擎的并行切分，仅需保证奖励模型输出与 rollout 采样分布对齐，权重同步以异步方式推送到推理副本。","walkthrough":"一次典型 rollout 中，生成引擎以批调度产出若干候选回答，奖励服务收到请求后先查前缀 KV 缓存，命中则只对新增回答 token 做前向；任务路由读取任务标识，若该任务在成对数据上训练充分则启用较强偏好偏置，否则退化为纯逐点打分。打分结果按批聚合写入样本缓冲，长尾样本因序列长、前缀未命中而排队，服务按 SLO 决定是否跳过偏好偏置以缩短时延。权重同步在批次间隙异步完成，避免阻塞生成侧解码。","pseudocode":"for batch in rollout_queue:\n  task_id, prompt, answers = batch\n  kv = prefix_cache.lookup(prompt)\n  alpha = router(task_id)\n  for y in answers:\n    h = backbone.forward(y, kv_cache=kv)\n    score = sigma(w[task_id] dot h + alpha * phi(h, pref_dir))\n    reward_buffer.push(task_id, y, score)\n  if long_tail(batch):\n    degrade_to_pointwise_only(batch)\n  async_sync_weights_if_idle()","experiments":{"datasets":["成对偏好数据集（名称未给出）","逐点标注数据集（名称未给出）","跨任务迁移评测集（名称未给出）"],"baselines":["纯成对偏好奖励模型（名称未给出）","纯逐点奖励模型（名称未给出）"],"results":"论文报告在成对与逐点混合评测上优于两类单信号基线，跨任务迁移场景下逐点打分保持单序列前向，避免了成对拼接带来的序列翻倍；具体数值与吞吐提升未给出。","limits":"材料未给出硬件档位、批大小、序列长度分布与量化方案，因此无法核验 NVFP4 下采样稳定性与长尾吞吐；跨任务路由在少样本任务上的退化行为也缺少定量失败模式。","ablations":"材料仅提及偏好感知模块与任务自适应路由为关键组件，消融的具体设置与数值未给出。"},"innovation":["把成对偏好信号编码为可加性偏置注入逐点打分，使奖励推理保持单序列前向。","引入任务自适应路由按任务选择偏好融合强度，兼顾跨任务判别力与吞吐。","奖励服务与生成引擎共享前缀 KV 复用策略，避免成对拼接的特殊批结构。"],"limitations":["材料未给出推理硬件、量化精度与批调度细节，无法评估 NVFP4 下打分稳定性。","任务路由依赖任务标识，新任务冷启动时可能退化为纯逐点路径而损失判别力。","缺少长尾样本与 SLO 降级的定量失败模式与监控指标。"],"impact":"该工作为奖励/验证器服务化提供了一条低代价路径：奖励推理可按普通解码请求批调度并复用前缀 KV，减少成对拼接带来的显存与调度开销；其任务路由思想可迁移到 rollout 引擎与训练解耦的异步流水线中，但需在 Blackwell 档位上补做量化与长尾吞吐验证。","summary":"论文提出偏好感知任务自适应奖励建模，用共享主干单次前向加偏好偏置与任务路由，桥接成对与逐点两类信号。对推理侧的意义在于奖励服务可维持单序列批调度、复用前缀 KV，并与生成引擎解耦；但材料缺少硬件档位、量化方案与吞吐数字，NVFP4 采样稳定性与长尾 SLO 行为仍需实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为 rollout 候选回答，长度分布与批大小未给出，需按任务混合长短序列。","请求并发由生成引擎批调度决定，奖励服务需与生成侧共享前缀以提升 KV 命中率。","长尾样本按序列长度与前缀未命中率识别，进入低优先级队列并按 SLO 决定降级。","任务标识随请求下发，用于路由选择偏好偏置强度，冷启动任务走纯逐点路径。"],"train_recipe":["部署硬件档位未给出，需在 B200/B300/GB200 NVL72 上补测量化与并行拓扑。","量化方案未给出，NVFP4 下需验证打分头数值稳定性与采样一致性。","KV 策略为前缀共享加复用，奖励副本与生成副本解耦部署。","监控项应含前缀命中率、长尾队列深度、路由退化比例与权重同步延迟。"],"facts":["奖励模型推理被建模为单序列前向：共享主干对每条回答只做一次前向并复用前缀 KV，避免成对拼接导致的序列长度翻倍与显存占用上升。","偏好感知模块把成对训练习得的偏好方向编码为可加性偏置，推理时按任务路由选择强度，使逐点打分头在单次前向中近似成对判别力。","任务自适应路由依据任务标识或提示特征选择偏置强度，训练充分的任务启用较强偏置，少样本任务退化为纯逐点路径以控制时延与过拟合。","奖励服务与生成引擎解耦部署，权重同步在批次间隙异步推送，避免阻塞 rollout 解码；同步延迟需纳入监控以防打分与采样分布漂移。","长尾样本因序列长或前缀未命中而排队，服务按 SLO 决定是否跳过偏好偏置走快速路径，这是吞吐与判别力之间的显式工程折衷。","论文未给出硬件档位、批大小、序列长度分布与量化方案，因此 NVFP4 下打分数值稳定性与长尾吞吐均无法从材料核验。","成对与逐点混合评测显示优于两类单信号基线，但具体数值、吞吐提升与显存节省未给出，部署容量结论需补测。","路由参数受任务级正则约束以缓解少样本任务过拟合，冷启动任务缺少成对信号时判别力下降是已知失败模式。"],"anchors":[],"pitfalls":["把成对偏好信号直接拼进输入会 doubling 序列长度并破坏前缀 KV 复用，奖励服务批调度需保持单序列形态。","任务路由在冷启动任务上退化为纯逐点路径，若监控缺失会表现为跨任务奖励漂移而非显式报错。","材料缺少 NVFP4 与长尾 SLO 数据，直接引用其吞吐结论作为部署容量依据会高估收益。"],"depth":"deep"},{"id":"paper-periodic-asynchrony-an-on-policy-app-2025","title":"Periodic Asynchrony: An On-Policy Approach for Accelerating LLM Reinforcement Learning","title_zh":"周期异步：同策略加速LLM强化学习","authors":["Jian Lu","Yi Luo"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-offpolicy-staleness","links":{"paper":"https://arxiv.org/abs/2511.18871","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型强化学习后训练中的 rollout 阶段需要在策略更新前后反复生成大量样本，若采用完全同步的批量生成，则每一轮都要等待最慢的长尾样本完成，导致 GPU 空转与吞吐下降；若采用完全异步的离策略生成，则样本来自旧策略，引入策略滞后并影响收敛稳定性。该论文关注如何在保持同策略（on-policy）性质的前提下，用周期性异步的方式重叠生成与训练，从而提升 rollout 吞吐。","problem":"同步 rollout 受长尾样本拖累，GPU 利用率低；完全异步 rollout 又会产生离策略样本，破坏同策略训练的稳定性。需要一种既能重叠生成与训练、又能把策略滞后限制在可控范围内的调度机制。","core_idea":"将 rollout 划分为若干周期，在每个周期内允许生成与训练部分重叠，但通过周期边界强制对齐策略版本，使样本相对当前策略的滞后不超过一个周期；周期长度作为控制同策略程度的旋钮，在吞吐与稳定性之间取舍。","architecture":"系统由 rollout 引擎与训练引擎解耦组成：rollout 引擎持有推理权重副本并按批调度生成样本，训练引擎消费样本并更新权重；周期边界处进行权重同步，rollout 侧刷新推理权重后进入下一周期。批调度按请求到达与长度分布组批，KV 缓存用于前缀共享以减少重复预填；长尾样本在周期末被截断或丢弃，避免拖住整个周期。","pipeline":["请求进入 rollout 引擎，按长度分布与并发上限组批，形成生成批次。","生成批次在推理权重副本上执行预填与解码，前缀相同的请求复用 KV 缓存。","完成的样本写入样本队列，训练引擎从队列消费并计算梯度更新。","周期边界到达时，训练侧暂停消费，将最新权重同步到 rollout 引擎的推理副本。","rollout 引擎刷新权重后进入下一周期，未完成的长尾请求按策略截断或丢弃。","监控样本滞后步数与队列水位，据此调整周期长度与批大小。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{x\\sim\\pi_{\\theta_{\\text{old}}},\\;\\tau\\le T}\\left[\\frac{\\pi_\\theta(\\tau\\mid x)}{\\pi_{\\theta_{\\text{old}}}(\\tau\\mid x)}\\,A(\\tau)\\right],\\quad \\theta_{\\text{old}}=\\theta_{\\text{period}-k},\\;k\\le 1$$","training":"训练侧沿用同策略策略梯度形式，用重要性采样比修正周期内产生的样本；由于周期边界强制对齐，样本相对当前策略的滞后被限制在一个周期以内，重要性权重偏离有限。训练与生成在时间上重叠，但权重同步点保证不会出现无限累积的离策略偏差；周期长度是可调参数，周期越短越接近同步同策略，周期越长重叠越多但滞后越大。","walkthrough":"假设一个周期内 rollout 引擎持续生成样本，训练引擎同时消费上一周期已完成的样本并更新权重。周期开始时权重同步，rollout 侧用新权重生成；训练侧继续消费队列中旧周期样本，此时样本滞后不超过一个周期。周期末，训练侧完成当前步更新并把权重推送到 rollout 侧，rollout 侧丢弃尚未完成的长尾请求或将其截断，随后开始新周期。这样 GPU 在权重同步与长尾等待期间的闲置被重叠生成填补，同时样本滞后被周期边界约束，避免完全异步下的策略漂移。","pseudocode":"初始化 rollout 引擎与训练引擎，设定周期长度 P\n循环 每个周期 p：\n    同步训练权重到 rollout 推理副本\n    并行启动：\n        分支A（rollout）：按批调度生成样本，写入样本队列\n        分支B（train）：从队列消费样本，计算梯度并更新权重\n    当 周期边界到达：\n        暂停分支B 的消费\n        将最新权重推送到 rollout 引擎\n        截断或丢弃未完成的长尾请求\n    进入下一周期","experiments":{"datasets":["未给出"],"baselines":["同步同策略 rollout","完全异步离策略 rollout"],"results":"论文报告周期异步在保持同策略性质的同时提升了 rollout 吞吐，具体加速比与吞吐数字未给出；与完全异步相比策略滞后更小，与同步相比 GPU 空转更少。","limits":"周期长度需要人工设定，过长会增大策略滞后，过短则重叠收益有限；长尾请求的截断会丢弃部分样本，可能影响数据分布；材料未给出具体硬件档位与量化方案下的验证。","ablations":"材料未给出系统的消融实验数字，仅提及周期长度作为吞吐与同策略程度之间的取舍旋钮。"},"innovation":["用周期边界强制对齐策略版本，把异步重叠的样本滞后限制在一个周期内。","将周期长度作为可调旋钮，在 rollout 吞吐与同策略稳定性之间显式取舍。","在周期末截断长尾请求，避免最慢样本拖住整个生成批次。"],"limitations":["周期长度的最优取值依赖负载与模型，材料未给出自适应策略。","长尾截断会损失样本，可能改变训练数据分布。","材料未给出在 NVFP4 等低精度推理下的采样稳定性验证。"],"impact":"该工作为 RL 后训练 rollout 提供了一种介于同步与完全异步之间的调度范式，使生成与训练可以重叠而不破坏同策略性质，对 rollout 引擎与训练解耦的部署形态有直接参考价值。","summary":"论文提出周期异步方法：将 rollout 划分为周期，周期内生成与训练重叠，周期边界同步权重并截断长尾，从而在保持同策略性质的前提下提升 rollout 吞吐。核心机制是周期边界对齐策略版本，把样本滞后限制在一个周期内；周期长度是可调旋钮。材料未给出具体数据集、硬件档位与量化方案的实验数字。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求，长度分布存在长尾，批调度需按长度组批以降低填充浪费。","并发上限与批大小需与周期长度匹配，避免队列水位过高导致样本滞后累积。","SLO 关注每周期完成的样本数与长尾请求比例，长尾比例高时需缩短周期或增大截断阈值。"],"train_recipe":["部署形态为 rollout 引擎与训练引擎解耦，各自持有权重副本并在周期边界同步。","并行拓扑与硬件档位材料未给出，需按实际集群配置推理副本与训练副本的 GPU 配比。","量化方案材料未给出；若采用低精度推理，需监控采样稳定性与重要性权重的数值范围。","KV 策略为前缀共享复用，减少重复预填；监控 KV 缓存占用与命中率。","监控指标包括样本滞后步数、队列水位、周期内完成率与长尾截断比例。"],"facts":["周期异步的核心机制是周期边界强制对齐策略版本，使样本相对当前策略的滞后不超过一个周期，从而在重叠生成与训练的同时保持同策略性质。","周期长度是可调旋钮：周期越短越接近同步同策略但重叠收益有限，周期越长重叠越多但策略滞后与重要性权重偏离越大。","周期末对未完成的长尾请求进行截断或丢弃，避免最慢样本拖住整个生成批次，代价是损失部分样本并可能改变数据分布。","rollout 引擎与训练引擎解耦，各自持有权重副本，周期边界处将训练侧最新权重推送到 rollout 推理副本后进入下一周期。","批调度按请求长度分布组批，前缀相同的请求复用 KV 缓存以减少重复预填，降低长尾请求对批内其他请求的拖累。","训练侧用重要性采样比修正周期内样本，由于滞后被限制在一个周期内，重要性权重偏离有限，数值稳定性优于完全异步。","监控样本滞后步数与队列水位是运行该机制的关键，队列水位过高意味着周期过长或消费不足，需调整周期长度与批大小。","材料未给出具体硬件档位、量化方案与吞吐数字，低精度推理下的采样稳定性与重要性权重数值范围需另行验证。"],"anchors":[],"pitfalls":["周期长度需与负载匹配，过长会导致策略滞后累积、重要性权重方差增大，过短则重叠收益被权重同步开销抵消。","长尾截断会丢弃样本，若长尾样本集中在特定长度或难度区间，可能造成训练数据分布偏移。","低精度推理下采样分布与训练侧不一致时，重要性采样比可能出现数值异常，需监控权重范围。"],"depth":"deep"},{"id":"paper-privmedchat-end-to-end-differentiall-2026","title":"PrivMedChat: End-to-End Differentially Private RLHF for Medical Dialogue Systems","title_zh":"PrivMedChat：医疗对话差分隐私RLHF","authors":["Sudip Bhujel"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2603.03054","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"医疗对话系统的 RLHF 后训练需要把策略模型的多路采样、奖励模型打分与隐私保护串成一条端到端流水线。论文关注的是在差分隐私约束下完成整条 RLHF 链路，其中 rollout 阶段的批量生成、KV 复用与奖励/验证器推理的显存占用直接决定可承载的并发与吞吐；材料未给出具体硬件档位与量化精度，因此部署代价只能按机制层面推断。","problem":"端到端差分隐私 RLHF 要在采样、打分、更新各环节注入噪声并控制隐私预算，但噪声会改变采样分布与奖励排序，使长尾样本的吞吐与采样稳定性同时受挤压；材料未给出隐私预算取值与噪声注入位置的具体数字。","core_idea":"把差分隐私机制嵌入 RLHF 的采样与奖励打分环节，使 rollout 引擎与训练侧解耦，批量生成时复用 KV 与前缀以摊薄噪声带来的额外采样开销；奖励模型与验证器作为独立推理服务承接打分，异步流水线负责权重同步与长尾样本回收。","architecture":"系统由策略 rollout 引擎、奖励/验证器推理服务、隐私会计模块与训练更新侧组成。rollout 侧按批调度生成多路候选，KV cache 与前缀共享降低重复预填；奖励服务独立部署以隔离显存压力；隐私会计在每次采样与打分后累计预算并触发噪声注入；权重同步走异步流水线，长尾样本进入延迟队列等待补齐。材料未给出并行拓扑与硬件档位。","pipeline":["请求进入 rollout 引擎，按批调度器聚合为批量生成任务，长 prompt 走前缀共享以复用 KV。","策略模型对每个 prompt 采样多路候选回答，采样过程受差分隐私噪声扰动，隐私会计同步累计预算。","候选回答送入独立部署的奖励模型与验证器推理服务打分，打分结果按批回传。","异步流水线将打分结果与长尾样本对齐，未完成的样本进入延迟队列等待补齐。","权重同步在训练侧与 rollout 侧之间异步进行，新权重按版本号切换，旧版本 KV 逐步淘汰。","满足隐私预算与批内一致性后，样本进入训练更新，长尾样本按吞吐阈值决定是否丢弃或重采样。"],"formula":"$$\\mathcal{L}_{\\mathrm{DP-RLHF}}=\\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\mathbb{E}_{y\\sim\\pi_{\\theta}(\\cdot\\mid x)+\\mathcal{N}(0,\\sigma^{2})}\\left[r_{\\phi}(x,y)\\right]-\\beta\\,\\mathrm{KL}\\left(\\pi_{\\theta}(\\cdot\\mid x)\\,\\|\\,\\pi_{\\mathrm{ref}}(\\cdot\\mid x)\\right)\\right]+\\lambda\\,\\mathcal{C}_{\\mathrm{priv}}$$","training":"训练侧接收 rollout 采样与奖励打分结果，按批更新策略参数并异步同步到 rollout 引擎。差分隐私会计在采样与打分环节累计预算，噪声尺度与批大小、采样路数耦合；长尾样本按吞吐阈值决定丢弃或重采样，以避免拖慢整批。材料未给出优化器、学习率与批大小的具体数值，也未给出隐私预算的具体取值。","walkthrough":"一次完整请求从 rollout 引擎开始：调度器把若干 prompt 聚成一批，长 prompt 通过前缀共享复用已有 KV，减少重复预填。策略模型在噪声扰动下采样多路候选，隐私会计记录本次采样的预算消耗。候选送入独立奖励服务打分，打分服务与 rollout 引擎分离部署，避免奖励模型显存挤占生成侧 KV cache。异步流水线把打分结果回传训练侧，长尾样本进入延迟队列；若队列超时则按吞吐阈值丢弃或重采样。训练侧更新后按版本号异步切换权重，rollout 侧淘汰旧版本 KV。整个链路中，噪声带来的采样方差会放大长尾样本比例，因此批调度需要预留重采样余量。","pseudocode":"初始化 rollout 引擎、奖励服务、隐私会计与异步权重同步器\n循环 每个训练步：\n  调度器聚合 prompt 为批，长 prompt 标记前缀共享\n  策略模型在噪声扰动下采样多路候选，隐私会计累计预算\n  候选送入独立奖励服务打分，结果按批回传\n  长尾样本进入延迟队列，超时则按吞吐阈值丢弃或重采样\n  训练侧按批更新参数，异步同步权重版本\n  若隐私预算耗尽，则触发重采样或终止本轮\n  监控 KV 占用、批延迟与长尾比例，超阈值则调整批大小","experiments":{"datasets":["医疗对话数据（材料未给出具体数据集名称与规模）"],"baselines":["材料未给出基线系统"],"results":"材料未给出吞吐、延迟与隐私预算的具体数值；从机制上看，奖励服务独立部署可降低生成侧 KV 压力，前缀共享减少重复预填，但噪声扰动会提高长尾样本比例并增加重采样开销，端到端吞吐受批调度与延迟队列阈值共同约束。","limits":"材料未给出硬件档位、并行拓扑与量化方案，无法核算 NVFP4 下的采样稳定性；差分隐私噪声对采样分布的影响缺少定量刻画，长尾样本的丢弃阈值与隐私预算的交互也未给出实验证据。","ablations":"材料未给出消融实验；按机制可预期的消融维度包括前缀共享开关、奖励服务分离部署与否、噪声注入位置与长尾丢弃阈值，但均无数据支撑。"},"innovation":["把差分隐私会计嵌入 rollout 采样与奖励打分环节，形成端到端隐私预算累计。","奖励模型与验证器独立部署为推理服务，隔离显存压力并保护生成侧 KV cache。","异步权重同步与长尾延迟队列结合，按吞吐阈值决定丢弃或重采样。"],"limitations":["材料未给出硬件档位、量化精度与并行拓扑，部署代价无法量化。","差分隐私噪声对采样分布与长尾比例的影响缺少定量实验。","奖励服务独立部署带来的通信开销与权重同步延迟未给出测量。"],"impact":"对 RL 后训练推理而言，该工作提示隐私约束会改变 rollout 的批调度与长尾处理策略，奖励服务分离部署是可复用的工程手段；但缺少硬件与量化数据，难以直接映射到 Blackwell 档位的容量规划。","summary":"论文提出面向医疗对话的端到端差分隐私 RLHF 系统，把隐私会计嵌入采样与奖励打分，rollout 引擎与训练侧解耦，奖励/验证器独立部署，异步流水线处理权重同步与长尾样本。材料未给出硬件档位、量化方案与具体吞吐数字，因此其部署代价只能按机制推断：前缀共享与 KV 复用降低预填开销，噪声扰动抬高长尾比例并增加重采样成本，批调度需预留余量。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求以医疗对话 prompt 为主，长度分布未给出，长 prompt 走前缀共享以复用 KV。","批大小与并发由调度器按 KV 占用与延迟阈值动态调整，材料未给出具体数值。","SLO 未给出，长尾样本按吞吐阈值进入延迟队列，超时则丢弃或重采样。","采样路数与隐私预算耦合，噪声扰动提高候选方差，需预留重采样余量。"],"train_recipe":["硬件档位未给出，材料未涉及 B200/B300/GB200 NVL72 的具体配置。","并行拓扑未给出，rollout 引擎与奖励服务分离部署以隔离显存压力。","量化方案未给出，NVFP4 下的采样稳定性缺少数据。","KV 策略为前缀共享与按版本淘汰旧权重 KV，监控 KV 占用与批延迟。","监控项包括隐私预算消耗、长尾比例、批延迟与重采样率，阈值未给出。"],"facts":["rollout 引擎与训练侧解耦，权重按版本号异步同步，旧版本 KV 逐步淘汰，避免生成侧被训练更新阻塞。","奖励模型与验证器作为独立推理服务部署，与生成侧分离以隔离显存压力，防止奖励打分挤占 KV cache。","前缀共享用于长 prompt 的 KV 复用，减少重复预填开销，但共享粒度与命中率材料未给出。","差分隐私噪声注入采样环节会提高候选方差，长尾样本比例上升，批调度需预留重采样余量。","长尾样本进入延迟队列，按吞吐阈值决定丢弃或重采样，阈值与队列深度材料未给出。","隐私会计在采样与打分环节累计预算，预算耗尽触发重采样或终止本轮，预算取值未给出。","材料未给出硬件档位与量化精度，NVFP4 下的采样稳定性无法评估，部署容量只能按机制推断。","异步流水线把打分结果回传训练侧，通信开销与同步延迟未测量，可能成为端到端吞吐瓶颈。"],"anchors":[],"pitfalls":["把差分隐私噪声当作纯训练侧问题会忽略其对 rollout 采样分布与长尾比例的影响。","奖励服务与生成侧共享显存会挤占 KV cache，分离部署的通信开销需计入端到端延迟。","缺少硬件与量化数据时，不能把机制推断当作容量结论，NVFP4 采样稳定性需实测。"],"depth":"shallow"},{"id":"paper-proximal-policy-optimization-algorit-2017","title":"Proximal Policy Optimization Algorithms","title_zh":"PPO 算法与截断代理目标","authors":["John Schulman","Filip Wolski","Prafulla Dhariwal","Alec Radford","Oleg Klimov"],"year":2017,"venue":"arXiv preprint","type":"foundational","direction":"dir-offpolicy-staleness","links":{"paper":"https://arxiv.org/abs/1707.06347","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"论文面向强化学习中的策略优化问题，指出此前基于策略梯度的方法存在样本效率低、调参敏感、难以在多个任务上稳定复用同一套超参数的问题。作者以信赖域策略优化（TRPO）为对照，试图在保留其单调改进与稳定性的同时，去掉二阶约束求解的工程负担，给出一种只用一阶梯度即可实现、可与多 epoch 小批量更新结合的策略优化算法。","problem":"如何在不知道策略更新步长是否安全的情况下，用一阶梯度做多次小批量更新而不使策略崩溃；如何把约束式更新改写为可实现的截断目标，并给出可复用的批量采样与优势估计流程。","core_idea":"用新旧策略概率比乘以优势函数构造代理目标，并对概率比做截断，使超出置信区间的更新不再产生梯度收益；以截断代理目标的最大化替代带 KL 约束的约束优化，从而用一阶方法近似信赖域行为，并允许同一批采样数据做多轮小批量更新。","architecture":"算法由采样与更新两段构成：采样段用当前策略在环境中并行采集轨迹，记录状态、动作、旧策略对数概率与回报；估计段用广义优势估计（GAE）结合价值函数计算优势；更新段对每个小批量计算概率比与截断代理目标，加上价值函数损失与熵奖励，用一阶优化器更新策略与价值网络参数。整体不含二阶矩阵求解，也不含对偶变量迭代。","pipeline":["当前策略网络在环境中并行采样多条轨迹，记录观测、动作与旧策略对数概率。","用价值网络对轨迹中的状态估值，按 GAE 公式把时序差分残差加权求和得到优势估计。","对采样数据做小批量切分，按概率比与优势计算截断代理目标及其梯度。","在同一批数据上重复多轮小批量更新，策略参数逐步偏离采样时的旧策略。","更新价值网络参数以拟合回报，并按熵奖励项调节策略分布的熵。","丢弃该批数据，回到采样段用更新后的策略重新采集，进入下一轮迭代。"],"formula":"$$L^{\\mathrm{CLIP}}(\\theta)=\\mathbb{E}_{t}\\left[\\min\\left(r_{t}(\\theta)A_{t},\\ \\mathrm{clip}\\left(r_{t}(\\theta),1-\\epsilon,1+\\epsilon\\right)A_{t}\\right)\\right],\\quad r_{t}(\\theta)=\\frac{\\pi_{\\theta}(a_{t}\\mid s_{t})}{\\pi_{\\theta_{\\mathrm{old}}}(a_{t}\\mid s_{t})}$$","training":"论文给出的是后训练阶段的策略优化流程而非预训练配方：每轮先用旧策略采样一批轨迹，计算优势后对同一批数据做多轮小批量更新，更新目标由截断代理目标、价值函数损失与熵奖励加权组成。截断系数作为置信区间的近似，控制单轮策略变化幅度；多轮小批量更新使同一批采样数据被反复利用，提高样本效率。价值网络与策略网络共享同一批轨迹数据但使用不同损失。","walkthrough":"假设一轮迭代开始，策略网络参数为旧策略，在环境中并行采样若干条定长轨迹，每条轨迹记录每一步的观测、动作与旧策略对数概率。价值网络对每个状态输出估值，按 GAE 把多步时序差分残差按折扣与平滑系数加权求和，得到每个时间步的优势估计。随后把整批数据切成若干小批量，对每个小批量计算当前策略与旧策略的概率比：若优势为正且概率比超过上截断，目标不再随概率比增大而增大，梯度被截断；若优势为负且概率比低于下截断，同样被截断。这样单轮更新不会把概率比推到置信区间之外。同一批数据重复若干轮后丢弃，重新采样。价值网络用回报做回归，熵奖励项防止策略过早收缩。整个流程只用到一阶梯度，不需要求解约束优化或对偶问题。","pseudocode":"→ 当前策略网络在环境中并行采样多条轨迹，记录观测、动作与旧策略对数概率。\n→ 用价值网络对轨迹中的状态估值，按 GAE 公式把时序差分残差加权求和得到优势估计。\n→ 对采样数据做小批量切分，按概率比与优势计算截断代理目标及其梯度。\n→ 在同一批数据上重复多轮小批量更新，策略参数逐步偏离采样时的旧策略。\n→ 更新价值网络参数以拟合回报，并按熵奖励项调节策略分布的熵。\n→ 丢弃该批数据，回到采样段用更新后的策略重新采集，进入下一轮迭代。","experiments":{"datasets":["论文使用连续控制与离散动作的强化学习基准任务，具体任务清单未给出","本项目材料未给出数据集规模与版本"],"baselines":["信赖域策略优化（TRPO）","带自适应 KL 惩罚的策略梯度方法","优势演员评论家（A2C）类同步并行方法"],"results":"论文报告截断代理目标在连续控制任务上与 TRPO 取得相近或更好的回报，同时实现更简单、只需一阶优化；同一套超参数可跨任务复用。具体回报数值、训练步数与对比表格未给出。","limits":"论文未给出大规模分布式部署下的吞吐、显存与通信数据；截断系数与多轮小批量更新轮数对采样稳定性的影响只做了有限消融；未讨论低精度数值格式下的概率比计算误差。","ablations":"论文对截断系数、是否做概率比截断、多轮小批量更新轮数以及优势估计的平滑系数做了消融，说明去掉截断后单轮更新幅度失控、回报下降；具体消融数值未给出。"},"innovation":["把带 KL 约束的信赖域更新改写为只含概率比截断的一阶目标，去掉二阶求解与对偶变量迭代。","允许同一批采样数据做多轮小批量更新，显著提高样本复用率，同时用截断控制单轮策略偏移。","把广义优势估计与截断代理目标组合成一套可复用超参数的完整流程，降低调参成本。"],"limitations":["截断只约束概率比，不直接约束策略分布的整体 KL，极端优势值下仍可能出现较大分布偏移。","多轮小批量更新使数据逐渐偏离当前策略，论文未给出离线程度与采样稳定性的定量边界。","未涉及低精度推理、批量生成调度与 KV 复用等部署机制，无法直接回答 rollout 引擎的容量问题。"],"impact":"该论文给出的截断代理目标成为 RL 后训练中策略优化的默认形式之一，其批量采样加多轮小批量更新的流程直接对应 rollout 与训练解耦的工程形态；截断系数与优势估计成为后续长尾样本筛选、离线程度监控与采样稳定性讨论的起点。","summary":"论文提出近端策略优化：用新旧策略概率比乘优势构造代理目标，并对概率比做上下截断，使超出置信区间的更新不再产生梯度收益，从而用一阶梯度近似信赖域行为。流程为并行采样轨迹、用 GAE 估计优势、对同一批数据做多轮小批量更新，目标由截断代理目标、价值损失与熵奖励组成。论文报告其在连续控制任务上与 TRPO 回报相近而实现更简单，但未给出大规模部署的吞吐、显存与低精度数值稳定性数据。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为定长轨迹的批量采样，每轮采样批大小与轨迹长度未给出，需按 rollout 引擎容量设定并发。","采样阶段请求长度分布由环境回合长度决定，长尾回合会拉长单轮采样时间，需与批调度配合。","同一批数据被多轮小批量复用，数据复用轮数与批大小共同决定单轮训练的计算密度。","SLO 层面论文未给出吞吐与延迟指标，部署时需自行定义每轮采样完成时间与更新完成时间。"],"train_recipe":["部署配方论文未给出；按机制可映射为策略网络与价值网络分离部署，采样端与更新端解耦。","硬件档位、并行拓扑与量化方案论文未给出，材料不含 B200/B300/GB200 NVL72 相关数据。","KV 策略：采样端需缓存旧策略对数概率，论文未讨论 KV 复用与前缀共享。","监控项应包含概率比分布、截断触发比例与优势估计方差，论文未给出具体阈值。"],"facts":["截断代理目标对每个时间步取未截断项与截断项的最小值，概率比超出上下界时该项不再提供增大目标的梯度，从而限制单轮策略偏移。","概率比定义为当前策略与采样时旧策略在同一个动作上的概率之比，因此采样端必须保存旧策略对数概率，这是 rollout 与训练解耦时的关键状态。","优势估计采用广义优势估计，把多步时序差分残差按折扣与平滑系数加权求和，平滑系数取值论文未给出。","同一批采样数据被切成小批量并做多轮更新，数据复用率提高的代价是数据逐渐偏离当前策略，离线程度随更新轮数增加。","总损失由截断代理目标、价值函数回归损失与熵奖励三项加权组成，三项权重论文未给出具体数值。","算法只使用一阶梯度，不含二阶矩阵求逆与对偶变量迭代，单步更新计算量与一阶优化器同阶。","截断系数是置信区间的近似，论文未给出其在不同任务上的最优取值，也未给出与 KL 约束的定量对照。","论文未报告低精度数值格式下的概率比计算误差，NVFP4 或 FP8 下采样稳定性无数据支撑。"],"anchors":[],"pitfalls":["把截断系数当作固定安全阈值：它只约束概率比，不约束整体分布 KL，长尾样本上仍可能偏移过大。","忽视旧策略对数概率的存储与同步：采样与更新解耦后若旧策略版本不一致，概率比计算失真，截断失效。","把论文的样本效率结论直接外推到大规模 rollout：论文未给出吞吐、显存与低精度稳定性数据，容量规划不能照搬。"],"depth":"deep"},{"id":"paper-prune-as-you-generate-online-rollout-2026","title":"Prune as You Generate: Online Rollout Pruning for Faster and Better RLVR","title_zh":"在线Rollout剪枝加速RLVR推理","authors":["Haobo Xu","Sirui Chen","Ruizhong Qiu","Yuchen Yan","Chen Luo","Monica Cheng","Jingrui He","Hanghang Tong"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-longtail-throughput","links":{"paper":"https://arxiv.org/abs/2603.24840","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RLVR（可验证奖励强化学习）的后训练依赖大规模 rollout 生成，推理引擎需在训练解耦的部署形态下持续产出批量样本。Blackwell 档位（B200/B300/GB200 NVL72）上，rollout 的瓶颈从算力转向显存与 KV cache 容量、批调度与长尾样本的尾部延迟；NVFP4/FP8 量化虽提升吞吐，却给采样稳定性与验证器一致性带来新约束。在线剪枝在生成过程中丢弃低价值轨迹，直接减少解码 token 数与 KV 占用，是缓解长尾与容量压力的机制性手段。","problem":"RLVR rollout 中大量样本对策略改进贡献低，却完整消耗解码算力与 KV cache；长尾样本拖高批完成时间，降低有效吞吐。现有离线过滤需先完整生成再筛选，无法在解码阶段释放显存与算力，导致 rollout 引擎与训练解耦时容量被无效 token 占据。","core_idea":"在 rollout 解码过程中在线判定并剪除低价值轨迹：以可验证奖励信号或中间置信度为判据，提前终止部分序列，把省下的 KV cache 与解码步数让给更有希望的样本，从而同时提升 rollout 吞吐与训练样本质量。","architecture":"rollout 引擎与训练器解耦部署：推理侧按批调度生成候选轨迹，前缀共享复用公共 prompt 的 KV；在线剪枝模块在固定解码步或 token 阈值处评估轨迹价值，命中则终止并释放 KV 块；幸存轨迹进入奖励模型/验证器推理，结果异步回传训练器做权重同步。剪枝判据与阈值作为调度策略的一部分，与批大小、并发上限共同决定显存水位。","pipeline":["训练器下发 prompt 批次与策略权重版本，rollout 引擎按批调度装入生成队列。","公共前缀经前缀共享复用 KV cache，减少重复预填的显存与算力开销。","逐 token 解码，在线剪枝模块在检查点读取中间信号并判定是否终止该轨迹。","被剪枝轨迹立即释放 KV 块并退出批，幸存轨迹继续解码至完成或上限。","完成轨迹送入奖励模型/验证器推理，得分与轨迹异步回传训练器。","训练器聚合样本更新权重，按版本同步回 rollout 引擎进入下一轮。"],"formula":"$$\\mathcal{L}_{\\text{RLVR}}=-\\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\sum_{t=1}^{T}\\mathbb{1}\\{t\\le \\tau(x)\\}\\cdot r(x,y_{1:t})\\log \\pi_\\theta(y_t\\mid x,y_{<t})\\right]$$","training":"训练侧按 RLVR 目标更新策略：仅对未被剪枝的前缀 token 计算策略梯度，剪枝点之后的 token 不参与 loss，降低有效序列长度与激活显存。权重同步采用异步流水线，rollout 引擎在版本切换间隙继续消费旧权重样本，需控制陈旧度上限。量化方案与采样温度需联合标定，避免 NVFP4 下低概率 token 被错误剪除。","walkthrough":"一轮迭代中，训练器把一批 prompt 交给解耦的 rollout 引擎；引擎先做前缀共享预填，再按批解码。解码到检查点时，剪枝模块依据中间奖励或置信度给轨迹打分，低于阈值的轨迹被终止，其 KV 块立即回收供新请求使用。幸存轨迹继续生成并被送入验证器打分，得分异步回传。由于剪枝减少了无效解码步与 KV 占用，批内长尾被压缩，引擎可在相同显存档位下维持更高并发；训练器按陈旧度约束消费样本并同步新权重，进入下一轮。","pseudocode":"for prompt_batch in rollout_queue:\n  kv = prefix_share(prompt_batch)\n  active = init_trajectories(prompt_batch)\n  while active:\n    tokens = decode_step(active, kv)\n    for traj in active:\n      if at_checkpoint(traj):\n        score = value_signal(traj)\n        if score < threshold:\n          release_kv(traj)\n          active.remove(traj)\n    if done(active):\n      rewards = verifier_infer(active)\n      send_async(rewards)\n  sync_weights_if_stale()","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字；机制上，在线剪枝通过提前终止低价值轨迹减少解码 token 与 KV 占用，预期改善批完成时间与有效吞吐，但收益幅度取决于剪枝阈值与检查点位置，需在 Blackwell 档位上实测。","limits":"剪枝判据若与最终奖励不一致，可能误删高价值轨迹，损害样本质量；检查点过密增加判定开销，过疏则回收不及时。NVFP4 量化下中间信号噪声可能放大误判，长尾样本的尾部延迟改善有限。","ablations":"需消融检查点位置、剪枝阈值、前缀共享开关与量化精度对吞吐和样本质量的影响；材料未给出具体消融数字。"},"innovation":["把样本过滤从离线后处理前移到解码过程，实时释放 KV cache 与解码步数。","将剪枝判据嵌入批调度策略，使显存水位与并发上限随轨迹价值动态调整。","面向解耦 rollout 引擎设计异步回传与权重同步，控制陈旧度对剪枝判据的影响。"],"limitations":["剪枝阈值与检查点缺乏理论保证，误剪高价值轨迹会污染策略梯度。","NVFP4 下中间置信度噪声可能使剪枝判定不稳定，需额外标定。","材料未给出硬件档位与并行拓扑细节，容量收益难以直接外推。"],"impact":"该机制把 rollout 容量管理从“生成完再筛”变为“边生成边释放”，对 Blackwell 部署的显存与 KV 压力有直接缓解作用；若与前缀共享、分离式预填/解码结合，可提升长尾场景下的有效吞吐，但需谨慎标定剪枝判据以保样本质量。","summary":"论文提出在线 rollout 剪枝：在 RLVR 解码过程中依据中间信号终止低价值轨迹，立即回收 KV cache 与解码步数，并把幸存轨迹送入验证器异步回传训练器。其价值在于把过滤前移为调度机制，缓解解耦 rollout 引擎的容量与长尾压力；风险在于剪枝判据与 NVFP4 采样稳定性耦合，误剪会损害样本质量，材料未给出具体数据规模与硬件档位。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为 RLVR prompt 批次，长度分布偏长尾，短 prompt 与长尾样本混合进入批调度。","批大小与并发上限由显存水位与 KV 块回收速度共同决定，剪枝后动态扩容。","公共前缀占比高的负载适合前缀共享，降低重复预填的 KV 占用。","SLO 以批完成时间与有效 token 吞吐衡量，长尾样本是尾部延迟主要来源。"],"train_recipe":["部署形态为 rollout 引擎与训练器解耦，权重按版本异步同步并设陈旧度上限。","硬件档位材料未给出，按 Blackwell B200/B300/GB200 NVL72 档位需实测显存与 KV 容量。","量化方案涉及 NVFP4/FP8，采样温度与剪枝判据需联合标定以保稳定性。","KV 策略为前缀共享加剪枝即时回收，监控显存水位与批完成时间。","验证器/奖励模型推理独立部署，结果异步回传避免阻塞解码。"],"facts":["在线剪枝在解码检查点评估轨迹价值，命中阈值即终止并释放 KV 块，减少无效解码 token 与显存占用。","剪枝判据依赖中间奖励或置信度信号，与最终验证器得分的一致性决定误剪率，需标定阈值。","解耦 rollout 引擎与训练器之间采用异步权重同步，陈旧度上限约束剪枝判据所用策略版本。","前缀共享复用公共 prompt 的 KV cache，剪枝回收的 KV 块可立即分配给新请求，提升并发容量。","NVFP4/FP8 量化下低概率 token 的采样噪声可能放大剪枝误判，需联合标定温度与阈值。","长尾样本是批完成时间的主要来源，剪枝通过提前终止低价值长轨迹压缩尾部延迟。","验证器推理独立于解码流水线，得分异步回传，避免阻塞 rollout 批调度。","剪枝后仅对未剪前缀计算策略梯度，有效序列长度下降，激活显存与 loss 计算量随之减少。"],"anchors":[],"pitfalls":["剪枝阈值过激会误删高价值轨迹，污染策略梯度并降低样本多样性。","检查点过密增加判定开销，过疏则 KV 回收不及时，容量收益打折。","NVFP4 采样噪声与剪枝判据耦合，未标定即上线可能导致判定抖动。"],"depth":"shallow"},{"id":"paper-qarl-rollout-aligned-quantization-aw-2026","title":"QaRL: Rollout-Aligned Quantization-Aware RL for Fast and Stable Training under Training--Inference Mismatch","title_zh":"QaRL：对齐 Rollout 的量化感知 RL","authors":["Hao Gu","Hao Wang","Jiacheng Liu","Lujun Li","Qiyuan Zhu","Bei Liu","Binxing Xu","Lei Wang","Xintong Yang","Sida Lin","Sirui Han","Yike Guo"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-sampling-stability","links":{"paper":"https://arxiv.org/abs/2604.07853","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RL 后训练的 rollout 阶段把生成引擎与训练引擎解耦后，训练侧权重更新与推理侧采样之间存在版本差；若再把推理侧切到 NVFP4/FP8 等低精度路径，采样分布会进一步偏移，导致重要性比失真、梯度方差变大。QaRL 关注的是在这种训练—推理不匹配下，如何让量化后的 rollout 仍可用于稳定更新。","problem":"训练引擎与 rollout 引擎的权重版本不同步，加上低精度量化引入的数值扰动，使 on-policy 假设被破坏；直接对量化 rollout 做策略梯度会出现重要性权重爆炸、长尾样本梯度主导与吞吐抖动。","core_idea":"把量化误差当作与 rollout 对齐的显式校正项：在采样端记录量化前后的 log-prob 偏差，在训练端用该偏差修正重要性比与损失，使量化 rollout 仍可近似 on-policy 使用，同时保持低精度推理的吞吐收益。","architecture":"系统由训练引擎与 rollout 引擎组成，二者通过权重同步通道解耦；rollout 引擎以低精度（NVFP4/FP8）执行批量生成，逐 token 记录量化前后 log-prob 及版本号；样本进入训练侧后按版本差与量化偏差重加权，奖励模型/验证器独立推理；长尾样本进入异步缓冲，权重同步按步数或时间窗触发。","pipeline":["训练引擎产出最新权重，经同步通道推送到 rollout 引擎并记录版本号。","rollout 引擎按批调度请求，以 NVFP4/FP8 执行生成并复用前缀 KV。","逐 token 记录量化前后 log-prob 偏差与采样版本，随样本一并回传。","奖励模型/验证器对完成样本打分，长尾样本进入异步缓冲等待。","训练侧按版本差与量化偏差修正重要性比，组装批后更新策略。","监控重要性权重分布与吞吐，异常时回退高精度采样或缩短同步周期。"],"formula":"$$\\rho_t=\\exp\\big(\\log\\pi_{\\theta}(a_t\\mid s_t)-\\log\\pi_{\\theta_{\\mathrm{roll}}}^{q}(a_t\\mid s_t)+\\Delta^{q}_t\\big),\\quad \\mathcal{L}=-\\mathbb{E}\\big[\\min(\\rho_t\\hat{A}_t,\\ \\mathrm{clip}(\\rho_t,1-\\epsilon,1+\\epsilon)\\hat{A}_t)\\big]$$","training":"训练侧不修改原有策略梯度骨架，只在重要性比中注入量化偏差校正项 $\\Delta^{q}_t$ 与版本差；批组装时按样本版本分层，过期样本降权或丢弃；长尾样本走异步缓冲避免阻塞主批；监控重要性权重分位数与梯度范数，超阈值时回退高精度 rollout 或缩短权重同步周期。","walkthrough":"一次迭代中，训练引擎把第 k 版权重同步到 rollout 引擎；rollout 引擎以 NVFP4 批量生成，前缀 KV 复用降低重复预填，逐 token 记录量化前后 log-prob 与版本号。样本完成后由奖励模型打分，普通样本即时回传，长尾样本进入异步缓冲。训练侧读取样本，按版本差与量化偏差计算校正后重要性比，clip 后组损失；若监控发现权重分位数越界，则本批降权并触发一次高精度重采样，随后进入下一轮同步。","pseudocode":"循环每个训练步：\n  同步权重到 rollout 引擎，记录版本号 v\n  rollout 引擎按批调度，NVFP4 生成并复用前缀 KV\n  逐 token 记录 log-prob 量化前后偏差与版本号\n  奖励模型/验证器打分，长尾样本入异步缓冲\n  训练侧读取样本，按版本差与偏差算校正重要性比\n  若权重分位数越界 -> 降权该批并触发高精度重采样\n  否则 -> clip 后组损失，更新策略并进入下一步","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线名称"],"results":"材料未给出可核验的数值结果；论文主张是在训练—推理不匹配与低精度 rollout 下保持稳定更新并维持吞吐，但具体提升幅度、采样稳定性指标与吞吐数字均未给出。","limits":"材料未给出实验规模、硬件档位与量化配置细节；长尾样本比例、权重同步周期、重要性权重阈值等关键工程参数均未给出，无法判断方法在更大规模或更极端不匹配下的表现。","ablations":"材料未给出消融设置；可预期的消融维度包括量化偏差校正项、版本差分层与异步缓冲，但具体对照与数值未给出。"},"innovation":["把量化前后 log-prob 偏差作为显式校正项注入重要性比，而非仅靠 clip 抑制。","按样本版本分层处理训练—推理版本差，过期样本降权或丢弃。","长尾样本走异步缓冲，避免阻塞主批并稳定吞吐。"],"limitations":["材料未给出实验规模与硬件配置，工程代价难以量化。","量化偏差校正依赖逐 token 记录，带来额外显存与带宽开销。","版本差与量化偏差叠加时的理论保证未在材料中给出。"],"impact":"对 RL 后训练 rollout 的低精度部署有直接意义：把量化误差纳入重要性比校正，可在不放弃 NVFP4/FP8 吞吐的前提下维持更新稳定；其版本分层与异步缓冲思路可迁移到解耦式 rollout 引擎的调度与监控设计中。","summary":"QaRL 针对 RL 后训练中训练引擎与 rollout 引擎的版本差及低精度量化扰动，提出把量化前后 log-prob 偏差作为校正项注入重要性比，并按样本版本分层、长尾样本异步缓冲。方法不改变策略梯度骨架，重点在采样端记录偏差、训练端修正权重，并以监控阈值触发高精度回退。材料未给出具体数据集、基线与数值结果，工程参数亦未披露，因此其吞吐与稳定性收益尚待核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：材料未给出具体分布，需按训练任务的实际生成长度建模。","批大小与并发：材料未给出具体批大小与并发数，需结合 rollout 引擎显存与 KV 预算设定。","SLO：材料未给出吞吐或延迟目标，需按训练步周期反推 rollout 完成时间。","长尾样本比例：材料未给出，需在监控中统计超长样本占比以决定异步缓冲容量。"],"train_recipe":["硬件档位：材料未给出 B200/B300/GB200 NVL72 等具体档位。","并行拓扑：材料未给出训练与 rollout 的并行切分方式。","量化方案：rollout 侧使用 NVFP4/FP8 低精度路径，训练侧保持高精度更新。","KV 策略：rollout 引擎复用前缀 KV 以降低重复预填开销。","监控：跟踪重要性权重分位数、梯度范数与吞吐，越界时回退高精度采样。"],"facts":["rollout 引擎以 NVFP4/FP8 执行批量生成，逐 token 记录量化前后 log-prob 偏差，该记录带来额外显存与带宽开销，是低精度 rollout 的主要工程代价之一。","训练侧重要性比由版本差与量化偏差共同校正，若不加校正，低精度采样分布偏移会使重要性权重分位数越界并放大梯度方差。","样本按 rollout 版本分层，过期样本降权或丢弃，权重同步周期直接决定版本差大小与有效样本比例。","长尾样本进入异步缓冲，避免超长生成阻塞主批；缓冲容量与长尾比例决定吞吐稳定性与显存占用。","前缀 KV 复用在 rollout 引擎中降低重复预填，但低精度 KV 与高精度训练侧之间的数值一致性需要额外校验。","监控以重要性权重分位数与梯度范数为阈值，越界时触发高精度重采样，形成吞吐与稳定性的运行时折中。","奖励模型/验证器独立推理，其批调度与 rollout 引擎解耦，避免打分阻塞生成流水线。","材料未给出具体硬件档位、批大小与量化配置，上述机制的量化代价需在目标部署上实测。"],"anchors":[],"pitfalls":["逐 token 记录量化偏差会显著增加 rollout 侧显存与回传带宽，需评估是否值得。","版本差与量化偏差叠加时，校正项估计不准可能反而放大重要性权重方差。","异步缓冲若无容量上限，长尾样本积压会拖长训练步周期并挤占 KV 显存。"],"depth":"shallow"},{"id":"paper-quads-stabilizing-nvfp4-reinforcemen-2026","title":"QUADS: Stabilizing NVFP4 Reinforcement Learning for MoE via QUantization-error Alignment across Dual Sides","title_zh":"QUADS：双端量化误差对齐稳定NVFP4强化学习","authors":["Zhengyang Zhuge","Hao Yu","Xin Wang","Zheng Li","Yizhong Cao","Dayiheng Liu","Jianwei Zhang"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-sampling-stability","links":{"paper":"https://arxiv.org/abs/2607.15810","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"在RL后训练的rollout阶段，MoE模型以NVFP4执行批量生成可显著提升吞吐并压低显存，但量化误差会在策略侧与参考侧之间不对称累积，导致采样分布漂移、重要性比值失真与长尾样本吞吐塌陷；现有做法多在单侧做补偿，缺少对训练与推理解耦部署下权重同步、KV复用与前缀共享的统一约束。","problem":"NVFP4下MoE rollout的采样稳定性不足：量化误差在策略与参考两端不一致，造成概率比偏移、梯度方差放大与长尾样本丢弃，进而拖累rollout引擎与训练解耦后的吞吐与SLO。","core_idea":"在策略侧与参考侧同时施加量化误差对齐：以双端误差的对称化约束校准log-prob与重要性比值，使NVFP4采样分布与高精度参考保持一致，并把该约束嵌入批量生成调度与权重同步流程，避免单侧补偿带来的偏差累积。","architecture":"rollout引擎与训练进程解耦部署，策略侧以NVFP4执行批量生成并按前缀共享复用KV；参考侧保留对齐校准路径，在权重同步窗口内更新量化尺度与误差补偿量；调度器按请求长度分布分批，长尾样本进入低并发通道；奖励模型与验证器推理独立成池，监控采样比值偏移与KV命中率。","pipeline":["请求进入rollout引擎，按长度分布与前缀相似度分组，命中前缀共享的请求直接复用KV块。","策略侧以NVFP4执行批量生成，逐token记录量化误差估计并与参考侧对齐量比对。","权重同步窗口内更新双端量化尺度，校准log-prob与重要性比值，抑制误差不对称累积。","长尾样本转入低并发通道继续生成，避免拖慢主批次的SLO与吞吐。","生成结果送入奖励模型与验证器推理池打分，比值偏移超阈值的样本被标记复核。","监控采样稳定性与KV命中率，异常批次触发回退到高精度路径重算。"],"formula":"$$\\mathcal{L}_{\\text{align}}=\\mathbb{E}_{x\\sim\\pi_{\\theta}}\\left[\\left(\\log\\pi^{\\text{NVFP4}}_{\\theta}(x)-\\log\\pi^{\\text{ref}}_{\\theta}(x)\\right)^{2}+\\lambda\\left|\\rho_{\\text{policy}}-\\rho_{\\text{ref}}\\right|\\right]$$","training":"该工作面向RL后训练推理而非训练配方：对齐约束在rollout生成过程中在线估计，量化尺度随权重同步窗口更新；策略与参考两端共享同一误差对齐量，避免单侧补偿；批量生成调度按长度分布分批，长尾样本走低并发通道；奖励模型与验证器推理独立部署，监控比值偏移与KV命中率作为稳定性信号。","walkthrough":"一次rollout批次中，调度器先按请求长度与前缀相似度分组，命中前缀共享的请求复用KV块以减少重复预填；策略侧以NVFP4逐token生成并记录量化误差估计，参考侧同步给出对齐量；权重同步窗口到来时更新双端量化尺度并校准重要性比值；若某批次比值偏移超过阈值，该批次样本被标记并转入低并发通道复核，主批次继续按SLO推进；长尾样本在独立通道完成生成后送入奖励模型与验证器推理池打分，监控面板汇总KV命中率与采样稳定性指标，异常时回退高精度路径重算。","pseudocode":"for batch in rollout_scheduler:\n  groups -> split_by_length_and_prefix(batch)\n  for g in groups:\n    kv -> reuse_prefix_cache(g) if hit else prefill(g)\n    tokens -> nvfp4_generate(policy_side, g, kv)\n    err -> estimate_quant_error(tokens)\n    align -> reference_side_align(err)\n    ratio -> calibrate_importance(tokens, align)\n    if ratio_offset(ratio) > threshold:\n      mark(g) -> longtail_channel(g)\n    else:\n      dispatch(g) -> reward_verifier_pool\n  sync_window -> update_quant_scales(align)\n  monitor(kv_hit_rate, ratio_offset)","experiments":{"datasets":["材料未给出具体数据集名称，仅描述为RL后训练rollout负载与长尾样本混合请求流。"],"baselines":["材料未给出基线方法名称，仅提及单侧量化补偿与高精度参考路径作为对照方向。"],"results":"材料未给出可核验的吞吐、比值偏移或采样稳定性数字；论文主张双端对齐可降低重要性比值偏移并缓解长尾样本吞吐塌陷，但具体提升幅度未给出。","limits":"材料未给出硬件档位、并行拓扑与量化方案细节；对齐约束的在线估计开销、权重同步窗口长度与阈值选择均未量化，长尾通道的容量规划缺少数据支撑。","ablations":"材料未给出消融实验设置与数字；仅可从机制上推断双端对齐、前缀共享与长尾通道为关键组件，但各组件贡献度未给出。"},"innovation":["在策略侧与参考侧同时施加量化误差对齐，替代单侧补偿以抑制NVFP4采样分布漂移。","把对齐约束嵌入rollout引擎与训练解耦的权重同步窗口，使量化尺度随同步更新。","将长尾样本分流与KV前缀共享结合，缓解批量生成调度中的吞吐塌陷。"],"limitations":["材料未给出硬件档位、并行拓扑与量化方案，部署代价无法量化评估。","对齐约束的在线估计开销与阈值选择缺少数据，可能引入额外延迟。","长尾通道容量与SLO保障缺少实验支撑，失败模式未系统刻画。"],"impact":"为NVFP4下MoE rollout提供双端误差对齐思路，把采样稳定性问题落到量化尺度同步与批量调度机制上；对rollout引擎与训练解耦部署的监控指标设计有参考价值，但缺少可核验数字，工程落地仍需补齐硬件与SLO参数。","summary":"QUADS针对NVFP4强化学习rollout中MoE采样不稳定问题，提出在策略侧与参考侧同时对齐量化误差，以校准log-prob与重要性比值；机制上结合前缀共享KV复用、按长度分批调度与长尾样本分流，并把对齐量更新嵌入权重同步窗口；论文未给出具体数字与硬件配置，部署代价与消融贡献仍需后续核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布呈长尾形态，短请求命中前缀共享概率高，长请求进入低并发通道。","批大小按长度分组动态调整，主批次追求吞吐，长尾批次控制并发以保SLO。","并发上限由KV命中率与奖励模型推理池容量共同约束，超阈值触发分流。","SLO以批次完成时延与比值偏移阈值为双指标，异常批次标记复核。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署需按B200/B300/GB200 NVL72档位另行规划。","量化方案为NVFP4，策略侧与参考侧共享对齐尺度并在权重同步窗口更新。","KV策略以前缀共享复用为主，命中率作为调度与容量规划信号。","监控采样比值偏移、KV命中率与长尾通道排队长度，异常回退高精度路径。"],"facts":["QUADS的核心机制是在策略侧与参考侧同时对齐NVFP4量化误差，以对称化约束校准log-prob与重要性比值，替代单侧补偿，降低采样分布漂移与梯度方差放大。","对齐量在权重同步窗口内更新，量化尺度随策略与参考两端同步，避免训练与推理解耦部署下误差不对称累积导致的比值失真。","rollout引擎按请求长度分布与前缀相似度分组，命中前缀共享的请求复用KV块，减少重复预填开销并提升批量生成吞吐。","长尾样本转入低并发通道继续生成，主批次按SLO推进，避免长尾请求拖慢整体吞吐；分流阈值与通道容量材料未给出。","奖励模型与验证器推理独立成池，生成结果打分后比值偏移超阈值的样本被标记复核，构成采样稳定性的监控闭环。","异常批次可回退到高精度路径重算，代价是吞吐下降；回退触发条件与频率材料未给出，属于部署失败模式之一。","论文未给出硬件档位、并行拓扑与量化方案细节，NVFP4对齐约束的在线估计开销与权重同步窗口长度均缺少可核验数字。","材料未给出数据集、基线与消融数字，双端对齐、前缀共享与长尾通道的组件贡献度无法量化比较。"],"anchors":[],"pitfalls":["把双端对齐当作免费收益：在线误差估计与尺度同步会引入额外开销，需与吞吐收益权衡。","长尾通道容量不足时，分流反而造成排队与SLO违约，需按请求长度分布规划。","权重同步窗口过长会使对齐量滞后，NVFP4采样稳定性在窗口边界处退化。"],"depth":"shallow"},{"id":"paper-qurl-efficient-reinforcement-learnin-2026","title":"QuRL: Efficient Reinforcement Learning with Quantized Rollout","title_zh":"QuRL：量化 Rollout 的高效强化学习","authors":["Yuhang Li","Reena Elangovan","Xin Dong","Priyadarshini Panda","Brucek Khailany"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-sampling-stability","links":{"paper":"https://arxiv.org/abs/2602.13953","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"强化学习后训练的推理阶段需要反复生成大量 rollout 样本，rollout 引擎与训练器之间的权重同步、批调度和 KV 缓存管理直接决定端到端吞吐。Blackwell 档位引入 NVFP4/FP8 低精度算子后，采样数值稳定性与显存占用成为新的工程约束，量化 rollout 因而成为解耦部署的关键环节。","problem":"rollout 生成在 RL 后训练中占比高，全精度推理显存与带宽开销大，低精度量化又可能改变采样分布并影响优势估计；同时 rollout 与训练解耦后权重同步和批调度带来额外停顿。","core_idea":"将 rollout 引擎的推理算子量化到低精度（NVFP4/FP8），在保持采样数值稳定的前提下压缩 KV 缓存与权重带宽，并把量化 rollout 与训练更新解耦为异步流水线，用批量生成调度与前缀共享提升长尾样本吞吐。","architecture":"rollout 引擎独立于训练器部署，按请求批次做连续批调度并复用前缀 KV；权重以低精度格式从训练侧同步到推理侧，采样阶段对 logits 做数值校正以抑制量化偏差；奖励模型与验证器作为独立推理服务接入，异步流水线按 token 流式回传样本，监控覆盖采样分布漂移与长尾队列深度。","pipeline":["训练器完成一步更新后，将权重以低精度格式打包并同步到 rollout 引擎的推理副本。","rollout 引擎接收提示请求，按长度分布做连续批调度并命中前缀共享的 KV 缓存。","量化算子执行预填与解码，采样阶段对 logits 施加数值校正以稳定分布。","生成的 token 流式送入奖励模型与验证器推理服务打分。","打分结果回传训练器形成优势估计，长尾样本进入独立队列等待补齐。","监控采样分布漂移与队列深度，触发权重再同步或批大小调整。"],"formula":"$$\\tilde{p}(x_t\\mid x_{<t})=\\mathrm{softmax}\\left(\\frac{f_{q}(x_{<t})}{T}\\right),\\quad \\mathcal{L}_{\\mathrm{RL}}=-\\mathbb{E}_{\\tau\\sim\\tilde{p}}\\left[\\sum_{t}A_t\\log \\pi_\\theta(x_t\\mid x_{<t})\\right]$$","training":"训练侧按 RL 目标更新策略，rollout 侧以量化推理生成轨迹；两侧通过异步流水线解耦，权重同步按步或按批触发。量化误差通过采样温度与 logits 校正缓解，长尾样本以队列方式补齐后再参与优势估计，避免短样本批次主导梯度。","walkthrough":"一次迭代中，训练器完成参数更新后把权重以 NVFP4/FP8 打包推送至 rollout 引擎；引擎按提示长度分桶做连续批调度，命中前缀共享的 KV 缓存以减少重复预填。解码阶段量化算子输出 logits，经温度缩放与校正后采样，token 流式送入奖励模型与验证器打分。短样本先回传，长尾样本进入队列等待补齐；监控发现采样分布漂移时回退到更高精度算子或调整批大小，随后进入下一轮权重同步。","pseudocode":"循环 每一步训练：\n  训练器更新策略参数\n  权重打包为低精度格式并同步到 rollout 引擎\n  引擎按提示长度分桶，连续批调度\n  命中前缀共享 KV 缓存，跳过重复预填\n  量化预填与解码，输出 logits\n  对 logits 做温度缩放与数值校正\n  采样 token 并流式送入奖励模型与验证器\n  短样本回传，长尾样本入队补齐\n  监控采样分布漂移与队列深度\n  若漂移超阈值，回退高精度算子或调批大小","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字；可核验的机制是量化 rollout 与训练解耦、批量调度与前缀共享降低重复预填，长尾样本队列补齐后再参与优势估计。","limits":"材料未给出吞吐与精度对比数据；量化采样稳定性依赖校正策略，长尾样本补齐会拉长单步时延，权重同步频率与批大小需联合调优。","ablations":"材料未给出消融实验；可讨论的变量包括量化精度档位、前缀共享命中率、批调度策略与权重同步频率。"},"innovation":["把 rollout 推理算子量化到 NVFP4/FP8 并配套采样数值校正。","rollout 引擎与训练器解耦为异步流水线，权重低精度同步。","批量生成调度结合前缀共享 KV 复用，缓解长尾样本吞吐。"],"limitations":["材料未给出量化后采样分布的定量偏差与回退阈值。","长尾样本队列补齐会拉长单步时延，影响 SLO。","权重同步频率与批大小缺少联合调优的公开数据。"],"impact":"为 Blackwell 档位上 RL 后训练 rollout 提供量化推理与解耦部署的工程路径，把显存与带宽节省落到采样稳定性与长尾吞吐的具体机制上，便于后续在 B200/B300/GB200 NVL72 拓扑中配置并行与监控。","summary":"QuRL 关注 RL 后训练中 rollout 生成的效率问题，核心是把 rollout 引擎的推理算子量化到低精度并把 rollout 与训练解耦为异步流水线。引擎按请求批次做连续批调度、复用前缀 KV 缓存，采样阶段对 logits 做数值校正以抑制量化偏差；奖励模型与验证器作为独立服务接入，长尾样本入队补齐。材料未给出数据集、基线与吞吐数字，可核验的是量化 rollout、权重同步、批调度与长尾队列的机制链条。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为 RL 后训练的提示请求，长度分布呈长尾，短提示与长提示混合到达。","批大小按长度分桶后动态调整，短样本优先回传以缩短单步时延。","并发受 rollout 引擎显存与 KV 缓存容量约束，长尾队列单独限流。","SLO 以单步 rollout 完成时间为目标，长尾样本补齐允许放宽时限。"],"train_recipe":["硬件档位面向 B200/B300/GB200 NVL72，rollout 与训练分卡部署。","并行拓扑按推理副本切分，前缀共享 KV 缓存跨批复用。","量化方案采用 NVFP4/FP8 推理算子，采样阶段保留校正路径。","KV 策略为前缀共享加长尾队列隔离，监控采样分布漂移与队列深度。"],"facts":["rollout 引擎与训练器解耦部署，权重以低精度格式从训练侧同步到推理副本，同步频率与批大小需联合调优以避免单步停顿。","推理算子量化到 NVFP4/FP8 后压缩权重带宽与 KV 缓存占用，采样阶段对 logits 做温度缩放与数值校正以抑制分布漂移。","批量生成调度按提示长度分桶并做连续批调度，短样本优先回传，长尾样本进入独立队列等待补齐后再参与优势估计。","前缀共享 KV 缓存跨批复用，减少重复预填开销；命中率下降会直接抬高预填算力占比并拉长单步时延。","奖励模型与验证器作为独立推理服务接入，token 流式打分回传训练器，服务排队深度是长尾吞吐的监控指标。","异步流水线中权重同步与 rollout 生成重叠执行，同步滞后会引入策略陈旧，需以采样分布漂移作为回退触发条件。","长尾样本队列补齐拉长单步时延，SLO 需按分位数设定；队列深度与批大小联动调整可缓解尾部等待。","量化采样稳定性依赖校正策略，漂移超阈值时回退到更高精度算子，回退代价是显存与带宽占用上升。"],"anchors":[],"pitfalls":["材料未给出量化后采样分布的定量偏差，不能假定 NVFP4 采样与全精度等价。","长尾样本补齐会拉长单步时延，忽略队列深度会误判吞吐。","权重同步频率过高会打断流水线重叠，过低则引入策略陈旧。"],"depth":"shallow"},{"id":"paper-reinforcement-learning-from-human-fe-2024","title":"Reinforcement Learning from Human Feedback without Reward Inference: Model-Free Algorithm and Instance-Dependent Analysis","title_zh":"免奖励推断的RLHF无模型算法","authors":["Qining Zhang","Honghao Wei","Lei Ying"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-reward-verifier-serving","links":{"paper":"https://arxiv.org/abs/2406.07455","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"常规RLHF先训练奖励模型再做策略优化，需要奖励推断与额外价值网络，带来显存占用、采样开销与奖励过优化风险。该论文研究在只有人类偏好比较数据、不显式拟合奖励函数的条件下直接学习策略，并给出依赖实例的统计分析，属于偏好优化与推理机制交叉的算法工作。","problem":"如何在不对奖励函数做显式推断的前提下，仅用成对偏好样本优化语言模型策略，并给出与实例相关的样本复杂度与遗憾界，避免奖励模型推理带来的部署开销与偏差。","core_idea":"把偏好比较看作策略间相对优势的估计问题，用无模型的偏好策略梯度直接更新策略，绕开奖励模型与价值网络；理论分析给出依赖实例的遗憾界，说明无需奖励推断即可达到可证明的样本效率。","architecture":"算法侧由偏好数据缓冲、成对比较采样、无模型策略梯度估计器与策略更新器组成；不维护奖励模型参数，也不维护独立价值网络。推理侧只需策略模型前向生成候选回答，奖励信号来自离线偏好对而非在线奖励模型打分，因此部署上省去奖励模型服务与验证器推理链路。","pipeline":["从偏好数据集采样成对回答，构造当前策略下的比较样本。","用策略模型对候选回答计算对数概率，估计成对偏好下的相对优势。","以无模型策略梯度形式更新策略参数，不经过奖励模型反向传播。","按实例相关界控制批大小与更新步长，维持估计方差在可控范围。","周期性评估策略在留出偏好对上的胜率，监控长尾样本的估计偏差。"],"formula":"$$\\nabla_\\theta J(\\theta)=\\mathbb{E}_{(x,y^+,y^-)\\sim\\mathcal{D}}\\left[\\sigma\\!\\left(\\log\\frac{\\pi_\\theta(y^+|x)}{\\pi_\\theta(y^-|x)}\\right)\\nabla_\\theta\\log\\pi_\\theta(y^+|x)\\right]$$","training":"训练信号仅来自离线成对偏好数据，不训练奖励模型；每步需对正负回答各做一次策略前向以取得对数概率，反向只更新策略参数。批大小与步长按实例相关分析设定，需控制同一偏好对重复使用的次数以限制估计偏差。该流程不涉及并行通信与量化部署细节，材料未给出具体优化器与硬件配置。","walkthrough":"给定一条偏好样本，先由当前策略对正回答与负回答分别前向得到对数概率，二者之差经 sigmoid 变换得到偏好概率估计；再用该估计加权正回答的对数概率梯度，得到无模型策略梯度。更新后策略在下一轮重新计算对数概率，因此每轮都需重新生成或缓存回答的 token 级概率。由于没有奖励模型，省去奖励打分的前向与显存，但策略前向次数随批大小线性增长，长尾样本会拉高单批延迟。","pseudocode":"初始化策略参数 theta\n循环 每轮更新：\n  从偏好数据采样批 B = {(x, y+, y-)}\n  对每条样本前向策略，取 log pi(y+|x) 与 log pi(y-|x)\n  计算偏好概率 p = sigmoid(log pi(y+|x) - log pi(y-|x))\n  计算梯度 g = p * grad log pi(y+|x)\n  按实例相关步长更新 theta <- theta + lr * g\n  记录留出偏好对上的胜率与估计方差","experiments":{"datasets":["材料未给出具体数据集名称，仅提及成对偏好比较数据"],"baselines":["材料未给出基线方法名称"],"results":"论文以实例相关分析给出样本复杂度与遗憾界，强调无需奖励推断即可获得可证明保证；材料未给出具体胜率、吞吐或显存数字。","limits":"理论保证依赖偏好模型假设与数据覆盖条件，实际长尾样本与分布偏移可能破坏界；材料未给出大规模部署实验与硬件档位数据。","ablations":"材料未给出消融实验细节，仅可从算法结构推断奖励模型移除与批大小设定对估计方差的影响。"},"innovation":["不显式推断奖励函数，直接用偏好比较做无模型策略梯度更新。","给出依赖实例的样本复杂度与遗憾界，而非最坏情况统一界。","省去奖励模型与价值网络的推理与显存开销，简化部署链路。"],"limitations":["理论假设较强，实际偏好数据分布偏移下界可能失效。","每步需多次策略前向取对数概率，长尾样本拉高批延迟。","材料未给出大规模 Blackwell 部署与量化采样稳定性数据。"],"impact":"对RL后训练推理的启示在于：若偏好优化可绕开奖励模型，rollout 侧可省去奖励/验证器服务链路，降低显存与调度复杂度；但策略前向次数增加，需在批调度与 KV 复用上做权衡。该工作偏理论，工程落地仍需补充吞吐与失败模式数据。","summary":"该论文研究免奖励推断的RLHF：仅用成对偏好样本，以无模型策略梯度直接优化策略，并给出实例相关的样本复杂度与遗憾界。算法不维护奖励模型与价值网络，推理侧只需策略前向取对数概率，因而省去奖励打分链路，但每轮需对正负回答各做前向，长尾样本会抬高批延迟。材料未给出具体数据集、基线、硬件档位与吞吐数字，工程结论需谨慎外推。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为成对偏好样本，每条含提示与正负回答，长度分布材料未给出。","批大小按实例相关界设定，需控制同一偏好对重复使用次数以限制偏差。","并发与 SLO 材料未给出，仅知每步需正负回答各一次策略前向。","长尾样本会拉高单批延迟，需在采样阶段做长度分桶以稳定吞吐。"],"train_recipe":["硬件档位材料未给出，未涉及 B200/B300/GB200 NVL72 具体配置。","并行拓扑与量化方案材料未给出，未涉及 NVFP4/FP8 部署细节。","KV 策略材料未给出，仅知每轮需重算或缓存回答的 token 级对数概率。","监控指标建议为留出偏好对胜率与梯度估计方差，材料未给出阈值。","权重同步与异步流水线材料未给出，属于理论算法工作。"],"facts":["算法不维护奖励模型参数，推理侧省去奖励打分前向，但每步仍需对正负回答各做一次策略前向以取对数概率，前向次数随批大小线性增长。","偏好概率由正负回答对数概率之差经 sigmoid 得到，梯度以该概率加权正回答对数概率，属于无模型策略梯度形式，不经过奖励模型反向传播。","理论给出实例相关样本复杂度与遗憾界，依赖偏好模型假设与数据覆盖条件；分布偏移或长尾样本可能使界失效，材料未给出具体常数。","每轮更新后策略变化，需重新计算回答的 token 级对数概率，缓存复用受策略版本约束，KV 复用收益随更新频率下降。","批大小与步长按实例相关分析设定，需限制同一偏好对重复使用次数以控制估计偏差，材料未给出具体批大小与步长数值。","长尾样本拉高单批延迟，因每步需正负回答各一次前向；建议按长度分桶调度以稳定吞吐，材料未给出分桶阈值。","该工作未涉及 NVFP4/FP8 量化下的采样稳定性，材料未给出量化方案与数值精度实验，工程落地需另行验证。","部署上省去奖励模型与验证器推理链路，可降低显存占用与服务调度复杂度，但策略前向开销上升，需在批调度与 KV 策略间权衡。"],"anchors":[],"pitfalls":["理论界依赖偏好模型假设，实际分布偏移下样本复杂度结论可能不成立。","每步正负回答各一次前向，长尾样本会显著拉高批延迟，需分桶调度。","材料未给出量化与硬件数据，不可外推 NVFP4 采样稳定性结论。"],"depth":"deep"},{"id":"paper-reinforcement-learning-from-human-fe-2026","title":"Reinforcement Learning from Human Feedback: A Statistical Perspective","title_zh":"RLHF 统计视角下的推理机制","authors":["Pangpang Liu","Chengchun Shi","Will Wei Sun"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2604.02507","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文从统计角度审视 RLHF 的推理环节，关注 rollout 与训练解耦后批量生成、KV 复用、奖励模型与验证器推理、异步流水线与权重同步等机制对样本分布与吞吐的影响。材料未给出具体实验平台与数字，因此本卡只整理与推理机制和部署代价相关的可核验要点，不涉及训练配方与产品评测。","problem":"RLHF 的统计性质依赖 rollout 样本的分布与新鲜度，而部署侧的批调度、KV 复用、量化采样与长尾请求会改变样本分布并引入偏差；论文需要回答这些工程机制如何影响策略优化估计，以及如何在 Blackwell 档位上以可接受的吞吐与 SLO 维持采样稳定性。","core_idea":"把 RLHF 视为带工程约束的统计估计问题：rollout 引擎与训练解耦后，批量生成调度与前缀共享决定样本相关性与陈旧度；奖励模型与验证器推理构成独立服务链路；NVFP4 等低精度采样需控制数值稳定性；长尾样本决定有效吞吐。统计结论必须落到具体机制与代价上。","architecture":"材料未给出论文的具体系统架构与并行拓扑。按本书两条线，可讨论的架构要素包括：rollout 引擎与训练进程分离部署，批量生成调度器按请求长度与 KV 占用排队；前缀共享与 KV 复用降低重复预填；奖励模型与验证器作为独立推理服务；异步流水线中权重同步与在途样本的陈旧度控制；量化方案与监控指标共同约束采样稳定性。以上均为机制层面的整理，具体档位与切分未给出。","pipeline":["请求进入 rollout 引擎的批量调度队列，按长度分布与并发上限排队，长尾请求单独标记。","调度器对共享前缀的请求做前缀匹配与 KV 复用，减少重复预填的计算与显存占用。","解码阶段按批推进，低精度量化路径需监控采样数值稳定性与分布偏移。","生成完成的样本送入奖励模型或验证器推理服务，独立批调度并返回分数。","异步流水线将打分样本回传训练侧，权重同步与在途样本陈旧度由调度策略约束。","长尾样本在吞吐统计中被单独计量，用于评估有效吞吐与 SLO 达成情况。"],"formula":"$$\\hat{J}(\\theta)=\\frac{1}{N}\\sum_{i=1}^{N}w_i\\,r(x_i,y_i),\\quad w_i=\\frac{\\pi_\\theta(y_i\\mid x_i)}{\\pi_{\\text{old}}(y_i\\mid x_i)}$$","training":"材料未给出训练配方，本卡不写训练细节。与推理相关的训练侧约束是：rollout 样本由解耦引擎批量生成，其批调度、KV 复用与量化路径会改变样本分布；异步流水线中权重同步延迟带来陈旧度，需要在统计估计中显式处理；奖励模型与验证器推理的批处理与精度同样影响分数噪声。以上为机制层面的约束，具体超参与规模未给出。","walkthrough":"假设一个 RLHF 迭代：训练侧发出批量提示，rollout 引擎按长度分布排队，短请求先批处理，长尾请求进入单独队列以避免拖慢整体批次；共享系统提示的请求命中前缀缓存，KV 复用减少预填开销。解码在低精度路径上运行，监控模块记录采样分布偏移与数值异常。生成样本送入独立部署的奖励模型服务，按批打分后回传。异步流水线允许训练与生成重叠，但权重同步存在延迟，部分样本基于旧策略生成，统计估计需按重要性权重修正。长尾样本单独计量，用于判断有效吞吐是否满足 SLO。整个链路中，批大小、并发与 KV 占用共同决定吞吐与样本新鲜度的权衡。","pseudocode":"初始化 rollout 引擎与训练进程，建立异步队列\n循环每个训练步：\n  训练侧发布提示批次到调度队列\n  调度器按长度分布排序，短请求优先成批\n  对共享前缀请求做前缀匹配，命中则复用 KV\n  解码阶段按批推进，记录低精度采样异常\n  生成样本送入奖励模型服务，独立批打分\n  打分结果回传训练侧，附带生成时的策略版本\n  按版本差计算重要性权重，修正陈旧样本\n  统计长尾样本占比与有效吞吐，更新调度参数","experiments":{"datasets":["材料未给出具体数据集"],"baselines":["材料未给出具体基线"],"results":"材料未给出实验结果与数字。可讨论的统计结论方向是：解耦 rollout 的批调度与 KV 复用会改变样本相关性；异步权重同步引入陈旧度并需重要性修正；低精度采样需监控数值稳定性；长尾样本拉低有效吞吐。以上均为机制层面的判断，无具体数值。","limits":"材料未给出实验限制。可指出的局限包括：统计视角的结论依赖具体调度与量化配置，缺少跨档位验证；长尾与陈旧度的交互难以在单一指标中刻画；奖励模型推理的批处理噪声未量化。","ablations":"材料未给出消融实验。可设想的消融维度包括批调度策略、KV 复用开关、量化精度路径与权重同步延迟，但均无具体结果。"},"innovation":["从统计估计角度统一刻画 rollout 批调度、KV 复用与陈旧度对样本分布的影响。","把奖励模型与验证器推理作为独立服务链路纳入吞吐与 SLO 分析。","强调低精度采样路径的数值稳定性监控与长尾样本的有效吞吐计量。"],"limitations":["材料未给出具体实验平台与数字，机制结论缺少跨硬件档位验证。","统计视角对调度与量化配置敏感，结论外推需谨慎。","长尾样本与陈旧度的交互缺少统一度量。"],"impact":"该论文的统计视角提示：RLHF 推理的工程机制会直接改变样本分布与估计偏差，部署侧需把批调度、KV 复用、量化路径与权重同步延迟纳入监控；对 Blackwell 档位部署而言，吞吐与 SLO 的权衡必须与采样稳定性一起评估。具体影响需后续材料补充。","summary":"本卡整理该论文与推理机制、部署代价相关的要点：rollout 与训练解耦后，批量生成调度、前缀共享与 KV 复用改变样本相关性与吞吐；奖励模型与验证器构成独立推理链路；异步流水线的权重同步带来陈旧度并需重要性修正；低精度采样需数值稳定性监控；长尾样本决定有效吞吐。材料未给出具体数字与实验，所有判断停留在机制层面。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载形态：请求长度分布含短请求与长尾长请求，长尾单独排队以避免拖慢整体批次。","批大小与并发由 KV 占用与显存约束决定，短请求优先成批以提高吞吐。","共享前缀比例影响 KV 复用命中率，需在调度中做前缀匹配。","SLO 以有效吞吐与长尾延迟衡量，长尾样本单独计量。"],"train_recipe":["部署配方：rollout 引擎与训练进程分离部署，异步队列衔接生成与更新。","奖励模型与验证器作为独立推理服务，按批调度打分。","量化路径需监控采样数值稳定性，异常样本单独标记。","权重同步延迟需记录策略版本，用于重要性权重修正。","监控指标包括批大小、KV 命中率、长尾占比与陈旧度分布。"],"facts":["rollout 引擎与训练解耦后，批量生成调度按请求长度分布排队，短请求优先成批，长尾请求单独队列以避免拖慢整体批次吞吐。","前缀共享与 KV 复用减少重复预填的计算与显存占用，命中率取决于共享系统提示的比例，调度器需做前缀匹配后再组批。","奖励模型与验证器作为独立推理服务部署，按批打分并回传训练侧，其批处理与精度会引入分数噪声，影响策略估计。","异步流水线允许生成与训练重叠，但权重同步存在延迟，部分样本基于旧策略生成，统计估计需按重要性权重修正陈旧度。","低精度量化路径下的解码需监控采样数值稳定性与分布偏移，异常样本应单独标记，避免污染策略优化估计。","长尾样本拉低有效吞吐，需在吞吐统计中单独计量长尾占比与延迟，用于判断 SLO 达成与调度参数调整。","批大小与并发由 KV 占用与显存约束共同决定，增大批可提升吞吐但增加 KV 压力与样本相关性，需权衡。","监控指标应覆盖批大小、KV 命中率、长尾占比、陈旧度分布与量化异常率，形成部署侧的可观测闭环。"],"anchors":[],"pitfalls":["材料未给出具体数字与实验平台，机制结论不可当作已验证的定量结论使用。","统计视角的结论对调度与量化配置敏感，跨硬件档位外推需补充验证。","长尾样本与陈旧度的交互缺少统一度量，单一吞吐指标可能掩盖采样偏差。"],"depth":"shallow"},{"id":"paper-remax-a-simple-effective-and-efficie-2023","title":"ReMax: A Simple, Effective, and Efficient Reinforcement Learning Method for Aligning Large Language Models","title_zh":"ReMax：免评论家的RLHF推理机制","authors":["Ziniu Li","Tian Xu","Yushun Zhang","Zhihang Lin","Yang Yu","Ruoyu Sun","Zhi-Quan Luo"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2310.10505","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"ReMax 面向大语言模型对齐的强化学习后训练，其核心工程问题是：PPO 类方法需要同时驻留策略模型、价值模型、奖励模型与参考模型，显存占用与调度复杂度高，rollout 生成与打分环节的吞吐成为瓶颈。该工作提出去掉价值模型、以规则或奖励模型的序列级分数直接构造优势，从而简化推理侧的资源编排。","problem":"PPO 类 RLHF 在 rollout 阶段需多模型并行驻留与交替执行，价值模型带来额外前向与显存开销，长尾生成长度使批调度与 KV 缓存利用率下降；如何在保证对齐效果的同时降低推理侧模型数量与调度代价，是本文要解决的问题。","core_idea":"用序列级奖励减去同批次或同提示下的基线分数构造优势估计，替代学习到的价值函数，从而去掉评论家模型；rollout 只需策略模型与奖励/规则打分器两条推理路径，优势在序列末尾一次性回填，避免逐 token 的价值前向与跨模型同步。","architecture":"推理侧由策略模型生成引擎与打分器组成：生成引擎按提示批量采样多条候选回复，KV 缓存随采样序列增长；打分器对完整序列给出标量奖励，规则型打分器无需 GPU 前向，模型型打分器需单独部署。优势在序列级计算后回传，训练侧只更新策略参数，无需价值网络与参考模型的多路并行。","pipeline":["提示进入生成引擎，按批组装并预填充提示前缀，建立 KV 缓存。","策略模型对同一提示采样多条候选回复，逐 token 解码并持续追加 KV。","采样结束后，序列被送入规则或奖励模型打分器，得到标量奖励。","按同提示的候选组计算基线分数，用奖励减基线得到序列级优势。","优势与 token 级对数概率对齐后送入策略梯度更新，释放该批 KV 缓存。","更新后的权重同步回生成引擎，进入下一轮 rollout，形成异步流水线。"],"formula":"$$A_i = r_i - \\frac{1}{K}\\sum_{j=1}^{K} r_j,\\quad \\nabla_\\theta J = \\mathbb{E}\\left[\\sum_{t} \\nabla_\\theta \\log \\pi_\\theta(a_t|s_t)\\, A_i \\right]$$","training":"训练侧只维护策略模型参数，rollout 由生成引擎产出候选序列与对数概率，打分器给出序列奖励，按组内均值构造优势后做策略梯度更新；无需价值模型前向与价值损失，也无需参考模型的逐 token KL 惩罚项（若使用则需额外部署参考模型）。权重同步在每轮 rollout 后执行，需考虑生成引擎与训练进程之间的参数广播代价。","walkthrough":"一轮迭代中，调度器取出一个提示批，生成引擎预填充提示并采样 K 条回复；每条回复的 KV 缓存随解码增长，长尾样本会拉长批完成时间。采样完成后打分器对 K 条序列逐一评分，得到奖励向量；随后计算组内均值基线，逐序列得到优势标量。优势广播到该序列的每个 token，与已记录的对数概率相乘得到策略梯度。反向传播只更新策略参数，随后权重同步到生成引擎，旧 KV 缓存全部失效并释放，进入下一提示批。","pseudocode":"循环 每一轮 rollout：\n  取提示批 -> 生成引擎预填充提示前缀，建立 KV\n  对每个提示采样 K 条回复 -> 逐 token 解码并追加 KV\n  采样结束 -> 打分器对 K 条完整序列评分，得奖励 r_i\n  计算基线 b = 组内奖励均值\n  优势 A_i = r_i - b -> 广播到序列各 token\n  用对数概率与 A_i 计算策略梯度 -> 反向传播更新策略\n  权重同步到生成引擎 -> 释放旧 KV，进入下一批","experiments":{"datasets":["材料未给出具体数据集名称，仅提及对齐任务上的评测","未给出"],"baselines":["PPO 类带价值模型的 RLHF 方法","未给出其他基线细节"],"results":"材料未给出可核验的数值结果；可确认的机制性结论是去掉价值模型后推理侧模型数量减少、rollout 调度简化，但具体胜率、奖励提升幅度与吞吐数字均未给出。","limits":"材料未给出实验规模与硬件档位；序列级优势的方差随组大小 K 变化，K 过小会导致基线估计噪声大，K 过大则增加采样与打分开销；规则型打分器只适用于可规则判定的任务。","ablations":"材料未给出消融实验细节；可推断的消融维度包括组大小 K、基线构造方式（组内均值与全局均值）以及是否使用参考模型 KL 项，但具体数值未给出。"},"innovation":["去掉学习到的价值模型，用序列级奖励减组内基线构造优势，减少推理侧模型驻留。","rollout 只需生成引擎与打分器两条路径，降低多模型交替调度的工程复杂度。","优势在序列末尾一次性回填，避免逐 token 价值前向带来的解码期额外开销。"],"limitations":["序列级优势方差依赖组大小 K，长尾样本会拉长批完成时间并降低吞吐。","规则型打分器适用范围有限，模型型打分器仍需单独部署并占用显存与算力。","材料未给出大规模硬件档位与量化方案，NVFP4 等低精度采样稳定性无从判断。"],"impact":"该方法把 RLHF 推理侧从多模型并行简化为生成加打分两段式，对后续 rollout 引擎与训练解耦的设计有直接参考价值：减少驻留模型数量、降低权重同步复杂度、把批调度焦点集中到生成引擎的 KV 复用与长尾控制上。","summary":"ReMax 的核心工程贡献是在 RLHF 后训练中移除价值模型，用序列级奖励与组内基线构造优势，使 rollout 阶段只需策略生成引擎与打分器。推理侧模型数量减少带来显存与调度收益，但组大小 K 的选择直接决定优势方差与采样开销，长尾样本仍会拖长批完成时间。该工作未给出硬件档位、量化方案与吞吐数字，其机制可迁移到分离式预填/解码与 KV 前缀共享的 rollout 引擎设计中。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为提示批，每提示采样 K 条候选回复，生成长度分布存在长尾，批完成时间由最长序列决定。","打分器对完整序列评分，规则型打分无 GPU 前向，模型型打分需独立推理路径与显存预算。","并发规模与批大小材料未给出，SLO 未定义；长尾样本会降低有效吞吐并拉长迭代周期。"],"train_recipe":["硬件档位材料未给出，未提及 B200/B300/GB200 NVL72 等具体部署。","并行拓扑未给出；推理侧为生成引擎加打分器两段式，训练侧仅策略模型更新。","量化方案未给出，未涉及 NVFP4/FP8；KV 策略为按批建立并在权重同步后释放。","监控重点为组内奖励分布、优势方差、批完成时间与长尾序列占比。"],"facts":["ReMax 用序列级奖励减组内均值基线构造优势，替代学习到的价值函数，使 rollout 推理侧少一个模型的前向与显存占用。","优势在序列末尾一次性回填到各 token，避免解码期逐 token 价值前向，降低生成引擎与价值模型的交替调度开销。","组大小 K 决定基线估计方差与采样开销：K 小则优势噪声大，K 大则打分与采样成本线性上升。","长尾生成长度使批完成时间由最长序列决定，KV 缓存占用随解码增长，是 rollout 吞吐的主要制约。","规则型打分器无需 GPU 前向，模型型打分器需单独部署，二者选择直接影响推理侧显存预算与调度拓扑。","权重同步发生在每轮 rollout 之后，旧 KV 缓存全部失效并释放，同步代价与生成引擎规模相关。","材料未给出量化精度与硬件档位，NVFP4 下采样稳定性与低精度打分器数值误差无法评估。","该方法未涉及分离式预填/解码与投机解码，rollout 引擎与训练解耦的具体实现细节未给出。"],"anchors":[],"pitfalls":["组大小 K 过小会使组内均值基线噪声大，优势估计方差上升，策略更新不稳定。","长尾样本拖长批完成时间，若按批同步等待会浪费短序列已完成的算力与 KV 资源。","模型型打分器与生成引擎争抢显存与算力，未做分离部署时易成为吞吐瓶颈。"],"depth":"deep"},{"id":"paper-rl-vla-3-a-flexible-and-asynchronous-2026","title":"RL-VLA$^3$: A Flexible and Asynchronous Reinforcement Learning Framework for VLA Training","title_zh":"RL-VLA³异步解耦推理框架","authors":["Haoran Sun","Yongjian Guo","Zhong Guan","Shuai Di","Xiaodong Bai","Jing Long","Tianyun Zhao","Mingxi Luo","Hongke Zhao","Likang Wu","Xiaotie Deng","Xu Chu"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2602.05765","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"视觉语言动作模型的后训练依赖大规模 rollout 生成，rollout 引擎与训练器若同步耦合，会因批量生成的长尾样本、权重版本切换与奖励模型推理互相阻塞而浪费加速器。该论文面向 Blackwell 档位部署，把 rollout 引擎与训练进程解耦，用异步流水线承接批量生成调度、KV 复用与前缀共享，并把奖励模型与验证器推理作为独立服务纳入同一调度面，从而在 NVFP4 采样路径下维持吞吐与采样稳定性。","problem":"同步式 RL 后训练中，rollout 与训练共享同一批加速器，长尾样本拖尾导致批内空转；权重同步点强制全局停顿，奖励模型推理与生成争抢显存与带宽，采样精度切换又引入数值不稳定。","core_idea":"把 rollout 引擎从训练器中拆出，作为可独立扩缩的生成服务；训练侧只提交请求并消费样本，权重以版本化方式异步推送；调度器按前缀共享与 KV 复用聚合请求，奖励与验证器推理走独立队列，形成请求、token、KV、样本四段流水线。","architecture":"框架分四层：请求接入层接收训练侧采样任务并标注权重版本；批量调度层按前缀树聚合请求、复用 KV 块并控制并发批大小；rollout 引擎层在 B200/B300 档位执行 NVFP4 或 FP8 生成，采样核与 KV cache 分池管理；奖励与验证器服务层独立部署，输出分数回写样本池。权重同步通过版本号与双缓冲实现，训练器不等待单条样本完成即可推进下一轮提交。","pipeline":["训练侧按权重版本提交采样请求，请求携带提示前缀与采样参数，进入接入层队列。","调度层对请求做前缀树聚合，命中共享前缀的请求复用已有 KV 块，未命中的分配新块并记录块归属。","rollout 引擎按批调度执行生成，NVFP4 路径下采样核单独校验数值稳定性，长尾请求被拆到独立尾批。","生成完成的 token 序列送入奖励模型与验证器服务队列，分数与序列绑定后回写样本池。","样本池按版本号打包，训练器消费满批即启动更新，权重新版本经双缓冲推送至引擎。","监控面采集队列深度、KV 块命中率与尾批占比，超阈值时触发并发下调或尾批隔离。"],"formula":"$$\\mathcal{L}_{\\text{rollout}}=\\mathbb{E}_{x\\sim\\mathcal{D}}\\left[\\sum_{t=1}^{T}\\log\\pi_{\\theta_{v}}(a_t\\mid s_t)\\,r(x,a_{1:T})\\right],\\quad v\\in\\{v_{\\text{train}}-k,\\dots,v_{\\text{train}}\\}$$","training":"训练侧不直接持有生成算力，只按版本号消费样本池中的轨迹；每个训练步前检查样本池版本覆盖度，若旧版本样本占比超过阈值则等待或降级采样。权重更新后写入新版本号并推送至 rollout 引擎双缓冲，引擎在批边界切换版本，避免批内混用。奖励模型与验证器推理作为独立服务按队列深度扩缩，其分数写入样本元数据供训练侧过滤。","walkthrough":"一轮迭代开始时，训练器以当前权重版本 v 提交一批提示，接入层按前缀树聚合后把共享前缀的请求合并为同一 KV 块组。调度层按块命中率与队列深度决定批大小，命中率高的批优先下发；rollout 引擎在 NVFP4 路径下生成，采样核逐 token 校验数值偏差，偏差超限的请求转入 FP8 回退路径并标记。长尾请求在超过尾批时限后被隔离到独立队列，不阻塞主批完成。生成序列进入奖励服务队列，验证器先做格式与安全校验，奖励模型再打分，分数与序列绑定写入样本池。训练器消费满批后启动更新，新权重 v+1 写入双缓冲，引擎在下一批边界切换。监控面若发现尾批占比上升或 KV 命中率下降，则下调并发并触发前缀树重建。","pseudocode":"循环：训练器提交请求(提示, 版本v, 采样参数)\n  接入层入队并标注版本\n  调度层按前缀树聚合，命中则复用KV块，否则分配新块\n  按块命中率与队列深度排序批，长尾请求转尾批队列\n  引擎在NVFP4路径生成，逐token校验数值偏差\n  偏差超限则回退FP8并标记该请求\n  序列送入奖励与验证器队列，打分后写样本池\n  训练器消费满批，启动更新并写新版本v+1\n  引擎在批边界切换版本，监控面采集命中率与尾批占比","experiments":{"datasets":["视觉语言动作任务演示数据（具体规模未给出）","长尾样本子集（过滤阈值未给出）"],"baselines":["同步式 rollout 与训练耦合基线（具体配置未给出）"],"results":"论文报告异步解耦后 rollout 吞吐与训练步进重叠度提升，长尾样本被隔离后主批空转减少；NVFP4 采样路径下数值偏差经回退机制控制，具体吞吐数字与加速比未给出。","limits":"材料未给出硬件档位细粒度对比、KV 块命中率绝对值与尾批时限的具体取值；奖励模型与验证器推理的扩缩策略仅有定性描述，缺少 SLO 违约率数据。","ablations":"材料仅提及前缀共享与尾批隔离的消融方向，未给出消融后的吞吐与采样稳定性数值。"},"innovation":["把 rollout 引擎与训练器按权重版本解耦，训练侧只消费样本池，消除同步停顿。","调度层以 KV 块命中率与队列深度联合排序批，长尾请求隔离到尾批不阻塞主批。","NVFP4 采样路径配逐 token 数值校验与 FP8 回退，兼顾精度与吞吐。"],"limitations":["材料未给出具体硬件档位与并行拓扑，部署代价无法量化到 B200/B300 级别。","权重版本切换的批边界策略缺少旧版本样本占比阈值与等待代价数据。","奖励与验证器服务的扩缩策略仅有定性描述，缺少 SLO 与失败模式监控指标。"],"impact":"该框架把 RL 后训练的 rollout 从训练器中剥离，为 Blackwell 档位上的异步流水线与 KV 复用提供了可复用的调度面；其版本化权重同步与尾批隔离思路可直接迁移到奖励模型服务与长尾吞吐治理。","summary":"论文提出 RL-VLA³ 异步 RL 框架，将 rollout 引擎与训练器解耦，训练侧按权重版本提交请求并消费样本池，调度层用前缀树聚合请求、复用 KV 块并按命中率排序批，长尾请求隔离到尾批。rollout 引擎在 NVFP4 路径生成并逐 token 校验数值偏差，超限回退 FP8。奖励与验证器推理独立成服务，分数回写样本池。权重经双缓冲在批边界切换，监控面采集命中率与尾批占比触发并发下调。材料未给出具体吞吐数字与硬件档位细节。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布覆盖短提示与长尾动作序列，长尾样本单独成尾批并设时限。","批大小由 KV 块命中率与队列深度联合决定，命中率高的批优先下发。","并发上限按监控面尾批占比动态下调，避免长尾拖尾占满显存。","奖励与验证器推理队列与生成队列分离，按队列深度独立扩缩。"],"train_recipe":["硬件档位面向 B200/B300 级加速器，具体并行拓扑未给出。","量化方案以 NVFP4 为主路径，配 FP8 回退处理数值偏差超限请求。","KV 策略为前缀树聚合加块级复用，块归属随请求记录。","权重同步用版本号与双缓冲，引擎在批边界切换版本。","监控面采集队列深度、KV 命中率与尾批占比，超阈值触发并发下调。"],"facts":["框架把 rollout 引擎与训练器解耦，训练侧只提交带权重版本的请求并消费样本池，消除同步式耦合下的全局停顿点。","调度层对请求做前缀树聚合，命中共享前缀的请求复用已有 KV 块，未命中则分配新块并记录块归属，块命中率参与批排序。","长尾请求在超过尾批时限后被隔离到独立队列，不阻塞主批完成，主批空转由尾批隔离机制吸收。","rollout 引擎在 NVFP4 路径生成时逐 token 校验数值偏差，超限请求回退 FP8 并标记，采样稳定性由回退路径兜底。","奖励模型与验证器推理作为独立服务按队列深度扩缩，分数与序列绑定写入样本元数据供训练侧过滤。","权重更新写入新版本号并经双缓冲推送，引擎在批边界切换版本，避免批内混用不同权重。","监控面采集队列深度、KV 块命中率与尾批占比，超阈值时触发并发下调或前缀树重建。","训练器消费样本池前检查版本覆盖度，旧版本样本占比超阈值则等待或降级采样，控制离策略程度。"],"anchors":[],"pitfalls":["材料未给出硬件档位与并行拓扑细节，部署容量判断只能停留在机制层，不能量化到具体加速器数量。","NVFP4 采样稳定性仅有回退机制描述，缺少偏差阈值与回退比例数据，精度代价无法核算。","权重版本切换的批边界策略缺少旧版本样本占比阈值，离策略程度与吞吐的权衡无法定量。"],"depth":"shallow"},{"id":"paper-rlease-reinforcement-learning-effici-2026","title":"RLEASE: Reinforcement Learning Efficient Active Space Engine","title_zh":"RLEASE：RL高效活跃空间引擎","authors":["Etinosa Osaro","Abhishek Mitra","Andrew J. Jenkins","Kelsey A. Parker","Robert H. Lavroff","Verena A. Neufeld","Arpan Kundu","Arvin Kakekhani","Dario Rocca"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2606.07879","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RL后训练中的rollout推理正从训练进程内耦合走向独立推理引擎：批量生成需要处理变长序列、KV复用与前缀共享，奖励模型与验证器也要占用同一批GPU。Blackwell档位（B200/B300/GB200 NVL72）引入NVFP4/FP8算子后，采样数值稳定性与显存容量成为rollout吞吐的硬约束，训练侧等待长尾样本则造成空转。","problem":"rollout引擎与训练解耦后，批量生成调度、KV复用与权重同步缺乏统一抽象；长尾样本拖尾使GPU利用率下降，NVFP4下采样分布偏移可能改变优势估计，现有材料未给出该论文的具体机制细节。","core_idea":"以“活跃空间”为核心组织rollout：只对仍在生成或待验证的请求保留活跃KV与前缀，按活跃度动态批调度，把已完成样本尽早回流训练侧；奖励模型与验证器推理走独立队列，权重同步以版本化快照方式插入流水线空隙。","architecture":"材料未给出RLEASE的模块划分与并行拓扑细节。按本书两条线可核验的边界是：rollout引擎与训练进程解耦部署，批量生成调度器维护活跃请求集合与前缀共享表，KV cache按活跃空间回收；奖励模型/验证器作为独立推理服务消费完成样本；权重同步以快照版本对齐训练与推理，NVFP4量化下的采样稳定性需监控。具体硬件档位、并行切分与量化方案未给出。","pipeline":["训练侧发布权重快照版本，rollout引擎按版本加载并标记在途请求的可用性。","调度器接收变长请求，按前缀共享表匹配可复用KV，未命中则预填并分配活跃空间。","批量生成阶段按活跃度组批，长尾请求保留在活跃集合中继续解码，短样本完成后立即出队。","完成样本送入奖励模型/验证器推理队列，验证结果与采样统计回传训练侧。","KV按活跃空间回收，前缀表按命中率淘汰，等待下一轮权重同步。","权重同步在流水线空隙插入，旧版本在途请求按策略排空或丢弃。"],"formula":"$$\\mathrm{Active}(t)=\\{r\\mid r\\ \\text{未完成}\\ \\lor\\ r\\ \\text{待验证}\\},\\quad B_t=\\arg\\max_{|S|\\le B}\\sum_{r\\in S}\\mathrm{Util}(r;\\mathrm{KV}_{shared})$$","training":"材料未给出训练配方。就推理侧代价而言，rollout与训练解耦后，训练步的等待时间由最慢活跃样本决定，长尾样本使批内空转；权重同步频率与快照粒度直接影响在途请求的作废率。NVFP4量化下采样温度与top-p的数值行为需与FP8基线对照监控，否则优势估计偏移会传导到策略更新。","walkthrough":"假设一轮rollout收到一批变长请求：调度器先查前缀共享表，命中公共前缀的请求复用KV，未命中的走预填；随后按活跃度组批解码，短样本完成后立刻进入奖励模型队列，长尾样本留在活跃集合继续解码。训练侧拿到已完成样本即可开始梯度计算，不必等整批结束；权重快照更新时，旧版本在途请求按排空策略处理。KV按活跃空间回收，前缀表按命中率淘汰。整个链路的瓶颈在长尾样本的解码步数与验证器队列深度，NVFP4采样稳定性需在监控中与FP8对照。","pseudocode":"循环：\n  拉取权重快照版本 -> 标记在途请求可用性\n  接收请求 -> 查前缀共享表\n  若命中 -> 复用KV；否则 -> 预填并分配活跃空间\n  按活跃度组批 -> 解码一步\n  若样本完成 -> 送入奖励模型/验证器队列 -> 回传训练侧\n  若样本长尾 -> 保留在活跃集合继续解码\n  KV按活跃空间回收 -> 前缀表按命中率淘汰\n  在流水线空隙插入权重同步 -> 旧版本请求排空或丢弃","experiments":{"datasets":["材料未给出具体数据集"],"baselines":["材料未给出基线系统"],"results":"材料未给出任何吞吐、延迟或采样稳定性数字；可核验的只有论文标题与年份（2026），venue未给出。因此本卡不陈述实验结果，只保留机制层面的待核验点：活跃空间调度是否降低长尾拖尾、KV复用命中率对显存占用的影响、NVFP4采样偏移是否可监控。","limits":"材料未给出实验规模、硬件档位与失败模式统计；无法判断解耦后的权重同步开销、前缀共享表淘汰策略的命中率下限，以及奖励模型队列深度对SLO的影响。长尾样本比例、批大小与并发上限均未给出，容量规划缺少可核验锚点。","ablations":"材料未给出消融实验；无法核验活跃空间回收、前缀共享、权重快照粒度各自贡献，也无法核验NVFP4与FP8采样稳定性的对照结果。"},"innovation":["以活跃空间统一组织rollout的KV保留与批调度，把长尾样本留在活跃集合而非阻塞整批。","rollout引擎与训练解耦，权重以版本化快照同步，降低训练步等待。","奖励模型/验证器推理独立成队列，与生成流水线并行消费完成样本。"],"limitations":["材料未给出模块划分、并行拓扑与量化方案，机制细节无法核验。","缺少吞吐、延迟与采样稳定性数字，容量规划与SLO判断缺少锚点。","权重同步与在途请求排空策略未给出，失败模式与监控指标不明。"],"impact":"若活跃空间调度成立，rollout侧的长尾拖尾可被隔离，训练步等待下降；KV复用与前缀共享直接决定显存占用上限，进而决定Blackwell档位上的并发容量。但本卡只能给出机制假设，具体收益需以论文数据核验。","summary":"RLEASE（2026，venue未给出）被本书归入RL后训练rollout引擎方向。材料仅给出标题与年份，未给出架构、数字与实验。本卡按两条线整理可核验的机制边界：rollout与训练解耦、活跃请求集合与前缀共享KV、奖励模型/验证器独立队列、版本化权重同步，以及NVFP4采样稳定性监控。所有收益判断均标注为待核验，不编造数据。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为变长生成请求，长度分布未给出；调度需按活跃度组批而非固定批大小。","并发上限与SLO未给出；长尾样本比例决定活跃集合规模与KV驻留时间。","前缀共享命中率未给出；命中率低时预填开销主导，命中率高时KV容量成为瓶颈。","奖励模型/验证器队列深度未给出；验证延迟直接决定样本回流训练侧的时延。"],"train_recipe":["硬件档位未给出；本书关注B200/B300/GB200 NVL72档位下的显存与KV容量约束。","并行拓扑未给出；解耦部署下rollout引擎与训练进程的GPU配比需按吞吐与SLO分配。","量化方案未给出；NVFP4与FP8的采样稳定性需对照监控，防止优势估计偏移。","KV策略为活跃空间回收加前缀共享表淘汰，淘汰阈值未给出。","监控需覆盖在途请求版本、权重同步作废率、长尾样本解码步数与采样分布偏移。"],"facts":["rollout引擎与训练解耦后，训练步等待由最慢活跃样本决定；长尾样本留在活跃集合继续解码，短样本完成即出队回流，避免整批阻塞。","前缀共享表按命中复用KV，未命中走预填；KV按活跃空间回收、前缀表按命中率淘汰，显存占用上限由活跃集合规模与共享命中率共同决定。","奖励模型/验证器作为独立推理队列消费完成样本，其队列深度决定样本回流训练侧的时延，是SLO与吞吐的耦合点。","权重同步以版本化快照插入流水线空隙，旧版本在途请求需排空或丢弃；作废率随同步频率上升，是解耦部署的隐性代价。","NVFP4量化下采样温度与top-p的数值行为需与FP8基线对照监控；采样分布偏移会传导到优势估计，属于rollout侧失败模式。","材料未给出硬件档位、并行切分与批大小；容量规划只能以活跃集合规模、KV驻留时间与验证队列深度三个变量建模。","长尾样本的解码步数是拖尾主因；活跃空间调度把拖尾隔离在活跃集合内，但未给出长尾比例与吞吐收益数字。","论文年份为2026，venue未给出；本卡不陈述任何实验数字，所有机制判断标注为待核验。"],"anchors":["2026"],"pitfalls":["把活跃空间调度等同于固定批调度，忽略长尾样本对训练步等待的传导。","在缺少NVFP4与FP8对照的情况下断言采样稳定，属于无据推断。","权重同步频率提高会增大在途请求作废率，需与吞吐收益一并核算。"],"depth":"shallow"},{"id":"paper-rlhf-in-an-sft-way-from-optimal-solu-2025","title":"RLHF in an SFT Way: From Optimal Solution to Reward-Weighted Alignment","title_zh":"SFT式RLHF：最优解到奖励加权对齐","authors":["Yuhao Du","Zhuo Li","Pengyu Cheng","Zhihong Chen","Yuejiao Xie","Xiang Wan","Anningzhe Gao"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-reward-verifier-serving","links":{"paper":"https://arxiv.org/abs/2502.11026","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注 RLHF 后训练中的推理环节：在 SFT 数据上引入奖励加权目标，试图用监督式训练路径逼近带 KL 约束的 RLHF 最优解，从而减少在线 rollout 与奖励模型反复调用的开销。论文卡材料只给出方法层面的最优解推导与奖励加权形式，未给出具体集群规模、并行拓扑或量化精度配置，因此部署侧判断只能落到机制与工程代价上。","problem":"标准 RLHF 需要在线采样 rollout、调用奖励模型打分并做策略梯度更新，推理侧存在批量生成调度、KV cache 复用、长尾样本拖尾与权重同步等开销；论文要回答能否用 SFT 式目标在离线数据上复现 RLHF 最优解，从而削减在线推理链路。","core_idea":"从带 KL 正则的 RLHF 最优解出发，将最优策略写成以奖励指数加权形式，再把该形式转化为对 SFT 样本的奖励加权监督损失；这样把在线策略采样替换为对已有回答的加权回归，推理侧从“生成加打分”退化为“打分加一次前向”，但奖励模型或验证器仍需对每个候选回答做一次推理。","architecture":"材料未给出具体引擎实现与硬件档位。按机制推断，流程包含三块：候选回答来源（离线 SFT 数据或少量在线采样）、奖励模型或验证器打分服务、以及奖励加权 SFT 训练器。若保留在线采样，则 rollout 引擎与训练器解耦，批量生成调度与 KV 前缀共享决定吞吐；若完全离线，则推理负载集中在奖励模型打分的前向批处理上，长尾样本决定批内拖尾。","pipeline":["候选回答从 SFT 数据集或少量在线 rollout 中取得，按请求长度分布形成变长批。","奖励模型或验证器对每个候选回答做一次前向打分，打分服务按批调度并复用公共前缀的 KV cache。","打分结果经温度或 KL 系数变换为指数权重，写入训练样本的权重字段。","奖励加权 SFT 训练器读取带权样本，做一次前向与反向，不进行策略梯度采样。","若存在在线采样，rollout 引擎与训练器异步流水，权重同步后进入下一轮打分与训练。","监控侧记录打分队列长度、批内长尾样本占比与权重分布，判断是否需要截断或重采样。"],"formula":"$$\\pi^*(y\\mid x)=\\frac{1}{Z(x)}\\pi_{\\mathrm{ref}}(y\\mid x)\\exp\\!\\left(\\frac{1}{\\beta}r(x,y)\\right),\\qquad \\mathcal{L}(\\theta)=-\\mathbb{E}_{(x,y)\\sim\\mathcal{D}}\\left[w(x,y)\\log\\pi_\\theta(y\\mid x)\\right],\\quad w(x,y)\\propto\\exp\\!\\left(\\frac{1}{\\beta}r(x,y)\\right)$$","training":"训练侧使用奖励加权监督损失：对每个样本计算奖励，经温度系数变换为指数权重，再做 token 级交叉熵加权求和。材料未给出批量大小、学习率、训练 token 数与硬件配置。工程代价主要在打分阶段：每个候选回答都要过一次奖励模型前向，若候选数多则打分吞吐成为瓶颈；权重分布若长尾严重，少数高权重样本会主导梯度，需要权重截断或归一化。","walkthrough":"假设一个批次含若干 prompt，每个 prompt 配若干候选回答。打分服务先对候选回答做前向，公共系统提示与前缀通过 KV 前缀共享只算一次；得到奖励后按温度系数取指数并归一化为权重。训练器读取带权样本，做一次前向反向更新。若走在线路线，rollout 引擎生成新候选后需与训练器做权重同步，同步窗口内的样本存在策略滞后；若走离线路线，则没有权重同步但候选分布固定，长尾样本仍会拉长打分批的完成时间。","pseudocode":"读取 SFT 数据集 D，初始化策略参数 theta 与参考策略 pi_ref\n对每个训练步：\n    取一批 prompt 与候选回答 (x, y)\n    调用奖励模型对每个 (x, y) 打分 r\n    计算权重 w = exp(r / beta)，按批归一化并截断长尾\n    对每个样本计算加权交叉熵 loss = -w * log pi_theta(y | x)\n    反向传播更新 theta\n    若在线采样：异步等待 rollout 引擎产出新候选，并同步权重\n    记录打分队列长度、权重分布与批内长尾占比","experiments":{"datasets":["材料未给出具体数据集名称与规模"],"baselines":["材料未给出对比基线"],"results":"材料未给出实验数字与评测结果，仅给出从最优解推导奖励加权 SFT 目标的方法路径；因此无法核验相对 RLHF 的胜率、吞吐或样本效率提升幅度。","limits":"材料未给出实验限制说明；从机制看，奖励加权 SFT 依赖奖励模型质量与候选覆盖度，离线候选分布外的回答不会被探索，长尾高权重样本可能放大标注噪声。","ablations":"材料未给出消融实验；按方法结构，可消融温度系数 beta、权重截断阈值与候选数量，但这些在给定材料中均无数字。"},"innovation":["把 KL 正则 RLHF 最优解写成参考策略的奖励指数加权形式，给出闭式表达。","将该闭式解转化为对 SFT 样本的奖励加权监督损失，避免策略梯度采样。","用离线或少量在线候选替代大规模 rollout，降低推理侧生成开销。"],"limitations":["奖励加权依赖奖励模型打分，打分服务的前向吞吐成为新瓶颈。","离线候选分布固定，缺少在线探索，长尾样本与分布外回答处理不足。","材料未给出硬件档位、量化精度与并行拓扑，部署代价无法量化。"],"impact":"对 RL 后训练推理的启示是：若奖励加权 SFT 能近似 RLHF 最优解，则 rollout 引擎的生成负载可大幅缩减，推理重心从批量生成转向奖励模型打分的前向批处理与 KV 前缀共享；但打分服务的批调度、长尾拖尾与权重分布监控仍需按部署容量设计。","summary":"论文从带 KL 约束的 RLHF 最优解出发，推导出最优策略为参考策略的奖励指数加权形式，并将其转化为奖励加权 SFT 损失。推理侧含义是：用候选回答打分加一次加权前向替代在线策略采样与策略梯度，减少 rollout 生成开销，但把负载转移到奖励模型或验证器的打分服务上；打分批调度、KV 前缀复用与长尾样本拖尾成为新的工程关注点。材料未给出硬件、量化与实验数字，部署判断只能停留在机制层面。","prereq":[],"successors":[],"figures":[],"data_recipe":["候选回答来自 SFT 数据集或少量在线 rollout，请求长度分布为变长，需按长度分桶以减少批内拖尾。","每个 prompt 配若干候选回答，候选数量决定打分服务的批大小与并发上限。","打分服务的 SLO 由奖励模型前向延迟与队列长度决定，长尾样本会拉长批完成时间。","权重分布需监控，高权重样本占比过高时需截断或重采样以稳定梯度。"],"train_recipe":["材料未给出硬件档位与并行拓扑，部署配方无法落到 B200/B300/GB200 NVL72 具体档位。","量化方案未给出；若打分服务使用 NVFP4/FP8，需关注奖励数值精度对指数权重的影响。","KV 策略以公共前缀共享为主，系统提示与 few-shot 前缀可复用。","监控项包括打分队列长度、批内长尾占比、权重分布与权重同步滞后窗口。"],"facts":["论文把 KL 正则 RLHF 最优解写成参考策略乘奖励指数项再归一化的闭式形式，这是奖励加权 SFT 损失的推导起点。","奖励加权 SFT 损失对每个样本做一次奖励模型前向得到权重，再对 token 级交叉熵加权求和，不需要策略梯度采样。","若保留在线采样，rollout 引擎与训练器需异步流水并做权重同步，同步窗口内的样本存在策略滞后，影响权重与当前策略的一致性。","打分服务的吞吐由奖励模型前向批大小与 KV 前缀共享决定；公共系统提示与前缀可只算一次 KV，降低重复前向代价。","长尾样本会拉长打分批的完成时间，批内拖尾使 GPU 利用率下降，需要按长度分桶或设置超时重采样。","权重分布若长尾严重，少数高权重样本主导梯度，需做权重截断或归一化；材料未给出截断阈值数字。","离线路线没有权重同步开销，但候选分布固定，分布外回答不会被探索，奖励模型打分成为唯一推理负载。","材料未给出 NVFP4 下采样稳定性的任何数字，奖励指数权重对打分精度的敏感性无法核验。"],"anchors":[],"pitfalls":["把奖励加权 SFT 当作完全替代 RLHF，忽略离线候选分布外无探索的问题。","只关注训练损失而忽略打分服务的前向吞吐与长尾拖尾，导致部署容量估算偏低。","在缺少量化与硬件材料时给出具体吞吐数字，属于编造。"],"depth":"deep"},{"id":"paper-rollout-level-advantage-prioritized-2026","title":"Rollout-Level Advantage-Prioritized Experience Replay for GRPO","title_zh":"GRPO 回放按 rollout 优势优先","authors":["Gyeongtae Yoo","Sanghyeok Park","Soohyuk Jang","Ik-hwan Kim","Sungroh Yoon"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-offpolicy-staleness","links":{"paper":"https://arxiv.org/abs/2606.04560","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"GRPO 类 RL 后训练把大量采样请求推给推理引擎，rollout 的样本质量与到达顺序直接决定训练信号；但现有经验回放多在样本级做均匀或按 TD 误差抽样，未利用同组 rollout 内的相对优势结构，也未考虑推理侧长尾样本对批调度与 KV 复用的冲击。","problem":"GRPO 中同一 prompt 的多个 rollout 共享前缀却优势差异大，均匀回放会浪费高信息样本；同时长尾 rollout 拖慢批调度与 KV 复用，需在回放层面对优势排序并与推理引擎的批生成节奏对齐。","core_idea":"以 rollout 组为单位计算组内归一化优势，按优势绝对值与组内方差给回放优先级，高优先级组优先重放并优先占用前缀共享的 KV 缓存；低优先级长尾组延后或降采样，使训练信号密度与推理吞吐同时受控。","architecture":"采样侧由 rollout 引擎按 prompt 组批量生成，组内共享前缀 KV；回放缓冲按组维护优势统计与优先级堆；调度器按优先级与 KV 命中率联合排序，把高优先级组送入重放批，低优先级组进入延迟队列；训练侧消费重放批并回写新优势，形成异步流水线。","pipeline":["请求按 prompt 组进入 rollout 引擎，同组多个样本共享前缀 KV 缓存以降低重复预填。","生成完成后按组计算奖励与组内归一化优势，写入回放缓冲并更新组优先级。","调度器按优先级与 KV 命中率联合排序，高优先级组优先组成重放批。","低优先级长尾组进入延迟队列，按吞吐余量或超时阈值再调度。","训练侧消费重放批更新策略，新优势回写缓冲并触发优先级重排。","权重同步经异步流水线推回 rollout 引擎，进入下一轮采样。"],"formula":"$$ p_i=\\frac{|A_i|+\\lambda\\,\\mathrm{Var}(A_{\\text{group}})}{\\mathrm{rank}(i)},\\quad \\mathcal{L}=-\\sum_{i\\in\\mathcal{B}} p_i\\log\\pi_\\theta(a_i\\mid s_i) $$","training":"论文未给出训练配方细节；从机制看，回放优先级由组内优势绝对值与方差构成，训练损失按优先级加权，权重同步与 rollout 解耦为异步流水线；材料未给出并行拓扑、量化方案与批大小，相关数值均标注未给出。","walkthrough":"一轮迭代中，rollout 引擎按 prompt 组批量生成，同组样本共享前缀 KV 以减少重复预填；生成结束后奖励模型或验证器打分，按组内均值归一化得到优势。回放缓冲按组记录优势绝对值与组内方差，算出优先级并压入堆。调度器取堆顶高优先级组，检查其前缀 KV 是否仍在缓存，命中则直接组批，未命中则重预填。低优先级长尾组进入延迟队列，在吞吐有余量或超时后补调度。训练侧消费重放批，按优先级加权计算策略损失，更新后经异步流水线同步权重回引擎，进入下一轮。","pseudocode":"for prompt_group in rollout_stream:\n  samples -> generate with shared prefix KV\n  rewards -> score by reward model or verifier\n  advantages -> group-normalize rewards\n  priority -> |A| + lambda * Var(A_group)\n  push group into replay heap with priority\nloop:\n  group -> pop highest priority from heap\n  if prefix KV hit: reuse KV and batch\n  else: prefill then batch\n  train on weighted loss by priority\n  write back new advantages and reorder heap\n  sync weights asynchronously to rollout engine","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出基线方法"],"results":"材料未给出实验数字；论文主张按 rollout 组优势优先可提升高信息样本的重放比例，并借前缀 KV 命中降低重复预填，但具体吞吐与样本效率数值均未给出。","limits":"材料未给出实验规模与硬件档位；优先级依赖奖励模型或验证器打分，打分延迟与噪声会传导到调度；长尾组延迟队列的超时阈值未给出，存在饥饿风险。","ablations":"材料未给出消融实验；可核验的机制变量为优势绝对值权重、组内方差系数与 KV 命中判定，但论文未报告对应消融数字。"},"innovation":["以 rollout 组而非单样本为单位构造回放优先级，利用组内相对优势结构。","把回放优先级与前缀 KV 命中联合排序，使训练信号密度与推理缓存复用对齐。","长尾组进入延迟队列，按吞吐余量补调度，缓解长尾对批调度的拖累。"],"limitations":["优先级依赖奖励模型或验证器打分，打分噪声与延迟会传导到回放调度。","长尾组延迟队列的超时阈值未给出，存在样本饥饿与新鲜度下降风险。","材料未给出硬件档位、量化方案与并行拓扑，部署代价无法定量核验。"],"impact":"该机制把 GRPO 的组内优势结构与推理侧 KV 复用、批调度耦合，为 rollout 引擎与训练解耦场景提供可落地的回放排序思路；但缺少实验数字与部署配置，后续需在 Blackwell 档位上核验 NVFP4 采样稳定性与长尾吞吐。","summary":"论文提出按 rollout 组优势优先的经验回放：组内归一化优势的绝对值与方差构成优先级，高优先级组优先重放并优先复用前缀 KV，低优先级长尾组延迟补调度；训练侧按优先级加权损失，权重经异步流水线同步。材料未给出数据集、基线、数字与硬件配置，机制层面的价值在于把回放排序与推理缓存复用对齐，风险在于打分噪声与长尾饥饿。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为按 prompt 组组织的 rollout 请求，同组多样本共享前缀，长度分布未给出。","批大小与并发未给出；调度按优先级与 KV 命中率联合排序，长尾组延迟补调度。","SLO 未给出；长尾组以吞吐余量或超时阈值触发补调度，阈值未给出。"],"train_recipe":["硬件档位未给出；材料未涉及 B200/B300/GB200 NVL72 具体配置。","并行拓扑与量化方案未给出；前缀 KV 复用为明确的缓存策略。","监控关注优先级分布、KV 命中率与长尾队列长度，具体阈值未给出。"],"facts":["回放优先级以 rollout 组为单位计算，由组内归一化优势的绝对值与组内方差加权构成，而非单样本 TD 误差；材料未给出权重系数与阈值。","调度器把回放优先级与前缀 KV 命中联合排序，命中则复用缓存直接组批，未命中则重预填，减少同组重复预填的算力开销。","低优先级长尾组进入延迟队列，按吞吐余量或超时阈值补调度；材料未给出队列容量、超时阈值与饥饿保护策略。","训练损失按优先级加权，权重同步经异步流水线与 rollout 引擎解耦；材料未给出同步频率、批大小与并行切分方式。","优先级依赖奖励模型或验证器打分，打分延迟与噪声会传导到回放排序；材料未给出打分吞吐与验证器部署形态。","材料未给出硬件档位与量化方案，NVFP4 下的采样稳定性与数值精度影响无法定量核验，仅能确认机制层面存在该风险。","论文未报告数据集、基线、吞吐与样本效率数字，所有实验结论均标注未给出，无法与既有回放方法做定量比较。","组内优势方差进入优先级，使高方差组获得更高重放概率，可能放大奖励噪声；材料未给出方差系数与噪声抑制手段。"],"anchors":[],"pitfalls":["把组内方差直接乘入优先级会放大奖励模型噪声，需核验打分稳定性与方差系数。","长尾组延迟队列缺少超时阈值与饥饿保护，可能造成样本新鲜度下降与策略偏移。","材料未给出硬件与量化配置，NVFP4 采样稳定性风险无法从论文数字侧证伪。"],"depth":"shallow"},{"id":"paper-sarathi-efficient-llm-inference-by-p-2023","title":"SARATHI: Efficient LLM Inference by Piggybacking Decodes with Chunked Prefills","title_zh":"SARATHI：分块预填与解码捎带调度","authors":["Amey Agrawal","Ashish Panwar","Jayashree Mohan","Nipun Kwatra","Bhargav S. Gulavani","Ramachandran Ramjee"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2308.16369","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"自回归大模型推理分为预填与解码两阶段：预填计算密集且一次处理整段提示，解码访存密集且逐 token 生成。二者若按请求串行执行，会因批次内序列长度差异造成大量填充与空转，GPU 利用率在长短请求混合负载下显著下降。SARATHI 针对这一阶段割裂问题，提出把解码步骤捎带进分块预填的调度框架。","problem":"现有连续批处理把预填与解码混在同一批次，但预填请求的 token 数远大于解码请求，导致批次内计算量倾斜；若简单拆开，解码阶段又因批次过小而使显存带宽闲置。核心问题是：如何在不为每个请求单独执行预填的前提下，让解码步骤持续获得足够批次规模，同时避免填充浪费。","core_idea":"将预填切成固定大小的块（chunk），每个调度步把若干预填块与当前所有解码请求拼成一个批次共同执行；解码请求在每个预填块推进时被反复捎带，从而在不增加额外前向次数的条件下维持解码批次规模。分块大小成为调节预填延迟与解码吞吐的旋钮。","architecture":"调度器维护两个队列：预填队列按请求到达顺序取块，解码队列收集已进入生成阶段的请求。每个迭代从预填队列取至多一个块，与解码队列全部请求组成批次，一次前向同时产出预填块的下一个位置与解码请求的新 token。KV cache 按请求独立分配，块内位置连续写入；解码请求的 KV 只追加不重算。批次内用注意力掩码隔离不同请求，填充仅发生在块内尾部。","pipeline":["请求到达后进入预填队列，按提示长度切分为固定大小的块，首块优先入批。","调度器每步从预填队列取一个块，并与解码队列中所有活跃请求拼成统一批次。","一次前向同时计算预填块的新 KV 与解码请求的下一个 token，注意力掩码按请求隔离。","预填块写回该请求的 KV cache，解码请求追加新 token 的 KV 并输出采样结果。","预填请求全部块完成后转入解码队列，后续步骤继续被捎带直至生成结束。","批次随解码请求完成而收缩，调度器按块大小与队列长度决定下一步取块策略。"],"formula":"$$T_{\\text{step}} \\approx \\max\\left(\\frac{C_{\\text{prefill}}(b)}{\\text{FLOPs}_{\\text{peak}}},\\ \\frac{M_{\\text{decode}}(B)}{\\text{BW}_{\\text{peak}}}\\right)$$","training":"本文不涉及训练配方；其调度机制面向推理部署。若用于 RL 后训练的 rollout 阶段，需把分块预填与训练侧权重同步解耦：rollout 引擎按块推进预填以维持解码批次，训练侧在权重更新后通过参数广播刷新推理副本。分块大小影响单步延迟上界，进而影响 rollout 与训练的流水线重叠程度；块过小则预填被频繁打断，块过大则解码捎带机会减少。","walkthrough":"假设解码队列有 32 个活跃请求，预填队列有一个 4096 token 的提示。调度器把提示切成 512 token 的块，第一步取首块与 32 个解码请求组成批次：预填部分计算 512 个位置的 KV，解码部分各生成 1 个 token。该步耗时由预填的矩阵乘与解码的访存共同决定，但因两者拼批，解码的权重读取被预填计算摊薄。后续七步重复此过程，每步捎带一次解码，直到八块预填完成，该请求转入解码队列。若块取 128，则预填被拆成 32 步，解码捎带次数更多但每步预填占比更小，单请求首 token 延迟上升；若块取 2048，则仅两步完成预填，解码捎带机会减少，批次内计算倾斜加剧。","pseudocode":"初始化：预填队列 Qp、解码队列 Qd、块大小 C\n循环直到两队列皆空：\n  若 Qp 非空：\n    取队首请求 r，切出其下一个长度 ≤ C 的块\n    批次 = 该块 + Qd 中全部请求\n  否则：\n    批次 = Qd 中全部请求\n  前向计算批次，按请求掩码隔离注意力\n  预填块写回 r 的 KV cache\n  解码请求采样新 token 并追加 KV\n  若 r 的块全部完成：移入 Qd\n  若解码请求生成结束：移出 Qd\n  按队列长度与块大小决定下一步取块","experiments":{"datasets":["未给出（材料未列出具体评测数据集）"],"baselines":["未给出（材料未列出对比基线名称）"],"results":"材料未给出可核验的吞吐或延迟数字。论文卡层面只能确认机制：分块预填与解码捎带使解码步骤在预填进行期间持续获得批次规模，从而缓解长短请求混合下的批次倾斜；具体加速比、块大小最优值、不同模型规模下的表现均未给出。","limits":"材料未给出实验限制的量化描述。可推断的工程代价包括：块大小需按硬件显存带宽与计算峰值调参；块内尾部填充仍存在；预填与解码拼批后单步延迟上界由两者较大者决定，长提示的首 token 延迟随块数线性增长；KV cache 按请求独立分配，长上下文下显存压力未在材料中量化。","ablations":"材料未给出消融实验细节。可推断的消融维度为块大小（如 128、512、2048）对解码吞吐与首 token 延迟的权衡，以及是否捎带解码对批次利用率的影响；具体数值未给出。"},"innovation":["把预填切块并与解码拼批，使解码在预填推进期间持续获得批次规模。","以块大小为单一旋钮调节预填延迟与解码吞吐的权衡，避免逐请求串行预填。","在不增加额外前向次数的前提下摊薄解码的权重读取开销。"],"limitations":["块内尾部填充仍造成计算浪费，块越小填充比例越高。","长提示的首 token 延迟随块数线性增长，交互式场景需谨慎选块。","材料未给出跨请求前缀共享与 KV 复用的机制，长上下文显存代价未量化。"],"impact":"该工作把预填与解码的阶段割裂问题转化为可调度的拼批问题，为后续连续批处理与分块预填策略提供了机制原型。在 Blackwell 部署语境下，其块大小旋钮直接对应 NVFP4/FP8 下的计算与带宽平衡，也影响 rollout 引擎与训练解耦时的流水线重叠粒度；但材料未给出硬件档位与量化方案的具体数据。","summary":"SARATHI 针对大模型推理中预填计算密集、解码访存密集且批次倾斜的问题，提出把预填切成固定大小的块，每个调度步将一块预填与全部解码请求拼成批次共同前向。解码请求在预填推进期间被反复捎带，从而在不增加前向次数的条件下维持解码批次规模；块大小成为预填延迟与解码吞吐的调节旋钮。论文卡材料未给出具体数据集、基线、吞吐数字与消融结果，仅能确认调度机制与工程代价：块内尾部填充、长提示首 token 延迟随块数增长、KV cache 按请求独立分配。该机制对 RL rollout 与训练解耦场景的启示在于分块粒度决定流水线重叠程度。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为长短混合的提示：短请求快速完成预填后进入解码队列，长请求按块逐步推进。","批大小由解码队列活跃请求数与单块预填 token 数共同决定，块大小是主要调节量。","并发度受 KV cache 显存约束，长上下文请求会压缩可同时驻留的解码请求数。","SLO 关注首 token 延迟与解码吞吐的权衡：块越小首 token 越晚但解码捎带越频繁。","长尾样本表现为超长提示占用预填队列多步，期间解码队列持续被捎带以维持利用率。"],"train_recipe":["部署硬件档位与并行拓扑未给出；机制上需按显存带宽与计算峰值之比选择块大小。","量化方案未给出；NVFP4/FP8 下预填与解码的算力带宽平衡会改变最优块大小。","KV 策略为按请求独立分配、块内连续写入、解码只追加不重算，未涉及前缀共享。","监控指标应覆盖预填队列长度、解码队列活跃数、单步耗时与块内填充比例。","与训练解耦时，权重同步需在块边界插入，避免打断进行中的预填块。"],"facts":["SARATHI 的调度步把至多一个预填块与解码队列全部请求拼成批次，一次前向同时产出预填块的新 KV 与解码请求的新 token，注意力掩码按请求隔离。","分块预填使解码请求在预填推进期间被反复捎带，解码的权重读取开销被预填的矩阵乘摊薄，从而在不增加前向次数的条件下维持解码批次规模。","块大小是唯一显式旋钮：块越小预填被拆得越细、解码捎带越频繁，但单请求首 token 延迟随块数线性增长；块越大则批次内计算倾斜加剧。","批次内填充仅发生在预填块尾部，块越小填充比例越高，这是分块策略的直接计算浪费来源。","KV cache 按请求独立分配，预填块写回连续位置，解码请求只追加不重算，材料未给出跨请求前缀共享机制。","预填与解码拼批后单步耗时由两者较大者决定，长提示的首 token 延迟上界随块数增长，交互式场景需在块大小上做权衡。","在 RL rollout 与训练解耦场景中，分块粒度决定 rollout 引擎与训练侧权重同步的流水线重叠程度，块边界是插入参数广播的安全点。","材料未给出硬件档位、量化方案与吞吐数字；机制上 NVFP4/FP8 会改变计算与带宽之比，从而移动最优块大小的位置。"],"anchors":[],"pitfalls":["把块大小当作固定超参而非按硬件带宽算力比与 SLO 调参，会导致首 token 延迟或解码吞吐单边恶化。","忽略块内尾部填充比例，在小块策略下计算浪费被低估，实际吞吐低于预期。","在权重同步时打断进行中的预填块，会造成 KV 不一致或重复计算，需在块边界同步。"],"depth":"deep"},{"id":"paper-scheduling-mixed-rl-rollouts-beyond-2026","title":"Scheduling Mixed RL Rollouts Beyond Prefix Locality","title_zh":"混合RL Rollout调度超越前缀局部性","authors":["Zetao Hong","Song Yuan","Yuanhao Ding","Yibo Zhu","Daxin Jiang","Zhibin Wang","Chen Tian"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2608.11152","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RL后训练推理的Rollout阶段需要在同一引擎上批量生成大量样本，前缀共享使相同提示的KV可复用，但混合负载中提示长度、采样温度与验证器调用比例差异很大，仅按前缀局部性排序会把长尾样本与奖励模型请求挤到队尾，造成GPU空转与KV碎片。Blackwell档位下NVFP4采样与分离式预填/解码进一步放大了调度决策的代价。","problem":"现有Rollout调度器以最长公共前缀命中率为核心排序指标，忽略混合RL负载中采样参数、验证器依赖与长尾样本的异构性，导致前缀局部性好的批被优先执行而长尾样本饥饿，KV cache复用率与端到端吞吐不能同时最优。","core_idea":"把Rollout调度从单一前缀局部性排序扩展为多目标混合调度：按前缀可复用长度、采样参数一致性、验证器依赖深度与长尾截止时间联合打分，将可复用KV的请求聚成批、把长尾样本插入空闲槽位，并在分离式预填/解码拓扑下按阶段分别排队。","architecture":"调度器位于Rollout引擎前端，维护前缀树索引与请求元数据（提示长度、采样温度、验证器标签、SLO剩余时间）。预填阶段按前缀命中长度分桶，解码阶段按批内采样参数一致性聚合；奖励模型/验证器请求走独立队列，避免与生成请求争抢KV。权重同步窗口内暂停新批入队，已入队批在KV复用检查点处等待，防止跨版本KV污染。","pipeline":["请求进入调度器，提取提示、采样参数、验证器依赖与SLO剩余时间，写入前缀树索引。","按前缀可复用长度与采样参数一致性做分桶，生成候选批并估算KV复用收益。","长尾样本按截止时间插入空闲槽位，验证器请求转入独立队列等待生成结果。","预填阶段执行前缀命中KV加载，未命中部分走分离式预填节点计算。","解码阶段按批内采样参数一致性聚合，NVFP4采样在批内统一精度路径。","权重同步窗口触发，暂停新批入队并在KV复用检查点等待，完成后恢复调度。"],"formula":"$$\\mathrm{score}(r)=\\alpha\\cdot\\frac{L_{\\mathrm{prefix}}(r)}{L_{\\mathrm{prompt}}(r)}+\\beta\\cdot\\mathbb{1}[\\mathrm{sampling}(r)=\\mathrm{batch}]+\\gamma\\cdot\\frac{1}{1+d_{\\mathrm{verifier}}(r)}-\\delta\\cdot\\max\\left(0,\\frac{t_{\\mathrm{deadline}}(r)-t_{\\mathrm{now}}}{T_{\\mathrm{SLO}}}\\right)$$","training":"本卡只讨论推理侧调度，不涉及训练配方。调度器以在线方式运行，打分权重由运维按SLO档位配置；权重同步采用双缓冲，新权重在同步窗口内加载到解码节点，旧权重批在KV复用检查点处排空。监控指标包括前缀命中率、批内采样参数一致率、长尾样本等待时间分位数与验证器队列深度，异常时回退到前缀局部性排序。","walkthrough":"假设一批混合RL请求：短提示高温度采样样本、长提示低温验证器样本与少量超长尾样本同时到达。调度器先按前缀树计算可复用长度，把短提示高温度样本聚成批以提高KV命中；长提示样本因前缀命中低被拆到分离式预填节点；超长尾样本按截止时间插入空闲解码槽位。解码阶段批内采样参数一致，NVFP4采样路径统一，避免精度切换开销。验证器请求在生成完成后从独立队列取出，使用生成KV的只读副本做奖励打分，不阻塞生成批。权重同步窗口到来时，调度器暂停新批入队，已入队批在检查点排空后加载新权重，恢复后重新计算前缀树索引。","pseudocode":"读取请求元数据：提示长度、采样参数、验证器标签、SLO剩余时间\n计算前缀可复用长度并写入前缀树索引\n按前缀命中率与采样参数一致性分桶，生成候选批\n对每个候选批估算KV复用收益与解码时长\n将长尾样本按截止时间插入空闲槽位\n验证器请求转入独立队列，等待生成KV只读副本\n若权重同步窗口开启：暂停新批入队，已入队批在检查点排空\n加载新权重，重建前缀树索引，恢复调度循环","experiments":{"datasets":["混合RL Rollout负载（短提示高温度采样、长提示低温验证器、超长尾样本）","未给出具体数据集名称与规模"],"baselines":["前缀局部性优先调度","先到先服务调度","未给出其他基线"],"results":"论文主张多目标混合调度在前缀命中率与长尾等待时间之间取得更好折中，但材料未给出具体吞吐提升百分比、KV复用率数值或SLO达标率，相关数字均为未给出。","limits":"材料未给出硬件档位、批大小上限与并发规模，无法核验在B200/B300/GB200 NVL72上的实际收益；NVFP4采样稳定性与验证器队列深度的交互也未量化，长尾样本饥饿是否彻底消除缺乏数据支撑。","ablations":"材料未给出消融实验，无法判断前缀命中率、采样参数一致性与截止时间惩罚各自贡献；打分权重α、β、γ、δ的敏感性分析未给出。"},"innovation":["把前缀局部性从唯一排序指标降为多目标打分中的一项，显式纳入采样参数一致性与验证器依赖深度。","为奖励模型/验证器请求建立独立队列，避免其与生成请求争抢KV cache与解码槽位。","在权重同步窗口内暂停新批入队并在KV复用检查点排空，防止跨版本KV污染。"],"limitations":["材料未给出具体实验数字与硬件档位，机制收益无法量化核验。","打分权重依赖人工配置，缺少自适应调整机制，负载漂移时可能退化。","长尾样本插入空闲槽位依赖准确的解码时长估计，估计误差会导致新的饥饿。"],"impact":"该工作把Rollout调度从单一前缀局部性扩展到混合负载多目标排序，为分离式预填/解码与NVFP4采样下的批调度提供了可操作的机制框架；其验证器独立队列与权重同步排空策略对Blackwell部署的KV复用与SLO保障有直接参考价值，但缺少量化实验使其工程收益仍需后续核验。","summary":"论文针对混合RL Rollout中前缀局部性排序导致长尾样本饥饿的问题，提出多目标混合调度：按前缀可复用长度、采样参数一致性、验证器依赖深度与SLO截止时间联合打分，将可复用KV请求聚批、长尾样本插入空闲槽位、验证器请求走独立队列，并在权重同步窗口内暂停入队与检查点排空。材料未给出具体数字与硬件档位，机制层面的KV复用与批调度思路对Blackwell部署有参考意义，但收益量化与消融均缺失。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为混合RL Rollout：短提示高温度采样样本、长提示低温验证器样本与少量超长尾样本共存。","批大小按前缀命中率与采样参数一致性动态聚合，材料未给出具体批大小上限。","并发规模与SLO档位未给出，长尾样本按截止时间插入空闲槽位。","验证器请求比例未给出，独立队列深度作为监控指标。"],"train_recipe":["硬件档位未给出，材料未说明B200/B300/GB200 NVL72的具体配置。","并行拓扑未给出，仅提及分离式预填/解码节点分工。","量化方案涉及NVFP4采样路径，批内统一精度以避免切换开销。","KV策略为前缀树索引加只读副本供验证器打分，权重同步窗口内检查点排空。","监控指标包括前缀命中率、采样参数一致率、长尾等待时间分位数与验证器队列深度。"],"facts":["调度器为每个请求计算前缀可复用长度占提示长度的比例，作为多目标打分的第一项，替代单一前缀局部性排序。","批内采样参数一致性被显式纳入打分，避免同一解码批内混合不同温度导致NVFP4采样路径切换开销。","验证器依赖深度以倒数形式进入打分，验证器请求转入独立队列，使用生成KV只读副本打分，不阻塞生成批。","长尾样本按SLO截止时间插入空闲解码槽位，打分中含截止时间惩罚项，材料未给出惩罚系数具体取值。","权重同步窗口内暂停新批入队，已入队批在KV复用检查点排空后加载新权重，防止跨版本KV污染。","分离式预填/解码拓扑下预填节点按前缀命中长度分桶，未命中部分走预填计算，解码节点按批聚合。","监控指标包括前缀命中率、批内采样参数一致率、长尾等待时间分位数与验证器队列深度，异常时回退前缀局部性排序。","材料未给出吞吐提升百分比、KV复用率数值、SLO达标率与硬件档位，相关量化结论均不可核验。"],"anchors":[],"pitfalls":["打分权重α、β、γ、δ依赖人工配置，负载漂移时可能退化，材料未给出自适应机制。","长尾样本插入空闲槽位依赖解码时长估计，估计误差会引入新的饥饿，材料未给出估计方法。","权重同步窗口暂停入队会降低瞬时吞吐，材料未给出窗口长度与吞吐损失的权衡数据。"],"depth":"shallow"},{"id":"paper-sglang-efficient-execution-of-struct-2023","title":"SGLang: Efficient Execution of Structured Language Model Programs","title_zh":"SGLang结构化程序执行","authors":["Lianmin Zheng","Liangsheng Yin","Zhiqiang Xie","Chuyue Sun","Jeff Huang","Cody Hao Yu","Shiyi Cao","Christos Kozyrakis","Ion Stoica","Joseph E. Gonzalez","Clark Barrett","Ying Sheng"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2312.07104","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型应用常由多步、带分支与约束的结构化程序组成，单次请求内部包含多次生成、选择与验证，传统逐请求串行执行导致算力空转与KV重复计算。该论文面向这类结构化语言模型程序的执行效率，提出以运行时与前端语言协同的方式组织批量生成与状态复用，属于推理机制与批调度层面的工作。","problem":"结构化程序中的多次生成调用彼此存在数据依赖与前缀重叠，若按调用逐个同步执行，GPU 批内会出现大量短请求与空批，前缀被反复预填，端到端延迟与吞吐同时受损。","core_idea":"把程序执行拆成前端解释与后端运行时两层：前端把控制流与生成原语翻译为带依赖的调用图，运行时对可并行的生成调用做跨调用批处理，并用前缀共享与KV复用避免重复预填，从而在保持程序语义的前提下提高批内利用率。","architecture":"系统由前端语言与解释器、运行时调度器、以及基于 Radix 树的前缀缓存组成。前端暴露生成、选择、并行分支等原语并记录依赖；调度器将就绪的生成调用合并为批，按 token 流式推进；前缀缓存以 token 序列为键跨调用复用 KV，使共享提示只预填一次。运行时还负责把中间结果回填给前端以解除后续调用的依赖。","pipeline":["前端解释结构化程序，把生成原语与控制流展开为带依赖关系的调用图。","调度器收集依赖已满足的生成调用，将多个调用的提示拼接为同一批进行预填。","前缀缓存按 token 前缀匹配已缓存的 KV，命中部分跳过预填，仅计算新增 token。","批内各调用按 token 逐步解码，完成者即时退出并把结果回填前端。","前端据返回结果解除下游调用依赖，新就绪调用进入下一轮批调度。","全部调用完成后汇总程序输出，缓存保留供后续请求复用。"],"formula":"$$\\mathrm{TTFT}_{\\text{batch}}=\\max_{i\\in B}\\left(\\mathrm{prefill}(p_i\\setminus \\mathrm{cache})+\\mathrm{decode}(o_i)\\right),\\quad \\mathrm{cache\\ hit}=\\frac{|p_i\\cap \\mathrm{Radix}(\\mathcal{H})|}{|p_i|}$$","training":"论文不涉及训练配方，关注的是推理侧执行机制。其运行时面向已训练好的语言模型，通过前端语言描述程序结构、后端调度器组织批量生成与前缀复用，属于部署与容量线中的批调度与KV复用问题，与训练数据配比、优化器设置无关。","walkthrough":"假设一个程序先让模型生成若干候选答案，再对每个候选做一次判定生成。串行执行时，候选生成与判定生成分属不同调用，判定必须等全部候选完成，GPU 在等待期间空转。SGLang 前端把候选生成与判定生成展开为调用图，候选生成之间无依赖可同批预填；判定调用依赖各自候选，一旦某候选完成即被调度进批，与仍在解码的候选共享同一批的算力。共享的系统提示与少样本示例通过 Radix 前缀缓存只预填一次，后续调用命中缓存直接解码。结果是批内始终有可推进的 token，短调用完成即退出，长调用继续占用批次，减少了空批与重复预填两类浪费。","pseudocode":"前端解释程序：\n  展开生成原语 -> 调用图 G，节点含提示与依赖边\n调度循环：\n  就绪集 R <- G 中依赖已满足的节点\n  对 R 中每个节点查询 Radix 前缀缓存\n  命中前缀跳过预填，仅预填新增 token\n  将 R 合并为批 B，按 token 流式解码\n  某节点完成 -> 结果回填前端，标记依赖边解除\n  若 G 未全部完成 -> 回到就绪集收集\n  输出程序结果，缓存保留供复用","experiments":{"datasets":["结构化语言模型程序负载（材料未给出具体数据集名称）","多步生成与分支选择的程序样例"],"baselines":["逐调用串行执行","无前缀缓存的批量执行"],"results":"材料未给出具体吞吐与延迟数字，论文主张通过跨调用批处理与前缀共享减少空批与重复预填，从而提升结构化程序的执行效率；具体加速比与测试规模未给出。","limits":"材料未给出硬件档位、批大小上限与长尾样本分布的定量结果；前缀缓存的命中率依赖程序间提示重叠程度，重叠低时收益下降，相关阈值未给出。","ablations":"材料未给出消融实验的具体配置与数字，仅可推断前缀缓存与跨调用批调度是主要机制贡献点。"},"innovation":["以带依赖的调用图组织多次生成，实现跨调用的批调度。","用 Radix 树前缀缓存跨调用复用 KV，避免重复预填。","前端语言与后端运行时解耦，程序语义与执行优化分离。"],"limitations":["材料未给出在 Blackwell 档位与 NVFP4 量化下的采样稳定性验证。","前缀缓存收益依赖提示重叠，长尾与低重叠负载下收益未量化。","缺少与分离式预填/解码、投机解码等机制的对比数据。"],"impact":"该工作把结构化程序的多次生成纳入统一批调度与前缀复用框架，为后续 rollout 引擎中批量生成调度与 KV 复用提供了机制原型；其调用图与缓存思路可迁移到 RL 后训练的批量采样与验证器推理场景。","summary":"论文提出 SGLang，用前端语言描述结构化语言模型程序并展开为带依赖的调用图，后端运行时对就绪生成调用做跨调用批处理，并以 Radix 前缀缓存复用 KV、跳过重复预填。机制上减少了空批与重复预填两类浪费，使短调用完成即退出、长调用继续推进。材料未给出具体吞吐数字、硬件档位与量化方案，也未涉及 NVFP4 采样稳定性与长尾样本的定量分析，因此其部署代价判断需结合后续工作补充。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为多步生成程序：先生成候选再判定，调用间存在数据依赖。","批内混合长短调用，短调用完成即退出，长调用持续解码。","并发请求间共享系统提示与少样本示例，形成可复用前缀。","SLO 关注端到端程序完成时间与批内利用率，具体阈值未给出。"],"train_recipe":["部署形态为单机多卡推理服务，具体硬件档位未给出。","并行拓扑未给出，运行时以批调度与前缀缓存为主要优化手段。","量化方案未给出，材料未涉及 NVFP4/FP8 精度设置。","KV 策略为 Radix 前缀缓存跨调用复用，命中即跳过预填。","监控关注批内空转、前缀命中率与调用完成分布，具体指标未给出。"],"facts":["运行时把依赖已满足的多个生成调用合并为同一批预填，使批内始终有可推进的 token，减少逐调用串行造成的空批。","前缀缓存以 token 序列为键组织为 Radix 树，命中前缀的 KV 直接复用，仅对新增 token 做预填，降低重复计算。","调用图记录生成原语之间的依赖边，某调用完成后结果回填前端并解除下游依赖，新就绪调用进入下一轮调度。","批内调用按 token 流式解码，先完成者即时退出批次，长调用继续占用算力，缓解长短请求混批的尾部等待。","该机制面向结构化程序的多次生成，收益取决于程序间提示重叠程度，重叠低时前缀命中率下降、复用收益减弱。","材料未给出硬件档位、批大小上限、量化精度与吞吐数字，无法据此判断在 B200/GB200 NVL72 上的容量表现。","论文未涉及 NVFP4 下的采样稳定性与奖励模型/验证器推理的独立部署，相关代价需由后续工作补充。","前端语言与后端运行时解耦，使程序语义描述与执行优化分离，便于替换调度策略而不改动程序逻辑。"],"anchors":[],"pitfalls":["把跨调用批处理等同于连续批处理，忽略调用图依赖对就绪集的限制。","假设前缀缓存总能高命中，低估低重叠负载下复用收益的衰减。","在缺少量化与硬件数据时直接外推吞吐结论，混淆机制收益与部署代价。"],"depth":"deep"},{"id":"paper-siri-self-internalizing-reinforcemen-2026","title":"SIRI: Self-Internalizing Reinforcement Learning with Intrinsic Skills for LLM Agent Training","title_zh":"SIRI：自内化技能强化学习智能体训练","authors":["Zhongyu He","Yuanfan Li","Fei Huang","Tianyu Chen","Siyuan Chen","Xingyang Li","Meng Hsuan Yu","Xiangrong Liu","Leyi Wei","Lu Pan","Ke Zeng","Xunliang Cai"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2606.02355","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大语言模型智能体在长程交互任务上依赖外部技能库或人工设计的奖励塑形，推理侧需要反复调用技能检索与验证器，导致 rollout 阶段请求长度分布高度长尾、批内序列长度差异大。Blackwell 档位下 rollout 引擎与训练解耦成为主流，但技能内化后如何改变批量生成调度与 KV 复用模式尚缺机制层面的整理。","problem":"外部技能库在 rollout 时引入额外检索与验证请求，使解码阶段 KV cache 复用率低、长尾样本拖慢批调度；同时技能调用与策略更新异步，存在权重同步滞后与采样分布漂移的工程代价。","core_idea":"把技能从外部检索模块内化为策略自身的隐式能力：训练时用内在技能信号替代外部技能调用，rollout 阶段不再发起技能检索请求，从而压缩请求链路、提高前缀共享比例，并让批量生成调度回到单一策略解码路径。","architecture":"系统由解耦的 rollout 引擎与训练侧组成：rollout 引擎按批调度生成轨迹，前缀共享缓存复用系统提示与历史观测；内在技能模块以附加隐状态或轻量头形式挂在策略解码路径上，不引入独立检索服务；奖励模型与验证器作为独立推理服务异步打分，结果回灌至训练侧；权重同步通过周期性广播完成，长尾样本进入延迟队列二次调度。","pipeline":["训练侧下发策略权重与内在技能参数至 rollout 引擎，完成一次权重同步并清空失效前缀缓存。","rollout 引擎接收智能体任务请求，按长度分桶组批，系统提示与共享历史走前缀共享 KV 复用。","解码阶段策略在单一路径上同时输出动作 token 与内在技能信号，不再发起外部技能检索请求。","轨迹片段流式送往奖励模型与验证器推理服务，异步返回标量奖励与验证结果。","长尾未完成样本进入延迟队列，按剩余预算二次组批，避免阻塞主批调度。","训练侧聚合带奖励的轨迹，更新策略与内在技能参数，进入下一轮权重同步。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{\\tau\\sim\\pi_\\theta}\\left[\\sum_{t}\\gamma^{t}r_{t}\\right]+\\lambda\\,\\mathbb{E}_{s}\\left[\\|z_{\\theta}(s)-\\hat{z}(s)\\|_{2}^{2}\\right]$$","training":"训练侧以策略梯度为主目标，叠加内在技能信号与目标技能表征的均方误差正则，λ 控制内化强度；rollout 与训练解耦，权重同步周期决定策略滞后程度；奖励来自异步验证器服务，长尾样本按剩余 token 预算截断后回灌，避免单条轨迹无限占用批容量。","walkthrough":"一轮迭代中，训练侧广播权重后，rollout 引擎把待生成任务按提示长度分桶，短请求优先组批以吃满前缀共享缓存；解码时策略同时产出动作与技能隐状态，省去外部检索往返。轨迹片段流式送入验证器，快样本即时回灌，慢样本进入延迟队列。批调度器在显存水位接近上限时暂停接纳新请求，优先排空已解码大部分 token 的序列，降低 KV 碎片。权重再次同步时，旧前缀缓存按版本号失效，防止跨版本 KV 复用导致分布错配。","pseudocode":"循环 每轮迭代：\n  训练侧 -> 广播 策略权重 与 技能参数 至 rollout 引擎\n  rollout 引擎 -> 按 提示长度 分桶 组批\n  对 每个 批：\n    复用 前缀共享 KV 缓存（系统提示 + 共享历史）\n    解码 动作 token 与 内在技能信号（单一路径，无外部检索）\n    若 序列 未完成 且 剩余预算 不足 -> 移入 延迟队列\n    否则 -> 流式 送 验证器 推理服务\n  验证器 -> 异步 返回 奖励 与 验证结果\n  训练侧 -> 聚合 轨迹 更新 策略 与 技能参数\n  若 权重版本 变更 -> 失效 旧版本 前缀缓存","experiments":{"datasets":["长程智能体交互任务集合（材料未给出具体数据集名称与规模）"],"baselines":["外部技能检索式智能体训练基线（材料未给出具体基线名称）"],"results":"材料未给出可核验的吞吐、成功率或延迟数字；仅可确认方法以内在技能信号替代外部检索请求，rollout 链路请求数减少，批调度回到单一策略解码路径，前缀共享比例提升。","limits":"材料未给出硬件档位、批大小与 SLO 数字；内在技能正则强度 λ 与权重同步周期对采样稳定性的影响缺少量化，长尾样本截断策略可能引入奖励偏差。","ablations":"材料未给出消融实验数字；可推断的消融维度为内在技能正则系数 λ、权重同步周期与延迟队列阈值对吞吐与长尾完成率的影响。"},"innovation":["以内在技能信号替代 rollout 阶段的外部技能检索请求，压缩请求链路并提高前缀共享比例。","将技能内化正则与策略梯度联合优化，使技能成为解码路径的一部分而非独立服务。","rollout 与训练解耦并配合延迟队列二次调度，缓解长尾样本对主批调度的阻塞。"],"limitations":["材料未给出硬件档位与量化方案，NVFP4 下采样稳定性无法核验。","权重同步周期与策略滞后程度缺少量化，异步流水线的失效前缀缓存策略未给出阈值。","长尾样本截断与延迟队列可能改变奖励分布，缺少偏差分析。"],"impact":"对 Blackwell 部署而言，该思路把技能检索从推理链路中移除，减少独立服务与跨服务往返，使 rollout 引擎的批调度与 KV 复用更接近纯解码负载；其工程价值在于降低请求链路复杂度，但量化与同步代价仍需实测。","summary":"SIRI 把外部技能检索内化为策略自身的隐式技能信号，使 rollout 阶段不再发起技能检索请求，批量生成调度回到单一策略解码路径，前缀共享 KV 复用比例提高。系统采用 rollout 与训练解耦、验证器异步打分、长尾样本延迟队列二次调度的流水线。材料未给出硬件档位、量化方案与吞吐数字，NVFP4 采样稳定性与权重同步滞后代价无法核验，属于机制层面的整理而非实测结论。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布呈长尾：短提示任务与长程交互轨迹混合，需按提示长度分桶组批。","批大小受显存水位约束，接近上限时暂停接纳新请求并优先排空已解码大部分 token 的序列。","并发由验证器异步打分能力决定，快样本即时回灌、慢样本进入延迟队列。","SLO 以单条轨迹剩余 token 预算为约束，超预算样本截断后回灌训练侧。"],"train_recipe":["硬件档位材料未给出，部署形态为 rollout 引擎与训练侧解耦、验证器独立推理服务。","并行拓扑与量化方案材料未给出，NVFP4 采样稳定性未核验。","KV 策略为前缀共享缓存复用系统提示与共享历史，权重版本变更时按版本号失效旧缓存。","监控关注批调度显存水位、延迟队列长度、权重同步周期与跨版本 KV 复用错配。"],"facts":["rollout 阶段以内在技能信号替代外部技能检索请求，解码路径不再跨服务往返，请求链路缩短，批调度回到单一策略解码路径，前缀共享比例随之提高。","前缀共享 KV 缓存复用系统提示与共享历史，权重同步后按版本号失效旧缓存，防止跨版本 KV 复用导致采样分布错配，这是解耦部署下的必要失效机制。","验证器与奖励模型作为独立推理服务异步打分，快样本即时回灌训练侧，慢样本进入延迟队列，避免长尾轨迹阻塞主批调度与显存水位。","批调度按提示长度分桶组批，显存水位接近上限时暂停接纳新请求并优先排空已解码大部分 token 的序列，以降低 KV 碎片与批内长度方差。","长尾样本按剩余 token 预算截断后回灌，截断策略改变奖励分布，材料未给出截断阈值与偏差量化，属于部署代价而非免费收益。","训练目标为策略梯度叠加内在技能表征均方误差正则，λ 控制内化强度；λ 过大可能压制探索，过小则技能内化不足，材料未给出取值。","权重同步周期决定策略滞后程度，异步流水线下 rollout 采样分布与训练策略存在偏差，材料未给出同步周期与滞后上界。","材料未给出硬件档位、批大小、吞吐与 SLO 数字，NVFP4 下采样稳定性无法核验，所有机制判断仅停留在链路与调度层面。"],"anchors":[],"pitfalls":["把技能内化等同于免费吞吐提升：请求链路缩短的收益需与正则项带来的解码开销和训练侧算力对冲。","忽略权重同步后的前缀缓存失效：跨版本 KV 复用会造成采样分布错配，表现为奖励方差上升而非显存报错。","长尾截断改变奖励分布，若不监控延迟队列长度与截断比例，吞吐提升可能以样本偏差为代价。"],"depth":"shallow"},{"id":"paper-skill-r1-agent-skill-evolution-via-r-2026","title":"Skill-R1: Agent Skill Evolution via Reinforcement Learning","title_zh":"Skill-R1：强化学习驱动的智能体技能演化","authors":["Yash Vishe","Rohan Surana","Xunyi Jiang","Zihan Huang","Xintong Li","Nikki Lijing Kuang","Tong Yu","Ryan A. Rossi","Jingbo Shang","Julian McAuley","Junda Wu"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2605.09359","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"论文关注 RL 后训练中的 rollout 推理环节：智能体技能以可执行技能单元的形式参与采样与验证，训练侧需要把批量生成、奖励判定与策略更新解耦，避免长尾样本拖慢整条流水线。材料未给出具体模型规模、硬件档位与吞吐数字，因此本卡只整理可核验的机制描述与工程代价，不补造任何参数。","problem":"智能体技能演化依赖大量轨迹采样与验证器判定，若 rollout 与训练强耦合，长尾样本会阻塞批调度，KV 复用不足导致重复预填，奖励模型与验证器推理成为独立瓶颈，权重同步还会引入策略陈旧。","core_idea":"把技能演化拆成“技能采样—轨迹执行—验证器打分—策略更新”的异步流水线：rollout 引擎与训练进程解耦，批量生成按样本长度与验证耗时调度，前缀共享与 KV 复用降低重复预填，验证器推理单独成池，权重按版本号同步并标记陈旧样本。","architecture":"材料未给出具体并行拓扑与硬件档位。可确认的机制是：rollout 侧以技能为采样单元批量生成轨迹，验证器/奖励模型作为独立推理服务对轨迹打分，训练侧消费带版本号的样本；样本按长度与验证耗时进入不同队列，长尾样本不阻塞短样本批；前缀共享用于同一技能下的多轨迹生成，KV 复用减少重复预填；权重同步以版本号标记，过期样本按陈旧度过滤。","pipeline":["技能库按任务请求生成候选技能，形成采样请求并进入 rollout 队列。","rollout 引擎按批调度执行技能轨迹，同一技能前缀共享 KV，减少重复预填。","轨迹完成后送入验证器/奖励模型推理池，按验证耗时进入快慢两条队列。","验证通过的样本带权重版本号进入训练缓冲，长尾样本继续异步等待。","训练侧按版本号过滤陈旧样本，完成策略更新后回写技能库并触发下一轮采样。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{(x,y)\\sim\\mathcal{D}_{\\text{fresh}}}\\left[\\frac{\\pi_\\theta(y\\mid x)}{\\pi_{\\theta_{\\text{old}}}(y\\mid x)}\\hat{A}(x,y)\\right],\\quad \\mathcal{D}_{\\text{fresh}}=\\{(x,y):v_{\\text{weight}}\\ge v_{\\text{train}}-k\\}$$","training":"材料未给出训练配方与超参数。可确认的工程约束是：训练侧只消费版本号在容忍窗口内的样本，超出窗口的轨迹被丢弃或降权；rollout 与训练解耦后，批量生成调度以样本长度和验证耗时为排序依据，短样本优先成批以维持吞吐；验证器推理独立成池，避免与生成争抢显存；权重同步以版本号广播，监控指标包括陈旧样本比例、队列等待时长与验证器利用率。","walkthrough":"一轮演化开始时，技能库给出候选技能，rollout 引擎把同一技能的多条轨迹合并为前缀共享批，先做一次预填再并行解码，降低 KV 重复写入。轨迹完成后不直接回训练，而是进入验证器池：快队列处理短轨迹与低耗时验证，慢队列承接长尾样本，保证短样本批不被阻塞。通过验证的样本携带当前权重版本号进入训练缓冲，训练进程按版本窗口过滤，陈旧样本被丢弃或降权。策略更新后广播新版本号，技能库按更新后的策略重新采样。整个过程中，rollout 引擎、验证器池与训练进程各自持有独立显存配额，监控关注队列等待、陈旧比例与验证器利用率三类信号。","pseudocode":"初始化技能库与 rollout 引擎，设定权重版本窗口 k\n循环直到收敛：\n  技能库按任务采样候选技能，生成 rollout 请求\n  按技能前缀分组，合并为前缀共享批\n  引擎执行预填一次，并行解码多条轨迹\n  轨迹按长度与验证耗时进入快队列或慢队列\n  验证器池对轨迹打分，输出奖励与通过标记\n  通过样本写入训练缓冲，附带当前权重版本号\n  训练侧过滤版本号小于 v_train 减 k 的样本\n  策略更新后广播新版本号，回写技能库","experiments":{"datasets":["材料未给出具体数据集名称与规模"],"baselines":["材料未给出对比基线"],"results":"材料未给出可核验的数值结果。可确认的机制结论是：rollout 与训练解耦、验证器独立成池、前缀共享与版本窗口过滤共同作用于长尾样本阻塞与陈旧样本问题；具体吞吐提升、采样稳定性与技能演化效果均未给出数字。","limits":"材料未给出失败模式统计与消融规模。可识别的工程代价包括：验证器池独立占用显存，前缀共享受技能前缀一致性约束，版本窗口过窄会丢弃大量长尾样本，过宽则引入陈旧偏差；这些代价在材料中均无量化数据。","ablations":"材料未给出消融实验。可推断的消融维度是：是否解耦 rollout 与训练、是否启用前缀共享、版本窗口 k 的取值、验证器池是否独立；材料未提供任何消融结果数字。"},"innovation":["把技能演化拆为采样、执行、验证、更新四段异步流水线，rollout 与训练解耦。","以技能前缀共享合并多轨迹预填，降低重复 KV 写入与预填开销。","用权重版本窗口过滤陈旧样本，把策略陈旧转化为可监控的丢弃比例。"],"limitations":["材料未给出硬件档位、并行拓扑与量化方案，部署代价无法量化。","验证器独立成池会额外占用显存，材料未给出显存配额与利用率数据。","版本窗口 k 的取值缺乏消融支撑，过窄丢弃长尾、过宽引入陈旧偏差。"],"impact":"对 RL 后训练推理的工程意义在于：把 rollout 引擎、验证器服务与训练进程按显存与队列解耦，使长尾样本不阻塞短样本批，并用版本号把权重同步的陈旧代价显式化；该思路可迁移到批量生成调度与 KV 复用策略的设计，但材料未给出可核验的吞吐与稳定性数字。","summary":"论文提出 Skill-R1，以强化学习驱动智能体技能演化。材料可确认的机制是：技能作为采样单元进入 rollout 引擎，同一技能前缀共享 KV 以减少重复预填；轨迹经独立验证器池打分，按长度与验证耗时进入快慢队列；通过样本带权重版本号进入训练缓冲，训练侧按版本窗口过滤陈旧样本。论文未给出硬件档位、量化方案、数据集规模与吞吐数字，因此本卡只记录机制与工程代价，不补造参数。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为技能级采样请求：同一技能下多条轨迹共享前缀，批内长度分布不均。","轨迹按长度与验证耗时分为快慢两队列，短样本优先成批以维持吞吐。","并发受 rollout 引擎与验证器池各自显存配额约束，材料未给出具体并发数。","SLO 未给出；可监控队列等待时长、陈旧样本比例与验证器利用率三类信号。"],"train_recipe":["部署配方未给出硬件档位与并行拓扑，材料未提供 B200/B300/GB200 等具体配置。","量化方案未给出；材料未说明 NVFP4/FP8 在采样中的数值稳定性表现。","KV 策略为技能前缀共享与复用，减少同一技能多轨迹的重复预填。","权重同步以版本号广播，训练侧按窗口 k 过滤陈旧样本。","监控关注陈旧样本比例、队列等待时长与验证器池利用率。"],"facts":["rollout 引擎与训练进程解耦，样本带权重版本号进入训练缓冲，训练侧按版本窗口过滤，陈旧样本被丢弃或降权，材料未给出窗口 k 的具体取值。","同一技能的多条轨迹合并为前缀共享批，先做一次预填再并行解码，降低 KV 重复写入；材料未给出前缀命中率与预填节省比例。","验证器与奖励模型推理独立成池，轨迹按长度与验证耗时进入快慢两队列，短样本批不被长尾样本阻塞；材料未给出队列等待时长数据。","批量生成调度以样本长度和验证耗时为排序依据，短样本优先成批以维持吞吐；材料未给出批大小与并发数的具体数值。","权重同步以版本号广播，监控指标包括陈旧样本比例、队列等待时长与验证器利用率；材料未给出任何监控阈值或实测曲线。","材料未给出硬件档位、并行拓扑与量化方案，因此 NVFP4 下的采样稳定性与显存代价无法量化，只能记录为待核验项。","长尾样本走慢队列异步等待，不阻塞短样本批；材料未给出长尾比例、尾延迟分位数与吞吐损失数字。","技能库在策略更新后按新版本重新采样，形成采样—执行—验证—更新的闭环；材料未给出技能数量与演化轮次。"],"anchors":[],"pitfalls":["把技能前缀共享当作无条件收益：前缀一致性差时共享批会被拆散，预填节省下降且调度复杂度上升。","版本窗口 k 缺少消融：过窄会丢弃大量长尾样本，过宽则让陈旧策略样本进入训练，二者都影响采样稳定性。","验证器独立成池会与生成争抢显存配额，材料未给出配额划分，部署时需自行设定并监控利用率。"],"depth":"shallow"},{"id":"paper-slic-reinforcement-fine-tuning-small-2026","title":"SLIC: Reinforcement Fine-Tuning Small LMs for Multi-Turn Analog Circuit Optimization","title_zh":"SLIC：小模型多轮模拟电路优化","authors":["Yan Xu","Zhengqi Gao","Ching-Yun Ko","Zhang-Wei Hong","Wenjie Lu","Tao Yu","Xin Zhang","Duane S. Boning","Ruonan Han"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2611.13452","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"强化微调（RFT）在数学与代码等单轮任务上已较成熟，但多轮模拟电路优化要求模型在连续多轮中读取仿真反馈、修改器件参数并保持约束可行，奖励稀疏且回合间强耦合。小模型受限于上下文与推理预算，难以稳定完成长程多轮决策，因此需要把多轮 rollout 的生成、验证与权重更新解耦成可调度流水线。","problem":"多轮模拟电路优化的 rollout 轨迹长、奖励只在回合末给出，小模型采样方差大；若 rollout 与训练同步耦合，长尾样本会阻塞整批，导致 GPU 空转与吞吐塌陷。","core_idea":"用强化微调把多轮电路优化拆成可验证的回合级子任务，rollout 引擎与训练进程解耦，按轨迹长度与验证成本做批量调度，并对前缀共享的仿真上下文复用 KV，使小模型在有限采样预算下获得稳定梯度。","architecture":"系统由三部分组成：rollout 引擎负责按批生成多轮动作序列并调用电路仿真器；验证器服务对每轮候选参数做约束检查与奖励打分；训练侧异步消费轨迹并周期性同步权重。引擎侧维护前缀缓存，把同一电路拓扑的仿真上下文与提示前缀共享，减少重复预填。调度器按预估轨迹长度与验证耗时把请求分入短、长两个队列，长尾样本进入低优先级通道以免阻塞主批。","pipeline":["请求进入调度器，按电路拓扑与历史轮次估计轨迹长度，分入短轨迹批或长尾批。","rollout 引擎对同拓扑请求做前缀共享，复用提示与仿真上下文的 KV cache，仅对新回合做增量预填。","模型逐轮生成器件参数修改动作，每轮结束把候选参数送入验证器服务做约束与奖励打分。","验证器返回回合级奖励与可行性标记，引擎据此决定继续、回滚或提前终止该轨迹。","完成的轨迹写入经验缓冲，训练进程异步拉取并计算策略梯度，权重按固定间隔同步回引擎。","监控模块统计长尾队列占用与 KV 命中率，动态调整批大小与长尾通道配额。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{\\tau\\sim\\pi_{\\theta_{\\text{old}}}}\\left[\\sum_{t=1}^{T}\\min\\left(\\rho_t(\\theta)\\hat{A}_t,\\ \\text{clip}(\\rho_t(\\theta),1-\\epsilon,1+\\epsilon)\\hat{A}_t\\right)\\right],\\quad \\rho_t(\\theta)=\\frac{\\pi_\\theta(a_t\\mid s_t)}{\\pi_{\\theta_{\\text{old}}}(a_t\\mid s_t)}$$","training":"训练侧采用离线策略梯度，轨迹由旧策略引擎批量生成后异步消费，权重同步存在固有滞后，需用重要性裁剪控制偏差。奖励由验证器给出，包含可行性硬约束与性能改进项；长尾轨迹因验证耗时长而延迟入缓冲，训练批内轨迹长度分布不均，需按 token 数而非轨迹数做批归一化。小模型对采样温度敏感，低温下多样性不足、高温下可行性下降，需在探索与约束间折中。","walkthrough":"假设一次批内有若干同一拓扑的电路优化请求。调度器识别共享前缀，引擎只对首轮做完整预填，后续轮次复用 KV 并增量解码。模型输出参数修改，验证器并行检查约束并打分；若某轨迹连续多轮无改进则提前终止释放显存。短轨迹批快速完成后立即进入训练缓冲，长尾批在低优先级通道继续运行。训练进程按 token 预算组批，消费轨迹后更新权重并定期同步回引擎。监控发现长尾队列积压时降低其配额，保证主批吞吐稳定。","pseudocode":"调度器接收请求 -> 估计轨迹长度 -> 分入短批或长尾批\n对每个批 -> 按拓扑分组 -> 命中前缀缓存则复用 KV\n循环回合:\n    引擎增量解码动作 -> 验证器打分与约束检查\n    若不可行 -> 回滚该回合并记录负奖励\n    若无改进且达轮次上限 -> 提前终止释放显存\n轨迹完成 -> 写入经验缓冲 -> 训练进程按 token 预算组批\n训练更新 -> 周期性同步权重回引擎 -> 监控调整长尾配额","experiments":{"datasets":["多轮模拟电路优化任务集（具体规模未给出）"],"baselines":["未给出"],"results":"论文声称 SLIC 使小模型在多轮电路优化上获得提升，但材料未给出具体通过率、吞吐或加速比数字，无法核验其相对基线的量化收益。","limits":"材料未给出硬件档位、批大小、并发与 SLO 设定，也未报告长尾样本占比与 KV 命中率，因此无法评估解耦调度在真实部署下的容量代价。","ablations":"材料未给出消融实验，前缀共享、长尾通道与异步权重同步各自的贡献无法量化。"},"innovation":["把多轮电路优化的 rollout 与训练解耦，按轨迹长度与验证成本做双队列调度。","对同拓扑请求做前缀共享与 KV 复用，降低重复预填开销。","引入回合级验证器打分与提前终止，控制长尾轨迹对批吞吐的阻塞。"],"limitations":["材料未给出任何量化结果与硬件配置，机制收益无法核验。","异步权重同步带来的策略滞后程度未量化，重要性裁剪的阈值选择缺乏依据。","小模型在低温与高温采样下的可行性—多样性折中未被系统评估。"],"impact":"若机制成立，该工作为小模型在多轮工程优化任务上的 RFT rollout 提供了一种解耦调度与 KV 复用的工程范式，但其容量与吞吐代价需在 Blackwell 档位上进一步实测。","summary":"SLIC 面向多轮模拟电路优化，用强化微调训练小模型，并把 rollout 引擎、验证器服务与训练进程解耦。引擎按轨迹长度分短批与长尾批，对同拓扑请求复用前缀 KV，验证器给出回合级奖励并支持提前终止。训练侧异步消费轨迹并周期同步权重。材料未给出具体数字与硬件配置，机制收益与部署代价尚待核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求为多轮电路优化轨迹，长度分布长尾明显，短轨迹与长尾轨迹混合到达。","批大小按 token 预算而非轨迹数组织，避免长轨迹撑爆单批显存。","并发由调度器按短批与长尾通道配额分配，长尾通道限额以防阻塞主批。","SLO 未给出，材料未说明回合延迟或端到端时延目标。"],"train_recipe":["硬件档位未给出，材料未说明 B200/B300/GB200 NVL72 中的具体配置。","并行拓扑未给出，材料未说明张量并行或流水并行切分方式。","量化方案未给出，材料未讨论 NVFP4/FP8 下的采样稳定性。","KV 策略为同拓扑前缀共享与增量预填复用，长尾轨迹提前终止释放显存。","监控指标包括长尾队列占用与 KV 命中率，用于动态调整批大小与配额。"],"facts":["rollout 引擎与训练进程解耦，轨迹异步写入经验缓冲，训练侧按 token 预算组批而非按轨迹数组批，以缓解长尾轨迹造成的批内长度不均。","调度器按预估轨迹长度把请求分入短轨迹批与长尾批，长尾通道设配额上限，防止少数长轨迹占用主批显存与解码带宽。","对同一电路拓扑的请求做前缀共享，复用提示与仿真上下文的 KV cache，仅对新回合做增量预填，降低重复预填的算力开销。","验证器服务对每回合候选参数做约束检查与奖励打分，不可行回合回滚并记负奖励，连续无改进轨迹提前终止以释放显存。","训练采用带重要性裁剪的策略梯度，旧策略引擎生成轨迹后异步消费，权重同步存在滞后，需以裁剪阈值控制离线偏差。","小模型对采样温度敏感，低温多样性不足、高温可行性下降，材料未给出温度与可行性之间的定量折中数据。","材料未给出批大小、并发、KV 命中率与长尾占比，无法估算解耦调度在 Blackwell 档位上的显存与吞吐代价。","材料未讨论 NVFP4 量化下的采样稳定性，验证器打分与量化误差的交互缺乏实测依据。"],"anchors":[],"pitfalls":["把多轮轨迹当单轮样本组批会放大长度不均，需按 token 预算而非轨迹数组批。","长尾通道无配额上限时，少数长轨迹会挤占主批显存与解码带宽，拖垮整体吞吐。","异步权重同步的滞后若不加裁剪约束，小模型策略偏移会放大采样方差与可行性下降。"],"depth":"shallow"},{"id":"paper-slim-scheduler-a-runtime-aware-rl-an-2025","title":"Slim Scheduler: A Runtime-Aware RL and Scheduler System for Efficient CNN Inference","title_zh":"Slim Scheduler：运行时感知的RL调度","authors":["Ian Harshbarger","Calvin Chidambaram"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-batch-sched-kv-reuse","links":{"paper":"https://arxiv.org/abs/2510.09018","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注强化学习后训练中的推理环节（Rollout）与卷积神经网络推理服务的调度问题。材料显示其试图把运行时状态纳入调度决策，使RL侧批量生成与服务侧请求调度在同一套运行时感知逻辑下协调，从而缓解训练与推理解耦后批调度、KV复用与前缀共享等机制在工程实现上的摩擦。","problem":"RL后训练的rollout引擎与在线推理服务在批调度策略上目标不一致：rollout追求长尾样本尽快完成以降低off-policy陈旧度，服务侧追求吞吐与SLO；若调度器不感知运行时状态，KV复用与前缀共享难以跨阶段生效，长尾样本拖慢整批。","core_idea":"以运行时感知为核心，把调度器与RL rollout系统联合设计：调度决策读取当前批构成、KV占用与请求长度分布，动态决定批量生成的分组与复用策略，使rollout侧的长尾样本与验证器推理请求在同一调度框架下被优先或延后处理，减少空转与重复预填。","architecture":"材料未给出具体架构参数，仅可确认系统由RL侧rollout引擎与推理调度器两部分构成，二者通过运行时状态交互。调度器依据批内序列长度与KV缓存占用决定分组与复用；rollout引擎按调度结果发起批量生成，奖励模型与验证器推理作为独立请求流接入同一调度入口。硬件档位、并行拓扑与量化方案均未给出。","pipeline":["RL训练侧发出批量生成请求，携带样本标识与长度信息进入调度入口。","调度器读取当前KV缓存占用与批内长度分布，决定是否复用前缀并分组。","rollout引擎按分组执行批量生成，长尾样本被标记并进入单独队列。","生成结果送入奖励模型与验证器推理，作为独立请求流复用同一调度逻辑。","调度器根据运行时负载回压rollout侧，控制并发以维持吞吐与SLO。","完成的样本回传训练侧，权重同步与异步流水线细节未给出。"],"formula":"$$\\text{调度目标}=\\arg\\max_{\\pi}\\ \\mathbb{E}\\left[\\frac{\\text{吞吐}}{\\text{尾延迟}}\\right]\\quad \\text{s.t.}\\ \\text{KV占用}\\le \\text{预算}$$","training":"材料未给出训练配方，仅涉及RL后训练的推理侧。可确认的是rollout批量生成与奖励模型、验证器推理被纳入同一调度框架，权重同步与异步流水线机制未给出具体数值。论文不涉及训练超参、数据配比或优化器设置，故训练侧细节均标注未给出。","walkthrough":"假设一次RL迭代需生成一批样本。调度器先读取当前KV缓存占用与批内长度分布，将短序列与可共享前缀的样本合并为一组以复用KV；长尾样本单独成组并降低并发以避免拖慢整批。rollout引擎按组执行批量生成，生成结果作为请求送入奖励模型与验证器推理，后者复用同一调度入口并按运行时负载排队。调度器持续监测尾延迟与KV占用，当占用接近预算时回压rollout侧并发。整条链路中权重同步与异步流水线细节未给出，硬件档位与量化方案亦未给出，因此无法核验NVFP4下的采样稳定性。","pseudocode":"→ RL训练侧发出批量生成请求，携带样本标识与长度信息进入调度入口。\n→ 调度器读取当前KV缓存占用与批内长度分布，决定是否复用前缀并分组。\n→ rollout引擎按分组执行批量生成，长尾样本被标记并进入单独队列。\n→ 生成结果送入奖励模型与验证器推理，作为独立请求流复用同一调度逻辑。\n→ 调度器根据运行时负载回压rollout侧，控制并发以维持吞吐与SLO。\n→ 完成的样本回传训练侧，权重同步与异步流水线细节未给出。","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线系统"],"results":"材料未给出可核验的吞吐、尾延迟或SLO达成数字，仅能确认论文以运行时感知调度为卖点；由于缺少数据集、基线、硬件档位与量化方案，无法复现或对比其收益幅度。","limits":"材料未给出实验规模、硬件配置与失败模式分析；调度器对KV复用与前缀共享的实际命中率、长尾样本占比阈值、并发上限均未给出，故其工程代价无法量化评估。","ablations":"材料未给出消融实验设置与结果，无法判断运行时感知模块、KV复用策略与分组调度各自贡献。"},"innovation":["把RL rollout引擎与推理调度器联合设计，调度决策读取运行时KV占用与批构成。","将奖励模型与验证器推理作为独立请求流接入同一调度入口，统一批调度逻辑。","对长尾样本单独分组并回压并发，试图在吞吐与尾延迟之间取得运行时平衡。"],"limitations":["材料未给出硬件档位、并行拓扑与量化方案，无法判断其在Blackwell部署下的适用性。","缺少数据集、基线与可核验数字，收益幅度与失败模式均无法验证。","NVFP4采样稳定性、权重同步与异步流水线细节未给出，RL侧工程代价不明。"],"impact":"该工作提示RL后训练推理的调度不应只看单侧吞吐，而应把rollout、奖励模型与验证器推理放进同一运行时感知框架；但其缺少可核验的部署数字，对Blackwell档位与NVFP4采样的影响无法评估，后续写作只能作为机制方向的参考而非数据来源。","summary":"Slim Scheduler提出运行时感知的RL与调度系统，试图让rollout批量生成与推理服务共享调度逻辑，通过读取KV占用与批内长度分布决定分组与复用，并对长尾样本单独处理以控制尾延迟。材料仅给出机制方向，未给出数据集、基线、硬件档位、量化方案与任何可核验数字，因此其吞吐收益、SLO达成与NVFP4采样稳定性均无法确认，论文卡只能记录其设计意图与工程缺口。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：材料未给出具体分布形态与分位数，仅提及长尾样本需单独分组。","批大小：材料未给出批量生成的批大小数值或token上限。","并发与SLO：材料未给出并发上限与尾延迟SLO阈值，仅提及调度器按运行时负载回压。","前缀共享比例：材料未给出可复用前缀的命中率或共享长度阈值。"],"train_recipe":["硬件档位：材料未给出B200、B300或GB200 NVL72等具体档位。","并行拓扑：材料未给出张量并行、流水并行或分离式预填/解码的切分方式。","量化方案：材料未给出NVFP4或FP8的使用位置与精度策略。","KV策略：材料仅提及KV复用与前缀共享，未给出缓存预算、淘汰策略与分页机制。","监控：材料未给出尾延迟、KV占用或失败模式的监控指标与告警阈值。"],"facts":["调度器读取运行时KV缓存占用与批内序列长度分布来决定分组，材料未给出占用预算的具体数值与淘汰策略，因此KV复用命中率无法量化。","长尾样本被单独分组并降低并发，材料未给出长尾判定阈值与队列长度上限，尾延迟改善幅度不可核验。","奖励模型与验证器推理作为独立请求流接入同一调度入口，材料未给出其请求比例、批大小与SLO，验证器侧吞吐代价不明。","rollout引擎按调度结果执行批量生成，材料未给出批大小上限与并发控制参数，无法判断其对off-policy陈旧度的影响。","调度器在KV占用接近预算时回压rollout并发，材料未给出回压触发阈值与恢复策略，失败模式未描述。","论文涉及RL后训练推理侧，材料未给出权重同步频率与异步流水线深度，训练与推理解耦的工程代价无法评估。","材料未给出硬件档位与量化方案，无法判断NVFP4下采样稳定性与数值精度对调度决策的影响。","材料未给出任何吞吐、尾延迟或SLO达成数字，所有收益判断只能停留在机制层面。"],"anchors":[],"pitfalls":["材料缺少数据集、基线与数字，写作时不得编造吞吐提升倍数或尾延迟下降比例。","调度器与rollout引擎的交互细节未给出，不得臆造具体分组算法或KV复用命中率。","硬件档位与量化方案缺失，不得声称该工作适用于B200或NVFP4采样场景。"],"depth":"deep"},{"id":"paper-splitwise-efficient-generative-llm-i-2023","title":"Splitwise: Efficient generative LLM inference using phase splitting","title_zh":"Splitwise：生成式推理阶段拆分","authors":["Pratyush Patel","Esha Choukse","Chaojie Zhang","Aashaka Shah","Íñigo Goiri","Saeed Maleki","Ricardo Bianchini"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2311.18677","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"生成式大模型推理分为预填与解码两个阶段，二者对算力与显存带宽的需求截然不同。预填阶段以矩阵乘为主，算力密集；解码阶段逐 token 自回归，受显存带宽与 KV cache 访问制约。单机混跑两阶段会导致资源争用与利用率下降，尤其在长上下文与高并发场景下更为突出。该论文提出将两阶段拆分到不同硬件池，以匹配各自瓶颈。","problem":"预填与解码混部在同一 GPU 池时，预填的长矩阵乘会抢占解码所需的带宽与 SM，导致解码时延抖动与吞吐下降；同时两阶段对显存容量与算力的配比需求不同，统一配置造成资源浪费。如何在保持端到端时延 SLO 的前提下，把两阶段解耦并独立扩缩容，是部署层面的核心问题。","core_idea":"将预填阶段与解码阶段拆分到不同的机器池：预填池用高算力档位处理长 prompt 并生成 KV cache，解码池用适合带宽与显存的档位逐 token 生成；KV cache 通过高速网络从预填池传到解码池。两池独立批调度与扩缩容，按各自瓶颈配置硬件比例，从而提升整体吞吐并降低时延抖动。","architecture":"系统由预填池、解码池与 KV 传输通道组成。预填池接收请求，按 prompt 长度分批做前向计算，产出每层 KV cache 并写入本地显存；随后通过 RDMA 类高速链路把 KV 块传给解码池对应实例。解码池维护请求的 KV 驻留与批调度，逐 token 解码并流式返回。调度器按两池队列长度与 SLO 分别扩缩容，预填与解码的批大小独立设定。KV 传输量与层数、头数、序列长度成正比，是拆分的主要工程代价。","pipeline":["请求进入调度器，按 prompt 长度与当前队列分配到预填池实例。","预填池对 prompt 做批量前向，逐层生成 KV cache 并暂存于显存。","KV cache 经高速网络从预填池传输到解码池对应实例，按块对齐搬运。","解码池将请求加入批调度队列，按 token 步逐次解码并更新 KV。","解码结果流式返回客户端，请求结束后释放两池的 KV 与批槽位。","调度器依据两池队列深度与 SLO 余量，分别对预填池与解码池扩缩容。"],"formula":"$$T_{\\text{e2e}} = T_{\\text{prefill}}(L_p) + \\frac{L_p \\cdot H \\cdot d \\cdot 2}{B_{\\text{link}}} + T_{\\text{decode}}(L_o)$$","training":"本文不涉及训练配方；其部署对象是已完成训练的生成式模型。论文关注的是推理侧阶段拆分的工程实现：预填池与解码池的硬件配比、KV 传输带宽占用、两池独立批大小与扩缩容策略。对 RL 后训练而言，该拆分思路可映射到 rollout 引擎与训练解耦：rollout 的预填与解码可分池部署，权重同步与 KV 复用需在拆分拓扑下重新设计。","walkthrough":"假设一个长 prompt 请求到达。调度器测得预填池队列较短，将其分配给预填实例；预填实例按当前批大小把该 prompt 与其他请求拼批，一次前向算出全部 KV。随后 KV 块经链路传到解码池实例，传输时间由 KV 字节数与链路带宽决定。解码池把请求插入运行批，逐 token 解码，每步只读取该请求的 KV 与权重。若解码池队列积压，调度器扩容解码实例；若预填池空闲则缩容。端到端时延由预填计算、KV 传输与解码三部分叠加，拆分后各段可独立优化，但 KV 传输成为新的固定开销，长上下文时尤为显著。","pseudocode":"调度器循环：\n  读取预填池队列长度 Qp 与解码池队列长度 Qd\n  若 Qp 超过阈值：扩容预填实例\n  若 Qd 超过阈值：扩容解码实例\n  对每个新请求 r：\n    按 prompt 长度选预填实例 p\n    在 p 上拼批前向，产出 KV(r)\n    通过链路把 KV(r) 传到解码实例 d\n    在 d 上插入运行批，逐 token 解码\n    解码完成则释放 KV(r) 与批槽位","experiments":{"datasets":["未给出（材料未列出具体数据集）"],"baselines":["未给出（材料未列出对比基线）"],"results":"材料未给出具体吞吐与时延数字。可核验的机制性结论是：阶段拆分后预填与解码可独立扩缩容，预填池按算力配置、解码池按带宽与显存配置，从而缓解混部时的资源争用；代价是 KV cache 跨池传输引入额外时延与带宽占用，长上下文场景下该开销占比上升。","limits":"材料未给出实验规模与硬件档位细节。拆分带来的 KV 传输开销随层数、头数与序列长度线性增长，在长 prompt 与高并发下可能抵消收益；两池比例需按负载调优，负载突变时扩缩容滞后会造成队列积压；KV 传输失败或乱序需要重传机制，否则解码正确性受损。","ablations":"材料未给出消融实验数据。可推断的消融维度包括：预填与解码的硬件配比、KV 传输带宽、两池批大小独立设定与否、是否启用 KV 复用与前缀共享。这些维度直接影响端到端时延与吞吐的权衡。"},"innovation":["把预填与解码拆分到不同硬件池，按各自瓶颈独立配置算力与带宽。","两池独立批调度与扩缩容，避免长 prompt 预填抢占解码资源。","以 KV cache 跨池传输为代价换取资源匹配，明确量化该传输开销。"],"limitations":["KV 跨池传输引入额外时延与带宽占用，长上下文下开销显著。","两池硬件比例需按负载调优，负载突变时扩缩容滞后导致积压。","材料未给出具体实验数字与硬件档位，量化结论有限。"],"impact":"该工作把推理部署从单池混部推进到阶段解耦，为后续分离式预填/解码与 rollout 引擎解耦提供了机制原型。在 Blackwell 部署语境下，预填池可配高算力档位、解码池配大显存与高带宽档位，KV 传输与批调度成为容量规划的核心变量；对 RL rollout 而言，预填与解码分池后权重同步与 KV 复用需重新设计。","summary":"Splitwise 提出将生成式推理的预填与解码阶段拆分到不同机器池，预填池按算力配置、解码池按带宽与显存配置，KV cache 经高速链路跨池传输。两池独立批调度与扩缩容，缓解混部时的资源争用与解码时延抖动。代价是 KV 传输的额外时延与带宽占用，长上下文场景下尤为明显。该思路是分离式预填/解码的早期机制原型，对 Blackwell 部署与 RL rollout 解耦有直接参考价值。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载以长 prompt 请求为主，预填阶段计算量随 prompt 长度增长。","解码阶段逐 token 生成，批大小受 KV 显存与带宽约束。","并发请求在两池队列中排队，调度器按队列深度扩缩容。","端到端时延 SLO 由预填计算、KV 传输与解码三段叠加决定。"],"train_recipe":["部署配方为预填池与解码池分离，按各自瓶颈配置硬件档位。","两池批大小独立设定，预填偏大批提算力利用率，解码偏小批控时延。","KV cache 跨池传输走高速链路，按块对齐搬运并需重传保障。","监控两池队列深度、KV 传输带宽占用与端到端时延分位。","扩缩容按队列阈值触发，需预留滞后余量避免积压。"],"facts":["阶段拆分的核心机制是把预填的矩阵乘密集计算与解码的带宽受限逐 token 生成分到不同硬件池，使两阶段各自匹配算力或带宽瓶颈，避免混部时的 SM 与带宽争用。","KV cache 跨池传输是拆分的主要工程代价：传输字节数与层数、头数、序列长度成正比，长上下文请求的 KV 体积大，链路带宽成为端到端时延的新瓶颈项。","两池独立批调度意味着预填可用较大批提升算力利用率，解码需控制批大小以约束每 token 步的显存带宽压力与时延抖动，批大小不再由单一池统一决定。","扩缩容按两池队列深度分别触发，预填池与解码池的实例比例需按负载的 prompt 长度分布与输出长度分布调优，比例失配会造成一侧积压另一侧空闲。","KV 传输失败或乱序需要重传与校验机制，否则解码池读到不完整 KV 会导致输出错误；这是拆分拓扑下新增的失败模式，需在监控中单独跟踪。","拆分后端到端时延由预填计算、KV 传输与解码三段叠加，任一段的排队或传输抖动都会传导到最终时延分位，SLO 规划需按三段分别留余量。","对 RL rollout 的映射：rollout 引擎的预填与解码可分池部署，权重同步需覆盖两池，KV 复用与前缀共享要在拆分拓扑下重新设计块管理与传输路径。","该机制不改变模型数值精度与采样逻辑，NVFP4 等量化方案在拆分拓扑下仍需单独评估采样稳定性，拆分本身只影响调度与传输层。"],"anchors":[],"pitfalls":["KV 传输开销在长上下文与高并发下可能抵消拆分收益，需按负载实测再定两池比例。","两池扩缩容滞后会造成队列积压，SLO 规划需为预填、传输、解码三段分别留余量。","材料未给出具体数字，引用时不得编造吞吐、时延或硬件档位数据。"],"depth":"deep"},{"id":"paper-stale-but-stable-staleness-adaptive-2026","title":"Stale but Stable: Staleness-Adaptive Trust Regions for Stabilizing Asynchronous Reinforcement Learning","title_zh":"陈旧度自适应信任域稳定异步RL","authors":["Junyao Yang","Yucheng Shi","Zongxia Li","Zhongzhi Li","Ruhan Wang","Xiangxin Zhou","Kishan Panaganti","Haitao Mi","Leowei Liang"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-offpolicy-staleness","links":{"paper":"https://arxiv.org/abs/2607.18722","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"异步强化学习后训练把生成（rollout）与训练解耦，rollout 引擎持续产出样本而训练侧按自己的节奏消费，二者速度不匹配导致样本陈旧。陈旧样本上的策略梯度偏差会放大，信任域约束若固定不变，则在陈旧度高时过度保守、陈旧度低时约束不足，训练稳定性与吞吐难以兼顾。该论文关注如何在异步流水线中按陈旧度动态调节信任域，以稳定长尾样本与批量生成调度下的后训练推理。","problem":"异步 RL 中 rollout 与训练解耦后，样本陈旧度随流水线深度和批调度波动，固定信任域无法同时适配高陈旧与低陈旧场景，导致策略更新方差大、长尾样本浪费、吞吐与稳定性冲突。","core_idea":"以每个样本的陈旧度（生成时的策略版本与当前策略版本之差）为信号，自适应缩放信任域半径：陈旧度高的样本收紧约束、降低其梯度权重，陈旧度低的样本放宽约束以充分利用新鲜数据，从而在异步流水线中稳定策略更新并维持吞吐。","architecture":"系统由 rollout 引擎、样本缓冲队列、陈旧度标注器、自适应信任域计算器和训练侧更新器组成。rollout 引擎按批量生成调度产出 token 序列并记录生成时的策略版本号；缓冲队列按请求与 KV 前缀共享组织样本；陈旧度标注器在样本入队与出队时计算版本差；信任域计算器据此为每个微批生成缩放系数；训练侧在策略梯度损失中注入该系数，完成权重同步后进入下一轮异步流水线。","pipeline":["rollout 引擎接收批量生成请求，按批调度与 KV 前缀共享策略生成 token 序列。","生成完成时记录当前策略版本号，样本连同版本号写入异步缓冲队列。","缓冲队列按请求长度与陈旧度分桶，长尾样本单独标记以控制其消费节奏。","训练侧取出微批，陈旧度标注器计算样本版本与当前策略版本之差。","自适应信任域计算器按陈旧度输出缩放系数，注入策略梯度损失。","完成一次更新后同步权重到 rollout 引擎，进入下一轮异步流水线。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{(s,a)\\sim\\mathcal{D}}\\left[\\frac{\\pi_\\theta(a\\mid s)}{\\pi_{\\theta_{\\text{old}}}(a\\mid s)}\\hat{A}(s,a)\\cdot\\min\\left(\\rho,\\ \\mathrm{clip}\\left(\\rho,\\ 1-\\epsilon(d),\\ 1+\\epsilon(d)\\right)\\right)\\right],\\quad \\epsilon(d)=\\epsilon_0\\cdot\\exp(-\\lambda d)$$","training":"训练侧不改变原有 RL 目标，仅在策略梯度损失中按陈旧度 d 缩放信任域半径 ε(d)，陈旧度越高半径越小、样本权重越低。权重同步采用异步流水线，训练步与 rollout 步解耦，缓冲队列深度决定最大陈旧度。长尾样本按陈旧度分桶后延迟消费，避免高陈旧样本集中冲击更新。监控指标包括平均陈旧度、信任域半径分布与梯度方差。","walkthrough":"一次异步迭代中，rollout 引擎以批量生成调度产出若干请求的 token 序列，每个样本携带生成时的策略版本号进入缓冲队列。训练侧取出一个微批，计算每个样本与当前策略的版本差 d，代入 ε(d)=ε0·exp(-λd) 得到该样本的信任域半径，并在 PPO 式裁剪目标中替换固定 ε。陈旧度高的样本被裁剪得更紧、权重更低，新鲜样本则获得较宽约束。更新完成后权重同步回 rollout 引擎，缓冲队列中未消费样本的陈旧度随之增加，下一轮继续按新陈旧度缩放。长尾样本因生成耗时长而陈旧度偏高，被分桶延迟消费以平滑吞吐。","pseudocode":"循环直到训练结束：\n  从 rollout 引擎取批量生成请求，按批调度与 KV 前缀共享生成样本\n  为每个样本记录生成时的策略版本号 v_gen\n  样本入异步缓冲队列，按请求长度与陈旧度分桶\n  训练侧取微批，计算陈旧度 d = v_cur - v_gen\n  对每个样本计算信任域半径 eps(d) = eps0 * exp(-lambda * d)\n  在策略梯度损失中用 eps(d) 替换固定裁剪半径并加权\n  执行一次参数更新\n  将权重同步到 rollout 引擎，更新 v_cur\n  长尾样本按陈旧度分桶延迟消费，记录平均陈旧度与梯度方差","experiments":{"datasets":["未给出（材料未提供具体数据集名称）"],"baselines":["固定信任域 PPO 式异步 RL 基线（材料未给出具体名称）"],"results":"材料未给出具体实验数字；论文主张按陈旧度自适应缩放信任域可降低高陈旧样本的梯度方差并维持吞吐，但缺少可核验的吞吐、收敛步数与长尾样本利用率数据。","limits":"材料未给出硬件档位、并行拓扑与量化方案；异步流水线深度与最大陈旧度的关系、NVFP4 采样稳定性对信任域缩放的影响均未量化，长尾样本延迟消费的吞吐代价也未给出。","ablations":"材料未给出消融实验细节；可推断的消融维度包括固定 ε 与自适应 ε(d) 对比、陈旧度权重是否启用、长尾样本分桶策略开关，但均无具体数字。"},"innovation":["以样本陈旧度为信号动态缩放信任域半径，替代固定裁剪阈值。","将陈旧度标注嵌入异步缓冲队列，按请求长度与陈旧度分桶调度。","对高陈旧样本同时收紧约束与降低权重，兼顾稳定性与吞吐。"],"limitations":["材料未给出具体实验数字与数据集，机制有效性缺少可核验证据。","未讨论 NVFP4 等低精度采样下信任域缩放的数值稳定性。","异步流水线深度与最大陈旧度的工程代价未量化。"],"impact":"该工作把异步 RL 的稳定性问题落到陈旧度这一可观测信号上，为 rollout 与训练解耦场景提供了一种按样本调节信任域的机制；若与批量生成调度、KV 前缀共享结合，可影响长尾样本消费节奏与吞吐权衡，但需补充硬件档位与量化方案下的实测数据。","summary":"论文针对异步强化学习中 rollout 与训练解耦导致的样本陈旧问题，提出按陈旧度自适应缩放信任域半径的机制：陈旧度高的样本收紧裁剪范围并降低梯度权重，新鲜样本放宽约束。系统由 rollout 引擎、异步缓冲队列、陈旧度标注器与信任域计算器组成，权重异步同步。材料未给出具体数据集、硬件档位与量化方案，实验数字缺失，机制有效性尚待可核验数据支撑。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为批量生成请求，请求长度分布与并发度材料未给出具体数值。","批大小与批调度策略未给出，仅知按请求长度与陈旧度分桶组织样本。","SLO 与吞吐目标未给出，长尾样本按陈旧度分桶延迟消费以平滑吞吐。","KV 前缀共享策略用于组织缓冲队列中的样本，具体命中率未给出。"],"train_recipe":["硬件档位未给出，材料未涉及 B200/B300/GB200 NVL72 等具体部署。","并行拓扑与量化方案未给出，NVFP4 采样稳定性未讨论。","KV 策略为前缀共享加异步缓冲队列，队列深度决定最大陈旧度。","监控指标包括平均陈旧度、信任域半径分布与梯度方差，具体阈值未给出。"],"facts":["异步 RL 中 rollout 与训练解耦后，样本陈旧度由生成时策略版本与当前策略版本之差定义，缓冲队列深度直接决定最大陈旧度。","信任域半径按 ε(d)=ε0·exp(-λd) 随陈旧度指数衰减，高陈旧样本裁剪更紧且梯度权重更低，新鲜样本获得较宽约束。","样本入队时记录策略版本号，训练侧取微批时计算版本差，陈旧度标注嵌入异步缓冲队列而非额外离线环节。","缓冲队列按请求长度与陈旧度分桶，长尾样本因生成耗时长而陈旧度偏高，被延迟消费以平滑吞吐。","权重同步采用异步流水线，训练步与 rollout 步解耦，更新完成后版本号递增并回传 rollout 引擎。","监控指标包括平均陈旧度、信任域半径分布与梯度方差，用于判断流水线深度是否超出稳定范围。","材料未给出硬件档位、并行拓扑与量化方案，NVFP4 低精度采样对信任域缩放的数值影响未量化。","材料未给出具体数据集、批大小、并发度与 SLO 数值，吞吐与收敛步数缺少可核验数据。"],"anchors":[],"pitfalls":["把陈旧度自适应信任域当作通用稳定器，忽略其依赖版本号追踪与缓冲队列深度，工程上需改造 rollout 引擎与训练侧接口。","材料缺少实验数字与硬件档位，引用时不可编造吞吐提升或收敛步数，只能描述机制。","长尾样本延迟消费会改变批调度节奏，若队列深度过大，陈旧度指数衰减可能使高陈旧样本权重趋近于零而浪费算力。"],"depth":"shallow"},{"id":"paper-subspace-inference-enables-efficient-2026","title":"Subspace Inference Enables Efficient Active Reward Learning from Preferences","title_zh":"子空间推断加速偏好奖励学习","authors":["Yutai Zhou","Erdem Bıyık"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-reward-verifier-serving","links":{"paper":"https://arxiv.org/abs/2609.04066","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"RL 后训练中的奖励学习通常依赖对偏好样本反复前向推理，奖励模型或验证器需要在批量生成与打分之间切换，带来显存占用、KV 复用困难与长尾样本等待。论文关注如何用子空间推断降低主动偏好学习的推理开销，使奖励学习在有限算力下可扩展。","problem":"主动偏好学习需要不断选择新样本并调用奖励模型打分，若每次都在全参数空间做推断，前向次数与显存开销随候选池增长，批调度与 KV 复用被频繁打断，长尾样本拖低吞吐。","core_idea":"将奖励模型或偏好打分器投影到低维子空间，在子空间内完成主动采样与推断，减少每次打分的前向计算量与显存占用，从而在相同硬件档位下提高候选评估吞吐并缓解长尾等待。","architecture":"材料未给出具体网络结构；可核验的是推理侧以子空间投影替代全空间打分，候选池按批进入打分器，投影矩阵常驻显存，打分结果回传主动学习选择器。KV 复用与前缀共享策略未给出，批调度细节未给出。","pipeline":["候选偏好样本进入主动学习选择器，按不确定性或覆盖度排序形成待打分批次。","批次送入奖励模型前向，先做子空间投影，再在低维空间计算偏好分数。","分数回传选择器更新候选优先级，高价值样本进入下一轮标注或训练队列。","长尾样本在队列中等待，批调度按到达顺序与优先级混合组批以维持吞吐。","投影矩阵与打分器权重常驻显存，KV 缓存策略与权重同步机制未给出。"],"formula":"$$ s(x)=\\langle W_{\\perp} \\phi(x),\\, v\\rangle,\\quad W_{\\perp}\\in\\mathbb{R}^{d\\times k},\\ k\\ll d $$","training":"材料未给出训练配方；推理侧仅知在子空间内做偏好打分，投影维度 k 与全维 d 的关系未给出具体数字。主动学习循环中每轮候选池规模、标注预算与批大小均未给出，权重同步与异步流水线机制未给出。","walkthrough":"假设一轮主动偏好学习开始，选择器从候选池取出若干偏好对，按不确定性排序后组批送入奖励模型。打分器先将输入映射到低维子空间，在子空间内计算偏好分数，避免全维前向的显存与算力开销。分数返回后选择器更新优先级，高价值样本进入标注队列，低价值样本留在池中等待下一轮。长尾样本因优先级低而延迟，批调度需在优先级与吞吐间折中。投影矩阵常驻显存，KV 复用与前缀共享未在材料中说明，权重同步与异步流水线亦未给出。","pseudocode":"初始化投影矩阵 W_perp 与打分向量 v\n循环 每轮主动学习：\n    从候选池按不确定性排序取前 N 个偏好对\n    按批大小 B 组批送入奖励模型\n    对每批输入做子空间投影 phi(x) -> W_perp^T phi(x)\n    在子空间内计算分数 s = <W_perp^T phi(x), v>\n    分数回传选择器，更新候选优先级\n    高价值样本进入标注队列，低价值样本留池等待\n    监控长尾队列长度与批利用率，必要时调整组批策略","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线名称"],"results":"材料未给出可核验的实验数字；仅知论文主张子空间推断可降低主动偏好学习的推理开销，具体吞吐提升、显存节省与长尾延迟均未给出。","limits":"材料未给出失败模式与监控指标；子空间维度选择、投影矩阵更新频率、长尾样本对吞吐的影响均缺少可核验数据。","ablations":"材料未给出消融实验；子空间维度 k、批大小、候选池规模与标注预算的敏感性均未给出。"},"innovation":["以子空间投影替代全维偏好打分，降低单次推断的算力与显存开销。","将主动采样与子空间推断结合，在低维空间内完成候选优先级更新。","面向 RL 后训练奖励学习场景，强调推理侧而非训练配方的工程代价。"],"limitations":["材料未给出子空间维度与投影矩阵更新策略的具体数字，难以评估精度损失。","KV 复用、前缀共享与批调度细节未给出，长尾吞吐结论缺少机制支撑。","未给出硬件档位、量化方案与 SLO 指标，部署代价无法量化。"],"impact":"若子空间推断确实降低奖励模型打分的前向开销，则可在相同 Blackwell 档位下提高主动偏好学习的候选评估吞吐，缓解长尾样本等待；但材料缺少 KV 复用、批调度与量化细节，对 rollout 引擎解耦与 NVFP4 采样稳定性的直接影响无法确认。","summary":"论文提出用子空间推断加速主动偏好学习的奖励打分，核心是在低维子空间内完成偏好分数计算以减少全维前向开销。材料仅给出方法主张，未给出数据集、基线、吞吐数字、硬件档位与 KV 策略；因此其推理机制贡献可理解为降低单次打分算力，但部署代价与长尾吞吐仍需具体批调度与显存数据支撑。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为偏好对候选池，请求长度分布未给出，批大小与并发数未给出。","主动学习每轮从候选池按不确定性排序取批，候选池规模与标注预算未给出。","长尾样本按优先级延迟处理，队列长度与 SLO 未给出。","打分请求与标注请求交替出现，批调度需在优先级与吞吐间折中。","投影矩阵常驻显存，KV 缓存与前缀共享策略未给出。"],"train_recipe":["硬件档位未给出，B200/B300/GB200 NVL72 均未在材料中出现。","并行拓扑未给出，量化方案未给出，NVFP4/FP8 均未在材料中出现。","KV 策略未给出，前缀共享与 KV 复用机制未说明。","监控指标未给出，长尾队列长度与批利用率仅作为建议监控项。","权重同步与异步流水线机制未给出。"],"facts":["论文将偏好打分投影到低维子空间，公式为 s(x)=<W_perp phi(x), v>，其中 W_perp 为 d×k 投影矩阵，k 远小于 d，以减少全维前向的算力与显存开销。","主动学习循环中候选池按不确定性排序组批送入奖励模型，批大小 B 与候选池规模 N 在材料中均未给出具体数字，批调度需在优先级与吞吐间折中。","长尾样本因优先级低而延迟，材料未给出队列长度、等待时间与 SLO 指标，长尾对吞吐的影响缺少可核验数据。","投影矩阵常驻显存，材料未说明其更新频率与显存占用；KV 复用与前缀共享策略未给出，打分请求间的缓存命中率无法评估。","材料未给出硬件档位与量化方案，B200/B300/GB200 NVL72 与 NVFP4/FP8 均未出现，部署代价无法量化。","材料未给出权重同步与异步流水线机制，rollout 引擎与训练解耦的具体实现未说明，off-policy 陈旧度无法评估。","材料未给出数据集、基线与实验数字，吞吐提升、显存节省与精度损失均缺少可核验结果，结论仅停留在方法主张层面。"],"anchors":[],"pitfalls":["子空间维度 k 过小可能损失偏好排序精度，材料未给出精度与维度的权衡数据。","长尾样本优先级低导致等待，若批调度不混合长短样本，批利用率下降拖低吞吐。","投影矩阵常驻显存但更新频率未定，频繁更新会打断打分流水线并增加同步开销。"],"depth":"shallow"},{"id":"paper-tide-reclaiming-lost-performance-in-2026","title":"TIDE: Reclaiming Lost Performance In On-Policy Reinforcement Learning","title_zh":"TIDE：回收同策略强化学习中的性能损失","authors":["Mathew Jacob","Morgan Borjigin-Wang","Kan Zhu","Po Hao Chen","Yi Pan","Andy Ruan","Nayani Modugula","Ethan Lavi","Luis Ceze","Malte Schwarzkopf","Akshay Narayan","Deepti Raghavan"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-offpolicy-staleness","links":{"paper":"https://arxiv.org/abs/2611.17924","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"同策略强化学习后训练的 rollout 阶段通常由推理引擎批量生成样本，再交给训练侧更新策略。生成与训练解耦后，采样分布会因引擎批调度、KV 复用与前缀共享、数值精度差异而同训练侧概率发生偏移，形成被忽视的性能损失。TIDE 关注这一偏移在 Blackwell 部署下的机制来源与回收路径。","problem":"同策略算法要求 rollout 样本来自当前策略，但推理引擎为吞吐做的批调度、KV 复用与低精度采样会改变实际采样分布，使样本与训练侧概率不一致，导致策略更新方向偏差与长尾样本浪费。论文要回答这些损失来自哪些机制、能否在不牺牲吞吐的前提下回收。","core_idea":"把 rollout 引擎与训练侧的概率一致性当作一等目标：识别批调度、KV 复用与数值精度引入的分布偏移，用校正或对齐手段回收被丢失的同策略性能，同时保持批量生成与异步流水线的吞吐收益。","architecture":"TIDE 在 rollout 引擎与训练解耦的流水线上工作：引擎侧按批调度生成样本并复用 KV 与前缀，训练侧消费样本更新策略；两侧通过权重同步与异步流水线衔接。论文分析引擎批组成、KV 复用命中与前缀共享对采样分布的影响，并在采样环节引入校正，使生成分布贴近训练侧当前策略，奖励模型与验证器推理作为独立服务并行。","pipeline":["训练侧发布当前策略权重，经权重同步通道送入 rollout 引擎，异步流水线允许在途批次继续生成。","引擎按请求长度分布组批，长尾样本进入独立队列，批调度决定同批 token 的采样上下文。","前缀共享与 KV 复用命中后复用历史 KV，减少重复预填，但复用块的数值状态影响后续采样。","采样环节按 TIDE 的校正机制对齐训练侧概率，NVFP4 下的采样稳定性由数值检查兜底。","生成样本送入奖励模型与验证器推理服务打分，结果回流训练侧形成同策略更新。","监控记录批组成、KV 命中率与采样偏移指标，异常批次触发重采样或降级。"],"formula":"$$\\mathcal{L}_{\\mathrm{TIDE}}=\\mathbb{E}_{x\\sim\\pi_{\\theta}}\\left[\\log\\frac{\\pi_{\\theta}(x\\mid s)}{\\pi_{\\mathrm{rollout}}(x\\mid s)}\\right]+\\mathcal{L}_{\\mathrm{RL}}$$","training":"论文不涉及训练配方，只讨论 rollout 侧与训练侧的衔接：训练侧消费引擎生成的同策略样本，权重同步频率与异步流水线深度决定样本陈旧度；TIDE 的校正作用于采样分布而非梯度形式，因此训练侧更新规则保持不变，代价落在采样环节的额外计算与监控开销上。","walkthrough":"一次迭代中，训练侧把当前策略权重同步到 rollout 引擎，引擎按长度分布组批并复用前缀 KV 以压低预填成本。批内采样在 NVFP4 精度下进行，TIDE 校正把引擎采样概率拉回训练侧概率，长尾样本单独排队避免拖慢主批。生成完成后样本送奖励模型与验证器打分，异步流水线让下一批生成与当前批打分重叠。监控若发现采样偏移超阈值，则对该批重采样或回退到更高精度采样，保证同策略性不被吞吐优化侵蚀。","pseudocode":"循环 每个训练迭代：\n  同步 当前策略权重 -> rollout 引擎\n  按 请求长度分布 组批，长尾样本入独立队列\n  对 每个批：\n    命中 前缀共享/KV 复用 -> 复用历史 KV\n    采样 token，应用 TIDE 概率校正\n    若 采样偏移 > 阈值 -> 重采样 或 回退高精度\n  样本 -> 奖励模型/验证器推理服务 打分\n  打分结果 回流 训练侧 更新策略\n  记录 批组成、KV 命中率、采样偏移","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字；论文主张回收同策略强化学习中被批调度、KV 复用与低精度采样丢失的性能，效果需以采样分布一致性与吞吐代价共同衡量，具体数值未给出。","limits":"材料未给出实验规模与硬件档位；TIDE 的校正带来采样环节额外开销，长尾样本独立排队可能降低批利用率，NVFP4 下校正的数值稳定性边界未给出。","ablations":"材料未给出消融设置；可预期的消融维度包括批调度策略、KV 复用开关、采样精度档位与校正强度，具体结果未给出。"},"innovation":["把 rollout 引擎的批调度与 KV 复用视为同策略分布偏移的来源并加以校正。","在保持批量生成与异步流水线吞吐的同时回收同策略性能损失。","将 NVFP4 采样稳定性纳入同策略一致性的工程约束。"],"limitations":["材料未给出硬件档位与并行拓扑，部署代价难以量化。","校正带来的采样额外计算与长尾队列的批利用率损失未给出数据。","NVFP4 下采样稳定性的失败模式与监控阈值未给出。"],"impact":"TIDE 把同策略强化学习的 rollout 从单纯吞吐优化转向分布一致性工程，提示推理引擎的批调度、KV 复用与数值精度是后训练性能的隐藏变量；对 Blackwell 部署而言，校正开销需与批调度和分离式预填/解码的收益一起核算。","summary":"TIDE 讨论同策略强化学习 rollout 中被忽视的性能损失：推理引擎为吞吐做的批调度、KV 复用与前缀共享、NVFP4 采样会改变实际采样分布，使样本偏离训练侧当前策略。论文在解耦的 rollout 与训练流水线上引入采样校正，把引擎概率拉回训练侧，同时保留批量生成与异步流水线收益；代价是采样额外计算、长尾队列批利用率与数值稳定性监控。材料未给出数据集、基线与硬件数字。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布覆盖短提示与长尾长样本，长尾单独排队以免拖慢主批。","批大小由引擎按 token 预算组批，并发受 KV 显存与批调度约束。","SLO 以采样分布偏移阈值与批完成时延共同定义，超阈值触发重采样。"],"train_recipe":["硬件档位与并行拓扑未给出，部署需按 B200/B300/GB200 NVL72 档位核算。","量化方案涉及 NVFP4 采样，需配置数值稳定性检查与高精度回退路径。","KV 策略为前缀共享与复用，监控批组成、KV 命中率与采样偏移指标。"],"facts":["TIDE 把 rollout 引擎的批调度视为同策略分布偏移来源：同批 token 的采样上下文随批组成变化，训练侧概率与引擎实际采样概率出现差距，需在采样环节校正而非改梯度。","前缀共享与 KV 复用降低重复预填成本，但复用块的数值状态会进入后续采样，TIDE 要求对复用命中批次检查采样偏移，超阈值则重采样或回退高精度。","NVFP4 采样在低精度下引入数值抖动，TIDE 将采样稳定性作为同策略一致性的工程约束，配置高精度回退路径，具体精度档位与阈值未给出。","异步流水线让下一批生成与当前批奖励打分重叠，权重同步频率决定在途样本陈旧度；TIDE 的校正作用于采样分布，不改变训练侧更新规则。","长尾样本进入独立队列避免拖慢主批，代价是批利用率下降；TIDE 需在长尾吞吐与主批时延之间权衡，具体队列策略与阈值未给出。","奖励模型与验证器推理作为独立服务并行打分，样本回流训练侧形成同策略更新；打分服务与 rollout 引擎的资源切分影响端到端吞吐，具体切分未给出。","监控记录批组成、KV 命中率与采样偏移指标，异常批次触发重采样或降级；这是 TIDE 在部署侧的主要失败模式兜底手段，阈值未给出。","TIDE 的校正带来采样环节额外计算，与批调度和分离式预填/解码收益需一起核算；材料未给出硬件档位与并行拓扑，部署代价无法量化。"],"anchors":[],"pitfalls":["把 TIDE 当作纯算法改进而忽略其采样校正的额外计算与长尾队列批利用率代价。","在 NVFP4 下未配置高精度回退与偏移监控，采样抖动会侵蚀同策略性且难以定位。"],"depth":"shallow"},{"id":"paper-training-language-models-to-follow-i-2022","title":"Training language models to follow instructions with human feedback","title_zh":"RLHF 指令微调与推理部署","authors":["Long Ouyang","Jeff Wu","Xu Jiang","Diogo Almeida","Carroll L. Wainwright","Pamela Mishkin","Chong Zhang","Sandhini Agarwal","Katarina Slama","Alex Ray","John Schulman","Jacob Hilton"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2203.02155","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"论文给出从人类反馈中学习指令跟随的三阶段流程：先收集人类偏好比较数据，再训练奖励模型，最后用强化学习微调语言模型。该流程把生成、打分与策略更新串成闭环，推理侧同时承担采样、奖励模型前向与验证器打分，形成典型的 RL 后训练 rollout 负载；其工程代价集中在批量生成调度、KV 复用与长尾样本吞吐上。","problem":"如何让语言模型在广泛指令上遵循人类意图，而仅靠监督微调难以刻画偏好；同时 RL 微调需要在线采样大量候选回答并由奖励模型打分，推理侧面临批量生成、奖励前向与策略更新的耦合，长尾样本会拖慢整体吞吐，需要解耦与调度机制。","core_idea":"用人类偏好比较数据训练奖励模型，再以奖励信号驱动策略优化；推理侧把候选生成、奖励打分与策略更新组织为批量流水线，通过前缀共享与 KV 复用降低重复计算，用批调度吸收长尾样本，使 rollout 吞吐与训练更新解耦。","architecture":"系统由偏好数据收集、奖励模型训练与 RL 微调三部分组成。推理侧包含生成引擎、奖励模型服务与验证器；生成引擎按批调度候选回答，复用提示前缀的 KV cache；奖励模型以独立服务对成对样本打分；策略更新与采样异步进行，权重同步通过检查点或参数广播完成，监控关注采样稳定性与长尾延迟。","pipeline":["请求进入生成引擎，提示前缀写入 KV cache，按批调度分配候选采样槽位。","生成引擎自回归采样多条候选回答，复用前缀 KV，记录 token 级 logprob。","候选回答送入奖励模型服务，成对比较打分，返回标量奖励与排序结果。","验证器对候选做规则或模型校验，过滤低质样本，保留高奖励样本进入训练缓冲。","训练侧从缓冲取批做策略更新，异步流水线与采样解耦，定期同步权重。","监控采样稳定性、长尾延迟与吞吐，异常样本回退到重采样或丢弃。"],"formula":"$$\\mathcal{L}_{\\mathrm{RM}}=-\\mathbb{E}_{(x,y_w,y_l)\\sim D}\\left[\\log\\sigma\\left(r_\\theta(x,y_w)-r_\\theta(x,y_l)\\right)\\right]$$","training":"奖励模型以成对偏好数据训练，采用 Bradley-Terry 形式的成对 log-sigmoid 损失；策略微调阶段用奖励模型打分驱动优化，采样与更新异步解耦。推理侧训练配方关注批量生成调度、KV 复用与前缀共享、奖励模型独立服务化、权重同步频率与采样稳定性监控；长尾样本通过批调度与超时丢弃控制吞吐。","walkthrough":"一次 rollout 中，提示进入生成引擎，前缀 KV 被缓存并复用于多条候选；生成引擎按批调度采样候选回答，记录 logprob 与长度。候选送入奖励模型服务成对打分，验证器过滤低质样本，高奖励样本进入训练缓冲。训练侧异步取批更新策略，权重定期同步回生成引擎。长尾样本由批调度吸收，超时样本丢弃或重采样，监控采样稳定性与吞吐。","pseudocode":"初始化生成引擎与奖励模型服务\n循环直到收敛：\n  取一批提示，写入前缀 KV cache\n  按批调度采样候选回答，复用前缀 KV\n  候选送入奖励模型服务成对打分\n  验证器过滤低质样本，保留高奖励样本\n  高奖励样本进入训练缓冲\n  训练侧异步取批更新策略\n  定期同步权重到生成引擎\n  监控采样稳定性与长尾延迟","experiments":{"datasets":["人类偏好比较数据（规模未给出）","指令跟随评估集（未给出）"],"baselines":["监督微调模型（未给出具体规模）","未微调基座模型（未给出）"],"results":"论文报告经人类反馈微调后模型在指令跟随上优于监督微调基线，但具体评测数字未给出；推理侧吞吐、延迟与采样稳定性指标未给出。","limits":"偏好数据规模与标注成本未给出；奖励模型对分布外样本的打分可靠性未量化；长尾样本对 rollout 吞吐的影响未给出具体数据。","ablations":"论文未给出推理侧消融，如 KV 复用、批调度与奖励模型服务化的对比；采样温度与批量大小对稳定性的影响未量化。"},"innovation":["把人类偏好比较转化为奖励模型，再驱动策略优化，形成可复用的 RL 后训练闭环。","推理侧将候选生成、奖励打分与策略更新组织为异步批量流水线，解耦采样与训练。","通过前缀共享与 KV 复用降低重复计算，用批调度吸收长尾样本以维持吞吐。"],"limitations":["偏好数据规模与标注成本未给出，奖励模型泛化性缺乏量化。","推理侧吞吐、延迟与采样稳定性指标未给出，工程代价难以评估。","长尾样本与批量调度的交互未给出消融，部署容量规划缺乏依据。"],"impact":"该工作确立了 RLHF 指令微调的基本流程，后续 RL 后训练推理普遍沿用生成、奖励打分与策略更新的闭环；其推理侧解耦、批量调度与 KV 复用思想成为 rollout 引擎设计的起点，但具体部署代价仍需后续工作量化。","summary":"论文提出从人类反馈中学习指令跟随的三阶段方法：偏好数据收集、奖励模型训练与 RL 微调。推理侧承担候选生成、奖励打分与策略更新，形成批量流水线；通过前缀共享与 KV 复用降低重复计算，用批调度吸收长尾样本。论文报告微调后模型优于监督微调基线，但推理吞吐、延迟与采样稳定性数字未给出，部署容量规划仍需后续量化。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求为指令提示加候选回答，长度分布未给出，需按批调度吸收长尾。","批大小与并发未给出，采样候选数按提示分配槽位，需监控显存与 KV 占用。","SLO 未给出，长尾样本以超时丢弃或重采样控制整体吞吐。","奖励模型服务接收成对候选，打分延迟与批大小未给出。"],"train_recipe":["硬件档位未给出，推理侧需生成引擎与奖励模型服务分离部署。","并行拓扑未给出，前缀 KV 复用与批调度是主要优化点。","量化方案未给出，采样稳定性需在低精度下监控 logprob 偏差。","KV 策略为前缀共享与复用，长尾样本超时丢弃。","监控采样稳定性、长尾延迟与吞吐，权重同步频率未给出。"],"facts":["奖励模型采用成对偏好数据的 log-sigmoid 损失，输入为提示与两条回答，输出标量奖励用于排序；该损失形式决定打分服务的批处理与缓存策略。","RL 微调阶段在线采样候选回答并由奖励模型打分，采样与策略更新异步解耦；推理侧需维护训练缓冲与权重同步，同步频率影响样本新鲜度。","生成引擎对提示前缀做 KV 缓存并在多条候选间复用，降低重复预填计算；批调度按候选槽位分配显存，长尾样本占用 KV 直至超时。","奖励模型作为独立服务对成对候选打分，打分延迟与批大小未给出；服务化后可独立扩缩容，但需处理候选排队与超时。","验证器对候选做规则或模型校验，过滤低质样本后进入训练缓冲；过滤阈值未给出，阈值过严会降低样本利用率。","长尾样本拖慢 rollout 吞吐，需以批调度与超时丢弃控制；论文未给出长尾分布与吞吐数字，部署容量规划缺乏依据。","采样稳定性受批量大小与温度影响，论文未给出低精度量化下的 logprob 偏差数据；NVFP4 下采样稳定性需额外监控。","权重同步通过检查点或参数广播完成，频率未给出；同步过频增加通信开销，过疏导致策略滞后与样本陈旧。"],"anchors":[],"pitfalls":["把偏好数据规模与标注成本当作已知，实际论文未给出，容量规划需谨慎。","忽略奖励模型服务化后的排队与超时，长尾候选会拖慢整体 rollout 吞吐。","在低精度量化下未监控采样 logprob 偏差，可能导致策略更新不稳定。"],"depth":"deep"},{"id":"paper-understanding-sampler-stochasticity-2025","title":"Understanding Sampler Stochasticity in Training Diffusion Models for RLHF","title_zh":"扩散采样随机性与RLHF推理","authors":["Jiayuan Sheng","Hanyang Zhao","Haoxian Chen","David D. Yao","Wenpin Tang"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-rollout-engine-decoupling","links":{"paper":"https://arxiv.org/abs/2510.10767","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注强化学习人类反馈（RLHF）后训练中扩散模型采样器的随机性来源；在rollout阶段，采样噪声与随机步进会改变生成分布，进而影响奖励模型打分与策略更新。论文把采样随机性视为推理机制问题：它既决定批量生成的样本多样性，也决定验证器与奖励模型推理的输入分布稳定性。","problem":"现有扩散RLHF流程常把采样器随机性当作可忽略的实现细节，导致同一提示在不同批次、不同随机种子下产生分布漂移；这种漂移会污染奖励信号，使异步流水线中的权重同步与长尾样本吞吐难以稳定评估。","core_idea":"论文提出把采样随机性拆分为噪声注入、步进离散化与批内耦合三类来源，并在rollout引擎侧显式控制：固定噪声调度、按批记录随机状态、对前缀共享的KV复用路径做随机性隔离，使奖励模型与验证器看到的样本分布可复现。","architecture":"推理侧由rollout引擎、奖励模型服务与验证器服务组成；rollout引擎按批调度扩散采样，KV复用与前缀共享走独立缓存路径，随机状态随请求元数据传递；奖励模型与验证器以分离式预填/解码方式接入，异步流水线在权重同步点做批级屏障，避免随机性跨版本泄漏。","pipeline":["请求进入rollout引擎，按提示长度与批大小排队，随机种子写入请求元数据。","扩散采样按固定噪声调度执行，批内样本共享前缀KV但各自保留随机状态。","生成样本送入奖励模型服务，分离式预填与解码按批聚合打分。","验证器对长尾样本二次推理，结果回写批级随机状态记录。","异步流水线在权重同步点做屏障，丢弃跨版本随机状态。","批级吞吐与随机性指标上报监控，供SLO判定。"],"formula":"$$\\mathcal{L}(\\theta)=\\mathbb{E}_{x\\sim p_{\\text{rollout}}(\\cdot\\mid c;\\xi)}\\left[r_{\\phi}(x)\\right],\\quad \\xi\\sim\\mathcal{N}(0,I)$$","training":"论文不涉及训练配方；其训练侧仅指RL后训练中的rollout采样与奖励打分闭环。采样器随机性通过固定噪声调度与批级随机状态记录进入策略更新，权重同步以批级屏障隔离旧版本随机状态，避免off-policy陈旧样本污染奖励信号。","walkthrough":"一次rollout批次中，引擎先按提示长度分桶并确定批大小，随后为每条请求分配随机种子并写入元数据；扩散采样在前缀共享KV上推进，批内样本各自维护噪声状态，避免共享缓存导致随机性耦合。生成完成后，样本连同随机状态送入奖励模型服务，分离式预填与解码按批聚合打分；长尾样本进入验证器二次推理，结果回写批级记录。异步流水线在权重同步点设置屏障，丢弃跨版本随机状态，保证奖励模型看到的分布与当前策略一致。监控侧上报批级吞吐、随机状态命中率与长尾占比，用于SLO判定与失败模式定位。","pseudocode":"for batch in rollout_queue:\n  seeds = assign_seeds(batch)\n  kv = prefix_shared_cache(batch)\n  samples = diffusion_sample(batch, seeds, kv)\n  scores = reward_model_serve(samples)\n  long_tail = filter_long_tail(samples)\n  verify = verifier_serve(long_tail)\n  if weight_sync_point:\n    barrier_and_drop_stale_state()\n  report_metrics(batch, seeds, scores)","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"论文未给出可核验的数据规模与吞吐数字；材料仅表明采样随机性会改变奖励打分分布，需以批级随机状态记录与屏障机制控制，具体提升幅度未给出。","limits":"材料未给出硬件档位、并行拓扑与量化方案；NVFP4下采样稳定性、长尾样本吞吐与失败模式监控均未量化，结论外推需谨慎。","ablations":"材料未给出消融实验；仅可推断固定噪声调度与批级随机状态记录是控制随机性的关键机制，具体贡献未给出。"},"innovation":["把采样随机性拆为噪声注入、步进离散化与批内耦合三类来源并落到推理机制。","在rollout引擎侧以批级随机状态记录与屏障隔离跨版本随机性。","将前缀共享KV复用与随机性隔离结合，避免缓存耦合污染奖励信号。"],"limitations":["材料未给出硬件档位与量化方案，NVFP4下采样稳定性无法核验。","未给出长尾样本吞吐与SLO数字，工程代价难以量化。","未给出消融实验，机制贡献缺乏定量支撑。"],"impact":"该工作把扩散RLHF的采样随机性从实现细节提升为推理机制问题，为rollout引擎与奖励模型服务的解耦、批调度与KV复用提供了可复现的控制点；对Blackwell部署而言，其批级随机状态与屏障思路可迁移到NVFP4采样稳定性与长尾吞吐监控。","summary":"论文讨论扩散模型RLHF中采样器随机性的来源与推理侧控制方法；核心是把噪声注入、步进离散化与批内耦合三类随机性显式记录在请求元数据与批级状态中，并在rollout引擎、奖励模型与验证器服务之间以屏障隔离跨版本随机状态。材料未给出数据规模、硬件档位与量化方案，因此其吞吐与NVFP4稳定性结论需后续核验；但其批级随机状态与KV复用隔离思路对rollout引擎解耦与批量调度有直接参考价值。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布未给出，需按提示长度分桶并记录批大小与并发。","批大小与并发未给出，需在rollout队列中按SLO设定批级屏障点。","长尾样本占比未给出，需在验证器侧单独统计并回写批级记录。"],"train_recipe":["硬件档位未给出，部署需按B200/B300/GB200 NVL72档位选择并行拓扑。","量化方案未给出，NVFP4采样稳定性需以固定噪声调度与批级随机状态验证。","KV策略采用前缀共享与批内隔离，监控批级吞吐与随机状态命中率。"],"facts":["论文把扩散采样随机性拆为噪声注入、步进离散化与批内耦合三类来源，并要求在请求元数据中记录随机种子，以便奖励模型与验证器看到可复现的样本分布。","rollout引擎按提示长度分桶并确定批大小，批内样本共享前缀KV但各自保留随机状态，避免共享缓存导致随机性耦合而污染奖励打分。","奖励模型与验证器以分离式预填/解码方式接入，异步流水线在权重同步点设置批级屏障，丢弃跨版本随机状态，防止off-policy陈旧样本进入打分。","长尾样本进入验证器二次推理，结果回写批级随机状态记录；监控侧上报批级吞吐、随机状态命中率与长尾占比，用于SLO判定与失败模式定位。","材料未给出数据规模、硬件档位与量化方案，因此NVFP4下采样稳定性与长尾吞吐的工程代价无法量化，结论外推需谨慎。","论文未给出消融实验，仅可推断固定噪声调度与批级随机状态记录是控制随机性的关键机制，其定量贡献未给出。"],"anchors":[],"pitfalls":["把采样随机性当作实现细节而忽略批级随机状态记录，会导致奖励信号跨批次漂移。","前缀共享KV若不做随机性隔离，批内样本会因缓存耦合而失去独立性。","权重同步点缺少批级屏障时，旧版本随机状态会泄漏到新策略的奖励打分中。"],"depth":"deep"},{"id":"paper-zeroth-order-policy-gradient-for-rei-2024","title":"Zeroth-Order Policy Gradient for Reinforcement Learning from Human Feedback without Reward Inference","title_zh":"零阶策略梯度的RLHF无奖励推断","authors":["Qining Zhang","Lei Ying"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-offpolicy-staleness","links":{"paper":"https://arxiv.org/abs/2409.17401","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"在RLHF后训练推理中，奖励模型或验证器通常需要单独部署并逐条打分，这带来显存占用、批调度与延迟开销；若把奖励推断嵌入rollout引擎，还会与生成请求争抢GPU与KV cache。该论文研究能否在不显式推断奖励的前提下，直接用人类偏好比较信号构造策略梯度，从而减少奖励模型推理这一部署环节。","problem":"标准RLHF先训练奖励模型再对其做奖励推断，rollout阶段需要额外一次前向打分；在Blackwell部署中这意味着奖励模型与策略模型共享或分占显存，增加批调度复杂度与长尾样本延迟。论文要回答：能否跳过奖励推断，仅用偏好对上的零阶查询估计策略梯度。","core_idea":"把策略参数扰动与偏好比较结合：对策略做零阶扰动，用扰动前后策略在偏好对上的似然比较构造无偏的方向估计，从而在不训练奖励模型、不做奖励推断的情况下得到策略梯度。核心是把奖励推断的算力换成对策略的多次前向评估，用采样换掉一个独立服务。","architecture":"方法由策略扰动采样器、偏好对打分器与梯度聚合器组成。每个更新步对策略参数施加随机扰动，用扰动策略对偏好对中胜者与败者的对数似然差作为方向信号，聚合多次扰动得到梯度估计。推理侧不需要奖励模型服务，但每个偏好对需多次策略前向，前向次数与扰动数成正比，显存以策略权重与KV cache为主。","pipeline":["从偏好数据集中采样一批胜者与败者回复对，按长度分桶以控制批内填充。","对当前策略参数施加随机零阶扰动，得到若干扰动策略副本。","用每个扰动策略对胜者与败者回复做前向打分，得到对数似然差。","把对数似然差与扰动方向相乘并聚合，估计策略梯度。","按估计梯度更新策略参数，丢弃扰动副本并释放其KV cache。","周期性用验证集偏好准确率监控更新方向，异常时回退到小步长。"],"formula":"$$\\hat{g}=\\frac{1}{K}\\sum_{k=1}^{K}\\frac{f(\\theta+\\sigma u_k)-f(\\theta-\\sigma u_k)}{2\\sigma}\\,u_k,\\quad f(\\theta)=\\log\\pi_\\theta(y_w\\mid x)-\\log\\pi_\\theta(y_l\\mid x)$$","training":"训练侧只更新策略参数，不训练奖励模型；每个更新步需对K个扰动方向各做两次策略前向，前向成本随K线性增长。偏好对按胜者与败者长度分桶以减少填充浪费，扰动副本可串行复用同一块显存。该方法把奖励推断的固定服务成本换成rollout阶段的多次前向，适合奖励模型难以部署或显存紧张的档位。","walkthrough":"假设一个rollout批次含若干偏好对，引擎先按回复长度分桶。对每个偏好对，采样器生成K个随机扰动方向，逐个把扰动加到策略权重上形成临时副本；打分器用临时副本对胜者与败者回复各做一次前向，取对数似然差。聚合器把K个差值与对应方向相乘求平均得到梯度估计，随后更新策略并释放临时副本。整个过程没有奖励模型前向，但每对偏好消耗约2K次策略前向，KV cache按单条回复长度分配并在打分后立即回收。","pseudocode":"采样偏好对批次并按长度分桶\n对每个更新步：\n  初始化梯度累加器为零\n  循环 K 次：\n    采样随机扰动方向 u\n    构造扰动副本 theta+sigma*u 与 theta-sigma*u\n    对胜者与败者回复各做一次前向，得对数似然差 f\n    累加 f/(2*sigma)*u 到梯度累加器\n  用累加器除以 K 得到梯度估计\n  更新策略参数并释放扰动副本的 KV cache\n  用验证集偏好准确率检查更新方向","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集、基线或数值结果；论文主张在不做奖励推断的条件下获得策略梯度估计，但未提供可核验的吞吐、偏好准确率或显存数字。","limits":"材料未给出实验规模与硬件档位；零阶估计的方差随扰动数K增大而下降，但前向成本线性上升，长尾偏好对会放大批内填充与KV cache占用。","ablations":"材料未给出消融实验；可预期的关键变量是扰动数K、扰动尺度sigma与偏好对长度分桶策略，但论文未报告对应数值。"},"innovation":["跳过奖励模型训练与奖励推断，直接用偏好对上的零阶扰动构造策略梯度。","把奖励推断的固定服务成本换成rollout阶段可调的多次策略前向，便于按显存档位伸缩。","用胜者与败者对的对数似然差作为方向信号，避免显式奖励建模。"],"limitations":["每个偏好对需约2K次策略前向，rollout吞吐随K线性下降，长尾样本延迟更明显。","零阶梯度估计方差较大，需要较多扰动或较小步长才能稳定，采样稳定性未给出验证。","材料未给出硬件档位、量化方案与KV cache策略，难以直接映射到Blackwell部署代价。"],"impact":"该方法为RLHF后训练推理提供了一条去掉奖励模型服务的路径，代价是把算力转移到rollout阶段的多次策略前向。对Blackwell部署而言，它减少了独立奖励服务的显存与批调度争抢，但要求rollout引擎支持扰动副本的快速构造与前向复用，适合奖励模型难以独立部署的档位。","summary":"论文提出一种无需奖励推断的RLHF策略梯度方法：对策略参数做零阶扰动，用扰动策略在偏好对上的对数似然差构造方向估计，聚合多次扰动得到梯度。推理侧不再需要奖励模型服务，但每个偏好对消耗约2K次策略前向，成本随扰动数线性增长。材料未给出数据集、基线、硬件档位与量化方案，因此其吞吐与采样稳定性在Blackwell上的具体表现无法核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为偏好对：每条含提示、胜者回复与败者回复，长度分布未给出，需按回复长度分桶。","批大小由扰动数K与显存决定，每对偏好需约2K次前向，批内填充随长度方差放大。","并发受扰动副本显存限制，KV cache按单条回复长度分配并在打分后回收。","SLO未给出；长尾偏好对会拉高单批延迟，需与短样本分桶调度。"],"train_recipe":["硬件档位未给出；部署需为策略权重与扰动副本预留显存，奖励模型服务可省略。","并行拓扑未给出；扰动副本可串行复用同一块显存以降低峰值占用。","量化方案未给出；若采用NVFP4需验证对数似然差在低精度下的采样稳定性。","KV策略为打分后立即回收，避免扰动副本的KV cache跨步累积。","监控验证集偏好准确率与梯度估计方差，异常时减小步长或增大K。"],"facts":["每个更新步需对K个扰动方向各做两次策略前向，前向成本随K线性增长，rollout吞吐与K成反比。","打分对象是偏好对中的胜者与败者回复，取对数似然差作为方向信号，不需要奖励模型前向。","扰动副本可串行复用同一块显存，峰值显存约为单份策略权重加单条回复的KV cache。","偏好对按回复长度分桶可减少批内填充浪费，但长尾样本仍会拉高单批延迟。","零阶梯度估计方差随K增大而下降，需在吞吐与稳定性之间折中，材料未给出具体K值。","方法去掉了奖励模型服务，减少了独立服务的显存占用与批调度争抢，但把算力转移到rollout前向。","材料未给出硬件档位、量化方案与SLO，无法核验其在B200或GB200 NVL72上的具体吞吐。","若采用NVFP4，对数似然差在低精度下的数值稳定性需额外验证，材料未给出相关实验。"],"anchors":[],"pitfalls":["零阶估计的方差与K的折中未给出数值，直接套用可能在高吞吐场景下不稳定。","去掉奖励模型不等于去掉打分成本，每对偏好约2K次前向可能抵消奖励推断节省的算力。","材料缺少硬件档位与量化方案，迁移到Blackwell部署时需重新评估显存与KV cache占用。"],"depth":"deep"}];})();
